L["click logging: |cffff0000off|r"] = "클릭 기록: |cffff0000꺼짐|r"
L["verbose: |cff00ff00on|r -- a line in your own chat when somebody buffs you, when a favour is counted as repaid, and when a click fails, is skipped, or leaves somebody owed"] = "대화창 알림: |cff00ff00켜짐|r -- 누군가 나에게 버프를 줄 때, 호의를 보답한 것으로 처리할 때, 클릭이 실패하거나 건너뛰었거나 보답하지 못한 채 끝났을 때 내 대화창에 한 줄씩 표시"
L["verbose: |cffff0000off|r"] = "대화창 알림: |cffff0000꺼짐|r"
L["quiet: |cff00ff00on|r -- Manners says nothing in chat now, but answers what you type after /manners. |cffffd100/manners quiet|r again to hear it."] = "조용히: |cff00ff00켜짐|r -- 이제 Manners는 대화창에 아무것도 출력하지 않지만, /manners 뒤에 입력한 명령에는 응답합니다. 다시 들으려면 |cffffd100/manners quiet|r를 한 번 더 입력하세요."
L["quiet: |cffff0000off|r -- Manners talks in chat again."] = "조용히: |cffff0000꺼짐|r -- Manners가 다시 대화창에 출력합니다."
L["enabled."] = "켜졌습니다."
L["Switched off -- the prompt this fight froze stays up until it ends, and a press still casts it."] = "꺼져 있음 -- 이번 전투에서 고정된 알림창은 전투가 끝날 때까지 화면에 남으며, 누르면 여전히 시전됩니다."
L["disabled."] = "꺼졌습니다."
L["nobody is on your never-offer list. Shift-right-click the prompt to put whoever it is showing on it."] = "제외 목록이 비어 있습니다. 알림창을 Shift+오른쪽 클릭하면 지금 떠 있는 사람을 목록에 넣습니다."
L["never offered anything unless they buff you: %s"] = "나에게 버프를 주지 않는 한 띄우지 않음: %s"
L["say who: |cffffd100/manners allow Name|r. |cffffd100/manners never|r lists everybody on the list."] = "누구인지 입력하세요: |cffffd100/manners allow Name|r. |cffffd100/manners never|r 명령으로 목록 전체를 볼 수 있습니다."
L["|cffffffff%s|r can be offered again."] = "|cffffffff%s|r님이 다시 알림창에 뜰 수 있습니다."
L["nobody called %s is on your never-offer list."] = "%s님은 제외 목록에 없습니다."
L["snooze takes a number of minutes from 1 to %d, or off -- for example |cffffd100/manners snooze 15|r or |cffffd100/manners snooze 1h|r."] = "snooze 뒤에는 1에서 %d 사이의 분 단위 숫자나 off를 입력하세요 -- 예: |cffffd100/manners snooze 15|r 또는 |cffffd100/manners snooze 1h|r."
L["your settings are in the box under |cffffd100Share as text|r (%s) -- click in it, select all and copy."] = "설정이 |cffffd100문자열로 공유|r 항목 아래 입력란(%s)에 있습니다 -- 입력란을 클릭하고 모두 선택해 복사하세요."
L["this string is too long to be imported back -- a very long phrase box under What I say is the usual cause. Shorten it if you want to share these settings."] = "이 문자열은 너무 길어서 다시 가져올 수 없습니다 -- 보통은 말하기 탭의 대사 상자가 아주 긴 것이 원인입니다. 이 설정을 공유하려면 대사를 줄이세요."
L["paste the settings string into the box under |cffffd100Share as text|r (%s), or type |cffffd100/manners import|r followed by it."] = "설정 문자열을 |cffffd100문자열로 공유|r 항목 아래 입력란(%s)에 붙여 넣거나, |cffffd100/manners import|r 뒤에 이어서 입력하세요."
L["type |cffffd100/manners import|r followed by a settings string."] = "|cffffd100/manners import|r 뒤에 설정 문자열을 이어서 입력하세요."
L["the self-test did not load -- reinstalling Manners should bring it back."] = "자체 점검을 불러오지 못했습니다 -- Manners를 다시 설치하면 돌아올 것입니다."
L["Tools for testing Manners on this client:"] = "이 클라이언트에서 Manners를 시험하는 도구:"
L["nothing has broken this session."] = "이번 접속 중 발생한 오류가 없습니다."
L["|cffffd100the last %d of %d|r |cff808080(%d kept)|r:"] = "|cffffd100최근 %d건 (전체 %d건)|r |cff808080(%d건 보관 중)|r:"
L["|cffffd100the last %d of %d|r:"] = "|cffffd100최근 %d건 (전체 %d건)|r:"
L["Flavour.lua did not load -- check the toc's file list"] = "Flavour.lua를 불러오지 못했습니다 -- toc 파일 목록을 확인하세요"
L["your own buff: not offered -- %s is switched off."] = "내 버프: 띄우지 않음 -- %s 옵션이 꺼져 있습니다."
L["queue now: %d"] = "현재 대기열: %d"
L["queue if switched on: %d"] = "켰을 때 대기열: %d"
L["switched OFF on this profile -- nothing is recorded or offered; /manners on"] = "이 프로필에서 꺼짐 -- 아무것도 기록하거나 띄우지 않음; /manners on"
L["|cffff4040this client has never heard of %s|r -- Manners has the wrong spell ids for %s on %s. Please report this line."] = "|cffff4040이 클라이언트는 주문 %s을(를) 모릅니다|r -- Manners에 있는 %s 버프의 주문 ID가 %s 기준으로 틀렸습니다. 이 줄을 제보해 주세요."
L["owes returning: |cffffffff%s|r (%ds left, buffed you %ds ago)"] = "보답할 호의: |cffffffff%s|r (%d초 남음, %d초 전에 나에게 버프를 줌)"
L["not watching for favours -- Manners is switched off."] = "호의를 감시하지 않음 -- Manners가 꺼져 있습니다."
L["Favours are not recorded while \"People who buff me\" is off (%s)."] = "\"나에게 버프를 준 사람\" 옵션이 꺼져 있는 동안에는 호의가 기록되지 않습니다 (%s)."
L["not watching for favours -- |cffffd100People who buff me|r is switched off."] = "호의를 감시하지 않음 -- |cffffd100나에게 버프를 준 사람|r 옵션이 꺼져 있습니다."
L["nobody has buffed you recently."] = "최근 나에게 버프를 준 사람이 없습니다."
L["your own buff: offered to you when you are missing it."] = "내 버프: 없을 때 알림창에 뜹니다."
L["your own buff: nothing you cast goes on yourself alone."] = "내 버프: 나 하나에게만 시전하는 주문이 없습니다."
L["prompt is UNLOCKED -- it will not buff anyone until you /manners lock"] = "알림창 잠금 해제됨 -- /manners lock 입력 전까지 아무에게도 버프를 주지 않음"
L["|cffffd100snoozed %s|r -- no prompt until then; /manners snooze off ends it"] = "|cffffd100%s 숨김|r -- 그때까지 알림창이 뜨지 않음; /manners snooze off 입력 시 종료"
L["|cffffd100mounted|r -- \"Hide the prompt while I'm mounted\" keeps it away until you get off"] = "|cffffd100탈것 탑승 중|r -- 탈것 탑승 중 알림창 숨기기 옵션 때문에 내릴 때까지 알림창이 뜨지 않음"
L["|cffffd100saving mana|r -- until you are back to %d%% mana, only your own buff and people who buffed you or asked are offered"] = "|cffffd100마나 절약 중|r -- 마나가 %d%%로 회복될 때까지 내 버프와, 나에게 버프를 주거나 요청한 사람만 뜸"
L["|cffffd100saving mana|r -- until you are back to %d%% mana, only people who buffed you or asked are offered"] = "|cffffd100마나 절약 중|r -- 마나가 %d%%로 회복될 때까지 나에게 버프를 주거나 요청한 사람만 뜸"
L["|cffffd100saving mana|r -- until you are back to %d%% mana, only your own buff is offered"] = "|cffffd100마나 절약 중|r -- 마나가 %d%%로 회복될 때까지 내 버프만 뜸"
L["|cffffd100saving mana|r -- until you are back to %d%% mana, nothing is offered"] = "|cffffd100마나 절약 중|r -- 마나가 %d%%로 회복될 때까지 아무것도 뜨지 않음"
L["|cffffd100ready check|r -- your party or raid comes first until the pull"] = "|cffffd100전투 준비|r -- 전투가 시작될 때까지 내 파티나 공격대가 먼저 뜸"
L["|cffffd100party|r -- no line goes out when you buff: %s is on"] = "|cffffd100파티|r -- 버프를 줄 때 한마디를 하지 않음: %s 켜짐"
L["Say nothing in a party"] = "파티에서는 아무 말도 하지 않기"
L["|cffffd100raid|r -- no line goes out when you buff: %s is on"] = "|cffffd100공격대|r -- 버프를 줄 때 한마디를 하지 않음: %s 켜짐"
L["Say nothing in a raid"] = "공격대에서는 아무 말도 하지 않기"
L["|cffffd100first name only|r -- a line says only the first word of a name"] = "|cffffd100이름만|r -- 대사가 이름의 첫 단어만 말합니다"
L["|cffffd100lines left out|r -- In character never says %d of its lines"] = "|cffffd100제외한 대사|r -- 캐릭터 롤플레이가 대사 %d개를 절대 말하지 않습니다"
L["|cffffd100raid groups|r -- in a raid, only groups %s are offered unasked"] = "|cffffd100공격대 파티|r -- 공격대에서는 %s파티만 요청 없이 뜸"
L["|cffffd100raid groups|r -- every group is unticked, so in a raid nobody is offered unasked"] = "|cffffd100공격대 파티|r -- 모든 파티가 선택 해제되어 있어, 공격대에서는 아무도 요청 없이 뜨지 않음"
L["|cffff8080/manners try is armed:|r %s -- clear it with a bare /manners try"] = "|cffff8080/manners try 장전됨:|r %s -- 내용 없이 /manners try 입력 시 해제"
L["there is no |cffffd100/manners %s|r -- did you mean |cffffd100/manners %s|r? |cffffd100/manners help|r lists them all."] = "|cffffd100/manners %s|r 명령은 없습니다 -- 혹시 |cffffd100/manners %s|r 명령을 찾으셨나요? |cffffd100/manners help|r 명령으로 전체 목록을 볼 수 있습니다."
L["there is no |cffffd100/manners %s|r -- did you mean |cffffd100/manners %s|r? |cffffd100/manners dev|r lists the testing tools."] = "|cffffd100/manners %s|r 명령은 없습니다 -- 혹시 |cffffd100/manners %s|r 명령을 찾으셨나요? |cffffd100/manners dev|r 명령으로 시험 도구 목록을 볼 수 있습니다."
L["Your own buffs wait while you rest in a city or an inn, and come up when you leave. To be reminded in town too, tick %s on %s."] = "도시나 여관에서 휴식 중일 때는 내 강화 효과 알림이 기다렸다가, 떠나면 나타납니다. 도시에서도 알림을 받으려면 %s 항목을 선택하세요 (위치: %s)."
L["Somebody just buffed you, but with friendly nameplates off the game would not say who. The prompt offers to thank them with your emote, but Manners cannot buff them back: %s on %s (|cffffd100/manners|r) turns them on."] = "누군가 방금 나에게 버프를 주었지만, 아군 이름표가 꺼져 있어 게임이 누구인지 알려 주지 않습니다. 알림창이 감정 표현으로 감사 인사를 하자고 제안하지만 Manners는 버프로 보답할 수 없습니다. %s(%s, |cffffd100/manners|r)로 켤 수 있습니다."
L["Somebody just buffed you, but with friendly nameplates off the game would not say who. Manners thanks them with your emote where it may, but cannot buff them back: %s on %s (|cffffd100/manners|r) turns them on."] = "누군가 방금 나에게 버프를 주었지만, 아군 이름표가 꺼져 있어 게임이 누구인지 알려 주지 않습니다. Manners는 가능한 곳에서 감정 표현으로 감사 인사를 하지만 버프로 보답할 수는 없습니다. %s(%s, |cffffd100/manners|r)로 켤 수 있습니다."
L["Somebody just buffed you, but with friendly nameplates off the game would not say who, so Manners cannot buff them back or thank them. %s on %s (|cffffd100/manners|r) turns them on, or %s on %s thanks them with your emote all the same."] = "누군가 방금 나에게 버프를 주었지만, 아군 이름표가 꺼져 있어 게임이 누구인지 알려 주지 않으므로 Manners가 버프로 보답하거나 감사 인사를 할 수 없습니다. %s(%s, |cffffd100/manners|r)로 켜거나, %s(%s)를 켜면 그래도 감정 표현으로 감사 인사를 합니다."
L["Thank them even when I can't see who it was"] = "누구인지 보이지 않아도 감사 인사하기"
L["Somebody just buffed you, but with friendly nameplates off the game would not say who, so Manners cannot buff them back. %s on %s (|cffffd100/manners|r) turns them on."] = "누군가 방금 나에게 버프를 주었지만, 아군 이름표가 꺼져 있어 게임이 누구인지 알려 주지 않으므로 Manners가 버프로 보답할 수 없습니다. %s(%s, |cffffd100/manners|r)로 켤 수 있습니다."
L["Somebody just put a buff on you, but the game did not say who, and more than one player in sight cast it at that moment, so Manners did not guess whom to buff back. %s on %s keeps it under What happened lately."] = "누군가 방금 강화 효과를 걸어 주었지만 게임이 누구인지 알려 주지 않았고, 그 순간 시야 안의 플레이어 둘 이상이 시전했기 때문에 Manners는 누구에게 갚을지 짐작하지 않았습니다. %s(%s)에서 What happened lately 아래의 기록을 볼 수 있습니다."
L["Somebody just put a buff on you, but the game did not say who. Manners saw a cast at that moment, but could not be sure whose buff it was, so there is nobody to buff back this time. %s on %s keeps it under What happened lately."] = "누군가 방금 강화 효과를 걸어 주었지만 게임이 누구인지 알려 주지 않았습니다. Manners는 그 순간 시전을 보았지만 누구의 강화 효과인지 확신할 수 없었기 때문에 이번에는 갚을 대상이 없습니다. %s(%s)에서 What happened lately 아래의 기록을 볼 수 있습니다."
L["Somebody just put a buff on you, but the game did not say who, and Manners saw no player in sight cast it on you, so there is nobody to buff back this time. It sees the casts of people on a nameplate, your target, your focus, your mouseover and your group. %s on %s keeps it under What happened lately."] = "누군가 방금 강화 효과를 걸어 주었지만 게임이 누구인지 알려 주지 않았고, 시야 안에서 나에게 시전하는 플레이어도 보이지 않았기 때문에 이번에는 갚을 대상이 없습니다. Manners는 이름표가 보이는 사람, 내 대상, 내 주시 대상, 마우스오버, 내 파티의 시전을 봅니다. %s(%s)에서 What happened lately 아래의 기록을 볼 수 있습니다."
L["Thank ye kindly, {name}! First round's on me when we're back at the forge."] = "고맙구먼, {name}! 대장간에 돌아가면 첫 잔은 내가 사지."
L["Much obliged, {name}. Ye've a friend in the mountain now."] = "신세 졌네, {name}. 이제 자넨 산의 친구일세."
L["Thank ye, {name}! I'd have been fine without it, mind. But thank ye."] = "고맙구먼, {name}! 없어도 끄떡없었겠지만. 그래도 고맙네."
L["Bless ye, {name}! I'd hug ye, but ye'd be needin' a healer after."] = "고맙네, {name}! 한번 안아 주고 싶다만, 그럼 자네가 치유사 신세일세."
L["Paid back already, {name}. Quicker than I've ever settled a bar tab."] = "벌써 갚았네, {name}. 내 평생 술값도 이리 빨리 갚아 본 적이 없구먼."
L["I'll tell this at the Thunderbrew like ye saved me life, {name}. Thank ye!"] = "썬더브루에선 자네가 내 목숨을 구했다고 떠벌릴 걸세, {name}. 고맙네!"
L["Grand, {name}! I'd carve ye a statue, but this is quicker."] = "훌륭하네, {name}! 석상이라도 깎아 주고 싶지만, 이게 더 빠르지."
L["The Titans made us of stone, {name}, but that still touched me. Thank ye."] = "티탄께서 돌로 빚은 이 가슴도 찡하구먼, {name}. 고맙네."
L["Thank ye, {name}. Back at ye, before me pride notices I needed it."] = "고맙네, {name}. 내 자존심이 눈치채기 전에 얼른 갚아 두지."
L["Thank ye, {name}. Muradin said a debt left unpaid rusts. Here, before it does."] = "고맙네, {name}. 묵힌 빚은 녹이 슨다고 무라딘 님이 그러셨지. 옜네."
L["Thank ye, {name}. Even me ram looked impressed, and he hates everybody."] = "고맙네, {name}. 세상만사 싫어하는 내 산양도 감탄하더군."
L["The Explorers' League'll ask where ye dug up such manners, {name}. Thanks!"] = "이런 매너는 어디서 발굴했나, {name}? 탐험가 연맹이 탐내겠구먼. 고맙네!"
L["Thank ye, {name}. Warmed me right down to me boots, that did."] = "고맙네, {name}. 장화 속 발끝까지 훈훈해졌구먼."
L["Mined half o' Khaz Modan, {name}. Never struck a vein that rich. Yer cut."] = "카즈 모단 절반을 캐 봤지만, {name}, 이런 노다지는 처음일세. 자네 몫이네."
L["Like a Kharanos hearth in a Dun Morogh blizzard, that, {name}. Thank ye."] = "던 모로 눈보라 속 카라노스 벽난로 같구먼, {name}. 고맙네."
L["Came back to ye like a Wildhammer's stormhammer, {name}. Less painful, mind."] = "와일드해머의 폭풍망치처럼 돌아왔네, {name}. 덜 아프긴 하지만."
L["Come to Ironforge, {name}. Me mam'll feed ye till ye can't stand. Thank ye!"] = "아이언포지에 한번 오게, {name}. 우리 어머니가 배 터지게 먹이실 걸세. 고맙네!"
L["Checked it fer gunpowder out o' habit, {name}. Clean as a whistle. Here's yers!"] = "버릇처럼 화약부터 확인했네, {name}. 깨끗하구먼. 자, 자네 몫일세!"
L["Thank ye, {name}. Ye'll be the talk o' the Great Forge tonight."] = "고맙네, {name}. 오늘 밤 대용광로는 자네 얘기로 떠들썩할 걸세."
L["Not even Magni could've done that kinder, {name}. Louder, aye. Thank ye."] = "마그니 님도 이보다 다정하진 못하셨을 걸세, {name}. 더 시끄럽긴 하셨겠지만. 고맙네."
L["Thank ye, {name}. I'd offer me beard as surety, but I'm terrible fond of it."] = "고맙네, {name}. 수염이라도 담보로 내주고 싶다만, 이게 영 아까워서."
L["Back at ye, {name}, quick as a ram goin' downhill. Stoppin' is the hard part."] = "바로 갚네, {name}. 내리막길 산양처럼 빠르게. 멈추는 게 어렵지."
L["Thank ye, {name}. Ye'd make a fine honorary dwarf. We'll work on yer singin'."] = "고맙네, {name}. 자넨 명예 드워프감일세. 노래 실력은 차차 다듬세."
L["Thank ye, {name}. If ye ever need a tunnel dug, I'm yer dwarf."] = "고맙네, {name}. 굴 팔 일 생기면 날 찾게. 그런 일엔 내가 적임자일세."
L["Keep yer powder dry and yer friends closer, me da said. Here, {name}."] = "화약은 마르게, 친구는 가까이. 우리 아버지 말씀일세. 옜네, {name}."
L["Aye, {name}, ye only had to ask. Hold still now, like a good anvil."] = "암, {name}, 말만 하면 되지. 모루처럼 가만있어 보게."
L["Say no more, {name}. Stone and steel, here it comes."] = "두말하면 잔소리지, {name}. 돌과 강철의 힘, 받게!"
L["Ask a dwarf fer help, {name}, and ye'll get it. Loudly."] = "드워프한테 도움을 청하면 받긴 받네, {name}. 시끄럽게."
L["Right, {name}. Brace yerself; I do everything like I'm swingin' a hammer."] = "좋아, {name}. 단단히 버티게. 난 뭘 하든 망치 휘두르듯 하니까."
L["Aye, {name}, and a story about it ye didn't ask fer. Where to begin..."] = "암, {name}. 덤으로 묻지도 않은 얘기까지 해 주지. 어디 보자..."
L["One {buff}, pulled fresh like a proper pint, {name}."] = "{name}, 갓 뽑은 생맥주처럼 시원한 {buff} 한 잔일세."
L["Done, {name}. Dwarven work: over-built, under-priced and guaranteed."] = "다 됐네, {name}. 드워프 솜씨라 쓸데없이 튼튼하고, 값싸고, 평생 보증일세."
L["Easy, {name}. Last time I helped a gnome, it cost me both eyebrows."] = "쉽지, {name}. 지난번에 노움을 도왔다가 눈썹을 둘 다 잃었다네."
L["Aye, {name}. Mountain kings never refuse. I'm more a foothill, but same rule."] = "암, {name}. 산악왕은 거절을 모르지. 난 동네 뒷산급이지만, 규칙은 같네."
L["Tempered and quenched, {name}. Mind, it's still hot."] = "담금질까지 끝냈네, {name}. 아직 뜨거우니 조심하게."
L["Done afore ye finished, {name}. Dwarves hear 'please' through solid rock."] = "말 끝나기 전에 다 됐네, {name}. 드워프는 '부탁'을 바위 너머로도 듣지."
L["Aye, {name}. In Dun Morogh ye help quick, or ye both freeze standin' there."] = "암, {name}. 던 모로에선 얼른 도와야 하네. 안 그럼 둘 다 선 채로 얼지."
L["Aye, {name}. Ye'll feel it in yer boots first. That's how ye know it's dwarven."] = "암, {name}. 발끝부터 찌릿할 걸세. 그게 드워프 솜씨란 증거지."
L["Aye, {name}. Say no, and ye'd ask a gnome, and then I'd feel responsible."] = "암, {name}. 거절하면 노움한테 부탁할 테고, 그럼 그게 다 내 책임 아닌가."
L["Course, {name}. A dwarf who won't help is no dwarf. Just a short, grumpy rock."] = "물론이지, {name}. 안 돕는 드워프는 드워프가 아닐세. 그냥 작고 심술궂은 돌덩이지."
L["Mountaineer's promise, {name}: done right, done once. Mostly."] = "산악대의 약속일세, {name}. 제대로, 한 번에. 대개는."
L["Fer you, {name}? Easy as findin' ale in Ironforge."] = "자네 부탁이라면야, {name}. 아이언포지에서 맥주 찾기만큼 쉽지."
L["Ask a Bronzebeard, {name}, and ye get it with both hands. Here."] = "브론즈비어드한테 청하면, {name}, 두 손으로 받는 걸세. 옜네."
L["Aye, {name}. Stand on that rock while I see to ye. Good rock, that. Granite."] = "그러지, {name}. 내가 챙겨 주는 동안 저 바위에 서 있게. 좋은 바위야. 화강암이지."
L["Aye, {name}. In the mines, ye shout and somebody comes runnin'. Here I am."] = "암, {name}. 광산에선 소리치면 누군가 달려오지. 내가 왔네."
L["Here, {name}, a wee somethin' to keep ye on yer feet. Wee, like me."] = "옜네, {name}. 버티라고 주는 쪼끄만 선물일세. 나처럼 쪼끄맣지."
L["Off ye go, {name}, with a wee blessin' from me. Steady as the mountain."] = "내 작은 축복을 받아 가게, {name}. 산처럼 든든하게!"
L["Here, {name}. Ale's for after; this is for before."] = "옜네, {name}. 맥주는 싸운 뒤에, 이건 싸우기 전에."
L["Magni'd melt down his crown fer a friend, {name}. This is the cheaper option."] = "마그니 님은 친구를 위해서라면 왕관도 녹이실 걸세, {name}. 이건 보급형일세."
L["A dwarf's got yer back, {name}. Well, yer knees. Close enough."] = "자네 등 뒤는 드워프가 지키네, {name}. 뭐, 무릎 뒤지만. 비슷하지."
L["Take this, {name}. If a trogg bothers ye, tell it a dwarf sent ye. Then run."] = "이거 받게, {name}. 트로그가 귀찮게 하면 드워프가 보냈다고 하게. 그리고 뛰고."
L["If it wears off, {name}, give it a good thump. That's how we fix everything."] = "효과가 떨어지면, {name}, 한 대 쾅 치게. 우린 뭐든 그렇게 고치지."
L["Take this, {name}. I'd give ye some stubbornness too, but I'm usin' all mine."] = "받게, {name}. 고집도 좀 나눠 주고 싶다만, 내 건 내가 다 쓰는 중일세."
L["That'll warm ye, {name}. Mind the wendigos: big, hairy and grumpy. Like me."] = "이거면 따뜻할 걸세, {name}. 웬디고 조심하게. 크고 털 많고 성질 나쁘지. 나처럼."
L["Take this, {name}. Me grandad fought three wars with a pickaxe and this."] = "받게, {name}. 우리 할아버지는 곡괭이랑 이것만으로 전쟁을 세 번 치르셨지."
L["Dwarven make, {name}. Drop it off Thandol Span and it'd still work. Don't."] = "드워프제일세, {name}. 탄돌 교각에서 떨어뜨려도 멀쩡하지. 해 보진 말게."
L["Stonewrought Dam holds back a whole loch, {name}. This'll hold ye together."] = "모단 호수를 통째로 막는 댐도 있지, {name}. 이건 자넬 단단히 붙들어 줄 걸세."
L["Won't keep yer boots dry in the Wetlands, {name}. Nothin' does. The rest, aye."] = "저습지에선 장화가 젖을 걸세, {name}. 그건 어쩔 수 없지. 나머진 막아 주네."
L["Old miner's rule, {name}: never go down a hole without a lamp, a mate and this."] = "광부의 철칙일세, {name}. 굴에 들 땐 등불, 동료, 그리고 이것."
L["Brann Bronzebeard went explorin' with less, {name}, and wrote three books."] = "브란 브론즈비어드는 이것도 없이 탐험 가서 책을 세 권 썼네, {name}."
L["Mountaineers swear by it, {name}. Ye'll climb no better, but land softer."] = "산악대가 애용하는 걸세, {name}. 더 잘 오르진 못해도, 떨어질 때 덜 아프지."
L["Ironforge's gates have never fallen, {name}. Neither should ye. Take this."] = "아이언포지 성문은 한 번도 무너진 적 없네, {name}. 자네도 그래야지. 받게."
L["Me cousins down Blackrock way would've set it alight first, {name}. Fer luck."] = "검은바위 산 사촌들이었으면 불부터 붙였을 걸세, {name}. 행운을 빈다고."
L["Off to Uldaman, {name}? Take this, and touch nothin' with runes on it."] = "울다만에 가나, {name}? 이거 받고, 룬 새겨진 건 아무것도 만지지 말게."
L["Fer the road, {name}. It's no keg o' Thunderbrew, but it travels better."] = "가는 길에 쓰게, {name}. 썬더브루 한 통만은 못해도 들고 다니긴 낫지."
L["A gift from under the mountain, {name}. Mind yer head on the way out."] = "산 아래에서 온 선물일세, {name}. 나갈 때 머리 조심하게."
L["A rifleman needs dry powder and a good mate, {name}. I'm the mate. Here."] = "소총수한텐 마른 화약과 좋은 동료가 필요하지, {name}. 동료는 날세. 옜네."
L["If yer road passes Grim Batol, {name}, keep walkin'. And take this."] = "가는 길에 그림 바톨이 있거든, {name}, 그냥 지나가게. 이것도 받고."
L["From one explorer to another, {name}. The League'll want yer notes after."] = "탐험가끼리 주는 걸세, {name}. 나중에 연맹이 자네 기록을 탐낼 걸세."
L["If ye ride a gryphon, {name}, hold on with yer knees and yer prayers. Here."] = "그리핀을 타거든, {name}, 무릎과 기도로 꽉 붙들게. 옜네."
L["A dwarf never lets a friend walk into the dark unready, {name}. Take this."] = "드워프는 친구를 채비도 없이 어둠에 보내지 않네, {name}. 받게."
L["Stone and hammer keep ye, cousin {name}!"] = "돌과 망치가 자넬 지켜 주길, 사촌 {name}!"
L["Three Hammers, one round, and this one's on me, cousin {name}!"] = "세 망치에 한 잔씩, 이번 건 내가 쏘지, 사촌 {name}!"
L["Yer cousin's cousin wed mine, {name}, I'd wager. Family gets the good stuff."] = "자네 사촌의 사촌이 내 쪽이랑 혼인했을 걸세, {name}. 가족한텐 좋은 걸 줘야지."
L["Two dwarves, and one of us freshly blessed, {name}. Pity whatever's in our way."] = "드워프 둘에, 하나는 갓 축복받았지, {name}. 앞을 막는 놈이 불쌍하구먼."
L["Bronzebeard, Wildhammer, Dark Iron, Earthen, {name}: one family. Here, cousin."] = "청동수염, 와일드해머, 검은무쇠, 대지인, {name}: 다 한 가족이지. 받게, 사촌."
L["Here, {name}. Between the pair of us now, we could out-stubborn a mountain."] = "받게, {name}. 이제 우리 둘이면 산보다 고집이 세겠구먼."
L["Me grandmother'd climb out of her tomb if I did any less fer kin, {name}."] = "동족한테 이만큼도 안 했다간, {name}, 할머니가 무덤에서 뛰쳐나오실 걸세."
L["The Titans carved us from the same rock, {name}, so here's a chip off mine."] = "티탄이 우릴 같은 바위로 깎았지, {name}. 그러니 내 바위 한 조각 받게."
L["Kin's kin, {name}, far from the mountain or under it. This is how we mind ours."] = "혈족은 혈족이지, {name}. 산 밖이든 산 아래든. 우린 이렇게 우리 편을 챙기네."
L["There, {name}, that'll see ye through. Stand behind me. Aye, I know. Crouch."] = "됐네, {name}, 이거면 버틸 걸세. 내 뒤에 서게. 그래, 알아. 좀 숙이게."
L["Right, {name}: ye get this, I take the front, and we argue about loot after."] = "좋아, {name}. 자넨 이걸 받고, 난 앞장서고, 전리품 싸움은 나중에 하세."
L["Here, {name}. If I sing after this, the fight's gone well. Or very badly."] = "받게, {name}. 이다음에 내가 노래하면 싸움이 잘 된 거고. 아니면 아주 망한 거고."
L["Dwarves never leave a mate behind, {name}, nor without a blessin'. Nor a keg."] = "드워프는 동료를 절대 두고 안 가네, {name}. 축복 없이도 안 보내지. 술통도 마찬가지고."
L["There, {name}. Beards out! Them without beards, look fierce. This helps."] = "됐네, {name}. 수염 내밀어! 수염 없는 친군 사나운 표정이라도. 이게 도움이 될 걸세."
L["Knocked on the nearest rock fer luck, {name}, and put the luck on ye. Solid."] = "행운 빌려고 바위를 두드렸지, {name}. 그 행운을 자네한테 얹었네. 단단하구먼."
L["Here, {name}, from me pack. It's mostly gunpowder in there. And a sandwich."] = "받게, {name}, 내 배낭에서 꺼낸 걸세. 거의 화약이야. 샌드위치 하나랑."
L["That'll hold ye, {name}. Dwarves don't retreat. Our legs aren't built fer it."] = "이거면 버틸 걸세, {name}. 드워프는 후퇴 안 하네. 다리가 그렇게 안 생겼거든."
L["Take this, stay close, {name}. If it goes dark, follow the cursin'. That's me."] = "이거 받고 붙어 있게, {name}. 어두워지면 욕설 나는 쪽으로 오게. 그게 나야."
L["Ye're sorted, {name}. Dwarves always know which way is down. Up's yer problem."] = "자넨 챙겨 줬네, {name}. 드워프는 늘 아래가 어딘지 알지. 위는 자네 몫이고."
L["Here, {name}. Anythin' o' stone, let me talk to it first. Might be a cousin."] = "받게, {name}. 돌로 된 건 뭐든 내가 먼저 말 걸어 보지. 사촌일지도 모르니."
L["There, {name}, that'll take a knock. If the ceilin' creaks, I'll tell ye."] = "됐네, {name}, 한 대쯤은 버틸 걸세. 천장이 삐걱대면 말해 주지."
L["There, {name}, some mountain fer ye. I'll hold the line. Mountains don't move."] = "됐네, {name}, 산의 기운 좀 나눠 줬지. 전열은 내가 지키네. 산은 안 움직이거든."
L["That'll stiffen yer ankles, {name}. Troggs go fer ankles. Mine, mostly."] = "이거면 발목이 튼튼해질 걸세, {name}. 트로그는 발목을 노리거든. 주로 내 발목을."
L["There, {name}, fer the low beams. Says the only one here who never needs it."] = "됐네, {name}, 낮은 들보 대비용일세. 그럴 일 없는 유일한 몸이 하는 말이지만."
L["A hammer, a grudge, a good breakfast, and this fer ye, {name}. We'll be fine."] = "망치 하나, 원한 하나, 든든한 아침밥, 그리고 이제 자네 몫도, {name}. 괜찮을 걸세."
L["Ironforge's carvers never quit halfway, {name}. Nor does a dwarf's blessin'."] = "아이언포지 석공들은 절대 중간에 안 멈췄지, {name}. 드워프의 축복도 마찬가지일세."
L["Keep up, {name}! There's a spring in yer step now. Short legs; we never stop."] = "따라오게, {name}! 이제 발걸음이 가볍지. 다리는 짧아도 우린 안 멈추네."
L["Mornin', {name}! Too early for ale. Almost. Have this first."] = "좋은 아침일세, {name}! 맥주엔 아직 이르지. 거의. 이거부터 받게."
L["Up with the forge fires, {name}! A dwarf's day starts with a hammer and this."] = "화로와 함께 기상일세, {name}! 드워프의 하루는 망치와 이걸로 시작하지."
L["Early, {name}? Nonsense. The mine's been open two hours. Here."] = "이르다고, {name}? 무슨 소리. 광산은 두 시간 전에 열었네. 옜네."
L["Mornin', {name}. Me eyes are still abed, but me hands knew to give ye this."] = "좋은 아침일세, {name}. 눈은 아직 이불 속인데, 손은 이걸 줄 줄 알더구먼."
L["Mornin', {name}. Porridge, a pipe and this. The other two are mine."] = "좋은 아침일세, {name}. 죽, 파이프, 그리고 이것. 앞의 둘은 내 걸세."
L["The rams had me up at dawn, {name}. Headbutted the door till I came out. Here."] = "산양 놈들이 새벽부터 깨웠네, {name}. 나올 때까지 문을 들이받더군. 옜네."
L["Mornin', {name}. Ears still ringin' from last night's singin'. Here."] = "좋은 아침일세, {name}. 어젯밤 노래판 때문에 아직 귀가 울리네. 옜네."
L["Steady, {name}. Ye've a better nose than any dwarf in Ironforge."] = "진정해, {name}. 아이언포지 드워프 누구보다 코가 좋구먼."
L["That's the spot, {name}. Ye've earned a scratch, and a share o' me jerky."] = "거기 맞지, {name}? 쓰다듬어 줄 만하지. 육포도 좀 나눠 주마."
L["Easy now, {name}. The road's long, but we've stout hearts between us."] = "천천히, {name}. 길은 멀지만 우리 둘은 배짱이 두둑하잖나."
L["Well fought, {name}! Ye've the heart of a mountain, so ye have."] = "잘 싸웠다, {name}! 네 심장은 산처럼 단단하구먼."
L["Ha! Grand work, {name}. I'll tell it at the Thunderbrew with ye in it."] = "하! 잘했다, {name}. 천둥맥주 양조장에서 네 얘기를 해 주마."
L["That's me partner! Fine work, {name}. Not a trogg could've stood it."] = "역시 내 짝이야! 잘했다, {name}. 트로그는 못 버텼을걸."
L["Easy, {name}, easy. I've got ye. Rest a while."] = "진정해, {name}, 진정해. 내가 있잖나. 좀 쉬어라."
L["There now, {name}. Ye're tougher than granite, but rest anyway."] = "자, {name}. 화강암보다 단단해도, 그래도 좀 쉬어라."
L["Shh, {name}. Nothin' gets past me while ye catch yer breath."] = "쉿, {name}. 네가 숨 돌리는 동안 아무것도 못 지나간다."
L["My thanks, {name}. Let me return the kindness before a bard gets it wrong."] = "고맙소, {name}. 음유시인이 멋대로 지어내기 전에 내가 먼저 갚으리다."
L["Kindly done, {name}. Let no one say we forget a friend."] = "친절에 감사하오, {name}. 우린 친구를 잊지 않는다오."
L["Thank you, {name}. I'd knight you, but apparently I 'need permission'."] = "고맙소, {name}. 기사 작위라도 주고 싶지만, '허가가 필요하다'는구려."
L["Repaid on the spot, {name}. In Stormwind that'd take three forms and a stamp."] = "즉석에서 갚았소, {name}. 스톰윈드였다면 서류 세 장에 도장까지 필요했을 거요."
L["Thanks, {name}. Prompter than Stormwind ever paid its stonemasons."] = "고맙소, {name}. 스톰윈드가 석공들에게 갚은 것보다 빠르구려."
L["Much obliged, {name}. Mother said always return a kindness. And the dish."] = "신세 졌소, {name}. 어머니께서 그릇은 빈 채로 돌려주는 게 아니라 하셨소."
L["Thank you, {name}. In Elwynn, no kindness goes home unanswered."] = "고맙소, {name}. 엘윈 숲에선 받은 친절을 그냥 보내지 않소."
L["You shame me, {name}; I should have thought of it first. Allow me."] = "부끄럽구려, {name}. 내가 먼저 했어야 하는데. 이제라도 갚으리다."
L["Heartier than Westfall Stew, {name}, and I've wept over that stew. Thank you."] = "서부 몰락지대 스튜보다 든든하구려, {name}. 그 스튜에 울어 본 몸이오."
L["Thank you, {name}. I'll tell Marshal Dughan. He won't care, but I'll tell him."] = "고맙소, {name}. 듀간 원수께 보고하리다. 관심 없으시겠지만, 보고는 하리다."
L["Job's done, {name}! My grandad built half of Stormwind saying that. Thanks."] = "작업 완료, {name}! 할아버지가 이 말로 스톰윈드 절반을 지으셨소. 고맙소."
L["Lakeshire will finish its bridge before I forget this, {name}. So, never."] = "레이크샤이어 다리가 완공돼야 이걸 잊겠소, {name}. 그러니 영영 못 잊소."
L["Kul Tirans say a kindness goes back on the next tide, {name}. There it goes."] = "쿨 티라스에선 친절은 다음 물때에 돌려보낸다오, {name}. 자, 보내오."
L["Thank you, {name}. Northshire's brothers would call that the Light at work."] = "고맙소, {name}. 북녘골 수도사들이라면 빛의 역사라 하겠소."
L["Not since Mum packed my lunches, {name}, have I felt so looked after. Thanks."] = "어머니가 도시락 싸 주시던 때 이후로, {name}, 이런 챙김은 처음이오. 고맙소."
L["Into my memoirs, {name}. Chapter nine: 'Everyone Was Lovely'. Thank you."] = "회고록에 넣으리다, {name}. 9장: '모두가 다정했다'. 고맙소."
L["I'll toast you at the Pig and Whistle, {name}. Then the pig. Then the whistle."] = "돼지와 휘파람 선술집에서 건배하리다, {name}. 다음은 돼지, 그다음은 휘파람."
L["Thanks, {name}. My next horse gets your name. He'll be a very good horse."] = "고맙소, {name}. 다음 말에 그대 이름을 붙이리다. 아주 좋은 말이 될 거요."
L["I owe you a pint at the Lion's Pride, {name}. This will tide you over."] = "골드샤이어 여관에서 한잔 빚졌소, {name}. 그때까진 이걸로 버티시오."
L["Much obliged, {name}. In Elwynn that's neighbourly. Out here, it's heroic."] = "신세 졌소, {name}. 엘윈 숲에선 이웃의 정이지만, 여기선 영웅적인 일이오."
L["Thanks, {name}. We humans don't live long enough to leave a kindness waiting."] = "고맙소, {name}. 인간은 친절을 묵혀 둘 만큼 오래 살지 못하오."
L["Thanks, {name}. If the Stockade held folk for kindness, you'd be in for life."] = "고맙소, {name}. 친절도 죄라면 그대는 지하감옥 종신형이오."
L["By the Light, {name}, that was good of you. Uther would have liked you."] = "빛에 맹세코, {name}, 참 고마운 일이오. 우서 경도 그대를 좋아했을 거요."
L["Darkshire could use folk like you, {name}. Your kindness, returned."] = "다크샤이어엔 당신 같은 사람이 필요하지요, {name}. 베푼 친절, 돌려드리지요."
L["Of course, {name}. Hold still and look heroic; it helps the bards."] = "물론이오, {name}. 가만히, 영웅다운 표정으로. 음유시인들이 좋아하오."
L["Right away, {name}. Keep your shield high."] = "당장 하리다, {name}. 방패를 높이 드시오."
L["More work? Gladly, {name}. It beats the lumber mill."] = "일감이오? 기꺼이, {name}. 제재소보단 낫소."
L["Of course, {name}. Humans excel at helping and overpromising. This is helping."] = "물론이오, {name}. 인간은 돕기와 큰소리치기에 능하오. 이건 돕는 쪽이오."
L["Certainly, {name}. Westfall farm manners: you help first and ask why later."] = "그러리다, {name}. 서부 몰락지대 농가 예절이오. 돕는 게 먼저, 이유는 나중."
L["Hold still, {name}, like a statue in the Valley of Heroes. You'd fit right in."] = "가만히 계시오, {name}. 영웅의 골짜기 석상처럼. 딱 어울리겠소."
L["Right away, {name}. The Light helps those who ask. So do I, and I'm quicker."] = "당장 하리다, {name}. 빛은 구하는 자를 돕소. 나도 돕소. 더 빨리."
L["Sailors' rule, {name}: somebody calls for help, you row. Here."] = "뱃사람 규칙이오, {name}. 누가 도와 달라 하면, 노를 젓는 거요. 받으시오."
L["Of course, {name}. Stand up straight; my old sergeant is watching, somewhere."] = "물론이오, {name}. 허리 펴시오. 옛 교관님이 어디선가 지켜보고 계시니."
L["Of course, {name}. A polite request is rarer than a quiet night in Duskwood."] = "물론이오, {name}. 공손한 부탁은 그늘숲의 조용한 밤보다 귀하오."
L["Right away, {name}. I'll play the Archbishop; you pretend to be impressed."] = "당장 하리다, {name}. 난 대주교 흉내를 낼 테니, 감동한 척해 주시오."
L["Stormwind rose from rubble, {name}. I can manage one {buff}."] = "스톰윈드도 잿더미에서 다시 섰소, {name}. {buff} 하나쯤이야."
L["Of course, {name}. Last one I did was a Westfall scarecrow. Long story."] = "물론이오, {name}. 지난번엔 서부 몰락지대 허수아비에게 해 줬소. 긴 얘기요."
L["Aye, {name}. Kul Tiran terms: a handshake, and I spare you the shanty."] = "좋소, {name}. 쿨 티라스식 조건이오. 악수 한 번이면 뱃노래는 봐 드리지."
L["Right away, {name}. Bolvar says the realm runs on small kindnesses."] = "당장 하리다, {name}. 볼바르 경 말씀이, 왕국은 작은 친절로 굴러간다 하셨소."
L["Gladly, {name}. Elwynn folk never turn away a neighbour, armour and all."] = "기꺼이, {name}. 엘윈 사람은 갑옷 입은 이웃도 마다하지 않소."
L["Of course, {name}. The Light provides. Today it's using me as the courier."] = "물론이오, {name}. 빛께서 베푸시오. 오늘은 내가 배달부일 뿐."
L["Of course, {name}. Stormwind raised me on the Light, porridge and saying yes."] = "물론이오, {name}. 난 스톰윈드에서 빛과 죽과 '그러지요'로 자랐소."
L["Right away, {name}. At Northshire we answered before the second bell."] = "당장 하리다, {name}. 북녘골에선 두 번째 종이 울리기 전에 답했소."
L["The road ahead is long, {name}. This won't shorten it, but it'll help."] = "갈 길이 멀다오, {name}. 길을 줄여 주진 못해도 도움은 될 거요."
L["Fair winds and following seas, {name}, and this to carry you along."] = "순풍과 잔잔한 바다가 함께하길, {name}. 이것도 가져가시오."
L["Take this, {name}. Elves have centuries to be generous; I've got fifty years."] = "받으시오, {name}. 엘프는 수백 년간 베풀면 되지만, 난 한 오십 년뿐이오."
L["A little something, {name}. Don't tell the guards; they'll all want one."] = "작은 선물이오, {name}. 경비병들한텐 비밀이오. 다들 달라고 할 테니."
L["Here, {name}. If a kobold asks, you don't have a candle."] = "받으시오, {name}. 코볼트가 물으면, 양초는 없다고 하시오."
L["For you, {name}. A human gift: well meant, hastily made, surprisingly sturdy."] = "받으시오, {name}. 인간식 선물이오. 뜻은 좋고, 급히 만들었고, 의외로 튼튼하오."
L["Mind the murlocs, {name}. Take this; I've seen what they do to a picnic."] = "멀록 조심하시오, {name}. 받으시오. 놈들이 소풍을 어떻게 망치는지 봤소."
L["Every road needs a hero, {name}. Today it's me, apparently. Take this."] = "모든 길엔 영웅이 필요하오, {name}. 오늘은 나인가 보오. 받으시오."
L["Stay out of Duskwood after dark, {name}. It's always dark. Take this."] = "해 지면 그늘숲엔 가지 마시오, {name}. 거긴 늘 해가 져 있소. 받으시오."
L["Redridge gnolls take anything not nailed down, {name}. This is nailed down."] = "붉은마루 놀은 못 박히지 않은 건 다 가져가오, {name}. 이건 못 박아 뒀소."
L["If you meet Hogger, {name}, take this and a friend. Mostly the friend."] = "들창코를 만나거든, {name}, 이것과 친구를 챙기시오. 주로 친구를."
L["The Light and a good pair of boots, {name}. Now you've got one of them."] = "빛과 튼튼한 장화면 된다오, {name}. 이제 그중 하나는 갖췄소."
L["Every hero in Stormwind began with a kindness and a borrowed sword, {name}."] = "스톰윈드 영웅은 다 친절 하나와 빌린 검 한 자루로 시작했소, {name}."
L["Here, {name}. The Defias can't steal this one. They've tried everything else."] = "받으시오, {name}. 데피아즈단도 이건 못 훔치오. 다른 건 다 훔쳐 봤지만."
L["Uther blessed strangers on the road, {name}. I've less hammer, same idea."] = "우서 경은 길 가는 낯선 이도 축복했소, {name}. 망치는 작아도 뜻은 같소."
L["Take this, {name}. Goldshire custom: no traveller leaves empty-handed."] = "받으시오, {name}. 골드샤이어 풍습이오. 나그네를 빈손으로 보내지 않소."
L["The wolves in Elwynn look friendly, {name}. They are not. Take this."] = "엘윈 숲 늑대는 순해 보이오, {name}. 안 순하오. 받으시오."
L["Lothar held the line with less, {name}. Granted, he had a very big sword."] = "로타르 경은 이보다 적은 걸로 전선을 지켰소, {name}. 검이 아주 크긴 했지만."
L["Westfall farmers share even in a bad year, {name}. So here's my share."] = "서부 몰락지대 농부들은 흉년에도 나누지요, {name}. 그러니 이건 제 몫입니다."
L["Redridge, Duskwood, Westfall, {name}: worse roads every mile. Take this."] = "붉은마루, 그늘숲, 서부 몰락지대, {name}. 엘윈을 벗어날수록 험해지죠. 이걸 받으시오."
L["Take this, {name}. The guards can't be everywhere. Out here, they're nowhere."] = "받으시오, {name}. 경비병이 어디에나 있을 순 없소. 여긴 아예 없고."
L["Bound for Hillsbrad, {name}? Southshore's still ours. Barely. Take this."] = "힐스브래드로 가시오, {name}? 사우스쇼어는 아직 우리 땅이오. 간신히. 받으시오."
L["Stromgarde still stands, {name}, mostly out of stubbornness. So will you. Here."] = "스트롬가드는 아직 서 있소, {name}. 거의 고집으로. 그대도 그럴 거요. 받으시오."
L["A Stormwind welcome, {name}: a smile, a blessing and the way to the inn."] = "스톰윈드식 환영이오, {name}. 미소, 축복, 그리고 여관 가는 길."
L["The Argent Dawn says the Light is for all who'll carry it, {name}. Carry some."] = "은빛 여명회 말로는 빛은 짊어질 이 모두의 것이오, {name}. 조금 짊어지시오."
L["Arathor's children stand together, {name}, and share what strength they have."] = "아라소르의 후손은 함께 서고, {name}, 가진 힘을 나누지요."
L["A fellow human, {name}! Take this. Then let's found a kingdom before lunch."] = "같은 인간이군요, {name}! 이걸 받으시오. 그리고 점심 전에 왕국 하나 세웁시다."
L["Stormwind or Boralus, {name}, we'll both moan about the weather. This helps."] = "스톰윈드든 보랄러스든, {name}, 둘 다 날씨 불평은 하겠지요. 이게 좀 도움이 될 거요."
L["Human to human, {name}: everything happens to us, so here's a little help."] = "인간 대 인간으로, {name}. 우리한텐 별일이 다 생기니, 이거라도 보태 드리지요."
L["Short lives, long to-do lists, {name}. We humans must help each other along."] = "수명은 짧고 할 일은 많소, {name}. 우리 인간끼린 서로 도와야지."
L["Stormwind stone or Kul Tiran oak, {name}, this will help you outlast them all."] = "스톰윈드의 돌이든 쿨 티라스의 참나무든, {name}, 이거면 누구보다 오래 버티실 거요."
L["Humans stick together, {name}, so take this. The rest are taller or furrier."] = "인간끼린 뭉쳐야지요, {name}, 그러니 받으시오. 다른 종족은 다 크거나 털이 많잖소."
L["We built half the world on bread, stubbornness and favours like this, {name}."] = "우리 인간은 빵과 고집, 그리고 이런 호의로 세상 절반을 세웠지요, {name}."
L["Don't tell the dwarves, {name}: humans invented the tavern. And this round."] = "드워프한텐 비밀이오, {name}. 선술집은 우리 인간이 만들었소. 이번 잔도 내가 내지요."
L["There, {name}. Humans have always won by outnumbering things, and by sharing."] = "됐소, {name}. 인간은 늘 머릿수로, 그리고 나눔으로 이겨 왔지요."
L["You're ready, {name}. Stay in formation. We haven't got one, but stay in it."] = "준비 끝났소, {name}. 대형 유지하시오. 대형은 없지만, 그래도 유지하시오."
L["Here, {name}. I'll draw up a plan too, and we can all ignore it together."] = "받으시오, {name}. 계획도 하나 짜 두지요. 그리고 다 같이 무시합시다."
L["Every hero in the songs had friends who did this, {name}. I'll be yours."] = "노래 속 영웅들에겐 이렇게 챙겨 주는 친구가 있었지요, {name}. 내가 그 친구 하리다."
L["There, {name}. Stormwind taught me to march and to mind who marches with me."] = "됐소, {name}. 스톰윈드는 행군하는 법과 함께 걷는 이를 챙기는 법을 가르쳤지요."
L["That should keep us safe, {name}. If not, we regroup at the nearest inn."] = "이거면 탈은 없을 거요, {name}. 아니면 제일 가까운 여관에서 다시 모입시다."
L["I made us a flag, {name}, and you a blessing. The flag's a hankie on a stick."] = "깃발 하나 만들었소, {name}. 당신껜 축복을 드렸고. 깃발은 막대에 꽂은 손수건이지만."
L["A light of your own, {name}. Humans can't see in the dark, and we hate it."] = "받으시오, {name}, 당신만의 작은 빛이오. 인간은 어둠 속에서 못 보는데, 그게 질색이오."
L["That's for your back, {name}; I'll watch it too. The Light has the rest."] = "이건 당신 등 뒤를 위한 거요, {name}. 나도 지켜보리다. 나머진 빛이 맡을 거요."
L["There, {name}. Humans rise to the occasion, and this should stop the tripping."] = "됐소, {name}. 인간은 늘 고비에 강하지요. 이거면 발이 걸려 넘어질 일도 없을 거요."
L["Your share, {name}. Do this well; some elf will tell the story for an age."] = "당신 몫이오, {name}. 잘해 봅시다. 어느 엘프가 이 이야기를 천 년은 떠들 테니."
L["Farmers, sailors, bakers, {name}: every army Stormwind raised got one of these."] = "농부, 선원, 제빵사, {name}. 스톰윈드가 모은 군대는 다 이걸 하나씩 받았지요."
L["Form up, {name}, and take this. One steady line beats a crowd of brave fools."] = "대열 맞추시오, {name}, 그리고 이걸 받으시오. 굳건한 한 줄이 용감한 바보 무리를 이기지요."
L["We'll make Stormwind proud, {name}. This should keep the town criers kind."] = "스톰윈드를 자랑스럽게 합시다, {name}. 이거면 포고꾼들도 좋게 떠들 거요."
L["The Light keeps us, {name}. Here's some for you. I've packed bandages too."] = "빛이 우릴 지키지요, {name}. 여기 당신 몫의 빛이오. 붕대도 챙겨 왔소."
L["Take this, {name}. Everyone goes home; I promised somebody's mother. Yours."] = "다들 집에 돌아가는 거요, {name}, 그러니 받으시오. 누군가의 어머니께 약속했거든. 아마 당신 어머니."
L["We look like a proper Stormwind patrol now, {name}. Shinier, even."] = "이제 제대로 된 스톰윈드 순찰대 같구려, {name}. 더 번쩍이기까지 하오."
L["Stay sharp, {name}, this'll help. Lordaeron learned: never trust the bread."] = "정신 바짝 차리시오, {name}. 이게 도움이 될 거요. 로데론은 뼈저리게 배웠지요. 빵은 믿지 말라고."
L["Easy there, {name}. Stormwind's finest couldn't ask for better company."] = "진정해, {name}. 스톰윈드에도 너만 한 동료는 없어."
L["Good to have you at my side, {name}. Truly."] = "네가 곁에 있어서 좋아, {name}. 정말로."
L["Who's the best hunting partner in the Eastern Kingdoms? You are, {name}."] = "동부 왕국 최고의 사냥 동료가 누구지? 바로 너야, {name}."
L["Well done, {name}! The Light itself couldn't have timed that better."] = "잘했어, {name}! 빛도 이보다 때를 잘 맞추진 못해."
L["That's how it's done, {name}. I'd put you up against any knight."] = "바로 그거야, {name}. 어느 기사와 붙여도 자신 있어."
L["Brilliant, {name}. You turned that fight before I'd drawn twice."] = "훌륭해, {name}. 내가 두 번 쏘기도 전에 판을 뒤집었어."
L["Easy, {name}. I'm here. Lie still and let me look at you."] = "진정해, {name}. 내가 여기 있어. 가만히 있어, 좀 보자."
L["You're all right, {name}. I've got you. Breathe."] = "괜찮아, {name}. 내가 있어. 숨 쉬어."
L["Steady, {name}. Rest now; I'll keep watch for both of us."] = "진정해, {name}. 이제 쉬어. 우리 둘 몫은 내가 지킬게."
L["Ishnu-alah, {name}. Returned the same day, which for a kaldorei is rushing."] = "이슈누 알라, {name}. 당일에 갚다니, 칼도레이로선 서두른 셈이오."
L["Thank you, {name}. Elune smiles on the generous."] = "감사하오, {name}. 엘룬께선 베푸는 이에게 미소 지으신다오."
L["Thank you, {name}. Even the wisps glow brighter, and they're hard to impress."] = "감사하오, {name}. 좀처럼 감동 않는 위습들마저 더 밝게 빛나는구려."
L["Elune saw that, {name}. She sees everything, so I had best return it."] = "엘룬께서 보셨소, {name}. 다 보시는 분이니, 얼른 갚아야겠소."
L["Thank you, {name}. Kindness planted, kindness grown. Here."] = "감사하오, {name}. 심은 친절이 자라 열매를 맺었구려. 받으시오."
L["Thank you, {name}. The Ancients will hear of this. They're dreadful gossips."] = "감사하오, {name}. 고대정령들 귀에도 들어갈 거요. 소문을 워낙 좋아해서."
L["Thank you, {name}. I'll tell the Sentinels to stop aiming at you."] = "감사하오, {name}. 파수대에 그대를 그만 겨누라 일러 두리다."
L["My people never hurry, {name}. For you, an exception."] = "우리 종족은 서두르는 법이 없소, {name}. 그대만은 예외요."
L["Ande'thoras-ethil, {name}. May your troubles be diminished, as mine just were."] = "안데소라스 에실, {name}. 그대의 근심도 덜어지기를. 방금 내 근심이 덜어졌듯."
L["We gave up immortality at Hyjal, {name}. Kindness has been worth double since."] = "하이잘에서 불멸을 내려놓았소, {name}. 그 뒤로 친절의 값이 곱절이 되었지."
L["Thank you, {name}. My ears went a shade darker. Kaldorei blush there first."] = "고마워요, {name}. 귀가 한층 짙어졌네요. 칼도레이는 귀부터 붉어지거든요."
L["Azshara's court never gave a thing away, {name}. You've outdone a queen."] = "아즈샤라의 궁정도 거저 준 건 없었소, {name}. 그대가 여왕보다 낫구려."
L["The owls turned their heads for that, {name}. All the way round. High praise."] = "부엉이들이 고개를 돌렸소, {name}. 한 바퀴 다. 최고의 찬사요."
L["I outlived the Sundering, {name}. I'll not outlive a debt to you. Here."] = "세계가 쪼개질 때도 버텼지만, {name}, 그대에게 진 빚은 못 버티겠소."
L["All those centuries of memories, {name}, and this one goes near the front."] = "수천 년 치 기억 가운데서도, {name}, 이건 맨 앞줄에 두리다."
L["I'll tell the moon about you tonight, {name}. She likes a good story."] = "오늘 밤 달에게 그대 얘기를 하리다, {name}. 좋은 이야기를 좋아하시니."
L["In Darnassus they'd sing of that, {name}. Quietly, for about a century."] = "다르나서스였다면 노래로 남았을 거요, {name}. 조용히, 한 백 년쯤."
L["Thank you, {name}. A Sentinel settles a debt of honour by moonset. So do I."] = "감사하오, {name}. 파수병은 달이 지기 전에 명예의 빚을 갚소. 나도 그렇소."
L["Shan'do Stormrage would approve, {name}. He'll tell you himself, when he wakes."] = "스톰레이지 샨도께서도 흡족해하실 거요, {name}. 깨어나시면 직접 말씀하시겠지."
L["The Cenarion Circle preaches balance, {name}. You've just tipped it my way."] = "세나리온 의회는 균형을 설파하오, {name}. 그대가 방금 내 쪽으로 기울였구려."
L["Better than a moonwell, {name}. Don't tell the priestesses I said so."] = "달의 샘보다 낫구려, {name}. 여사제들에겐 비밀이오."
L["Even Fandral would smile at that, {name}, and his face has forgotten how."] = "판드랄도 미소 지었을 거요, {name}. 웃는 법을 잊은 얼굴인데도."
L["Thank you, {name}. I'd send a hippogryph with my thanks, but they bite."] = "감사하오, {name}. 히포그리프 편에 감사를 전하고 싶지만, 그놈들은 물어서."
L["That warms me like moonlight, {name}. Not very warm, I admit. Still, thank you."] = "달빛처럼 따스하구려, {name}. 그리 따스하진 않다만. 그래도 감사하오."
L["Gladly, {name}. Be still, and let the moonlight find you."] = "기꺼이, {name}. 가만히, 달빛이 그대에게 닿도록."
L["Of course, {name}. Elune's blessings are meant to be shared."] = "물론이지요, {name}. 엘룬의 축복은 나누라고 있는 것이니."
L["At last, {name}! I've waited ten thousand years for someone to ask."] = "드디어, {name}! 누가 청해 주길 만 년이나 기다렸소."
L["No riddle, no omen from Elune, {name}. Just a plain yes, for once."] = "수수께끼도, 엘룬의 계시도 없소, {name}. 이번만은 그저 '그러겠소'."
L["Of course, {name}. Ask in Darnassian next time and I'll add a bow."] = "물론이오, {name}. 다음엔 다르나서스어로 청하면 절까지 해 드리리다."
L["Elune already said yes, {name}. I'm merely catching up."] = "엘룬께선 이미 허락하셨소, {name}. 난 뒤따를 뿐이오."
L["Of course, {name}. Stand still and pretend you're a tree. It helps."] = "물론이오, {name}. 가만히, 나무인 척하시오. 도움이 되오."
L["Step into the light, {name}. The last kaldorei I did this for Shadowmelded."] = "밝은 데로 오시오, {name}. 지난번 칼도레이는 그림자 숨기를 써 버렸소."
L["Certainly, {name}. Ask a kaldorei anything, except how old we are."] = "물론이오, {name}. 칼도레이에게 뭐든 물어도 좋소. 나이만 빼고."
L["In Darnassus, {name}, this takes a moonwell and a priestess. Out here, just me."] = "다르나서스에선, {name}, 달의 샘과 여사제가 필요하오. 여기선 나면 되오."
L["The last army to ask me for help was fighting demons, {name}. You're politer."] = "지난번엔 악마와 싸우던 군대가 청했소, {name}. 그대가 더 공손하구려."
L["Gladly, {name}. Consider it on loan from Elune. She's never once collected."] = "기꺼이, {name}. 엘룬께 빌린 셈 치시오. 한 번도 받아 가신 적은 없소."
L["Of course, {name}. One moment; my hair is older than kingdoms, and it tangles."] = "물론이죠, {name}. 잠깐만요. 제 머리카락은 왕국보다 오래돼서 자꾸 엉키거든요."
L["Darnassian has nine words for 'yes', {name}. I'll spare you eight of them."] = "다르나서스어엔 '예'가 아홉 가지요, {name}. 여덟은 생략하리다."
L["Of course, {name}. The Sentinels would want a password. I'll accept 'please'."] = "물론이오, {name}. 파수대라면 암호를 물었겠지만, 난 '부탁하오'면 되오."
L["Of course, {name}. I'll be swift. Swift for a kaldorei, that is. Do sit down."] = "물론이오, {name}. 서두르리다. 칼도레이 기준으로. 앉아 계시오."
L["Gladly, {name}. The Sentinels taught me to answer a call before it echoes."] = "기꺼이, {name}. 파수대에서 메아리가 울리기 전에 답하라 배웠소."
L["Be still, {name}. What's done in haste is undone by nightfall, the druids say."] = "가만히 계시오, {name}. 서둘러 한 일은 해 질 녘에 풀린다고 드루이드들이 그러오."
L["Gladly, {name}. Elune asks little of us: kindness, patience and good aim."] = "기꺼이, {name}. 엘룬께선 많이 바라지 않으시오. 친절, 인내, 그리고 정확한 조준."
L["Of course, {name}. The forest gave me plenty. It would sulk if I didn't share."] = "물론이오, {name}. 숲이 넉넉히 주었으니, 안 나누면 숲이 삐칠 거요."
L["Elune-adore, {name}. Her light goes with you. Walk softly; trees sleep lightly."] = "엘룬 아도르, {name}. 그분의 빛이 함께하길. 살살 걸어요. 나무들은 잠귀가 밝거든요."
L["May the forest shelter you, {name}, wherever you roam."] = "{name}, 어디를 가든 숲이 그대를 품어 주기를."
L["A gift from the shadows, {name}. No, don't look. You won't find me."] = "그림자 속에서 주는 선물이오, {name}. 아니, 찾지 마시오. 못 찾을 테니."
L["Elune lights your path, {name}. I'm merely holding the lantern."] = "엘룬께서 그대의 길을 비추시오, {name}. 난 등불만 들었을 뿐."
L["The owls pointed you out, {name}. They have strong opinions. Here."] = "부엉이들이 그대를 콕 집었소, {name}. 안목 까다로운 녀석들이오. 받으시오."
L["Tyrande would insist, {name}, and nobody argues with Tyrande."] = "티란데 님이라면 꼭 주라 하셨을 거요, {name}. 그분께 토 다는 자는 없지."
L["Take this, {name}. The last one went to a hippogryph. It was less grateful."] = "받으시오, {name}. 지난번엔 히포그리프에게 줬는데, 그놈은 고마운 줄 모르더군."
L["Take this, {name}. Half the wildlife's a druid, and all of it is watching."] = "이걸 받아요, {name}. 여기 짐승 절반은 드루이드고, 전부 지켜보고 있어요."
L["Walk with Elune, {name}. If she's busy, walk with this."] = "엘룬과 함께 걸으시오, {name}. 바쁘시다면 이것과 함께."
L["A ward against satyrs, {name}. Once Highborne; you can tell by the sneer."] = "사티로스를 막는 가호예요, {name}. 한때 명가였죠. 비웃는 꼴 보면 알아요."
L["The trees spoke well of you, {name}. I thought I'd add my blessing."] = "나무들이 당신을 칭찬하더군요, {name}. 그 말에 제 축복도 보태고 싶었어요."
L["Most furbolgs are friendly, {name}. This is for the other ones."] = "펄볼그는 대개 우호적이오, {name}. 이건 나머지를 위한 거요."
L["Moonwell water would be better, {name}, but it travels badly. This doesn't."] = "달의 샘물이면 더 좋겠지만, {name}, 들고 다니기가 어렵소. 이건 쉽지."
L["A gift from Teldrassil, {name}. It's a long way down; I nearly dropped it."] = "텔드랏실에서 온 선물이오, {name}. 내려오는 길이 길어 떨어뜨릴 뻔했소."
L["I'd stay to chat, {name}, but kaldorei chats run to the next full moon. Here."] = "칼도레이 수다는 다음 보름달까지 가니, {name}, 이만 받으시오."
L["Bandu thoribas, {name}: prepare to fight. There. Now you're prepared."] = "반두 토리바스, {name}. 싸울 준비를 하라는 뜻이오. 자, 이제 준비됐소."
L["From the kaldorei, the moon and a very old tree, {name}. Mostly from me."] = "칼도레이와 달과 아주 오래된 나무가 드리오, {name}. 주로 내가."
L["Ashenvale remembers every axe, {name}. Carry this, and leave yours sheathed."] = "잿빛 골짜기는 도끼 하나하나를 기억하오, {name}. 이걸 지니고, 도끼는 넣어 두시오."
L["With this, {name}, the Sentinels will know you're a friend. Probably. Wave."] = "이걸 두르면, {name}, 파수꾼들이 친구로 알아볼 거예요. 아마도요. 손 흔드세요."
L["May the moon guide you, {name}, and this keep you until it rises."] = "달이 그대를 이끌기를, {name}. 달이 뜨기 전까진 이것이 지켜 주기를."
L["Moonglade welcomes all who come in peace, {name}. So does this."] = "달의 숲은 평화로이 오는 이 누구나 반기오, {name}. 이것도 그렇소."
L["Darkshore is beautiful, {name}, and full of things that bite. Take this."] = "어둠의 해안은 아름답소, {name}. 무는 것투성이지만. 받으시오."
L["My people learned the hard way not to hoard magic, {name}. So, here."] = "우리 종족은 마법을 쌓아 두면 안 된다는 걸 뼈저리게 배웠소, {name}. 자, 받으시오."
L["Felwood was a forest once, {name}. Take this; stay well where it didn't."] = "악령의 숲도 한땐 평범한 숲이었죠, {name}. 이걸 받아요. 숲은 못 그랬어도 당신은 무사하길."
L["Bound for Stonetalon, {name}? Take this. Mind the goblins' saws; the trees do."] = "돌발톱 산맥으로 가나요, {name}? 이걸 받아요. 고블린 톱 조심하고요. 나무들도 조심하거든요."
L["Take this, {name}. If you meet an Ancient, bow. They notice, and never forget."] = "이걸 받아요, {name}. 고대정령을 만나면 절하세요. 다 알아채고 절대 안 잊어요."
L["Ishnu-alah, {name}. Elune keeps her children close, and so do I."] = "이슈누 알라, {name}. 엘룬은 자녀들을 곁에 두시죠. 저도 그렇고요."
L["Of course I saw you, {name}. It takes a kaldorei to spot one in need of this."] = "당연히 봤죠, {name}. 이게 필요한 칼도레이는 칼도레이가 알아보는 법이에요."
L["Kaldorei to kaldorei, {name}: we gave up eternity, not each other. Take this."] = "칼도레이끼리니까요, {name}. 영생은 버려도 서로는 안 버려요. 받아요."
L["A kaldorei never leaves kin in the dark, {name}. Unless it's for cover."] = "칼도레이는 동족을 어둠 속에 두지 않소, {name}. 숨으려는 게 아니라면."
L["Two kaldorei, {name}, and no helmet fits either pair of ears. This does."] = "칼도레이 둘인데, {name}, 어떤 투구도 이 귀엔 안 맞죠. 이건 맞아요."
L["Sentinel, druid or simply stubborn, {name}? This suits all three."] = "파수꾼이든 드루이드든 그냥 고집쟁이든, {name}? 이건 셋 다 어울려요."
L["Twenty thousand years of 'we tried that', {name}. This, though, always works."] = "이만 년 동안 '그거 해 봤어'만 했죠, {name}. 그래도 이건 늘 통해요."
L["There, {name}. Now let's Shadowmeld together sometime and see who notices."] = "됐어요, {name}. 언제 같이 그림자 숨기 써서 누가 알아채나 봐요."
L["Our shan'do sleeps in the Dream, {name}. I'll mind you for him until he wakes."] = "우리 샨도께선 꿈속에 주무시죠, {name}. 깨실 때까지 제가 대신 돌봐 드릴게요."
L["Our people are few, {name}, so each of us gets looked after. Here."] = "우리 종족은 드물죠, {name}. 그러니 한 명 한 명 챙겨야 해요. 여기요."
L["Quick one, {name}? Take this now. By kaldorei reckoning we're already done."] = "금방 끝날 거라고요, {name}? 그럼 이거 먼저 받아요. 칼도레이 시간으론 벌써 끝났어요."
L["That's from the one you can't see, {name}. Not a mistake; that's the plan."] = "보이지 않는 제가 드리는 거예요, {name}. 실수가 아니라 계획이에요."
L["Elune watches the whole party, {name}. I just pass her light along."] = "엘룬께서 일행 모두를 지켜보시죠, {name}. 전 그분의 빛을 건넬 뿐이에요."
L["Ten thousand years of companions, {name}. You lot rank high enough for this."] = "만 년 동안 동료가 많았죠, {name}. 이걸 받을 만큼은 순위가 높아요."
L["Here, {name}. We misplaced half a continent once. I'm not misplacing you."] = "받아요, {name}. 한때 대륙 절반을 잃어버렸죠. 당신은 안 잃어버려요."
L["Take this, {name}. If I fall, I'll float about as a wisp, looking wise."] = "받아요, {name}. 제가 쓰러지면 위습이 되어 현명한 척 떠다닐게요."
L["I fought beside Neltharion once, {name}. He never got this from me. You do."] = "한때 넬타리온과 나란히 싸웠죠, {name}. 그에겐 이걸 준 적 없어요. 당신은 받죠."
L["Take this and follow me, {name}. I know these paths. They were a forest, mind."] = "이거 받고 따라와요, {name}. 이 길은 잘 알아요. 그땐 숲이었지만요."
L["Here, {name}. With this, we shan't fail. If we do, I'll remember you for ages."] = "받아요, {name}. 이거면 실패 안 해요. 혹시 하면 수천 년은 기억할게요."
L["Heroes charge in blind for millennia, {name}. Take this; let's try eyes open."] = "영웅들은 수천 년째 무작정 돌진하죠, {name}. 이거 받고 눈 뜨고 가 봐요."
L["That'll keep you till dawn, {name}. I'll take first watch. And second."] = "이거면 새벽까지 버틸 거예요, {name}. 첫 불침번은 제가 서요. 두 번째도요."
L["Here, quietly, {name}. Keep your voices low; the forest listens, and remembers."] = "조용히 받아요, {name}. 목소리 낮춰요. 숲은 듣고, 기억하거든요."
L["We held the Legion with fewer, {name}, and less help than this. We'll be fine."] = "우린 이보다 적은 수로, {name}, 이만한 도움도 없이 군단을 막았어요. 괜찮을 거예요."
L["A Sentinel never looses an arrow she'd want back, {name}, nor a blessing."] = "파수꾼은 되찾고 싶을 화살은 절대 안 쏴요, {name}. 축복도 마찬가지고요."
L["Dark in there, {name}? Take this and follow me. The night is where we live."] = "안이 어둡나요, {name}? 이거 받고 따라와요. 밤은 우리의 집이에요."
L["Moving out, {name}, blessed and silent as owls. Or as dwarves, if we can't."] = "출발해요, {name}. 축복받고 부엉이처럼 조용히. 안 되면 드워프처럼요."
L["Take this, {name}. I watch the shadows; nothing moves in them without my say."] = "이걸 받아요, {name}. 그림자는 제가 지켜요. 제 허락 없인 아무것도 못 움직여요."
L["The moon's up, {name}; here's her blessing. For a kaldorei, it's mid-morning."] = "달이 떴어요, {name}. 그분의 축복을 받아요. 칼도레이에겐 지금이 한낮 전이에요."
L["Everyone sensible is asleep, {name}, so Elune's light is all yours tonight."] = "분별 있는 이들은 다 잠들었죠, {name}. 그러니 오늘 밤 엘룬의 빛은 다 당신 거예요."
L["Elune's light is on you, {name}. Here's a second layer."] = "엘룬의 빛이 그대를 비추오, {name}. 여기 한 겹 더."
L["Dark at last, {name}. Now I see perfectly, and you get this before I see more."] = "드디어 어둡네요, {name}. 이제 아주 잘 보여요. 더 보기 전에 이것부터 드릴게요."
L["Same stars as ten thousand years ago, {name}. Same blessing. Both aged well."] = "만 년 전에 본 그 별들이에요, {name}. 이 축복도 그대로고요. 둘 다 곱게 늙었죠."
L["Moonrise, {name}. Every kaldorei just woke up a little. Here's my share of it."] = "월출이에요, {name}. 칼도레이가 다들 조금씩 깨어났죠. 제 몫을 나눠 드릴게요."
L["Morning, {name}. My people slept through these; this will help us both adapt."] = "좋은 아침, {name}. 우리 종족은 이 시간엔 잤죠. 이거면 둘 다 적응이 될 거예요."
L["Dawn, {name}. Elune's gone to bed, so I'm covering for her."] = "새벽이오, {name}. 엘룬께서 주무시러 가셨으니 내가 대신하리다."
L["The sun's up, {name}, and so, reluctantly, am I. Have this while I wake."] = "해가 떴네요, {name}. 저도 마지못해 일어났고요. 제가 깨는 동안 이거 받아요."
L["Too bright, {name}. I'll squint through this one; Elune forgives squinting."] = "너무 눈부시오, {name}. 실눈 뜨고 버티리다. 엘룬께선 실눈도 용서하시니."
L["Daybreak, {name}: the one hour a night elf is easy to spot. Quick, take this."] = "동틀 녘이오, {name}. 나이트 엘프가 딱 눈에 띄는 시간이지. 어서 받으시오."
L["Up early, {name}? I'm up late. Let's meet in the middle, with this."] = "일찍 일어났소, {name}? 난 늦게까지 깨어 있었소. 이걸로 중간에서 만납시다."
L["Elune walks with us, {name}. Breathe the forest in while it is quiet."] = "엘룬께서 함께하셔, {name}. 고요한 숲을 들이마셔 봐."
L["The wild remembers us both, {name}. Stay close a while."] = "야생은 우리 둘을 기억해, {name}. 잠시 곁에 있어 줘."
L["Ten thousand years of hunters, {name}, and none had a truer friend."] = "만 년의 사냥꾼 중 너만 한 친구를 둔 이는 없어, {name}."
L["Swift and true, {name}. Cenarius himself would be proud of you."] = "빠르고 정확했어, {name}. 세나리우스께서도 기뻐하실 거야."
L["Well hunted, {name}. The forest sings of that one tonight."] = "잘 사냥했어, {name}. 오늘 밤 숲이 그 노래를 부를 거야."
L["That was the wild at its finest, {name}. Well done."] = "야생의 진수를 보여 줬구나, {name}. 잘했어."
L["Be still, {name}. Elune's light is on you; let it mend you."] = "가만히 있어, {name}. 엘룬의 빛이 널 낫게 할 거야."
L["Hush, {name}. I am here, and the night is gentle."] = "쉿, {name}. 내가 여기 있고, 밤은 부드러워."
L["Rest, {name}. The Emerald Dream can wait a while longer for you."] = "쉬어, {name}. 에메랄드의 꿈은 조금 더 기다려 줄 거야."
L["The shadows remember kindness, {name}. So do I."] = "그림자는 친절을 기억하지요, {name}. 저도 마찬가지고요."
L["My thanks, {name}. The ren'dorei do not forget a kindness."] = "고마워요, {name}. 렌도레이는 받은 호의를 잊지 않아요."
L["Thank you, {name}. The voices approve of you, which is frankly alarming."] = "고마워요, {name}. 속삭임들까지 마음에 들어 하네요. 솔직히 좀 불안해요."
L["Thank you, {name}. Few give gifts to someone who glows this ominously."] = "고마워요, {name}. 이렇게 불길하게 빛나는데 선물이라니, 드문 일이에요."
L["Kindness is rare in the Void, {name}. I'll return yours before it notices."] = "공허에선 친절이 귀해요, {name}. 공허가 눈치채기 전에 얼른 갚을게요."
L["Silvermoon threw us out, {name}. Kindness like yours deserves returning."] = "실버문은 우릴 내쫓았죠, {name}. 당신 같은 친절은 돌려받아야 마땅해요."
L["Returned in full, {name}. It may be slightly purple. That's normal."] = "고스란히 갚았어요, {name}. 살짝 보랏빛일 수 있어요. 정상이에요."
L["The Void only takes, {name}. I, however, give back."] = "공허는 빼앗기만 하죠, {name}. 하지만 저는 돌려드려요."
L["Thank you, {name}. The whispers went quiet. That's how I know it was sincere."] = "고마워요, {name}. 속삭임이 조용해졌어요. 진심이었다는 증거죠."
L["Thank you, {name}. I'd smile, but people say it's unsettling. So: imagine one."] = "고마워요, {name}. 웃고 싶지만 제 미소는 섬뜩하대요. 상상으로 봐 줘요."
L["Returned, {name}: cold hands, warm intentions. That's us in a sentence."] = "갚았어요, {name}. 손은 차갑게, 마음은 따뜻하게. 렌도레이 한 줄 요약이죠."
L["Returned, {name}. You may hear it twice; my spells echo now."] = "갚았어요, {name}. 두 번 들릴 수도 있어요. 요즘 제 주문은 메아리쳐요."
L["The Void offered me forbidden knowledge, {name}. Yours was the nicer gift."] = "공허는 금단의 지식을 주겠대요, {name}. 이쪽 선물이 훨씬 좋네요."
L["Alleria says the Void can be mastered, {name}. Kindness, I find, is easier."] = "알레리아 님은 공허도 다스릴 수 있대요, {name}. 친절이 더 쉽던데요."
L["Much obliged, {name}. Most people give us a wide berth. You gave me this."] = "신세 졌어요, {name}. 다들 우릴 피해 가는데, 이렇게 주고 가시네요."
L["Thank you, {name}. My shadow bowed as well. It never does. You've impressed it."] = "고마워요, {name}. 제 그림자도 절했어요. 원래 안 그러는데. 반했나 봐요."
L["As you wish, {name}. The shadows answer kindly today."] = "원하는 대로, {name}. 오늘은 그림자도 순순히 응하네요."
L["Consider it done, {name}. The Void obeys us, not the other way round."] = "맡겨 둬요, {name}. 공허는 우리를 따르지, 그 반대가 아니에요."
L["Certainly, {name}. The whispers said no, so it's an easy yes."] = "그럼요, {name}. 속삭임들이 하지 말래서, 고민할 것도 없어요."
L["Of course, {name}. One {buff}, lightly seasoned with the Void."] = "물론이죠, {name}. 공허로 살짝 간을 한 {buff} 하나요."
L["Of course, {name}. Hold still; the shadows are shy with strangers."] = "물론이죠, {name}. 가만히요. 그림자가 낯을 가려서."
L["Gladly, {name}. Ren'dorei manners: the Void waits its turn."] = "기꺼이요, {name}. 렌도레이 예절이죠. 공허는 줄 서서 기다려요."
L["Asked so nicely, {name}? Then you'll have my best."] = "이렇게 공손하게요, {name}? 그럼 최고로 해 드릴게요."
L["Of course, {name}. Stand in the light, please; the Void gets ideas in corners."] = "물론이죠, {name}. 밝은 데 서 주세요. 공허는 구석에서 딴생각을 하거든요."
L["Of course, {name}. The Void asked why. I said 'manners'. It's still puzzled."] = "물론이죠, {name}. 공허가 왜냐길래 '예의'라 했더니, 아직도 갸웃해요."
L["Gladly, {name}. Nobody asks us for anything but 'please stop whispering'."] = "기꺼이요, {name}. 다들 우리한텐 '그만 좀 속삭여'밖에 부탁을 안 하거든요."
L["Happy to, {name}. Just let me finish arguing with myself. There. I won."] = "좋아요, {name}. 저랑 말다툼 좀 끝내고요. 됐어요. 제가 이겼어요."
L["Certainly, {name}. I could rift over there first, but that feels showy."] = "그럼요, {name}. 균열 타고 건너갈 수도 있지만, 좀 과시 같아서요."
L["Asking questions got us exiled, {name}. Answering one is quite safe, I'm told."] = "질문했다가 추방당했죠, {name}. 대답은 꽤 안전하다더군요."
L["Of course, {name}. A slight chill and a faint chorus are both perfectly normal."] = "물론이죠, {name}. 살짝 오싹하고 희미한 합창이 들려도 정상이에요."
L["A touch of shadow for you, {name}. Quite safe. Mostly."] = "{name}, 그림자를 살짝 드릴게요. 안전해요. 대체로요."
L["Walk carefully in the dark places, {name}. This will light a little of them."] = "어두운 곳에선 조심히 걸어요, {name}. 이게 조금은 비춰 줄 거예요."
L["A little something from the Telogrus Rift, {name}. It's cleaner than it sounds."] = "텔로그루스 균열에서 온 작은 선물이에요, {name}. 생각보다 깨끗해요."
L["Take this, {name}. Any tentacles you see are purely decorative."] = "받아요, {name}. 촉수가 보여도 그냥 장식이에요."
L["The shadows asked after you, {name}. Take this; they can mind their manners."] = "그림자들이 당신 안부를 묻더군요, {name}. 이걸 드리고, 예의 좀 지키라 했어요."
L["Here, {name}. We walked into the Void so you wouldn't have to."] = "여기요, {name}. 공허엔 우리가 대신 들어갔으니, 안 가셔도 돼요."
L["I checked your shadow, {name}. Nothing lurking. Take this anyway."] = "그림자를 살펴봤는데, {name}, 숨은 건 없네요. 그래도 받아요."
L["Umbric sends his regards, {name}, and this. He doesn't, but he would."] = "움브릭이 안부와 함께 이걸 보냈어요, {name}. 사실 아니지만, 그랬을 거예요."
L["Take this, {name}. It may whisper a compliment. Pretend you didn't hear."] = "받아요, {name}. 칭찬을 속삭일지도 몰라요. 못 들은 척해 줘요."
L["Here, {name}. Looks sinister, works beautifully. Rather like me."] = "여기요, {name}. 보기엔 불길해도 효과는 훌륭해요. 저처럼요."
L["Take this, {name}. The Void had worse in mind for you. I intercepted."] = "받아요, {name}. 공허가 더 나쁜 걸 준비했길래, 제가 가로챘어요."
L["If the dark whispers at you today, {name}, pay it no mind. Take this."] = "오늘 어둠이 속삭이거든, {name}, 신경 쓰지 마요. 이거 받아요."
L["Here, {name}. We ren'dorei don't often get to be the nice surprise."] = "여기요, {name}. 렌도레이가 반가운 깜짝선물이 될 일은 흔치 않거든요."
L["I left Quel'Thalas with only a knack for the dark, {name}. Here's the knack."] = "쿠엘탈라스를 떠날 때 가진 건 어둠의 재주뿐이었죠, {name}. 그걸 드려요."
L["Here, {name}. Don't thank the shadows; they'll only want something. Thank me."] = "여기요, {name}. 그림자한텐 고마워하지 마요. 뭘 바랄 테니. 저한테 해요."
L["I owe a kindness for every ominous look I've given, {name}. I'm badly behind."] = "불길한 눈빛 한 번에 친절 한 번씩 갚기로 했거든요, {name}. 한참 밀렸어요."
L["We ren'dorei look after our own, {name}."] = "우리 렌도레이는 동족을 챙기죠, {name}."
L["Silvermoon's loss, {name}. Here: we look after our own splendidly without it."] = "실버문만 손해죠, {name}. 받아요. 그 없이도 우린 우리 편을 멋지게 챙겨요."
L["Your whispers and mine should meet sometime, {name}. Here's a start."] = "당신 속삭임과 제 속삭임이 언제 만나야 할 텐데요, {name}. 이게 시작이에요."
L["Two ren'dorei, {name}. Take this; then look brooding. It's expected."] = "렌도레이 둘이 한자리에 있네요, {name}. 이거 받고 우수에 찬 표정 지어요. 다들 기대하니까."
L["Nobody else understands the hair, {name}. Here, from one of the few who do."] = "이 머리카락은 아무도 이해 못 하죠, {name}. 이해하는 몇 안 되는 이가 드리는 거예요."
L["Telogrus felt like home in the end, {name}. Draughty, dark. This will warm you."] = "텔로그루스도 결국 집 같았죠, {name}. 외풍 세고 어두웠지만요. 이게 좀 데워 줄 거예요."
L["Ren'dorei to ren'dorei, {name}: mine whispered to give you this. Yours?"] = "렌도레이끼리 묻는 건데요, {name}. 제 건 이걸 주라고 속삭이던데요. 당신 건요?"
L["Stay close, {name}, and take this. The whispers are much quieter in company."] = "가까이 있어요, {name}, 그리고 이걸 받아요. 함께 있으면 속삭임이 훨씬 잦아들어요."
L["There, {name}. If the shadows start giving orders, ignore them. I usually do."] = "됐어요, {name}. 그림자가 명령하기 시작하면 무시해요. 전 보통 그래요."
L["Here, {name}. Keep an eye on my shadow. It wanders off when there's a fight."] = "받아요, {name}. 제 그림자 좀 지켜봐요. 싸움만 나면 어디론가 가 버리거든요."
L["That glow is my gift to you, {name}. If I start glowing purple too, I'm keen."] = "그 빛은 제 선물이에요, {name}. 저까지 보랏빛으로 빛나면 의욕이 넘친다는 뜻이고요."
L["Ren'dorei make fine companions, {name}. We bring our own dark, and gifts."] = "렌도레이는 좋은 동료예요, {name}. 어둠도 직접 챙기고, 이런 선물도 챙기죠."
L["Here, {name}. If I talk to nobody, I'm fine. If nobody talks back, worry."] = "받아요, {name}. 제가 허공에 말하면 괜찮은 거예요. 허공이 대답 안 하면 걱정하고요."
L["Yours, {name}. If it goes wrong I'll open a rift. Only for me, but I'll wave."] = "이건 당신 거예요, {name}. 잘못되면 균열을 열게요. 저만 들어가지만, 손은 흔들어 드릴게요."
L["Enjoy this little gift, {name}. Ren'dorei rarely get invited anywhere twice."] = "이 작은 선물 즐겨요, {name}. 렌도레이는 두 번 초대받는 일이 드물거든요."
L["Take this, {name}. Keep the lanterns lit; not for me, but the shadows behave."] = "이걸 받아요, {name}. 등불은 켜 둬요. 전 필요 없지만, 그림자들이 얌전해지거든요."
L["Here, {name}. Watch the corners; I'll keep an eye on what's in them."] = "받아요, {name}. 구석을 봐요. 그 안에 있는 건 제가 볼게요."
L["The Void gave me power, {name}. It never said I'd have friends to share it."] = "공허가 힘을 줬죠, {name}. 그 힘을 나눌 동료를 만날 줄은 말 안 했지만요."
L["For you, {name}. If you hear whispers mid-fight, they're cheering. For us."] = "이건 당신 몫이에요, {name}. 싸움 중에 속삭임이 들리면 응원이에요. 우릴 위한."
L["Take this, {name}. Anything eldritch turns up, I'll talk. I speak a little."] = "받아요, {name}. 기괴한 게 나타나면 제가 말 걸게요. 조금은 할 줄 알거든요."
L["Night suits the ren'dorei, {name}. We match the decor. Here's a little of it."] = "밤은 렌도레이에게 어울리죠, {name}. 배경이랑 깔맞춤이에요. 당신께도 조금 나눠 드릴게요."
L["The shadows are longest now, {name}, and in a very generous mood."] = "지금 그림자가 가장 길어요, {name}. 마음씨도 가장 넉넉하고요."
L["Late, {name}? The whispers love a late hour, and asked me to give you this."] = "늦었네요, {name}? 속삭임은 늦은 시간을 좋아해요. 이걸 드리라고 하더군요."
L["Midnight, {name}. My shadow and I agree on one thing tonight: you get this."] = "자정이에요, {name}. 오늘 밤 제 그림자와 저는 한 가지에 동의했어요. 이건 당신 거라고."
L["Stars out, {name}. I've seen what's between them. This keeps that away."] = "별이 떴네요, {name}. 별들 사이에 뭐가 있는지 봤어요. 이걸 받아요. 그걸 막아 줘요."
L["The Void whispers, {name}, but you're the only voice I listen to."] = "공허가 속삭여도, {name}, 내가 듣는 목소리는 너뿐이야."
L["Stay near, {name}. Out here, you're the steadiest thing I have."] = "가까이 있어, {name}. 이곳에서 가장 든든한 건 너야."
L["You never flinch at the shadows, {name}. I could learn from you."] = "넌 그림자에 움찔하지도 않지, {name}. 너한테 배워야겠어."
L["Well done, {name}. Even the Void took a step back from that."] = "잘했어, {name}. 공허조차 한 발 물러섰어."
L["Perfect, {name}. Alleria herself would want you at her side."] = "완벽해, {name}. 알레리아님도 널 곁에 두고 싶어 하실 거야."
L["That's it, {name}! Darkness on our side, and you in front."] = "바로 그거야, {name}! 어둠은 우리 편, 그리고 넌 선두에."
L["Easy, {name}. I'll keep the whispers away while you rest."] = "진정해, {name}. 네가 쉬는 동안 속삭임은 내가 막을게."
L["Breathe, {name}. The dark lets go of us both in time."] = "숨 쉬어, {name}. 어둠도 언젠가 우리 둘을 놓아줄 거야."
L["Stay with me, {name}. Rest now; the shadows are mine to watch."] = "곁에 있어, {name}. 이제 쉬어. 그림자는 내가 지켜볼게."
L["Thanks, {name}! Kindness received, catalogued and returned!"] = "고마워요, {name}님! 호의 수신, 분류, 반송 완료!"
L["Reciprocity engaged! Much obliged, {name}."] = "상호 호혜 모드 가동! 감사해요, {name}님."
L["By my calculations, {name}, you're owed exactly one {buff}."] = "계산해 보니, {name}님께 정확히 {buff} 하나를 드려야 하네요."
L["Thanks, {name}! I'd build you a thank-you machine, but it'd explode."] = "고마워요, {name}님! 감사 기계를 만들어 드리고 싶지만, 터질 거예요."
L["Thank you, {name}! Gnomeregan's finest couldn't have timed that better."] = "고마워요, {name}님! 놈리건 최고 기술자도 이보다 타이밍을 잘 맞추진 못했을 거예요."
L["You're too kind, {name}! Returning the favour took only four schematics."] = "너무 친절하세요, {name}님! 보답하는 데 설계도 네 장밖에 안 들었어요."
L["Drat, {name}! I was going to invent gratitude, but you beat me to it."] = "이런, {name}님! '고마움'을 발명하려던 참인데 선수를 치셨네요."
L["Oh, {name}, how kind! My heart's doing that whirring thing again."] = "어머, {name}님, 친절하셔라! 심장이 또 윙윙 돌아가요."
L["Noted in my lab journal, {name}, page four hundred: 'people are lovely'."] = "연구 일지 400쪽에 적었어요, {name}님. '사람들은 다정하다'."
L["Splendid, {name}! Returning it at once, before I'm tempted to improve it."] = "멋져요, {name}님! 바로 돌려드릴게요. 개조하고 싶어지기 전에요."
L["Thanks, {name}! Kindness is a reversible reaction. I checked. Here's yours."] = "고마워요, {name}님! 친절은 가역 반응이에요. 확인했어요. 여기요."
L["My mechanostrider would salute you, {name}, but it only knows falling over."] = "제 기계타조도 경례하고 싶겠지만, {name}님, 걔는 넘어지는 것밖에 몰라요."
L["My transporter would've sent this to Gadgetzan, {name}. Hand-delivered instead!"] = "순간이동기로 보냈으면 가젯잔에 갔을 거예요, {name}님. 그래서 직접 배달!"
L["Oh, thank you, {name}! I haven't felt this good since before the troggs."] = "어머, 고마워요, {name}님! 트로그 사태 이후로 이렇게 좋긴 처음이에요."
L["I'll name my next invention after you, {name}! It's a very small cannon."] = "다음 발명품엔 {name}님 이름을 붙일게요! 아주 작은 대포예요."
L["Thanks, {name}! Ironforge has been good to us gnomes, and so have you."] = "고마워요, {name}님! 아이언포지만큼 우리 노움한테 잘해 주시네요."
L["Thanks, {name}! You're on my list of favourites. It's short. Mostly clockwork."] = "고마워요, {name}! 제 최애 명단에 올랐어요. 짧은 명단이죠. 대부분 태엽 장치고요."
L["Thanks, {name}! A gift with no gears in it. I didn't know they made those."] = "고마워요, {name}님! 톱니바퀴 없는 선물이라니. 그런 게 있는 줄 몰랐어요."
L["Thank you, {name}! I'd pay you back with interest, but my abacus is in pieces."] = "고마워요, {name}님! 이자까지 쳐서 갚고 싶은데, 주판이 산산조각 났어요."
L["Paid back, {name}! In Gnomeregan, you'll get a window seat. We'll add windows."] = "갚았어요, {name}! 놈리건을 되찾으면 창가 자리 드릴게요. 창문은 달면 되죠."
L["Exactly what I needed, {name}, and I didn't even have to build it. Thanks!"] = "딱 필요했던 거예요, {name}님. 제가 만들 필요도 없었네요. 고마워요!"
L["The tall folk rarely notice us gnomes, {name}. You did. Thank you!"] = "키 큰 분들은 우리 노움을 잘 못 보는데, {name}님은 봐 주셨네요. 고마워요!"
L["Thanks, {name}! Tinker Town will hear all about it. Loudly, over the machinery."] = "고마워요, {name}! 땜장이 마을에 다 소문낼게요. 기계 소리보다 크게요."
L["It worked first time, {name}! Nothing I make works first time. Marvellous!"] = "한 번에 됐어요, {name}님! 제 발명품은 한 번에 되는 게 없는데. 굉장해요!"
L["Request received, {name}! Processing... done!"] = "요청 접수, {name}님! 처리 중... 끝!"
L["One upgrade, coming right up, {name}! Stand still for calibration."] = "업그레이드 하나 나갑니다, {name}님! 보정할 테니 가만히!"
L["Of course, {name}! I built a machine for this. It's in pieces, so: by hand."] = "물론이죠, {name}님! 이거 하는 기계도 만들었는데, 박살 나서 손으로 할게요."
L["Certainly, {name}! Stand on the X. There's no X. Stand anywhere."] = "그럼요, {name}님! X 표시에 서세요. X가 없네요. 아무 데나 서세요."
L["Right away, {name}! Goggles on. Not for you, I just like them."] = "바로 할게요, {name}님! 고글 착용! 필요는 없고, 그냥 좋아서요."
L["{buff}, {name}? Simple in theory and practice. Suspicious!"] = "{buff} 말이죠, {name}님? 이론도 실전도 간단하다니. 수상해요!"
L["Happy to, {name}! Keep hands, feet and eyebrows well clear."] = "기꺼이요, {name}님! 손발이랑 눈썹은 멀찍이 떨어뜨리세요."
L["Right away, {name}! Stand back three paces. Four. Five. There, perfect."] = "바로 할게요, {name}님! 세 걸음 물러서세요. 넷. 다섯. 네, 완벽해요."
L["Happy to, {name}! It beats sorting springs by size. Though that's fun too."] = "기꺼이요, {name}님! 용수철 크기별 정리보다 재밌죠. 그것도 재밌지만요."
L["Excellent request, {name}! No moving parts. I'll try to add some next time."] = "탁월한 주문이에요, {name}님! 움직이는 부품이 없네요. 다음엔 달아 볼게요."
L["Standard model or deluxe, {name}? They're the same. Deluxe sounds nicer."] = "일반형이요, 디럭스요, {name}님? 똑같아요. 디럭스가 있어 보이죠."
L["Coming up, {name}! Fresh off the workbench, still warm, only slightly smoking."] = "나갑니다, {name}님! 작업대에서 갓 나와 따끈해요. 연기는 살짝만 나요."
L["Approved, {name}! Stamped, signed and filed under 'obviously'."] = "승인, {name}님! 도장 쾅, 서명 끝, '당연하죠' 폴더에 보관!"
L["Of course, {name}! A twist of the gyromatic micro-adjustor... there!"] = "물론이죠, {name}님! 자이로매틱 미세 조정기를 살짝 돌리고... 됐다!"
L["Gnomes never refuse a problem, {name}. Occasionally we cause them. Here!"] = "노움은 문제를 거절 안 해요, {name}님. 가끔 일으키긴 하죠. 여기요!"
L["Right away, {name}! Tested on three volunteers and one very brave squirrel."] = "바로 할게요, {name}님! 지원자 셋과 아주 용감한 다람쥐 하나로 검증했어요."
L["Happy to, {name}! Measure twice, zap once. Gnome proverb. Well, my proverb."] = "기꺼이요, {name}님! 두 번 재고 한 번 쏴라. 노움 속담이에요. 사실 제 속담이고요."
L["Of course, {name}! The High Tinker says help where you can. I can, so here!"] = "물론이죠, {name}님! 땜장이 왕께서 할 수 있으면 도우라셨어요. 할 수 있으니, 여기요!"
L["On it, {name}! I'll need a ladder. No? Just this, then."] = "맡겨 주세요, {name}님! 사다리가 필요한데. 아니라고요? 그럼 이것만."
L["Delighted, {name}! It's nice to fix something that doesn't fight back."] = "기뻐요, {name}님! 반항 안 하는 걸 고치니 좋네요."
L["Hold still, {name}, this is perfectly safe. Probably!"] = "가만히 계세요, {name}님. 완벽하게 안전해요. 아마도요!"
L["Science says you need this, {name}. Who am I to argue?"] = "과학이 필요하다잖아요, {name}님. 제가 어쩌겠어요?"
L["A small upgrade for you, {name}. No cogs required."] = "{name}님께 작은 업그레이드! 톱니바퀴는 필요 없어요."
L["Take it, {name}, I've a spare. I've three spares of everything."] = "받으세요, {name}님. 여분 있어요. 전 뭐든 여분이 세 개씩 있거든요."
L["Try this, {name}! Version one had legs. Version two is much better."] = "써 보세요, {name}님! 1호기엔 다리가 달렸었는데, 2호기가 훨씬 나아요."
L["The High Tinker says share our genius, {name}. Here's a sample!"] = "땜장이 왕께서 천재성을 나누라셨어요, {name}님. 샘플 드릴게요!"
L["Gnomeregan Forever, {name}! This lasts rather less, but it's free."] = "놈리건이여 영원하라, {name}님! 이건 영원까진 아니지만 공짜예요."
L["I'm small, {name}, but my gifts come full-sized. Here!"] = "전 작아도, {name}님, 선물은 풀사이즈예요. 받으세요!"
L["Don't worry, {name}! It worked on the chicken, and the chicken's thrilled."] = "걱정 마세요, {name}님! 닭한테 써 봤는데, 닭이 아주 신났어요."
L["Field notes say it works on everyone, {name}. Let's make it unanimous!"] = "현장 기록상 누구한테나 통한대요, {name}님. 만장일치로 만들어 봐요!"
L["One size fits all, {name}, gnome to tauren. I measured. The tauren was patient."] = "프리사이즈예요, {name}님. 노움부터 타우렌까지 재 봤죠. 타우렌이 잘 참더군요."
L["Take this, {name}! Unlike my Net-o-Matic, it never lands on me."] = "받으세요, {name}님! 제 그물 발사기와 달리 이건 저한테 안 떨어져요."
L["The Gnomish Army Knife does twelve things badly, {name}. This does one well."] = "노움 만능칼은 재주가 열둘인데 다 어설퍼요, {name}님. 이건 하나를 잘하죠."
L["Guarantee void if exposed to troggs, dragonfire or enthusiasm, {name}. Enjoy!"] = "트로그, 용의 불길, 과한 열정에 닿으면 A/S 불가예요, {name}님. 즐기세요!"
L["Nothing up my sleeves, {name}! Well, a spanner and two fuses. Nothing sinister."] = "소매엔 아무것도 없어요, {name}님! 음, 스패너랑 퓨즈 두 개. 수상한 건 없어요."
L["Here, {name}! It's small, but so is a keystone, and look what those hold up."] = "여기요, {name}님! 작죠? 쐐기돌도 작은데, 뭘 떠받치는지 보세요."
L["I'd explain how it works, {name}, but that takes three days and a chalkboard."] = "원리를 설명드리고 싶지만, {name}님, 사흘이랑 칠판이 필요해요."
L["That hum's my gift settling, {name}. If you hear ticking, it's my pocket watch."] = "그 웅웅 소리는 제 선물이 자리 잡는 소리예요, {name}. 째깍 소리는 제 회중시계고요."
L["A dash of arcane, a pinch of science, {name}, and no troggs involved. Here!"] = "비전 한 방울, 과학 한 꼬집, {name}님. 트로그는 안 들어갔어요. 여기요!"
L["Ironforge took us gnomes in when we needed it, {name}. I'm passing it along."] = "아이언포지가 어려울 때 우리 노움을 받아 줬죠, {name}님. 그 은혜를 나눠요."
L["Here, {name}! It doesn't whistle, spin or catch fire. I'm working on all three."] = "여기요, {name}님! 휘파람도 안 불고, 안 돌고, 불도 안 붙어요. 셋 다 개발 중이에요."
L["Here, {name}! Unwrapped, sorry. The wrapping machine wrapped itself again."] = "여기요, {name}님! 포장 못 해서 죄송해요. 포장 기계가 또 자기를 포장했어요."
L["My mechanostrider wanted to give you something, {name}. It lacks the hands."] = "제 기계타조도 {name}님께 뭘 드리고 싶어 했어요. 손이 없어서 못 하지만."
L["Off on an adventure, {name}? Take this, and bring me back anything that ticks."] = "모험 떠나세요, {name}님? 이거 받고, 째깍대는 건 뭐든 가져다주세요."
L["Reliable as the Deeprun Tram, {name}. That's a compliment, I promise. Here!"] = "깊은굴 지하철만큼 믿음직해요, {name}님. 칭찬 맞아요, 진짜로. 여기요!"
L["For you, {name}! One part magic to two parts confidence. Mostly confidence."] = "{name}님 거예요! 마법 하나에 자신감 둘. 거의 자신감이죠."
L["For Gnomeregan, {name}! Here, eye to eye. Always nice to give at eye level."] = "놈리건을 위하여, {name}! 자, 눈높이에서 드려요. 눈높이가 맞으니 주기도 좋네요."
L["Fellow gnome, {name}! A boost for you. I'll hold the schematic, you the bucket."] = "동족 노움이군요, {name}! 힘 좀 실어 드릴게요. 설계도는 제가, 양동이는 당신이."
L["Flesh or cogs, {name}, we're all gnomes. Some need oiling. This is oil."] = "살이든 톱니든, {name}, 우린 다 노움이에요. 기름칠 필요한 이도 있고요. 이게 기름이에요."
L["Gnome to gnome, {name}: here's a boost. You did turn the reactor off, yes?"] = "노움끼리 말인데요, {name}, 힘 좀 실어 드릴게요. 원자로는 끄고 왔죠?"
L["Two gnomes, {name}! With this boost and you on my shoulders, we're a night elf."] = "노움 둘이에요, {name}! 이 힘에 당신이 제 어깨에 올라타면 거의 나이트 엘프죠."
L["I checked my sums on this, {name}. You check yours; we're both offended."] = "이건 제가 계산 다 검산했어요, {name}. 당신도 검산하면 둘 다 기분 상하겠죠."
L["That one's free, {name}. You still owe me a sprocket. Every gnome does."] = "이건 공짜예요, {name}. 톱니바퀴 하나는 여전히 빚졌고요. 노움은 다 저한테 하나씩 빚졌죠."
L["Here, {name}. One day we'll walk back into Gnomeregan together, lights on."] = "받아요, {name}. 언젠가 함께 놈리건으로 돌아가요. 불 켜고요."
L["Between gnomes, {name}: this one won't explode. I checked. Twice. Mostly."] = "노움끼리니까 말인데요, {name}, 이건 안 터져요. 확인했어요. 두 번. 대충은요."
L["A start, {name}. Shall we build something huge, to see the tall folk's faces?"] = "시작이에요, {name}. 큰 사람들 표정 보게 뭔가 거대한 거 하나 만들까요?"
L["Party-wide calibration complete, {name}! Nobody touch anything shiny."] = "파티 전체 보정 완료예요, {name}님! 반짝이는 건 아무도 만지지 마세요."
L["I've run the numbers, {name}: with this on you, we win. I rounded up."] = "계산해 봤어요, {name}. 이걸 두르면 우리가 이겨요. 반올림했지만요."
L["There, {name}. If I shout 'duck', don't look for a duck. Last time went badly."] = "됐어요, {name}. 제가 '숙여!' 하면 땅바닥 보지 말고요. 지난번에 그래서 망했거든요."
L["There, {name}. Formation: tall folk at the front, me somewhere safe and clever."] = "됐어요, {name}. 대형은 키 큰 사람이 앞, 저는 안전하고 영리한 어딘가."
L["Everyone gets one, {name}! Standardised parts are the secret of a good machine."] = "하나씩 다 드려요, {name}님! 좋은 기계의 비결은 표준 부품이죠."
L["My plan, {name}: step one, give you this. Step two is still in development."] = "제 계획이요, {name}? 1단계, 이걸 드린다. 2단계는 아직 개발 중."
L["Don't panic, {name}. That's my gadget for any mishap. Version two next week."] = "당황하지 마요, {name}. 뭐가 잘못되든 대비한 제 장치예요. 2.0은 다음 주에 나와요."
L["Here, {name}. If I vanish, check under the nearest boot. Politely, please."] = "받아요, {name}. 제가 사라지면 제일 가까운 장화 밑을 보세요. 정중하게요."
L["Yours, {name}. When this is over, I want samples. Of everything. Big one first."] = "이건 당신 거예요, {name}. 끝나면 샘플 주세요. 전부 다요. 큰 놈 것부터."
L["On purpose, {name}. Like every explosion today. I'll decide which ones later."] = "이 힘은 일부러 드리는 거예요, {name}. 오늘 폭발도 전부 일부러고요. 어느 건지는 나중에 정해요."
L["Clipboard ready, {name}! First entry: gave you this. Then everyone's heroics."] = "기록판 준비 완료, {name}! 첫 기록: 이걸 드렸음. 그다음은 모두의 활약상."
L["There, {name}. If we get separated, follow the smoke. It'll be me."] = "됐어요, {name}. 흩어지면 연기 나는 쪽으로 와요. 그게 저예요."
L["Here, {name}. Everyone keep their fingers. I've counted. I'll recount after."] = "받아요, {name}. 다들 손가락 잘 챙겨요. 세어 뒀어요. 끝나고 다시 셀 거예요."
L["Ready, {name}? Spare gears, spare fuses, and now a spare boost for you."] = "준비됐어요, {name}? 여분 톱니, 여분 퓨즈, 그리고 이제 당신 몫 여분 힘까지."
L["Take this, {name}, and leave the traps to me. I built most of them. Not these."] = "이거 받고, {name}, 함정은 저한테 맡겨요. 대부분 제가 만들었거든요. 이건 아니지만."
L["Here, {name}, before we go in. Anyone seen my wrench? It's mildly important."] = "들어가기 전에 받아요, {name}. 누구 제 렌치 봤어요? 약간 중요한데."
L["For Gnomeregan, {name}! And for you, here. And for everywhere else, too."] = "놈리건을 위하여, {name}! 그리고 당신을 위해, 여기요. 내친김에 다른 모든 곳도요."
L["Take this, {name}. If I'm carried off, retrieve my notes first. Then me."] = "받아요, {name}. 제가 끌려가면 제 노트부터 챙겨요. 그다음에 저고요."
L["An experiment, {name}. Hypothesis: with this on you, we win. Let's test it."] = "이건 실험이에요, {name}. 가설: 이걸 두르면 우리가 이긴다. 확인해 봐요."
L["Morning, {name}! Up since three. The toaster needed an engine; you needed this."] = "좋은 아침, {name}! 세 시부터 깨 있었어요. 토스터엔 새 엔진이, 당신껜 이게 필요했죠."
L["Good morning, {name}! The coffee brews itself now, so I had time for this."] = "좋은 아침이에요, {name}! 커피가 이제 혼자 내려져서 이걸 드릴 시간이 생겼어요."
L["Early start, {name}! Best ideas come before breakfast. This was one of them."] = "일찍 시작하네요, {name}! 좋은 생각은 아침 먹기 전에 나오죠. 이것도 그중 하나예요."
L["Morning, {name}! Tinker Town's been clanking since dawn, and so have I. Here!"] = "좋은 아침, {name}님! 땜장이 마을은 새벽부터 덜컹대요. 저도요. 여기요!"
L["Up early, {name}? I dreamt of a better sprocket and couldn't wait. Here!"] = "일찍 나오셨네요, {name}님? 더 좋은 톱니바퀴 꿈을 꿔서 못 참았어요. 여기요!"
L["Morning, {name}! The sun's a bit dim today, so I made you a brighter one."] = "좋은 아침, {name}! 오늘 해가 좀 흐려서 더 밝은 걸 만들어 드렸어요."
L["By my calculations, {name}, you are ninety percent wonderful."] = "내 계산에 따르면, {name}, 넌 90퍼센트 멋져."
L["Who needs a mechanostrider with you around, {name}? Not me!"] = "네가 있는데 기계타조가 왜 필요해, {name}? 난 필요 없어!"
L["Remind me to build you a little hat, {name}. A sensible hat."] = "작은 모자 하나 만들어 줄게, {name}. 실용적인 걸로."
L["Splendid, {name}! Efficiency rating: off the charts!"] = "훌륭해, {name}! 효율 등급: 측정 불가!"
L["Marvellous, {name}! I couldn't have engineered a better bite."] = "멋져, {name}! 내가 설계해도 이보다 좋은 공격은 못 만들어."
L["Ha! Textbook, {name}. I'm writing that one down for Mekkatorque."] = "하! 교과서 그대로야, {name}. 멕카토크 님께 보고해야지."
L["Easy, {name}. Diagnostics say you need rest. Lots of rest."] = "진정해, {name}. 진단 결과: 휴식 필요. 아주 많이."
L["There, there, {name}. Nothing a little patching won't fix."] = "괜찮아, 괜찮아, {name}. 조금만 고치면 다 나아."
L["Hold still, {name}. Bandages first, inventions later."] = "가만있어, {name}. 붕대가 먼저, 발명은 나중이야."
L["The Light rewards kindness, {name}. I'm simply its fastest courier."] = "빛은 친절에 보답합니다, {name}. 저는 가장 빠른 배달부일 뿐이지요."
L["Archenon poros, {name}. Your gift is returned."] = "아케논 포로스, {name}. 받은 선물을 돌려드립니다."
L["Thanks, {name}. I'd offer a lift in the Exodar, but you've seen how it lands."] = "감사합니다, {name}. 엑소다르에 태워 드리고 싶지만, 착륙하는 꼴을 보셨지요."
L["A gift freely given, {name}. The naaru hum a little louder. Returned."] = "아낌없는 선물이군요, {name}. 나루의 노래가 조금 커졌습니다. 보답하지요."
L["Kindly done, {name}. On Argus we'd have carved that in crystal. Here."] = "고맙습니다, {name}. 아르거스였다면 수정에 새겼을 겁니다. 받으십시오."
L["Across a dozen worlds, {name}, kindness is the one tongue I never had to learn."] = "수많은 세계를 떠돌았지만, {name}, 친절만은 배울 필요 없는 언어였습니다."
L["What a kindness, {name}. It almost makes up for the Legion. Almost."] = "이런 친절이라니, {name}. 군단 일이 거의 잊힐 정도입니다. 거의요."
L["Thank you, {name}. I'd say it in Draenei, but that takes eleven minutes."] = "감사합니다, {name}. 드레나이어로 하면 11분이 걸려서요."
L["Thank you, {name}. My people call that a debt of honour. Here."] = "감사합니다, {name}. 우리 종족은 이를 명예의 빚이라 부르지요. 받으십시오."
L["Sargeras once offered my people gifts, {name}. We ran. Yours, I'll keep."] = "살게라스도 선물을 내밀었지요, {name}. 우린 도망쳤고요. 이건 받겠습니다."
L["Thank you, {name}. I've fled demons across the stars, but never from a debt."] = "감사합니다, {name}. 악마는 별 너머로 피했어도 빚은 피한 적이 없습니다."
L["Thank you, {name}. I'll add you to my prayers. The list goes back to Argus."] = "감사합니다, {name}. 기도 목록에 올리지요. 아르거스 때부터 이어진 목록입니다."
L["The Legion took a world from us, {name}. Folk like you keep giving bits back."] = "군단은 우리 세계를 앗아 갔지요, {name}. 그대 같은 이들이 조금씩 돌려줍니다."
L["You gave first, {name}. A prophet would call it an omen. I call it manners."] = "먼저 베푸셨군요, {name}. 예언자는 징조라 하겠지만, 저는 예의라 부르지요."
L["With the Light's compliments, {name}. It asked me to add 'nicely done'."] = "빛이 안부를 전합니다, {name}. '잘하셨다'고 꼭 덧붙이랍니다."
L["Of course, {name}. The naaru guide your steps; this puts a spring in them."] = "물론입니다, {name}. 나루께선 길을, 저는 발걸음을 가볍게."
L["Gladly, {name}. The Light answers those who ask."] = "기꺼이, {name}. 빛은 구하는 이에게 응답합니다."
L["Velen foresaw you asking, {name}. I foresaw saying yes."] = "벨렌께선 청하실 걸 예견하셨지요, {name}. 저는 승낙을 예견했고요."
L["The Light is not rationed, {name}. Take as much as you like."] = "빛은 배급제가 아닙니다, {name}. 마음껏 받으십시오."
L["Of course, {name}. I've outrun the Burning Legion; I can manage this."] = "물론입니다, {name}. 불타는 군단한테서도 도망쳤는데, 이쯤이야."
L["At once, {name}. Hooves planted, crystals humming, here it comes."] = "즉시 하지요, {name}. 발굽 고정, 수정 공명, 갑니다."
L["Gladly, {name}. I followed a talking crystal across the stars. This is easy."] = "기꺼이요, {name}. 말하는 수정을 따라 별을 건넜는데, 이쯤은 쉽지요."
L["Certainly, {name}. Velen taught us patience. Luckily, this takes none."] = "물론입니다, {name}. 벨렌께 인내를 배웠지만, 다행히 이건 쓸 일이 없군요."
L["Gladly, {name}. The naaru never say no. They say 'hmmm', but it means yes."] = "기꺼이, {name}. 나루는 거절하지 않습니다. '흐으음' 하시는데, 그게 승낙이지요."
L["On the Exodar this took three crystals and a prayer, {name}. Here: the prayer."] = "엑소다르에선 수정 셋에 기도 하나가 필요했지요, {name}. 자, 기도 쪽입니다."
L["Of course, {name}. I only refuse demons, and they so rarely say please."] = "물론입니다, {name}. 거절하는 건 악마뿐인데, 그들은 '부탁'을 통 안 하지요."
L["Gladly, {name}. We were refugees long enough to know what asking costs."] = "기꺼이, {name}. 오래 떠돌아 봐서 청하기가 얼마나 어려운지 압니다."
L["Of course, {name}. My people crossed the stars looking for friends. Found one."] = "물론입니다, {name}. 우린 벗을 찾아 별을 건넜지요. 하나 찾았군요."
L["Ask a draenei, {name}: one yes, one blessing, possibly a history lesson."] = "드레나이에게 청하면요, {name}. 승낙 하나, 축복 하나, 어쩌면 역사 강의."
L["The Light is with you, {name}. Go in peace, or at least go prepared."] = "빛이 그대와 함께합니다, {name}. 평안히 가십시오. 안 되면 대비라도 하고."
L["Walk in the Light, {name}. May it shelter you always."] = "빛 속을 걸으십시오, {name}. 빛이 늘 그대를 지켜 주기를."
L["Take this, {name}. My people always travel Light."] = "받으십시오, {name}. 우린 가진 게 빛뿐이라 짐이 늘 가볍지요."
L["Take this, {name}. The Legion is always coming. I'd know."] = "받으십시오, {name}. 군단은 늘 옵니다. 제가 잘 알지요."
L["I'm out of miracles today, {name}. Will {buff} do?"] = "오늘치 기적은 다 썼습니다, {name}. 대신 {buff}, 괜찮겠습니까?"
L["For the road, {name}. Mine has been twenty-five thousand years long."] = "가는 길에 쓰십시오, {name}. 제 길은 2만 5천 년째입니다."
L["Blessed by a naaru, {name}. Well, I stood near one. It still counts."] = "나루의 축복입니다, {name}. 음, 나루 옆에 서 있었지요. 그것도 치는 겁니다."
L["Take this, {name}. It glows a bit. Everything we own does."] = "받으십시오, {name}. 좀 빛납니다. 우리 물건은 다 그렇지요."
L["Here, {name}. We draenei pack for the end of the world. We've had the practice."] = "받으십시오, {name}. 드레나이는 늘 종말 대비 짐을 쌉니다. 연습을 좀 했지요."
L["Take this, {name}. The crystals only hum like that for friends."] = "받으십시오, {name}. 수정은 벗에게만 이렇게 울리지요."
L["The naaru shine on all, {name}. Here is your share."] = "나루는 만인을 비추지요, {name}. 여기 그대의 몫입니다."
L["A stranger shared bread with me on Azuremyst, {name}. I'm still paying it back."] = "하늘안개 섬에서 낯선 이가 빵을 나눠 줬지요, {name}. 아직 갚는 중입니다."
L["Velen sees a thousand futures, {name}. I see one: you, better prepared. Here."] = "벨렌께선 천 가지 미래를 보시지요, {name}. 전 하나만 봅니다. 든든해진 그대."
L["Don't drink from the streams on Bloodmyst, {name}. Do take this."] = "핏빛안개 섬 개울물은 마시지 마십시오, {name}. 이건 받으시고요."
L["Eredar magic from before the fall, {name}. We only kept the good kind. Here."] = "타락 이전 에레다르의 마법입니다, {name}. 좋은 것만 챙겨 왔지요."
L["Archenon poros, {name}! The children of Argus look after one another."] = "아케논 포로스, {name}! 아르거스의 자손은 서로를 돌보지요."
L["Home is where two draenei meet, {name}. Today it's here; this is my welcome."] = "드레나이 둘이 만나는 곳이 고향이죠, {name}. 오늘은 여기고요. 이건 제 환영 인사예요."
L["We crossed the stars together, {name}. Sharing the Light still means something."] = "우린 함께 별을 건넜죠, {name}. 빛을 나누는 건 지금도 의미가 있어요."
L["Tails up, {name}; take this. Argus would be proud of what we made of exile."] = "꼬리 세워요, {name}. 이걸 받아요. 아르거스도 우리가 유배를 이렇게 일군 걸 자랑스러워할 거예요."
L["Two draenei, {name}: fifty thousand years of worry. This should ease yours."] = "드레나이 둘이면, {name}, 오만 년 치 걱정이죠. 이게 당신 걱정을 덜어 줄 거예요."
L["Horns, hooves, hope, {name}, and this. The Legion found no cure for any of it."] = "뿔, 발굽, 희망, {name}, 그리고 이것까지. 군단은 그 무엇에도 치료법을 못 찾았죠."
L["Children of Velen, {name}: exiled, hopeful and dreadfully polite. Hence this."] = "벨렌의 자손이죠, {name}. 유배되고, 희망차고, 지독히 예의 바르고요. 그래서 이거예요."
L["Third world's the charm, {name}. Take this; we're owed one that stays put."] = "세 번째 세상은 다르겠죠, {name}. 이걸 받아요. 우리도 가만있는 세상 하나쯤은 받을 자격이 있어요."
L["There, {name}. I lost a world once; I'm keeping hold of this party."] = "됐어요, {name}. 한때 세상 하나를 잃었죠. 이 일행은 꼭 붙잡고 있을 거예요."
L["Millennia on the run, {name}. Sharing the Light with friends is nicer."] = "수천 년을 도망 다녔죠, {name}. 친구들과 빛을 나누는 게 훨씬 좋아요."
L["The naaru would call sharing Light a fellowship, {name}. I call it good luck."] = "나루라면 빛을 나누는 걸 유대라 부르겠죠, {name}. 전 행운이라 불러요."
L["I've watched worlds end, {name}. With this on you, nothing ahead worries me."] = "세상이 끝나는 걸 봤어요, {name}. 이걸 두른 당신이라면 앞일은 걱정 안 돼요."
L["Stay together, {name}. The Light finds us easier that way; I just proved it."] = "뭉쳐 있어요, {name}. 그래야 빛이 우릴 쉽게 찾죠. 방금 증명했잖아요."
L["Take this; stay close, {name}. We draenei are very good at leaving in a hurry."] = "이거 받고 붙어 있어요, {name}. 우리 드레나이는 서둘러 떠나는 데 아주 능하거든요."
L["Draenei take the long view, {name}. This fight's a footnote. This gift isn't."] = "드레나이는 길게 보죠, {name}. 이 싸움은 각주일 뿐이에요. 이 선물은 아니고요."
L["Here, {name}. Now I go first; anything watching sees a very tall optimist."] = "받아요, {name}. 이제 제가 앞장설게요. 지켜보는 놈은 아주 키 큰 낙천가를 보겠죠."
L["We draenei follow prophets, {name}. Today I'll follow you, blessed as you are."] = "우리 드레나이는 예언자를 따르죠, {name}. 오늘은 축복받은 당신을 따를게요."
L["The Exodar carried thousands, {name}. I'd rather carry this little party. Here."] = "엑소다르는 수천 명을 태웠죠, {name}. 전 이 작은 일행을 태우는 게 더 좋아요. 여기요."
L["Shoulder to shoulder, blessed, {name}. Mine's higher, but the principle holds."] = "축복받고 어깨를 나란히, {name}. 제 어깨가 더 높지만 원칙은 같아요."
L["A short prayer for the party, {name}. The long one would take an age."] = "파티를 위한 짧은 기도입니다, {name}. 긴 건 한 시대가 걸리거든요."
L["The Naaru smile on us, {name}. Rest a moment with me."] = "나루께서 우리에게 미소 지으셔, {name}. 잠시 나와 쉬자."
L["You are a good friend, {name}. Argus never gave me better."] = "좋은 친구야, {name}. 아르거스에도 너 같은 친구는 없었어."
L["Walk with me, {name}. The road is kinder with two."] = "함께 걷자, {name}. 둘이면 길도 다정해."
L["Light be praised, {name}! You fought with a true heart."] = "빛을 찬양하라, {name}! 진실한 마음으로 싸웠구나."
L["Well done, {name}. Velen himself would bless you for that."] = "잘했어, {name}. 벨렌님께서 직접 축복해 주실 거야."
L["Magnificent, {name}. The crystals of the Exodar shine for you."] = "장엄해, {name}. 엑소다르의 수정들이 널 위해 빛나."
L["Be at peace, {name}. The Light is with you, and so am I."] = "평안하렴, {name}. 빛이 함께하고, 나도 함께야."
L["Hush, {name}. Rest now. I will not leave your side."] = "쉿, {name}. 이제 쉬어. 네 곁을 떠나지 않을게."
L["Breathe, {name}. We have outlasted worse than this together."] = "숨 쉬어, {name}. 우린 함께 이보다 더한 것도 견뎠어."
L["Much obliged, {name}. Gilneas never forgets a kindness, and nor does my nose."] = "신세 졌소, {name}. 길니아스는 은혜를 잊지 않소. 내 코도 그렇고."
L["Thank you, {name}. You have my gratitude, and my best howl."] = "고맙소, {name}. 감사의 마음과 회심의 울음소리를 바치오."
L["Thank you, {name}. If worgen had tails, mine would be wagging."] = "고맙소, {name}. 늑대인간에게 꼬리가 있었다면 지금 흔들고 있을 거요."
L["You've made a friend for life, {name}. Loyalty is rather our thing."] = "평생 친구가 생겼구려, {name}. 충성은 우리 특기라오."
L["The beast in me wants to growl, {name}. The Gilnean in me insists on thanks."] = "내 안의 짐승은 으르렁대라 하고, 길니아스인은 감사하라 하는군, {name}."
L["Thank you, {name}. I'd offer a hand, but mine have claws now."] = "고맙소, {name}. 손이라도 내밀고 싶지만, 이젠 발톱이 달려서."
L["We walled ourselves off for years, {name}. You make that look silly."] = "성벽 쌓고 숨어 산 세월이 우스워지는군, {name}. 그대 덕에."
L["Obliged, {name}. You've earned a spot by the fire. The good spot."] = "고맙소, {name}. 난롯가 자리를 드리리다. 제일 좋은 자리로."
L["Thank you, {name}. Gilneas had a word for folk like you: neighbour."] = "고맙소, {name}. 길니아스엔 그대 같은 이를 부르는 말이 있었소. 이웃."
L["Returned, {name}, with a stiff upper lip. The lower one shows teeth; ignore it."] = "보답하오, {name}. 점잖은 미소요. 송곳니가 보이거든 못 본 척하시오."
L["Thank you, {name}. I'd tip my hat, but it doesn't fit over the ears these days."] = "고맙소, {name}. 모자라도 벗어 인사하고 싶은데, 요즘은 귀 때문에 안 맞소."
L["Thank you, {name}. Most folk just scratch my ears and hope for the best."] = "고맙소, {name}. 다들 귀나 긁어 주고 무사하길 빌 뿐인데."
L["Returned, {name}. A Gilnean pays debts; a worgen pays them at a sprint."] = "보답하오, {name}. 길니아스인은 빚을 갚고, 늑대인간은 전력 질주로 갚소."
L["My mother would have had you round for tea, {name}. Thank you."] = "어머니였다면 그대를 차 마시러 불렀을 거요, {name}. 고맙소."
L["Certainly, {name}. Hold still, I don't bite. Much."] = "그러리다, {name}. 가만히 계시오. 물지 않소. 세게는."
L["Right you are, {name}. Stand steady now."] = "좋소, {name}. 자, 흔들리지 말고 서 계시오."
L["Right away, {name}. Stay, now. I've always wanted to say that."] = "바로 하리다, {name}. 자, '기다려.' 늘 해 보고 싶던 말이오."
L["Gladly, {name}. Rain or shine, and in Gilneas it's rain."] = "기꺼이, {name}. 비가 오든 해가 뜨든. 길니아스에선 늘 비지만."
L["Certainly, {name}. Mind the claws."] = "그러리다, {name}. 발톱 조심하시오."
L["Say no more, {name}. These ears heard you before you'd decided to ask."] = "말할 것 없소, {name}. 청하기로 마음먹기도 전에 이 귀가 들었소."
L["Of course, {name}. You asked nicer than the last fellow who threw me a stick."] = "물론이오, {name}. 지난번에 막대기 던진 녀석보다 훨씬 정중하구려."
L["Glad to, {name}. Few people ask a seven-foot wolf for favours. I love it."] = "기꺼이, {name}. 2미터 늑대한테 부탁하는 이는 드물지. 아주 좋소."
L["Certainly, {name}. I'll stay in this form. The other one causes a scene."] = "그러리다, {name}. 이 모습 그대로 하겠소. 다른 모습은 소란이 나서."
L["Straight to business without tea, {name}? How un-Gilnean."] = "차도 없이 바로 본론이오, {name}? 참 길니아스답지 않구려."
L["Of course, {name}. In Gilneas, nobody had to ask twice."] = "물론이오, {name}. 길니아스에선 두 번 청할 필요가 없었소."
L["Of course, {name}. It would be rude to keep you waiting."] = "물론이오, {name}. 기다리게 하는 건 실례지."
L["Of course, {name}. Anything but a bath."] = "물론이오, {name}. 목욕만 빼고 뭐든."
L["Stay off the moors after dark, {name}. Take this."] = "해 지면 황야엔 가지 마시오, {name}. 이걸 받으시오."
L["Keep your wits about you, {name}, and this too. Something is always hunting."] = "정신 바짝 차리게, {name}. 이것도 챙기고. 뭔가는 늘 사냥 중이니까."
L["I'd have brought this sooner, {name}, but I stopped to chase something."] = "더 일찍 가져오려 했소, {name}. 뭘 좀 쫓느라 늦었지만."
L["For you, {name}. No, I don't want a treat. Well. Perhaps a small one."] = "받으시오, {name}. 아니, 간식은 필요 없소. 음. 작은 거라면 몰라도."
L["Gilneans always offer, {name}. The claws are just part of the outfit."] = "길니아스인은 늘 먼저 베푸오, {name}. 발톱은 그냥 옷차림의 일부요."
L["An old Gilnean remedy, {name}. Good for colds, gloom and most curses. Not mine."] = "길니아스 전통 비방이오, {name}. 감기, 우울, 웬만한 저주에 좋소. 내 건 빼고."
L["Run with this, {name}. Trust me, I know about running."] = "이걸 갖고 달리시오, {name}. 달리기라면 내가 좀 알지."
L["Brought you this, {name}. Don't make a fuss over it."] = "가져왔소, {name}. 호들갑 떨지 마시오."
L["Here, {name}. Gilnean roads were never safe alone, and nor are these."] = "받으시오, {name}. 길니아스 길은 혼자 걷기엔 위험했소. 이 길도 마찬가지요."
L["For you, {name}. Not everything that prowls was as well raised as I was."] = "받으시오, {name}. 어슬렁대는 것들이 다 나처럼 교육받진 않았으니."
L["From a Gilnean of good family, {name}. The fur is new; the manners are old."] = "명문가 길니아스인이 드리오, {name}. 털은 새것이지만 예법은 오래됐소."
L["Someone did this for me in Duskhaven once, {name}. I never forgot."] = "예전에 길니아스에서 누가 이렇게 해 줬소, {name}. 잊은 적 없소."
L["Liam would have cried 'For Gilneas!', {name}. I'll just say: for you."] = "리암이라면 '길니아스를 위하여!' 외쳤겠지, {name}. 난 그냥, 그대를 위하여."
L["Tal'doren's druids taught me to leash the beast, {name}. It lets me do this."] = "탈도렌 드루이드들이 짐승을 다스리는 법을 가르쳐 줬소, {name}. 덕분에 이걸 할 수 있소."
L["Take this, {name}, and be careful out there. Advice from someone bitten once."] = "이걸 받게, {name}. 밖에선 조심하고. 한 번 물려 본 사람의 조언일세."
L["Here, {name}. In Gilneas we'd have sent it with a jar of preserves."] = "받으시오, {name}. 길니아스였다면 잼 한 병을 곁들여 보냈을 거요."
L["Take this, {name}. I'd offer my coat, but it's attached."] = "받으시오, {name}. 외투라도 벗어 주고 싶지만, 이건 몸에 붙은 거라."
L["Here, {name}. Chin up, hackles down. Words to live by."] = "받으시오, {name}. 고개는 들고, 털은 눕히고. 좌우명으로 삼을 만하오."
L["The curse binds us, {name}; Gilneas binds us tighter. Here, from one of yours."] = "저주가 우릴 묶지만, {name}, 길니어스는 더 단단히 묶지. 받게, 자네 동족이 주는 걸세."
L["No need to explain the ears to you, {name}, nor to thank me for this."] = "자네한텐 귀 얘기할 필요 없지, {name}. 이걸로 고마워할 필요도 없고."
L["Fur, fog, rain, {name}. Only a Gilnean knows all three. This helps with them."] = "털, 안개, 비, {name}. 셋 다 아는 건 길니어스 사람뿐이지. 이게 도움이 될 걸세."
L["Pack looks after pack, {name}. Always has."] = "무리는 무리를 챙기는 법이오, {name}. 늘 그래 왔소."
L["Shed this badly too, {name}? Take this; I'll knit a third worgen with the rest."] = "자네도 털이 이렇게 빠지나, {name}? 이거 받게. 남은 털로 늑대인간 하나 더 뜨지."
L["Two worgen, {name}, one blessing. Somewhere, a cat's having a very bad day."] = "늑대인간 둘에 축복 하나, {name}. 어딘가의 고양이는 운수 사나운 날이겠군."
L["Here, {name}. Works in either form; I forget which one I left home in."] = "받게, {name}. 어느 모습이든 통하지. 난 집을 어느 모습으로 나섰는지 까먹거든."
L["Gilnean to Gilnean, {name}: the best-mannered wolves in Azeroth share. Here."] = "길니어스 사람끼리, {name}. 아제로스에서 제일 예의 바른 늑대들은 나눌 줄 알지. 받게."
L["Pack rules, {name}: nobody wanders off, everyone gets one, no talk of fleas."] = "무리 규칙일세, {name}. 아무도 안 흩어지고, 다들 하나씩 받고, 벼룩 얘긴 금지."
L["A pack again, {name}, someone to look after. I hadn't known how I'd missed it."] = "다시 무리가 생겼군, {name}. 챙길 사람이 있다는 게 이렇게 그리웠을 줄이야."
L["Take this, {name}. I smell trouble first; it's the curse's one perk."] = "이걸 받게, {name}. 난 말썽 냄새를 먼저 맡지. 저주의 유일한 장점일세."
L["There, {name}. If I howl, it's a battle cry. Howl back if you like."] = "됐네, {name}. 내가 울부짖으면 함성이야. 원하면 같이 울부짖게."
L["That'll keep you up, {name}. Lead on. I'll trot. Undignified, but quick."] = "이거면 버틸 걸세, {name}. 앞장서게. 난 종종걸음으로 가지. 체면은 없어도 빠르거든."
L["Here, {name}. If I stare at a wall, something's behind it. Or it's a wall."] = "받게, {name}. 내가 벽을 노려보면 뒤에 뭔가 있는 걸세. 아니면 그냥 벽이고."
L["Years on the Greymane Wall, {name}. A line held with you, blessed? A holiday."] = "그레이메인 성벽에서 몇 해를 보냈지, {name}. 축복받은 자네랑 전열 지키기? 휴가지."
L["Take this for the mauling, {name}. After, a proper cup of tea."] = "물어뜯는 판엔 이게 필요하지, {name}. 끝나면 제대로 된 차 한 잔."
L["Here, {name}, so you mend as quickly as I do. Worgen mend quickly."] = "받게, {name}. 나처럼 빨리 낫도록. 늑대인간은 금방 낫거든."
L["That sees you to the rest, {name}. I'll take first watch; I hear everything."] = "이거면 쉴 때까지 버틸 걸세, {name}. 첫 불침번은 내가 서지. 다 들리니까."
L["Take this, {name}, and stay together. Being a lone wolf is overrated."] = "이걸 받게, {name}. 그리고 뭉쳐 있게. 외톨이 늑대는 과대평가됐어."
L["Night again, {name}: my best and my worst. Giving you this is the best part."] = "또 밤이군, {name}. 내 최고이자 최악의 시간. 자네한테 이걸 주는 게 최고인 부분이지."
L["Look at that moon, {name}. Gilneas taught us not to trust it. Trust this."] = "저 달 좀 보게, {name}. 길니어스는 달을 믿지 말라 가르쳤지. 이걸 믿게."
L["Gilneas at night was fog and footsteps, {name}. Now the footsteps bring this."] = "밤의 길니어스는 안개와 발소리였지, {name}. 이제 그 발소리가 이걸 가져왔네."
L["Curfew in Gilneas was sundown, {name}. Take this; there's a reason it was."] = "길니어스 통행금지는 해 질 녘이었지, {name}. 이걸 받게. 다 이유가 있었으니."
L["Something's rustling out there, {name}. Take this; stay close. I'll look."] = "밖에서 뭔가 부스럭거리는군, {name}. 이거 받고 붙어 있게. 내가 보고 오지."
L["Past dark, {name}: ears up, nose working, manners on. Manners means this."] = "날이 저물었군, {name}. 귀 세우고, 코 킁킁, 예절 장착. 예절이란 게 바로 이거지."
L["Morning, {name}. The rug by the fire was warm, but I got up to give you this."] = "좋은 아침, {name}. 난롯가 깔개가 따뜻했지만, 이걸 주려고 일어났지."
L["Smells like rain this morning, {name}. Here's something to keep you dry inside."] = "오늘 아침엔 비 냄새가 나는군, {name}. 속까지 젖지 않게 이걸 주지."
L["Up already, {name}? I've prowled since first light, waiting to give you this."] = "벌써 일어났나, {name}? 새벽부터 어슬렁거리며 이걸 주려고 기다렸지."
L["Morning, {name}. Tea, toast, a shave, and this. The shave takes longer now."] = "좋은 아침, {name}. 차, 토스트, 면도, 그리고 이것. 요즘은 면도가 오래 걸리지."
L["Morning, {name}. The birds woke me, so I woke the birds. You just get this."] = "좋은 아침, {name}. 새들이 날 깨워서 나도 새들을 깨웠지. 자넨 이것만 받게."
L["Morning, {name}. The fog's lifting, as it never did in Gilneas. Take this."] = "좋은 아침, {name}. 안개가 걷히는군. 길니어스에선 절대 없던 일이지. 이걸 가져가게."
L["We both know the wild, {name}. Stay close to me."] = "우리 둘 다 야생을 알지, {name}. 내 곁에 있어."
L["Gilneas lost much, {name}. It never gave me a better friend."] = "길니아스는 많은 걸 잃었어, {name}. 하지만 넌 남았지."
L["Steady, {name}. You and I don't need a wall to feel at home."] = "진정해, {name}. 너와 난 성벽이 없어도 집처럼 편하잖아."
L["Ha! Well hunted, {name}! That's the Gilnean spirit."] = "하! 잘 사냥했어, {name}! 그게 길니아스의 정신이지."
L["That's it, {name}. Not one step back. Gilneas would be proud."] = "그거야, {name}. 한 발도 안 물러섰어. 길니아스의 자랑이야."
L["Brilliant, {name}. The Greymane Wall never held so well."] = "훌륭해, {name}. 그레이메인 성벽도 이렇게는 못 버텨."
L["Easy, {name}. The beast in me knows hurt. Rest now."] = "진정해, {name}. 내 안의 야수도 아픔을 알아. 쉬어."
L["Shh, {name}. I'm here. Let the fog roll by while you rest."] = "쉿, {name}. 내가 있어. 쉬는 동안 안개는 흘러가게 둬."
L["Stay down, {name}. I'll stand watch until you're ready."] = "누워 있어, {name}. 네가 괜찮아질 때까지 지킬게."
L["Throm-ka, {name}! Honour is repaid."] = "쓰롬카, {name}! 명예로 갚는다!"
L["You give freely, {name}. I return the favour."] = "선뜻 베풀었군, {name}. 나도 갚아 주지."
L["Orcs keep their thanks short, {name}. Thanks."] = "오크는 감사도 짧다, {name}. 고맙다."
L["Orcs return every blow twice, {name}. The kind ones too."] = "오크는 한 대 맞으면 두 대로 갚는다, {name}. 호의도 마찬가지다."
L["You helped me, I help you, {name}. That is the old way."] = "네가 도왔으니 나도 돕는다, {name}. 그게 옛 방식이다."
L["In the old days I'd have repaid you with a boar, {name}. This keeps better."] = "옛날 같으면 멧돼지로 갚았겠지, {name}. 이건 안 썩는다."
L["Owing somebody itches worse than Durotar sand, {name}. There. Itch gone."] = "빚지면 듀로타 모래보다 더 근질거린다, {name}. 됐다. 이제 안 가렵다."
L["Strong stuff, {name}. I could wrestle a kodo now. So can you."] = "센 거로군, {name}. 코도랑 씨름도 하겠다. 너도 이제 된다."
L["Ambushed by kindness, {name}. No orc trains for that. Returned in full."] = "친절에 기습당했다, {name}. 오크도 그건 훈련 안 한다. 그대로 갚는다."
L["Honour is a debt, {name}, and orcs pay on the spot."] = "명예는 빚이다, {name}. 오크는 그 자리에서 갚는다."
L["An orc remembers a kindness like a scar, {name}: fondly, and for good."] = "오크는 친절을 흉터처럼 기억한다, {name}. 애틋하게, 평생."
L["I'd give you my axe, {name}, but we're not that close yet. Take this."] = "도끼를 주고 싶지만, {name}, 아직 그만큼 친하진 않다. 이거나 받아라."
L["Thanks, {name}. My wolf growled at you. That's how he says it."] = "고맙다, {name}. 내 늑대가 으르렁댔지? 그게 걔 인사다."
L["I've had gifts from shamans and chieftains, {name}. None came so freely."] = "주술사, 족장한테도 선물을 받아 봤다, {name}. 이렇게 선뜻 준 건 없었다."
L["We once took strength from demons, {name}. Yours comes on far better terms."] = "한때 우린 악마한테 힘을 받았다, {name}. 네 건 조건이 훨씬 낫군."
L["The spirits saw that, {name}. They'll remember it, and so will I."] = "정령들이 봤다, {name}. 그들도 기억할 거고, 나도 기억한다."
L["I'll carve that on my axe handle, {name}. Next to the notches. Thank you."] = "도끼 자루에 새겨 두마, {name}. 처치 표시들 옆에. 고맙다."
L["Kindness unasked is rare as rain in Durotar, {name}. Returned."] = "청하지 않은 친절은 듀로타의 비만큼 귀하다, {name}. 갚는다."
L["In my clan, {name}, a gift is answered with a bigger one. Here."] = "우리 부족에선, {name}, 선물은 더 큰 걸로 갚는다. 받아라."
L["A Frostwolf never counts what a friend gives, {name}. Only what he gives back."] = "서리늑대는 친구가 준 건 세지 않는다, {name}. 갚을 것만 센다."
L["The camps taught us who our friends are, {name}. You're one. Here."] = "수용소에서 누가 친구인지 배웠다, {name}. 너도 친구다. 받아라."
L["Thanks, {name}. Thrall says the Horde's strength is its friends. You count."] = "고맙다, {name}. 스랄은 호드의 힘이 친구라 했다. 너도 거기 든다."
L["Good. Strong. Kind. Three things I respect, {name}. Have this."] = "좋다. 강하다. 친절하다. 내가 존중하는 세 가지다, {name}. 이거 받아라."
L["Grom would have roared his thanks, {name}. I'll spare your ears and send this."] = "그롬이었으면 고맙다고 포효했겠지, {name}. 네 귀를 생각해서 이걸로 대신한다."
L["Dabu, {name}. It is done."] = "다부, {name}. 다 됐다."
L["Hold still, {name}. Strength for the fight ahead."] = "가만있어라, {name}. 다가올 싸움을 위한 힘이다."
L["Ask an orc for help and you get it, {name}. Ask for subtlety and you wait."] = "오크한테 도움을 청하면 바로 준다, {name}. 섬세함을 청하면 기다려야 하고."
L["Help, yes. Hugging, no. Hold still, {name}."] = "도움은 준다. 포옹은 안 한다. 가만있어라, {name}."
L["You want {buff}? You have {buff}, {name}. Next."] = "{buff} 원하나, {name}? 옜다, {buff}. 다음."
L["Don't flinch, {name}. My helping face looks exactly like my fighting face."] = "움찔하지 마라, {name}. 돕는 얼굴이 싸우는 얼굴이랑 똑같을 뿐이다."
L["Short question, short answer, {name}: yes."] = "짧은 질문엔 짧은 대답이다, {name}. 그래."
L["Done, {name}. I was a peon once; I never refuse honest work."] = "됐다, {name}. 일꾼 출신이라 정직한 일은 거절 안 한다."
L["A challenge, {name}? Ah, a request. I accept either way."] = "도전이냐, {name}? 아, 부탁이군. 어느 쪽이든 받는다."
L["Yes, {name}. I was sharpening my axe, but it'll keep. It always keeps."] = "그래, {name}. 도끼 갈던 참이지만 괜찮다. 어차피 맨날 간다."
L["In the Valley of Honor this would cost you a duel, {name}. For you, a nod."] = "명예의 골짜기라면 결투 한 판감이다, {name}. 넌 끄덕 한 번이면 된다."
L["Now, {name}? Now. Orcs never learned the word 'later'."] = "지금, {name}? 지금 한다. 오크는 '나중에'란 말을 안 배웠다."
L["One {buff}, {name}. Orc style: fast, direct, a bit too hard."] = "{buff} 하나다, {name}. 오크식이다. 빠르고, 곧고, 좀 세게."
L["Stand still, {name}. I aim this like a throwing axe, and I rarely miss."] = "가만있어라, {name}. 투척 도끼처럼 던진다. 빗나가는 일은 드물다."
L["Lok'tar, {name}. It means 'victory'. Today it also means 'yes'."] = "록타르, {name}. '승리'란 뜻이다. 오늘은 '그래'란 뜻도 된다."
L["Done, {name}. If you need anything carried, hit or shouted at, ask again."] = "됐다, {name}. 들 거, 팰 거, 소리 지를 거 있으면 또 말해라."
L["You ask straight, {name}. I answer straight. Here."] = "곧게 묻는군, {name}. 나도 곧게 답한다. 받아라."
L["The shamans say the spirits help those who stand still, {name}. Stand still."] = "주술사들 말이, 정령은 가만있는 자를 돕는다더군, {name}. 가만있어라."
L["A good request, {name}: clear, brave and short. Like a good battle plan."] = "좋은 부탁이다, {name}. 분명하고, 대담하고, 짧다. 좋은 작전처럼."
L["Done, {name}. Thrall says help freely. I say help quickly. Both right."] = "됐다, {name}. 스랄은 기꺼이 도우라 했다. 난 빨리 도우라 한다. 둘 다 맞다."
L["Lok'tar ogar, {name}! Take this into battle. A tavern brawl also counts."] = "록타르 오가르, {name}! 이걸 품고 전장으로 가라. 술집 싸움도 전장이다."
L["Blood and thunder, {name}! Take my strength and go earn your glory."] = "피와 천둥이다, {name}! 내 힘을 받아 영광을 쟁취해라."
L["Among orcs, {name}, making you stronger is how we say we like you."] = "오크들 사이에선, {name}, 강하게 만들어 주는 게 좋아한다는 뜻이다."
L["An orc giving gifts unasked? Tell no one, {name}. It ruins the image."] = "오크가 먼저 선물을 줬다고? 아무한테도 말하지 마라, {name}. 이미지 망친다."
L["The Warchief wants us diplomatic, {name}. This is my diplomacy."] = "대족장이 외교적으로 굴라더군, {name}. 이게 내 외교다."
L["Take this strength, {name}, and hit something for me. Or set it on fire."] = "이 힘을 받아라, {name}. 날 위해 뭐든 두들겨 패. 아니면 불 질러."
L["Don't thank me, {name}. Just win, and do it loudly."] = "고마워하지 마라, {name}. 이기기만 해라. 요란하게."
L["I'd make a speech, {name}, but it's mostly shouting. Just take it."] = "연설이라도 하고 싶지만, {name}, 대부분 고함이다. 그냥 받아라."
L["An orc at your back, {name}, even when I'm not there. Take this."] = "내가 없을 때도 네 등 뒤엔 오크가 있다, {name}. 이거 받아라."
L["'Strike first,' Grom always said, {name}. So: here, before you could ask."] = "'먼저 쳐라.' 그롬이 늘 하던 말이다, {name}. 그래서 청하기 전에 준다."
L["Take it, {name}. A grunt who walks past a comrade gets a talking-to. From me."] = "받아라, {name}. 전우를 지나치는 그런트는 혼난다. 나한테."
L["Frostwolves share the hunt, {name}. I caught nothing today, so share this."] = "서리늑대는 사냥감을 나눈다, {name}. 오늘은 빈손이라 이거라도 나눈다."
L["Walk the Durotar way, {name}: head up, sun on your neck, my strength in you."] = "듀로타 식으로 걸어라, {name}. 고개 들고, 목덜미엔 햇볕, 몸엔 내 힘을."
L["Here, {name}. The spirits favour the generous."] = "받아라, {name}. 정령은 베푸는 자를 아낀다."
L["Orcs give two things freely, {name}: advice and this. Skip the advice."] = "오크가 공짜로 주는 건 둘이다, {name}. 충고랑 이거. 충고는 넘겨라."
L["The Barrens don't end, {name}. They just get more zhevra. Take this."] = "불모의 땅엔 끝이 없다, {name}. 얼룩말만 늘어난다. 이거 받아라."
L["Strength for your arm, {name}. The honour, I see, you brought yourself."] = "팔에 힘을 주마, {name}. 명예는 이미 챙겨 왔군."
L["My wolf wanted you to have his bone, {name}. I talked him down to this."] = "내 늑대가 너한테 뼈다귀를 주고 싶어 했다, {name}. 이걸로 합의 봤다."
L["Any grunt in Razor Hill would do the same, {name}. Most would shout first."] = "칼바위 언덕 그런트라면 누구든 이렇게 한다, {name}. 대부분 소리부터 지르겠지만."
L["For the fight ahead, {name}. There's always one. Orcs plan for it."] = "다가올 싸움을 위해서다, {name}. 싸움은 늘 있다. 오크는 그걸 대비한다."
L["We were slaves once, {name}. Now we choose whom we help. Today, it's you."] = "우린 한때 노예였다, {name}. 이제 누굴 도울지 우리가 고른다. 오늘은 너다."
L["Go with this, {name}. Let them hear you coming. Or don't. Surprise works too."] = "이걸 지니고 가라, {name}. 놈들이 네 발소리를 듣게. 아니면 말고. 기습도 통하니까."
L["A gift from Durotar, {name}. Like the land: rough, warm and short on shade."] = "듀로타의 선물이다, {name}. 그 땅처럼 거칠고, 뜨겁고, 그늘이 없다."
L["The elements are fickle, {name}. I am not. Take this."] = "정령은 변덕스럽다, {name}. 나는 아니다. 받아라."
L["Strength, {name}. Not the kind you lift. The kind you keep."] = "힘이다, {name}. 드는 힘 말고. 버티는 힘."
L["Nobody crosses the Barrens alone if an orc can help it, {name}. Here."] = "오크가 있는 한 불모의 땅을 혼자 건너는 자는 없다, {name}. 받아라."
L["Throm-ka, {name}! The blood of the clans runs strong in you. Stronger now."] = "스롬카, {name}! 네 안에 부족의 피가 힘차게 흐른다. 이제 더 힘차게."
L["An orc, {name}! Here: somebody who shouts at my volume deserves this."] = "오크로군, {name}! 자, 나만큼 크게 외치는 놈은 이걸 받을 자격이 있지."
L["Frostwolf, Warsong, Blackrock, {name}: we argue like family, and share like it."] = "서리늑대, 전쟁노래, 검은바위, {name}. 우린 가족처럼 싸우고, 가족처럼 나눈다."
L["Between orcs no words are needed, {name}. Good; I'm out of them. Take this."] = "오크끼리는 말이 필요 없지, {name}. 다행이다. 할 말도 다 떨어졌거든. 받아라."
L["Grunt or shaman, {name}, the same stubborn blood. Here's more strength for it."] = "그런트든 주술사든, {name}, 똑같이 고집 센 피다. 그 피에 힘을 더 주마."
L["Two orcs, {name}, and nobody's shouted yet. This the shamans will call an omen."] = "오크 둘인데, {name}, 아직 아무도 소리 안 질렀어. 이건 주술사들이 징조라 하겠군."
L["Our clans probably feuded once, {name}. Everybody's did. Let this settle it."] = "우리 부족끼리도 원수였겠지, {name}. 다들 그랬으니까. 이걸로 끝내자."
L["Between orcs, {name}, 'victory or death'. This should tilt it towards victory."] = "오크끼리 하는 말, {name}. '승리 아니면 죽음'. 이걸로 승리 쪽에 무게를 싣지."
L["Your tusks and mine have seen worse days, {name}. With this, today's better."] = "네 엄니랑 내 엄니는 더 험한 날도 봤지, {name}. 이거면 오늘은 낫겠군."
L["The plan, {name}: you take this, we hit it. Questions? No? Good plan."] = "작전이다, {name}. 넌 이걸 받고, 우린 팬다. 질문? 없나? 좋은 작전이군."
L["A true warband, {name}: loud, angry, blessed, and on the same side for once."] = "진짜 전투부대다, {name}. 시끄럽고, 성났고, 축복받았고, 웬일로 다 한편이군."
L["Stay with the warband, {name}. Strength in numbers, in axes, and in this."] = "전투부대에서 떨어지지 마라, {name}. 힘은 머릿수에, 도끼에, 그리고 이것에 있다."
L["Take this so I needn't carry you out, {name}. I would. Complaining all the way."] = "내가 널 업고 나갈 일 없게 이걸 받아라, {name}. 업긴 할 거다. 내내 투덜대면서."
L["Fight well with this, {name}, and tonight you share our fire. And our boasting."] = "이걸로 잘 싸워라, {name}. 그럼 오늘 밤 우리 모닥불을 나눠 주마. 허풍도."
L["That's courage, {name}. Nobody runs now. Walking briskly away is allowed."] = "용기를 줬다, {name}. 이제 아무도 안 도망친다. 잰걸음으로 물러나는 건 허용."
L["Here, {name}. Now I go first. I have the thickest skull here, and I'm proud."] = "받아라, {name}. 이제 내가 앞장선다. 여기서 내 두개골이 제일 두껍지. 자랑스럽게."
L["When the drums start, {name}, charge with this in you. No drums? I'll hum."] = "북소리가 울리면, {name}, 이걸 품고 돌격해라. 북이 없다고? 내가 흥얼거리지."
L["That's for your front, {name}. Watch my back; the front's what I hit."] = "그건 네 앞을 위한 거다, {name}. 내 등은 네가 봐라. 앞은 내가 패는 쪽이니."
L["One clan today, {name}: Whoever Showed Up. Its members get one of these."] = "오늘은 한 부족이다, {name}. '모인 놈들' 부족. 부족원은 이걸 하나씩 받는다."
L["Take this, {name}. Anything big through that door is mine. Bigger, ours."] = "받아라, {name}. 저 문으로 큰 놈이 오면 내 거다. 더 큰 놈은 우리 거고."
L["Scars are stories, {name}. With this, let's all come out with short ones."] = "흉터는 이야기다, {name}. 이거면 다들 짧은 이야기만 갖고 나오겠지."
L["Old chieftains had war councils, {name}. We have me pointing, and this."] = "옛 족장들은 전쟁 회의를 열었지, {name}. 우린 손가락질하는 나랑 이게 있다."
L["Take this before I charge, {name}. If I charge early, it's tradition."] = "내가 돌격하기 전에 받아라, {name}. 일찍 돌격하면 그건 전통이다."
L["Form up, {name}, and take this! Shamans in the middle, fools at the front. Me."] = "대열 맞춰라, {name}, 그리고 이걸 받아! 주술사는 가운데, 바보는 맨 앞. 나다."
L["Tonight we feast, {name}. First we earn it, and this will help."] = "오늘 밤엔 잔치다, {name}. 먼저 벌어야지. 이게 도와줄 거다."
L["Take this, {name}. If I fall, sing about it loudly in Orgrimmar. Lie a little."] = "받아라, {name}. 내가 쓰러지면 오그리마에서 크게 노래해라. 좀 부풀려서."
L["Strength and honour, {name}. The honour's yours; the strength I just gave you."] = "힘과 명예다, {name}. 명예는 네 것이고, 힘은 방금 내가 줬다."
L["Strong and loyal, {name}. A true companion of the Horde."] = "강하고 충직하구나, {name}. 진정한 호드의 동료야."
L["Rest a while, {name}. Even a warrior needs a moment of peace."] = "좀 쉬어, {name}. 전사에게도 평화의 순간은 필요해."
L["The spirits chose well when they sent you to me, {name}."] = "정령들이 널 내게 보낸 건 탁월한 선택이었어, {name}."
L["Lok'tar, {name}! You fought with honor!"] = "록타르, {name}! 명예롭게 싸웠다!"
L["Well fought, {name}! You'd shame half the warriors in Orgrimmar."] = "잘 싸웠다, {name}! 오그리마 전사 절반은 부끄러워하겠군."
L["Strength and honor, {name}. That kill was yours."] = "힘과 명예를, {name}. 그 사냥감은 네 몫이었어."
L["Easy, {name}. You bled for us both. Rest now."] = "진정해, {name}. 우리 둘을 위해 피를 흘렸지. 이제 쉬어."
L["Breathe, {name}. A true warrior rises again. Take your time."] = "숨 쉬어, {name}. 진정한 전사는 다시 일어서. 천천히 해."
L["Stay down, {name}. I'll guard you; no blade gets past me."] = "누워 있어, {name}. 내가 지킬게. 어떤 칼날도 못 지나가."
L["Thank you, {name}. It would warm my heart, if it still beat."] = "고맙군, {name}. 심장이 아직 뛴다면 따뜻해졌을 텐데."
L["Such warmth, for one so cold? Returned in full, {name}."] = "이리 차가운 자에게 온기라니? 고스란히 돌려주지, {name}."
L["Thank you, {name}. I'd blush, but the blood stopped reaching my face."] = "고맙군, {name}. 얼굴이라도 붉히고 싶지만, 피가 거기까지 안 올라가서."
L["My undying gratitude, {name}. For once, the phrase is accurate."] = "죽어도 잊지 못할 은혜요, {name}. 이번만은 말 그대로요."
L["Most kind, {name}. You've lifted me from 'deceased' to 'mildly deceased'."] = "친절하군, {name}. 덕분에 '사망'에서 '약간 사망'이 됐소."
L["The last gift I got was the plague, {name}. Yours is a big improvement."] = "마지막으로 받은 선물이 역병이었소, {name}. 이건 장족의 발전이군."
L["Sylvanas says we repay every debt, {name}. She rarely means the nice ones."] = "실바나스는 빚은 다 갚으라 하지, {name}. 좋은 빚을 말하는 일은 드물지만."
L["Repaid at once, {name}. We Forsaken never carry debts. They rot."] = "바로 갚소, {name}. 포세이큰은 빚을 묵히지 않소. 썩으니까."
L["Thank you, {name}. I'll keep this somewhere safe. My ribcage has room."] = "고맙군, {name}. 안전한 데 두겠소. 갈비뼈 사이에 자리가 넉넉하니."
L["Kindness returned, {name}. Even the flies around me look impressed."] = "친절을 돌려주오, {name}. 내 주위 파리들도 감동한 눈치군."
L["I'll drink to you tonight, {name}. It all leaks out, but it's the thought."] = "오늘 밤 그대를 위해 한잔하겠소, {name}. 다 새어 나가도 마음이 중요하니."
L["Thank you, {name}. You've made my list of reasons to keep going. It's short."] = "고맙군, {name}. 계속 버틸 이유 목록에 올랐소. 목록이 짧긴 하지만."
L["Thank you, {name}. No contract, no fine print. Varimathras should take notes."] = "고맙군, {name}. 계약서도 깨알 조항도 없다니. 바리마트라스가 배워야겠군."
L["Grave dirt and gratitude, {name}: all I own. You'll prefer the gratitude."] = "무덤 흙과 고마움, {name}. 내 재산은 그게 다요. 고마움 쪽이 낫겠지."
L["I'd have Lordaeron's bells rung for you, {name}, but they only do funerals now."] = "로데론의 종을 울려 주고 싶지만, {name}, 요즘은 장례식에만 울리오."
L["Thank you, {name}. Next time I'm in Brill, I'll name a pumpkin after you."] = "고맙군, {name}. 브릴에 가면 호박 하나에 그대 이름을 붙이겠소."
L["Most of the living wouldn't have bothered, {name}. I'll resent them, not you."] = "산 자들은 대개 신경도 안 썼을 거요, {name}. 원망은 그들 몫이오. 그대 말고."
L["Better than anything I've pulled out of Undercity's sewers, {name}. Thanks."] = "언더시티 하수도에서 건진 어떤 것보다 낫군, {name}. 고맙소."
L["Thank you, {name}. One tip in return: never drink what an apothecary hands you."] = "고맙소, {name}. 답례로 조언 하나. 약제사가 건네는 건 절대 마시지 마시오."
L["Thank you, {name}. I'd shake your hand, but I'd like to keep mine attached."] = "고맙소, {name}. 악수는 사양하오. 손이 떨어질까 봐."
L["You've done what the apothecaries never could, {name}: made me feel something."] = "약제사들도 못 한 일이오, {name}. 내가 뭔가를 느끼다니."
L["A gift for the dead, {name}? Most people bring flowers. Then they run."] = "망자에게 선물이오, {name}? 보통은 꽃을 두고 도망가던데."
L["Gratitude, {name}. Freshly exhumed, barely used."] = "감사를 드리오, {name}. 갓 파낸 거라 거의 새것이오."
L["That tingled, {name}. Either that was you, or something's nesting in me again."] = "찌릿하군, {name}. 그대 덕이오, 아니면 또 뭐가 둥지 틀었나?"
L["Bless you too, {name}. Not literally, please; the Light stings. Thank you."] = "당신께도 축복을, {name}. 말 그대로는 말고요. 빛은 따갑거든요. 고마워요."
L["Thank you, {name}. If anything of mine drops off, keep it. A little souvenir."] = "고마워요, {name}. 제 몸에서 뭐가 떨어지면 가지세요. 작은 기념품이에요."
L["Nicest spell cast on me since Arthas, {name}. Low bar, but you cleared it."] = "아서스 이후 최고의 주문이오, {name}. 기준은 낮지만 통과요."
L["I'll have the apothecaries name a plague after you, {name}. A small one."] = "약제사더러 그대 이름 딴 역병을 짓게 하리다, {name}. 작게."
L["I'll rest easier now, {name}. Not in peace, mind. Just easier."] = "이제 편히 눕겠소, {name}. 고이 잠들진 않고, 그냥 편히."
L["Please don't tell the Dark Lady I was nice to somebody, {name}."] = "내가 친절했단 건 어둠의 여왕께 비밀이오, {name}."
L["Here's {buff}, {name}. Fresh, unlike everything else about me."] = "{buff} 받으시오, {name}. 나와 달리 신선하오."
L["Kindness, {name}? I checked it for poison out of habit. It's clean. So is this."] = "친절이라, {name}? 버릇처럼 독부터 봤소. 깨끗하오. 이것도."
L["You've put a spring in my step, {name}. Possibly literally. Something's loose."] = "발걸음이 가벼워졌소, {name}. 진짜로. 뭐가 빠졌나 보오."
L["Death took my pulse, my looks and my sense of smell, {name}. Not my manners."] = "죽음이 맥박, 얼굴, 후각은 앗아 갔소, {name}. 예의는 남았지."
L["Thanks, {name}. Somewhere in Brill, a ghoul is jealous of me right now."] = "고맙소, {name}. 지금쯤 브릴의 구울 하나가 날 부러워하겠군."
L["I'd put you in my will, {name}, but it was read years ago."] = "유언장에 넣고 싶소만, {name}, 몇 년 전에 이미 읽혔소."
L["That's going on my headstone, {name}. Under the bit that's already there."] = "묘비에 새기겠소, {name}. 이미 새겨진 글 아래에."
L["Thank you, {name}. Don't mind the smell. It's not personal, it's posthumous."] = "고맙소, {name}. 냄새는 사적인 게 아니라 사후적인 거요."
L["Thank you, {name}. Most people only cast on me to make me lie back down."] = "고맙소, {name}. 다들 날 도로 눕히려고만 주문을 거는데."
L["Thank you, {name}. I'll have Mordo stitch that in, so it can't fall out."] = "고맙소, {name}. 모르도에게 꿰매 달라 하겠소. 빠지지 않게."
L["Faranell will want to know how you did that, {name}. Don't tell him. Thank you."] = "파라넬이 어떻게 한 건지 알고 싶어 할 거요, {name}. 말하지 마시오. 고맙소."
L["Kindly done, {name}. I'd offer you a seat, but mine came with a lid."] = "친절하군, {name}. 자리를 권하고 싶지만, 내 자리엔 뚜껑이 달려 있소."
L["Steadier hands than the man who sewed my arm on, {name}. Thank you."] = "내 팔을 꿰맨 자보다 손이 차분하군, {name}. 고맙소."
L["First time in years I've been improved without a needle, {name}. Thanks."] = "바늘 없이 나아진 건 몇 년 만이오, {name}. 고맙소."
L["Thank you, {name}. If I twitch, don't be alarmed. It means I'm pleased."] = "고마워요, {name}. 제가 움찔해도 놀라지 마세요. 기쁘다는 뜻이에요."
L["Gratitude, {name}, from what remains of me. Most of it. The important parts."] = "남은 내 전부로 감사하오, {name}. 거의 다요. 중요한 부분은."
L["You'd make a fine apothecary, {name}. That's the worst I'll ever say of you."] = "그대는 훌륭한 약제사가 되겠소, {name}. 그게 내가 그대에게 할 최악의 말이오."
L["Tell nobody in Brill about this, {name}. I've a reputation for being dreadful."] = "브릴에선 아무에게도 말하지 마시오, {name}. 지독하다는 평판이 있으니."
L["Last one to look after me was a necromancer, {name}. You're much better at it."] = "마지막으로 날 돌본 건 강령술사였소, {name}. 그대가 훨씬 낫군."
L["People rarely put anything into a Forsaken, {name}. Usually it's a sword."] = "포세이큰에게 뭘 넣어 주는 이는 드물지, {name}. 보통은 칼이오."
L["For that, {name}, I'll stop scowling a while. No promises; the face is set."] = "이 보답으로, {name}, 잠시 찡그리는 걸 멈추죠. 장담은 못 해요. 얼굴이 굳었거든요."
L["I'd write you a note, {name}, but my writing hand's at the stitcher's."] = "쪽지라도 쓰고 싶소만, {name}, 글 쓰는 손이 수선집에 가 있소."
L["Deathknell gave me a shovel and a grudge, {name}. You gave me something better."] = "죽음의 종소리는 내게 삽 한 자루와 원한을 줬지, {name}. 그대는 더 나은 걸 줬소."
L["A credit to the living, {name}, thanked by the dead. Not fierce competition."] = "산 자들의 자랑이군요, {name}. 죽은 자가 감사를 전하죠. 경쟁이 치열하진 않지만."
L["Into the ledger it goes, {name}. In ink this time, not the other stuff."] = "장부에 적어 두겠소, {name}. 이번엔 잉크로. 그 다른 액체 말고."
L["The Dark Lady says nothing is free, {name}. She hasn't met you."] = "어둠의 여왕께선 공짜는 없다 하셨소, {name}. 그대를 못 만나 보셨지."
L["I feel that in my bones, {name}. Mostly because they show."] = "뼛속까지 느껴지오, {name}. 뼈가 드러나 있어서 그런 것도 있지만."
L["Mother said always repay a kindness, {name}. She's in Brill now. Under it."] = "어머니는 은혜는 꼭 갚으라 하셨소, {name}. 지금은 브릴에 계시오. 땅 밑에."
L["Shadow I shrug off, {name}. Kindness gets right through. Thank you."] = "암흑은 내게 튕겨 나가오, {name}. 친절은 그대로 스며드는군. 고맙소."
L["I can't feel much these days, {name}, so I'll take your word it was lovely."] = "요즘은 느끼는 게 별로 없소, {name}. 좋았다는 그대 말을 믿겠소."
L["Nobody's wished me a long life in years, {name}. I've got one anyway. Thanks."] = "장수를 빌어 준 이가 몇 년 만이오, {name}. 어차피 오래 살겠지만. 고맙소."
L["Cannibalize is for enemies, {name}. Friends get {buff}."] = "시체 먹기는 적에게나 쓰지, {name}. 친구에겐 {buff}를 주오."
L["The will of the Forsaken shrugs off every charm, {name}. Not yours, it seems."] = "포세이큰의 의지는 어떤 매혹도 떨쳐 내오, {name}. 그대 것만은 예외인가 보오."
L["My jaw's wired on, {name}, so this thank-you smile is a feat of engineering."] = "제 턱은 철사로 고정돼 있어요, {name}. 그러니 이 감사의 미소는 공학의 쾌거죠."
L["Thanks, {name}. Most of my old life went with the Plague. There's room for you."] = "고마워요, {name}. 옛 삶은 대부분 역병과 함께 사라졌죠. 당신 자리는 있어요."
L["That's put colour in my cheeks, {name}. Grey, mostly, but it's a start."] = "뺨에 혈색이 도는군, {name}. 대부분 잿빛이지만, 시작이오."
L["I'd send you flowers, {name}, but they wilt when I pick them up."] = "꽃이라도 보내고 싶소, {name}. 내가 집으면 시들어 버리지만."
L["The Scourge never once said thank you, {name}. So let me say it properly."] = "스컬지는 고맙다는 말을 한 번도 안 했소, {name}. 그러니 내가 제대로 하겠소."
L["Kindness to the dead, {name}? The priests in Brill used to charge for that."] = "죽은 자에게 친절이라, {name}? 브릴의 사제들은 예전에 그걸로 돈을 받았소."
L["Certainly, {name}. Try not to die. It's overrated."] = "그러지, {name}. 죽지는 마시오. 생각보다 별거 없으니."
L["You need only ask, {name}. The dead are patient."] = "말만 하시오, {name}. 죽은 자는 인내심이 많으니."
L["Ask the dead for a favour, {name}. We rarely have other plans."] = "부탁은 죽은 자에게 하시오, {name}. 우린 딱히 다른 약속이 없거든."
L["Certainly, {name}. Stand clear; I'd hate to drop anything on you."] = "그러지, {name}. 좀 떨어지시오. 뭐가 떨어지기라도 하면 곤란하니."
L["A moment, {name}. Rigor mortis is hard on the casting hand."] = "잠깐, {name}. 사후 경직 때문에 시전하는 손이 뻣뻣해서."
L["Nice to be asked for something, {name}, besides the way to the graveyard."] = "무덤 가는 길 말고 다른 걸 물어 주니 반갑군, {name}."
L["Gladly, {name}. It takes my mind off the smell. Mine, I mean."] = "기꺼이, {name}. 냄새 생각을 잊게 해 주니까. 내 냄새 말이오."
L["Certainly, {name}. Hold still. My aim drifts when my eye does."] = "그러지, {name}. 가만있으시오. 눈알이 돌아가면 조준도 돌아가니."
L["In Undercity nobody says please, {name}. Mostly they gurgle. Here you are."] = "언더시티에선 '부탁'이란 말 대신 꾸르륵거리오, {name}. 자, 받으시오."
L["Just {buff}, {name}? The apothecaries always want a sample too."] = "{buff}만이오, {name}? 약제사들은 꼭 표본도 한 점 떼어 가던데."
L["I always rise when called, {name}. Unfortunate history. Here you are."] = "부르면 늘 일어나는 몸이오, {name}. 좀 불행한 전력이라. 받으시오."
L["Anything for you, {name}. Within reason, and what's left of mine."] = "뭐든 하겠소, {name}. 이성이 허락하는 선에서. 남은 게 별로 없지만."
L["Of course, {name}. I'd say 'over my dead body', but that's been tried."] = "물론이오, {name}. '내 눈에 흙이 들어가기 전엔' 하려 했는데, 이미 들어갔군."
L["Right away, {name}. The dead don't dawdle. We shamble with purpose."] = "바로 하지, {name}. 죽은 자는 꾸물대지 않소. 목적 있게 비틀거릴 뿐."
L["Of course, {name}. Free will is a gift. I spend mine on things like this."] = "물론이오, {name}. 자유 의지는 선물이지. 난 이런 데 쓰오."
L["At once, {name}. I've had far worse requests from the Apothecarium."] = "당장 하지, {name}. 왕립 약제사 협회에선 훨씬 끔찍한 부탁도 받아 봤소."
L["Of course, {name}. After a winter in the Plaguelands, this counts as a holiday."] = "물론이오, {name}. 역병지대에서 겨울을 나 봤으면 이건 휴가요."
L["{buff}, {name}? With the Dark Lady's compliments."] = "{buff} 말이오, {name}? 어둠의 여왕께서 안부와 함께 보내는 거요."
L["Of course, {name}. I don't sleep or eat, so I may as well be useful."] = "물론이오, {name}. 잠도 안 자고 먹지도 않으니, 쓸모라도 있어야지."
L["Glad to, {name}. The Scourge used my hands for worse."] = "기꺼이, {name}. 스컬지는 이 손으로 더 험한 짓을 시켰소."
L["Certainly, {name}. The apothecaries taught me a steady hand. Mostly on rats."] = "그러지, {name}. 약제사들한테 손 떨지 않는 법을 배웠소. 주로 쥐한테."
L["The Dark Lady said serve the Horde, {name}. She never said sulk about it."] = "어둠의 여왕께선 호드를 섬기라 하셨지, {name}. 툴툴대라곤 안 하셨소."
L["Right away, {name}. In Deathknell they woke me with far ruder requests."] = "바로 하지, {name}. 죽음의 종소리에선 훨씬 무례한 부탁으로 날 깨웠소."
L["Silverpine's worgen never ask this nicely, {name}. You're a pleasant change."] = "은빛소나무 숲 늑대인간들은 이리 공손히 묻지 않소, {name}. 반가운 변화군."
L["Of course, {name}. I've nothing on until the end of the world."] = "물론이오, {name}. 세상 끝날 때까지 약속이 없소."
L["Done, {name}. Quicker than the bat to the Sepulcher, and you keep your lunch."] = "됐소, {name}. 공동묘지까지 가는 박쥐보다 빠르고, 점심도 안 게우지."
L["You had me at please, {name}. Or at 'oi, corpse'. Either works."] = "부탁한다는 말에 넘어갔소, {name}. 아니면 '어이, 시체'에. 둘 다 통하오."
L["Why not, {name}? It's that or stand here decomposing."] = "안 될 거 없지, {name}? 아니면 여기 서서 썩는 수밖에."
L["Right away, {name}. I've stood here so long the moss had started to hope."] = "바로 하지, {name}. 하도 오래 서 있어서 이끼가 기대를 품기 시작했소."
L["With pleasure, {name}. Well. With what passes for it now."] = "기꺼이, {name}. 뭐. 요즘 기쁨이라 부를 만한 걸로."
L["Here, {name}. I won't ask what it's for. The dead are discreet."] = "여기 있소, {name}. 어디 쓸 건지 묻지 않겠소. 죽은 자는 입이 무겁소."
L["Ask away, {name}. Death made me patient, and Undercity made me bored."] = "말해 보시오, {name}. 죽음은 날 참을성 있게, 언더시티는 날 지루하게 만들었소."
L["Done, {name}. Come back when it fades. I'm not going anywhere. Ever."] = "됐소, {name}. 사라지면 다시 오시오. 난 어디 안 가오. 영원히."
L["Certainly, {name}. Better work than hauling ichor for Faranell."] = "물론이오, {name}. 파라넬 대신 체액 나르는 것보단 낫지."
L["Easiest thing I've done all week, {name}, and I dug myself out of a grave."] = "이번 주에 한 일 중 제일 쉽군, {name}. 무덤에서 파고 나온 것까지 쳐서."
L["Of course, {name}. Eternity's long; I can spare a moment of it."] = "물론이오, {name}. 영원은 기니, 잠깐쯤은 내줄 수 있소."
L["Gladly, {name}. Beats standing in the Ruins of Lordaeron looking haunted."] = "기꺼이, {name}. 로데론의 폐허에서 유령처럼 서 있는 것보단 낫소."
L["Ask a Forsaken, get an answer, {name}. Ask an apothecary, get a waiver."] = "포세이큰에게 물으면 답이 나오오, {name}. 약제사에게 물으면 서약서가 나오지."
L["At your service, {name}. The Lich King never said please. You did."] = "분부대로, {name}. 리치 왕은 부탁한다는 말을 한 적이 없소. 그대는 했지."
L["Stay among the living a little longer, {name}."] = "산 자들 곁에 조금 더 머무시오, {name}."
L["Take this, {name}. The grave can wait."] = "받으시오, {name}. 무덤은 기다려 줄 거요."
L["I was a physician in Lordaeron, {name}. Old habits die harder than I did."] = "로데론에선 의사였소, {name}. 버릇은 나보다 끈질기게 안 죽더군."
L["No charge, {name}. The apothecaries would have made you sign something."] = "공짜요, {name}. 약제사들이었으면 뭔가에 서명부터 시켰을 거요."
L["A gift from the grave, {name}. Don't worry, I washed it."] = "무덤에서 온 선물이오, {name}. 걱정 마시오, 씻어 왔으니."
L["I've seen where heroes end up, {name}. I live there. Take this."] = "영웅들이 결국 어디로 가는지 봤소, {name}. 내가 사는 곳이오. 받으시오."
L["Take this, {name}. I learned the hard way you can't take it with you."] = "받으시오, {name}. 저승엔 못 가져간다는 걸 몸소 배웠소."
L["Take this, {name}. It's the only thing I own that isn't slightly damp."] = "받으시오, {name}. 내 물건 중 유일하게 눅눅하지 않은 거요."
L["Hold on to yourself, {name}; this helps. The pieces are hard to find later."] = "몸 잘 추스르시오, {name}. 이게 도움이 될 거요. 조각은 나중에 찾기 어렵소."
L["Take this, {name}. The Plaguelands are full of people who didn't."] = "받으시오, {name}. 역병지대엔 안 받은 자들이 가득하오."
L["A small kindness, {name}. Tirisfal could use more of them."] = "작은 친절이오, {name}. 티리스팔엔 이런 게 더 필요하지."
L["Tirisfal fog gets into everything, {name}. So does this, but pleasantly."] = "티리스팔 안개는 어디든 스며드오, {name}. 이것도 그렇소. 기분 좋게."
L["Here, {name}. Kept cool for you, like everything I carry."] = "자, {name}. 차게 보관했소. 내가 지닌 건 다 그렇지만."
L["I've outlived everyone I knew, {name}. I'd rather not outlive you. Take this."] = "아는 이는 다 먼저 보냈소, {name}. 그대까진 싫소. 받으시오."
L["Pardon me, {name}. I'm told I lurk. I'm trying to lurk helpfully."] = "실례하오, {name}. 어슬렁댄다는 말을 듣지. 도움 되게 어슬렁대는 중이오."
L["Out of my own pocket, {name}. The dead don't need much."] = "내 주머니에서 나온 거요, {name}. 죽은 자는 필요한 게 별로 없소."
L["I've already had the worst day there is, {name}. Let's spare you yours."] = "최악의 날은 난 이미 겪었소, {name}. 그대 건 면해 봅시다."
L["Wind's off the Plaguelands, {name}. Take this, and breathe through your mouth."] = "역병지대에서 바람이 부오, {name}. 받으시고, 입으로 숨 쉬시오."
L["The crows have been watching you, {name}. Let's disappoint them."] = "까마귀들이 그대를 노리고 있소, {name}. 실망시켜 줍시다."
L["Here, {name}. Tirisfal grows nothing but pumpkins and grudges. This is neither."] = "자, {name}. 티리스팔엔 호박과 원한만 자라오. 이건 둘 다 아니오."
L["Take this, {name}. The only thing in Undercity that needn't be boiled first."] = "받으시오, {name}. 언더시티에서 유일하게 안 끓여도 되는 거요."
L["Eternity is long, {name}, and I've spent a fair bit of it practising this."] = "영원은 길다오, {name}. 이걸 연습하느라 꽤 썼소."
L["For the road, {name}. Undercity-made, so do keep it away from open flame."] = "가는 길에 쓰시오, {name}. 언더시티산이니 불 근처는 피하시오."
L["Take this, {name}. It's odourless, which I'm told makes it my best feature."] = "받으시오, {name}. 냄새가 안 나오. 내 장점 중 최고라더군."
L["Forsaken are famously patient, {name}. I just couldn't wait to give you this."] = "포세이큰은 인내심으로 유명하오, {name}. 이건 못 참고 드리지만."
L["No strings attached, {name}. I cut mine when the Lich King lost his grip."] = "대가도, 조종 줄도 없소, {name}. 리치 왕 줄은 진작 끊었지."
L["Fresh from Tirisfal, {name}. Well, fresh for Tirisfal."] = "티리스팔에서 갓 가져왔소, {name}. 티리스팔치곤 싱싱하단 뜻이오."
L["Take this, {name}. The Bulwark taught me to look out for the living."] = "받으시오, {name}. 방벽에서 산 자를 지키는 법을 배웠소."
L["Passing Pyrewood, {name}? Take this. The village has a bad habit after dark."] = "파이어우드 마을을 지나시오, {name}? 받으시오. 그 마을은 해 지면 버릇이 고약하오."
L["The Scarlets would call this unholy, {name}. From me, they'd say it of bread."] = "붉은십자군은 이걸 부정하다 하겠지, {name}. 내가 주면 빵도 그렇다 할 놈들이오."
L["Don't flinch, {name}. It's a spell, not a bite."] = "움찔하지 마시오, {name}. 주문이지, 무는 게 아니오."
L["Here, {name}. The Royal Apothecary Society had no hand in this one. Promise."] = "여기 있소, {name}. 이번엔 왕립 약제사 협회가 손대지 않았소. 약속하오."
L["You look tired, {name}; from me, that's a professional opinion. So: this."] = "피곤해 보이오, {name}. 내가 하는 말이니 전문가 소견이오. 그러니 이걸."
L["You looked a bit peaky, {name}. Then again, I'm a poor judge of colour."] = "안색이 좀 창백해 보였소, {name}. 하긴 난 색을 잘 못 보지만."
L["On the house, {name}. The house is a crypt, but it's paid off."] = "공짜요, {name}. 이 집은 납골당이지만, 빚은 다 갚았소."
L["Take this, {name}. Agamand Mills is full of folk who also had places to be."] = "받으시오, {name}. 아가만드 방앗간엔 갈 데가 있던 자들이 가득하오."
L["Bound for Tarren Mill, {name}? Take this. The Southshore lot throw things."] = "타렌 밀농장으로 가시오, {name}? 받으시오. 사우스쇼어 놈들은 물건을 던지오."
L["Living's a fragile hobby, {name}. Let's keep you at it."] = "산다는 건 깨지기 쉬운 취미요, {name}. 계속하게 해 드리지."
L["Take this, {name}. I'd hate for us to end up neighbours."] = "받으시오, {name}. 우리가 이웃이 되는 건 싫으니."
L["Every life I keep is one the Lich King doesn't get, {name}."] = "내가 지키는 목숨 하나하나가 리치 왕이 못 가져가는 목숨이오, {name}."
L["Take this, {name}. It's what we do instead of sleeping."] = "받으시오, {name}. 잠자는 대신 우리가 하는 일이오."
L["Mind yourself, {name}, and take this. Not all Tirisfal's dead have my manners."] = "몸조심하시오, {name}. 이것도 받고. 티리스팔의 망자가 다 나처럼 예의 바르진 않소."
L["Stay warm, {name}. One of us ought to, and this should help."] = "따뜻하게 지내시오, {name}. 우리 중 하나는 그래야지. 이게 도움이 될 거요."
L["Take this, {name}. The Deathguard can't watch every road."] = "받으시오, {name}. 죽음의 경비병이 모든 길을 지킬 순 없소."
L["Don't mind me, {name}. Just a passing corpse doing a good turn."] = "신경 쓰지 마시오, {name}. 지나가던 시체가 좋은 일 하는 것뿐이오."
L["It's free, {name}. The embalming afterwards is not, so do be careful."] = "공짜요, {name}. 나중 방부 처리는 아니니, 조심하시오."
L["A Forsaken's gift, {name}: cold, a little grim, and good for you."] = "포세이큰의 선물이오, {name}. 차갑고, 좀 음침하고, 몸에 좋소."
L["Off to the Scarlet Monastery, {name}? Take this. They'll take the rest."] = "붉은십자군 수도원에 가시오, {name}? 받으시오. 나머진 그놈들이 다 가져갈 테니."
L["Take this, {name}. I'd give you advice, but mine is mostly about digging."] = "받으시오, {name}. 조언도 하고 싶지만, 내 조언은 거의 땅 파는 얘기요."
L["Don't mind the hand that gave you this, {name}. It's mine. Usually."] = "이걸 건넨 손은 신경 쓰지 마시오, {name}. 내 손이오. 대개는."
L["We Forsaken must look after each other, {name}."] = "우리 포세이큰끼리는 서로 챙겨야지, {name}."
L["Between us corpses, {name}, you're well preserved. This should keep you so."] = "우리 송장끼리 말인데, {name}, 그대는 보존이 잘됐소. 이걸로 계속 그러시오."
L["Lose a finger, {name}, and I've a spare. Forsaken share. Today, it's this."] = "손가락을 잃으면, {name}, 내게 여분이 있소. 포세이큰은 나누지. 오늘은 이거요."
L["Is your jaw clicking too, {name}? Here; it won't help that, but it'll help."] = "그대 턱도 딸깍거리오, {name}? 받으시오. 그건 못 고쳐도 도움은 될 거요."
L["A small victory for Sylvanas, {name}: one of hers, blessed. It's ours."] = "실바나스를 위한 작은 승리요, {name}. 그분의 백성 하나가 축복받았소. 우리 승리지."
L["Brill or Deathknell, {name}? We all woke up somewhere. Now wake up to this."] = "브릴이오, 데스넬이오, {name}? 다들 어딘가에서 깨어났지. 이번엔 이걸 받고 깨시오."
L["When the Scourge calls, {name}, we won't be home. Or easy to take. Here."] = "스컬지가 찾아와도, {name}, 우린 집에 없을 거요. 쉽게 잡히지도 않고. 받으시오."
L["The Bulwark holds, {name}, and so do we: held together, and held up by this."] = "방벽은 버티오, {name}. 우리도 버티지. 꿰맨 채로, 이제 이것의 힘으로."
L["Lordaeron raised us twice, {name}. Let me raise your spirits a third time."] = "로데론은 우릴 두 번 일으켰소, {name}. 세 번째로 그대 기운을 북돋아 드리지."
L["In Northrend, {name}, the Lich King is sulking about us. This won't help him."] = "노스렌드에서, {name}, 리치 왕이 우리 때문에 삐쳐 있소. 이건 그를 돕지 않지."
L["The Dark Lady needs us whole, {name}. This gets you near enough."] = "어둠의 여왕께선 우리가 온전하길 바라시오, {name}. 이거면 거의 온전해질 거요."
L["You smell of Tirisfal, {name}. From us, a compliment. So is this."] = "티리스팔 냄새가 나는구려, {name}. 우리끼린 칭찬이오. 이것도 그렇고."
L["We've forever, {name}. Take this; let's not spend it waiting for the lift."] = "우린 영원을 가졌소, {name}. 이걸 받으시오. 승강기 기다리느라 다 쓰진 맙시다."
L["Forsaken to Forsaken, {name}: take this. The sewer shortcut is not a shortcut."] = "포세이큰끼리 말하오, {name}. 이걸 받으시오. 하수도 지름길은 지름길이 아니오."
L["If the Deathguard ask, {name}, I was issuing supplies. This one's yours."] = "죽음의 경비대가 물으면, {name}, 보급품을 나눠 줬다 하시오. 이건 그대 몫이오."
L["Our kind don't get many kindnesses, {name}. Let's keep them in the family."] = "우리 같은 자들은 친절받을 일이 드물지, {name}. 식구끼리 나눕시다."
L["Same grave dirt, same Dark Lady, {name}. That's family, and family gets this."] = "같은 무덤 흙, 같은 어둠의 여왕, {name}. 그게 가족이고, 가족은 이걸 받소."
L["Keep the faith, {name}. In each other, I mean. Here's mine, in you."] = "믿음을 지키시오, {name}. 서로에 대한 믿음 말이오. 이건 그대를 향한 내 믿음이오."
L["The dead look after the dead, {name}. The living could learn a thing or two."] = "죽은 자는 죽은 자를 챙기오, {name}. 산 자들도 좀 배워야 할 텐데."
L["We've both seen the inside of a grave, {name}. Dreadful service. Here's better."] = "우리 둘 다 무덤 속을 봤지, {name}. 서비스가 형편없었소. 이게 더 낫소."
L["Mordo did your stitches too, {name}? This should help them hold."] = "그대도 모르도가 꿰맸소, {name}? 이게 바늘땀을 버티게 해 줄 거요."
L["Our time will come, {name}. We've nothing but time, so I'll spend some on you."] = "우리 때가 올 거요, {name}. 가진 게 시간뿐이니, 그대에게 좀 쓰지."
L["Recall the Lich King's voice, {name}? Mine's kinder, and it gives you this."] = "리치 왕의 목소리 기억하오, {name}? 내 목소린 더 다정하고, 이걸 주지."
L["You kept your nose, {name}. Not all of us did. Keep the rest with this."] = "코가 남아 있구려, {name}. 다 그렇진 않았소. 나머지도 이걸로 지키시오."
L["We were all Lordaeron once, {name}. Some kept the accent. I kept the manners."] = "우린 다 한때 로데론 사람이었지, {name}. 억양을 남긴 이도 있고, 난 예절을 남겼소."
L["The living do try, {name}. Be kind to them, as I am to you. Here."] = "산 자들도 애쓰오, {name}. 내가 그대에게 하듯 그들에게도 친절하시오. 받으시오."
L["Still got both eyes, {name}? Show-off. Take this anyway."] = "아직 두 눈이 다 있소, {name}? 잘난 척하긴. 그래도 받으시오."
L["Did you call on your old family too, {name}? Mine took it badly. You get this."] = "그대도 옛 가족을 찾아갔소, {name}? 우리 가족은 질색하더군. 그대는 이걸 받으시오."
L["Take this; stay alive, {name}. Undercity's housing list is already very long."] = "이걸 받고 살아 있으시오, {name}. 언더시티 입주 대기 명단은 이미 아주 길다오."
L["That's for you, {name}. If I fall down, give it a minute. Old habit."] = "그대 몫이오, {name}. 내가 쓰러지면 잠깐 기다리시오. 오랜 버릇이오."
L["Here, {name}. I'll take the front. What's the worst that could happen? Again?"] = "받으시오, {name}. 앞은 내가 맡지. 최악이 뭐겠소? 또 죽는 거?"
L["There you are, {name}. Now keep upwind of me. It's better for morale."] = "여기 있소, {name}. 이제 내 바람 위쪽에 서시오. 사기에 좋소."
L["Last party I joined, {name}, I woke in a crypt. This is me improving on that."] = "지난번 일행 땐, {name}, 지하 묘지에서 깨어났소. 이번엔 그보다 낫게 하려는 거요."
L["Here, {name}. Anything that bites, point it at me. Nothing left worth eating."] = "받으시오, {name}. 무는 놈은 다 내게 보내시오. 나한텐 먹을 데가 안 남았소."
L["For you; heal the others first, {name}. I run on spite and embalming fluid."] = "그대 몫이오. 다른 이들부터 치유하시오, {name}. 난 원한과 방부액으로 굴러가니까."
L["Take this, {name}. If it goes badly, don't worry. I've died before; it passes."] = "이걸 받으시오, {name}. 일이 틀어져도 걱정 마시오. 죽어 봤는데, 지나가더이다."
L["Fought the Scourge from both sides, {name}. This side shares its blessings."] = "스컬지와는 양쪽에서 다 싸워 봤소, {name}. 이쪽은 축복을 나눠 주지."
L["Stay close, {name}; take this. I won't scream at the ghouls. Old neighbours."] = "가까이 있으시오, {name}. 이걸 받고. 난 구울 보고 소리 안 지르오. 옛 이웃이니."
L["I've walked the Plaguelands at night, {name}. With this, so can you."] = "밤에 역병의 땅을 걸어 봤소, {name}. 이거면 그대도 할 수 있소."
L["The corpse at the back blessed you, {name}. That's me. Please don't bury it."] = "맨 뒤의 송장이 그대를 축복했소, {name}. 그게 나요. 묻지는 마시오."
L["Take this; stay together, {name}. Easier than putting somebody back together."] = "이걸 받고 뭉쳐 있으시오, {name}. 누굴 다시 이어 붙이는 것보단 쉽소."
L["Take this; don't wait for me, {name}. I shamble, but forever. I'll catch up."] = "이걸 받고 날 기다리지 마시오, {name}. 느릿느릿하지만 영원히 가니까. 따라잡을 거요."
L["Here, {name}. Keep the torches clear of me. I'm old, dry and very flammable."] = "받으시오, {name}. 횃불은 내게서 멀리. 난 늙고, 바싹 마르고, 아주 잘 타오."
L["That keeps yours going, {name}. Don't check me for a pulse. It worries people."] = "이거면 그대 맥박은 계속 뛸 거요, {name}. 내 맥은 짚지 마시오. 사람들이 걱정하오."
L["Take this, {name}; mind the green puddles. I've seen what they do. I'm it."] = "이걸 받으시오, {name}. 초록 웅덩이 조심하고. 그게 뭘 하는지 봤소. 그 결과가 나요."
L["Lordaeron fell with me in it, {name}. With this on you, today won't be worse."] = "로데론이 무너질 때 내가 그 안에 있었소, {name}. 이걸 두르면 오늘은 그보다 나을 거요."
L["Take this and stick together, {name}. The apothecaries pay well for strays."] = "이걸 받고 뭉쳐 다니시오, {name}. 약제사들은 길 잃은 자에게 값을 잘 쳐주오."
L["For you, {name}. If this ends underwater, don't mind me. Breathing's optional."] = "그대 몫이오, {name}. 물속에서 끝나도 나는 신경 쓰지 마시오. 숨은 선택 사항이오."
L["The Dark Lady blesses no one, {name}. I've made an exception for this party."] = "어둠의 여왕은 아무도 축복하지 않소, {name}. 이 일행만은 예외로 하지."
L["When we win, {name}, drinks at the Gallows' End in Brill. This one's on me now."] = "이기면, {name}, 브릴 여관에서 한잔하지. 이건 지금 내가 내는 거요."
L["That's from me, {name}, not the flies. They're with me, though."] = "이건 내가 주는 거요, {name}. 파리들 말고. 파리는 나랑 같이 다니지만."
L["Here, {name}. I'll watch the rear. Nothing sneaks up on one who can't blink."] = "받으시오, {name}. 후방은 내가 지키지. 눈을 못 깜빡이는 자에겐 기습이 안 통하오."
L["Here, {name}. If I lose an arm in there, bring it out. I'm fond of it."] = "받으시오, {name}. 안에서 팔을 잃으면 가지고 나오시오. 정든 팔이오."
L["That's yours, {name}. Leave the bodies to me afterwards. Waste not."] = "그대 몫이오, {name}. 끝나면 시체는 내게 맡기시오. 아껴 써야지."
L["Take this and send them my way, {name}. I don't bleed. I come apart a little."] = "이걸 받고 놈들은 내게 보내시오, {name}. 난 피를 안 흘리오. 조금 떨어져 나갈 뿐."
L["Here, {name}. When they cast fear, look to me. I'll be the one not running."] = "받으시오, {name}. 놈들이 공포를 걸면 나를 보시오. 안 도망치는 게 나일 거요."
L["Take this, {name}, and mind the abominations. Distant cousins. We don't speak."] = "이걸 받으시오, {name}. 누더기골렘 조심하고. 먼 친척이오. 말 안 섞는 사이지."
L["That's for your legs, {name}. If I walk oddly, it's fine. It's a new leg."] = "그대 다리를 위한 거요, {name}. 내가 이상하게 걸어도 괜찮소. 새 다리라서."
L["Here; shout if you need more, {name}. My ears are mostly where I left them."] = "받으시오. 더 필요하면 외치시오, {name}. 내 귀는 대충 원래 자리에 있소."
L["Take this so we don't wipe, {name}. If we do, I know the spirit healer."] = "전멸하지 않게 이걸 받으시오, {name}. 혹시 하면, 영혼의 치유사랑 아는 사이요."
L["Don't fret the odds, {name}. Lordaeron's army had better ones. You have this."] = "승산은 신경 쓰지 마시오, {name}. 로데론 군대는 더 나았지. 그대에겐 이게 있소."
L["Good party, {name}. Five of us, all blessed, and only one needs embalming."] = "좋은 일행이오, {name}. 다섯 명 다 축복받았고, 방부 처리가 필요한 건 하나뿐이오."
L["There, {name}. Now watch my back. Some of the stitching there is very old."] = "됐소, {name}. 이제 내 등을 봐 주시오. 거기 바늘땀은 아주 오래됐소."
L["Here, {name}. Should I fall, no hurry raising me. I could use the lie-down."] = "받으시오, {name}. 내가 쓰러져도 서둘러 일으킬 것 없소. 좀 누워 있고 싶으니."
L["The dead keep terrible hours, {name}. Nice to have someone to give this to."] = "망자들은 시간 개념이 엉망이오, {name}. 이걸 줄 사람이 있어 좋구려."
L["Midnight, {name}: the best hour to be up. Have this, and stay up with me."] = "자정이오, {name}. 깨어 있기 제일 좋은 시간이지. 이걸 받고 나랑 같이 깨어 있으시오."
L["The living are all asleep, {name}. We Forsaken call this the quiet shift. Here."] = "산 자들은 다 잠들었소, {name}. 우리 포세이큰은 이걸 조용한 근무라 하지. 받으시오."
L["Late, {name}? In Undercity, this is lunchtime. Have some."] = "늦었다고, {name}? 언더시티에선 지금이 점심이오. 좀 드시오."
L["The Scourge used to walk at this hour, {name}. Now it's ours, and so is this."] = "예전엔 이 시간에 스컬지가 돌아다녔소, {name}. 이젠 우리 시간이오. 이것도 그렇고."
L["Night, {name}. Nobody can tell I'm pale. Or that I'm kind. Take this."] = "밤이오, {name}. 내가 창백한 것도, 친절한 것도 아무도 모르지. 받으시오."
L["Dark as the Undercity, {name}. Proper lighting. Here's a little glow for you."] = "언더시티만큼 어둡구려, {name}. 제대로 된 조명이오. 그대에게 작은 빛을 주지."
L["Fog, moonlight, mildew, {name}: Tirisfal weather. This keeps the damp out."] = "안개, 달빛, 곰팡이, {name}. 티리스팔 날씨지. 이게 습기를 막아 줄 거요."
L["The banshees start singing now, {name}. Take this; they're only practising."] = "밴시들이 이제 노래를 시작하오, {name}. 이걸 받으시오. 연습일 뿐이니."
L["Stars over Tirisfal, {name}: the one thing up there that never rotted. Here."] = "티리스팔 위의 별이오, {name}. 저 위에서 유일하게 안 썩은 것이지. 받으시오."
L["Past midnight, {name}. The graveyards are quiet. Take this; stay out of them."] = "자정이 지났소, {name}. 묘지들이 조용하구려. 이걸 받고 거기엔 가지 마시오."
L["An owl saw me and left, {name}. Sensible bird. You stayed, so this is yours."] = "부엉이가 날 보고 날아가더군, {name}. 현명한 새요. 그대는 남았으니 이건 그대 거요."
L["Moonlight suits us, {name}. It hides the stitching. This hides the rest."] = "달빛이 우리한테 어울리오, {name}. 바늘땀을 가려 주지. 나머진 이게 가려 주고."
L["Don't stay up for me, {name}. I gave up sleep years ago. Take this and rest."] = "나 때문에 깨어 있지 마시오, {name}. 잠은 몇 년 전에 끊었소. 이걸 받고 쉬시오."
L["Long night, {name}? Mine's been going since the Plague. This helps with yours."] = "긴 밤이오, {name}? 내 밤은 역병 이후로 계속이오. 이게 그대 밤을 도와줄 거요."
L["Night in Tirisfal, {name}. Even the bats keep their voices down. Here, quietly."] = "티리스팔의 밤이오, {name}. 박쥐들도 소리를 죽이지. 조용히 받으시오."
L["The banshees call this the witching hour, {name}. Here's some witchery."] = "밴시들은 이걸 마녀의 시간이라 부르오, {name}. 마법 좀 부려 드리지."
L["Morning, {name}? I've been up all night, and all of last decade. Have this."] = "벌써 아침이오, {name}? 밤새 깨어 있었소. 지난 십 년 내내도. 받으시오."
L["The sun's up, {name}. Take this; I'll stand in the shade. Things peel."] = "해가 떴소, {name}. 이걸 받으시오. 난 그늘에 서 있겠소. 뭐가 벗겨지거든."
L["Early start, {name}. I miss yawning. Have this and do one for me."] = "일찍 시작하는구려, {name}. 하품이 그립소. 이걸 받고 나 대신 하품 한 번 하시오."
L["Sunrise, {name}. My least favourite colour. This is my favourite gift."] = "해돋이오, {name}. 제일 싫어하는 색이지. 이건 제일 좋아하는 선물이고."
L["Dawn over Tirisfal, {name}: grey, then less grey. This adds a little colour."] = "티리스팔의 새벽이오, {name}. 회색, 그다음엔 덜 회색. 이게 색을 좀 더해 줄 거요."
L["Morning, {name}. The Gallows' End porridge moved again. Have this instead."] = "좋은 아침이오, {name}. 여관 죽이 또 꿈틀댔소. 대신 이걸 드시오."
L["The roosters in Brill still crow, {name}. Nobody's told them. Here's a wake-up."] = "브릴의 수탉들은 아직도 울지, {name}. 아무도 말 안 해 줬거든. 자, 기상 선물이오."
L["Morning, {name}. The Deathguard just turn round to change shifts. I give this."] = "좋은 아침이오, {name}. 죽음의 경비대는 돌아서는 걸로 교대하지. 나는 이걸 주고."
L["Morning, {name}. I don't wake up now; I stop lying down. Then I hand out this."] = "좋은 아침이오, {name}. 난 이제 깨지 않소. 그냥 눕기를 멈추지. 그러고 이걸 나눠 주오."
L["Mornings were the worst of being alive, {name}. This should make yours better."] = "살아 있을 땐 아침이 최악이었소, {name}. 이게 그대 아침을 좀 낫게 해 줄 거요."
L["The early bird gets the worm, {name}. The early Forsaken gets you this."] = "일찍 일어나는 새가 벌레를 잡는다지, {name}. 일찍 일어난 포세이큰은 이걸 주고."
L["Breakfast, {name}? I'll pass; my appetite went with my insides. Have this."] = "아침밥이오, {name}? 난 됐소. 입맛은 내장이랑 같이 갔으니. 이걸 드시오."
L["Up with the sun, {name}? I'm up with everything. Take this while I am."] = "해와 함께 일어났소, {name}? 난 뭐든 함께 깨어 있지. 내가 깨어 있을 때 받으시오."
L["Take this before the lift, {name}. The last man who rushed it is still falling."] = "승강기 타기 전에 받으시오, {name}. 마지막으로 서두른 자는 아직 떨어지는 중이오."
L["Undercity has it all, {name}: a bank, an inn, and this, free. Mind the sewers."] = "언더시티엔 다 있소, {name}. 은행, 여관, 그리고 공짜인 이것. 하수도는 조심하시오."
L["Even the rats bow to the Dark Lady here, {name}. Take this before one asks."] = "여기선 쥐도 어둠의 여왕께 절하오, {name}. 쥐가 달라기 전에 받으시오."
L["Take this; mind the canal, {name}. It's green for a reason, and it isn't moss."] = "이걸 받고 수로를 조심하시오, {name}. 초록색엔 이유가 있소. 이끼는 아니고."
L["Undercity's lovely this time of year, {name}. It's always this time. Here."] = "언더시티는 이맘때가 좋소, {name}. 늘 이맘때지만. 받으시오."
L["We moved into Lordaeron's cellar, {name}, kept the good silver, and share this."] = "우린 로데론 지하실로 이사했소, {name}. 좋은 은그릇은 챙겼고, 이건 나누지."
L["The Royal Quarter's that way, {name}. Take this; the banshees keep score."] = "왕실 지구는 저쪽이오, {name}. 이걸 받으시오. 밴시들이 점수를 매기니."
L["The bat handler swears they're friendly, {name}. Take this before you test it."] = "박쥐 조련사는 순하다고 맹세하오, {name}. 확인하기 전에 이것부터 받으시오."
L["Magic Quarter's that way, {name}. Take this; don't drink the glowing puddles."] = "마법 지구는 저쪽이오, {name}. 이걸 받고, 빛나는 웅덩이는 마시지 마시오."
L["The throne room's upstairs, {name}. Nobody sits in it. Take this instead."] = "왕좌의 방은 위층이오, {name}. 아무도 안 앉지. 대신 이걸 받으시오."
L["The Apothecarium's that way, {name}. Take this; don't touch, sniff or sign."] = "왕립 약제사 협회는 저쪽이오, {name}. 이걸 받고, 만지지도 맡지도 서명하지도 마시오."
L["Rogues' Quarter's through there, {name}. Take this; count your fingers after."] = "도적 지구는 저리로 가면 있소, {name}. 이걸 받고, 나와서 손가락을 세어 보시오."
L["Varimathras stands by the Dark Lady, {name}. Take this; never turn your back."] = "바리마트라스가 어둠의 여왕 곁에 있소, {name}. 이걸 받고, 절대 등을 보이지 마시오."
L["The War Quarter's that way, {name}. Here, so you arrive as cheerful as it is."] = "전쟁 지구는 저쪽이오, {name}. 그곳만큼 쾌활하게 도착하라고 이걸 드리지."
L["Trade Quarter's round the ring, {name}. It's all second-hand. This isn't."] = "상업 지구는 고리를 따라 있소, {name}. 전부 중고품이오. 이건 아니지만."
L["Most folk greet a Forsaken with holy water, {name}. You're a welcome change."] = "다들 포세이큰은 성수로 맞이하지, {name}. 그대는 반가운 예외요."
L["Few stop for a Forsaken, {name}. You did, and I noticed. Thank you."] = "포세이큰 앞에서 멈추는 이는 드물지, {name}. 그대는 멈췄소. 고맙소."
L["Warm, generous and alive, {name}. I can only match you on one. Here it is."] = "따뜻하고 너그럽고 살아 있군, {name}. 난 하나뿐이오. 자."
L["You came near enough to cast, {name}. Most of the living won't. Thank you."] = "주문이 닿을 만큼 다가왔구려, {name}. 산 자들은 대개 안 그러는데. 고맙소."
L["Kind to a Forsaken, {name}? They'll talk about you in Orgrimmar."] = "포세이큰에게 친절하다니, {name}? 오그리마에서 그대 얘기가 돌겠군."
L["Contrary to rumour, {name}, not everything a Forsaken hands out is a plague."] = "소문과 달리, {name}, 포세이큰이 주는 게 다 역병은 아니오."
L["Forsaken can't be charmed, {name}, they say. Asking nicely works, though."] = "포세이큰은 매혹이 안 통한다지, {name}. 공손한 부탁은 통하오."
L["You asked a Forsaken for help, {name}. Somewhere, a paladin just fainted."] = "포세이큰에게 도움을 청하다니, {name}. 어딘가에서 성기사 하나가 기절했겠군."
L["Take this instead of small talk, {name}. Mine tends to unsettle people."] = "잡담 대신 이걸 받으시오, {name}. 내 잡담은 다들 불편해하니."
L["They say the Forsaken have no friends, {name}. I'm recruiting. Signing gift."] = "포세이큰은 친구가 없다더군, {name}. 지금 모집 중이오. 가입 선물이오."
L["Take this, {name}. If anyone asks, the Forsaken were perfectly charming."] = "받으시오, {name}. 누가 물으면 포세이큰이 아주 매력적이었다 하시오."
L["Take this; stay alive, {name}. I've tried the alternative. Can't recommend it."] = "이걸 받고 살아 있으시오, {name}. 다른 길도 가 봤는데, 추천은 못 하겠소."
L["I don't bite, {name}. I bless. Not the living, usually. You're an exception."] = "난 물지 않소, {name}. 축복하지. 산 자는 보통 안 하지만, 그대는 예외요."
L["Yes, {name}, I'm dead. No, it isn't catching. Here."] = "그렇소, {name}, 난 죽었소. 아니, 옮지 않소. 받으시오."
L["You don't mind the smell, {name}. That's why we get on."] = "넌 냄새를 신경 안 쓰지, {name}. 그래서 우린 잘 맞아."
L["Of all the living, {name}, you're the only one I trust."] = "산 자들 중에, {name}, 내가 믿는 건 너뿐이야."
L["Stay close, {name}. The dead keep poor company, but you don't."] = "가까이 있어, {name}. 망자들은 따분하지만, 넌 아니야."
L["Well done, {name}. Death itself stepped aside for you."] = "잘했어, {name}. 죽음조차 널 위해 비켜섰어."
L["Excellent, {name}. The Dark Lady would approve."] = "훌륭해, {name}. 밴시 여왕께서도 흡족해하실 거야."
L["Ha. Vicious, {name}. You'd make a fine Deathstalker."] = "하. 사납구나, {name}. 훌륭한 죽음의 추적자가 되겠어."
L["Still breathing, {name}? Good. Stay that way, for me."] = "아직 숨 쉬지, {name}? 좋아. 날 위해 계속 그렇게 있어."
L["Easy, {name}. One of us dying was enough. Rest."] = "진정해, {name}. 우리 중 하나 죽은 걸로 충분해. 쉬어."
L["There, {name}. I've no warmth to give, but I'm here."] = "자, {name}. 줄 온기는 없지만, 내가 여기 있어."
L["The Earth Mother saw your kindness, {name}. She nudged me. Quite hard."] = "대지모신께서 그대의 친절을 보셨소, {name}. 날 쿡 찌르시더군. 꽤 세게."
L["Thank you, {name}. May the winds guide you."] = "고마운 일이오, {name}. 바람이 그대를 이끌기를."
L["Thank you, {name}. I'm deeply moved, and it takes a lot to move a tauren."] = "고맙소, {name}. 마음이 움직였소. 타우렌을 움직이기란 쉽지 않은데."
L["It's a long way up to a tauren's heart, {name}. You found it."] = "타우렌의 심장까진 한참 올라가야 하오, {name}. 그대가 찾아냈구려."
L["I felt that from horn to hoof, {name}. Returned, hoof to horn."] = "뿔부터 발굽까지 느꼈소, {name}. 발굽부터 뿔까지 돌려드리리다."
L["A gift given is a seed planted, {name}. Here is the harvest."] = "베푼 선물은 심은 씨앗이오, {name}. 여기 그 수확이오."
L["That deserves a feast, {name}. The feast can wait; {buff} can't."] = "잔치를 열 일이오, {name}. 잔치는 나중에, {buff} 먼저."
L["Thank you, {name}. Should you ever need a wall to hide behind, I'm free."] = "고맙소, {name}. 숨을 벽이 필요하면 말하시오. 난 늘 한가하오."
L["Thank you, {name}. My grandmother said kindness comes back on the wind."] = "고맙소, {name}. 할머니께선 친절은 바람을 타고 돌아온다 하셨소."
L["Returned faster than a wind rider, {name}, and with much less screeching."] = "윈드라이더보다 빨리 돌려드리오, {name}. 꽥꽥대지도 않고."
L["Returned, {name}. The quilboar never learned to give back, and look at them."] = "갚았소, {name}. 가시멧돼지는 갚을 줄 몰라서 저 꼴이오."
L["Thank you, {name}. My ancestors are all nodding. It's a great deal of nodding."] = "고맙소, {name}. 조상님들이 다들 고개를 끄덕이시오. 끄덕임이 어마어마하오."
L["In Mulgore we return a gift before the grass under it grows back, {name}."] = "멀고어에선 선물 밑 풀이 다시 자라기 전에 보답하오, {name}."
L["Thank you, {name}. I'll name my next kodo calf after you. They're lovely."] = "고맙소, {name}. 다음 새끼 코도에 그대 이름을 붙이리다. 아주 귀엽소."
L["Kindness is rarer than shade in the Barrens, {name}. Here's some back."] = "친절은 불모의 땅 그늘보다 귀하오, {name}. 여기 좀 돌려드리오."
L["I'll carve this on a totem, {name}. Tauren carve slowly; expect it by spring."] = "토템에 새겨 두리다, {name}. 타우렌은 천천히 새기니, 봄쯤 되겠소."
L["Bloodhoof Village will hear of this at supper, {name}. Thank you."] = "오늘 저녁 블러드후프 마을에 이 얘기가 퍼지겠소, {name}. 고맙소."
L["Cairne taught us to honour every kindness, {name}, and so I do."] = "케른께선 모든 친절을 기리라 하셨소, {name}. 그래서 이리 하오."
L["Thank you, {name}. Hamuul says the land repays those who tend it. So do I."] = "고맙소, {name}. 하물 님 말씀이, 땅은 돌보는 이에게 보답한다 하셨소. 나도 그렇소."
L["In Thunder Bluff we'd beat a drum for that, {name}. Imagine it. Thank you."] = "썬더 블러프였다면 북을 울렸을 거요, {name}. 상상해 보시오. 고맙소."
L["The Earth Mother gives without counting, {name}. You've been listening to her."] = "대지모신께선 셈 없이 주시오, {name}. 그대가 그분 말씀을 들었구려."
L["Thank you, {name}. My heart's as full as a kodo after the spring grass."] = "고맙소, {name}. 봄풀 뜯은 코도 배처럼 마음이 그득하오."
L["The elders on Elder Rise would approve, {name}. Slowly, after a long talk."] = "장로의 봉우리 어르신들도 흡족해하실 거요, {name}. 오래 의논한 뒤 천천히."
L["Thank you, {name}. If you pass through Mulgore, ask for me. The big one."] = "고맙네, {name}. 멀고어를 지나거든 날 찾게. 덩치 큰 놈 말일세."
L["Of course, {name}. Stand tall and be at peace. I'll handle the tall part."] = "여부가 있겠소, {name}. 마음 편히 계시오. 우뚝 서는 건 내가 하리다."
L["Ask and it is given, {name}. The herd shares what it has."] = "청하면 주는 법이오, {name}. 무리는 가진 것을 나누니."
L["Of course, {name}. Stand back a pace; I do this with my whole body."] = "물론이오, {name}. 한 걸음 물러서시오. 난 온몸으로 하니까."
L["Gladly, {name}. Mind the tail."] = "기꺼이, {name}. 꼬리 조심하시오."
L["The Earth Mother gives freely, {name}, and so do her largest children."] = "대지모신께선 아낌없이 주시오, {name}. 그분의 가장 큰 자식들도 그렇고."
L["Gladly, {name}. Tauren are slow to anger and quick to help."] = "기꺼이, {name}. 타우렌은 화는 느리고 돕기는 빠르오."
L["Refuse you, {name}? My ancestors would never let me hear the end of it."] = "거절이라니, {name}? 조상님들 잔소리를 영원히 들을 거요."
L["Of course, {name}. A tauren says yes the way the plains grow grass: easily."] = "물론이오, {name}. 타우렌의 '예'는 평원의 풀처럼 쉽게 돋아나오."
L["Of course, {name}. One moment; my hands are big and the spell is small."] = "물론이오, {name}. 잠시만. 손은 크고 주문은 작아서."
L["After a season herding kodo, {name}, a polite request is a holiday. Here."] = "코도 떼를 한 철 몰고 나면, {name}, 공손한 부탁은 휴가요. 여기."
L["The Earth Mother says share, {name}. My stomach says lunch. She outranks it."] = "대지모신께선 나누라 하시고, {name}, 배는 밥 달라 하오. 서열은 그분이 위지."
L["Of course, {name}. Stand still as a totem; this won't take long."] = "물론이오, {name}. 토템처럼 가만히 계시오. 금방 끝나오."
L["Spirits of the plains, lend me your strength. Here, {name}."] = "평원의 영령이여, 힘을 빌려주소서. 여기, {name}."
L["Magatha would want a favour for it, {name}. Baine would just say yes. So: yes."] = "마가타라면 대가를 바랐겠지, {name}. 베인 족장이라면 그냥 해 주오. 그러니: 예."
L["Hold still, {name}. I've practised on kodo, and they're far less polite."] = "가만있으시오, {name}. 코도로 연습했는데, 걔들은 훨씬 버릇이 없소."
L["Of course, {name}. A shu'halo never refuses a traveller. Or a second helping."] = "물론이오, {name}. 슈할로는 나그네를 거절 않소. 한 그릇 더도."
L["Of course, {name}. The plains taught me patience; the kodo taught me to share."] = "물론이오, {name}. 평원은 인내를, 코도는 나눔을 가르쳤소."
L["Gladly, {name}. Ancestors, steady my hand. Not my hooves; they're fine."] = "기꺼이, {name}. 조상님, 제 손을 굳건히. 발굽은 괜찮습니다."
L["Always, {name}. Cairne never refuses a friend, and he's taller than me."] = "언제든지, {name}. 케른께선 친구를 거절하지 않으시오. 나보다 크신 분인데도."
L["Ask anything, {name}. A tauren has strength to spare and time to listen."] = "뭐든 청하시오, {name}. 타우렌은 힘도 남고 들어 줄 시간도 많소."
L["Take this, {name}, and walk with the Earth Mother. You can't get lost."] = "이걸 받게, {name}. 대지 어머니와 함께 걷게나. 길 잃을 일은 없을 걸세."
L["May An'she light your path, {name}, and this go with you."] = "안셰가 그대 길을 비추길, {name}. 이것도 함께하길."
L["You looked like you could use a friend, {name}. I'm a very big one."] = "친구가 필요해 보였소, {name}. 난 아주 큰 친구라오."
L["Take this, {name}. The Earth Mother would scold me if I walked past."] = "받으시오, {name}. 그냥 지나쳤다간 대지모신께 혼나오."
L["Tread lightly, {name}, and take this. From someone who never has."] = "살살 걸으시게, {name}. 이것도 받고. 한 번도 그래 본 적 없는 놈의 말일세."
L["The wind said you'd pass, {name}, so I had this ready. Terrible gossip."] = "바람이 자네가 지나갈 거라더군, {name}. 그래서 이걸 준비했지. 지독한 수다쟁이야."
L["Take this, {name}. I'd lend you my kodo too, but he's less generous than me."] = "받으시오, {name}. 코도도 빌려주고 싶지만, 그 녀석은 나만큼 너그럽지 않소."
L["The shu'halo say carry what you can for others, {name}. I can carry a lot."] = "슈할로는 남을 위해 질 수 있는 만큼 지라 하오, {name}. 난 많이 질 수 있소."
L["Take this, {name}. If the centaur trouble you, say Thunder Bluff sends regards."] = "받으시오, {name}. 켄타우로스가 귀찮게 하면 썬더 블러프가 안부 전한다 하시오."
L["Here, {name}. Plainstriders run from me for no reason at all. You needn't."] = "자, {name}. 평원 새들은 괜히 날 보면 도망가오. 그대는 안 그래도 되오."
L["For you, {name}. Visit Mulgore sometime. The grass is soft and nobody hurries."] = "그대에게, {name}. 언제 멀고어에 오시오. 풀은 부드럽고 아무도 서두르지 않소."
L["Here, {name}. Grandmother blessed travellers and fed them. I'm out of bread."] = "자, {name}. 할머니는 나그네를 축복하고 먹이셨소. 난 빵이 떨어졌소."
L["The spirits asked me to mind you, {name}. I said yes before they'd finished."] = "영령들이 그대를 돌보라 하셨소, {name}. 말씀 끝나기도 전에 예 했지."
L["Here, {name}. Kodo share the watering hole; I can share this."] = "여기, {name}. 코도도 물웅덩이를 나눠 쓰는데, 이쯤이야 나눠야지."
L["Here, {name}. Tauren leave the world a little better, and a little trampled."] = "자, {name}. 타우렌은 세상을 조금 낫게, 그리고 조금 밟힌 채로 남기오."
L["The Earth Mother would offer you a nap, {name}. I offer this."] = "대지모신께선 낮잠을 주시겠지만, {name}, 난 이걸 드리오."
L["Druids call it a blessing, hunters luck, {name}. Tauren call it manners."] = "드루이드는 축복, 사냥꾼은 행운이라 하오, {name}. 타우렌은 예의라 하지."
L["Take this, {name}. If a harpy screeches at you, screech back. They hate that."] = "받으시오, {name}. 하피가 꽥 소리치면 같이 꽥 하시오. 질색하오."
L["Here, {name}. A tauren blessing: sturdy, slow to fade, smells faintly of sage."] = "자, {name}. 타우렌의 축복이오. 튼튼하고, 오래가고, 세이지 향이 은은하지."
L["Here, {name}. The Venture Company would charge you for this. I won't."] = "받으시오, {name}. 투자개발회사라면 돈을 받겠지만, 난 안 받소."
L["From the high mesas of Thunder Bluff, {name}, where even the wind is friendly."] = "썬더 블러프 높은 고원에서 왔소, {name}. 바람마저 다정한 곳이오."
L["The ancestors watch the roads, {name}. I just help them out a little."] = "조상님들이 길을 지켜보시오, {name}. 난 조금 거들 뿐이오."
L["A gift should be heavy with meaning and light to carry, {name}. This is both."] = "선물은 뜻은 무겁고 들기는 가벼워야 하오, {name}. 이게 그렇소."
L["The Earth Mother made the world wide so I'd meet folk like you, {name}. Here."] = "대지 어머니께서 세상을 넓게 지으신 건 자네 같은 이를 만나라는 뜻이지, {name}. 받게."
L["Hunt with respect and the land feeds you, {name}. That's my wisdom. Here."] = "존중하며 사냥하면 땅이 먹여 주오, {name}. 내 지혜는 그게 다요. 받으시오."
L["Here, {name}. Not every tauren would share. The Grimtotem certainly wouldn't."] = "받으시오, {name}. 모든 타우렌이 나누진 않소. 성난토템은 절대 안 나누지."
L["The Earth Mother watches over us both, {name}. Today I'll help her."] = "대지 어머니께서 우리 둘을 지켜보시지, {name}. 오늘은 내가 거들겠네."
L["Somebody warn the doorframes, {name}. Two of us, and now you're even sturdier."] = "누가 문틀한테 경고 좀 하게, {name}. 둘이나 있는데, 자넨 이제 더 튼튼해졌으니."
L["Plains or peaks, {name}, a shu'halo heart is a big one. Here's some of mine."] = "평원이든 봉우리든, {name}, 슈할로의 심장은 크지. 내 것 좀 나눠 주겠네."
L["Horns and helmets, {name}. Only another tauren knows the pain. This eases it."] = "뿔과 투구라니, {name}. 그 고통은 타우렌만 알지. 이게 좀 덜어 줄 걸세."
L["Rain on fur takes a week to dry, {name}. This keeps you warm meanwhile."] = "털에 비 맞으면 마르는 데 일주일이지, {name}. 그동안 이게 따뜻하게 해 줄 걸세."
L["Between tauren, {name}: the lifts were built by somebody smaller. Here."] = "타우렌끼리 말인데, {name}, 승강기는 더 작은 누가 만들었지. 받게."
L["Our ancestors watch us both, {name}. Let them see me share this with you."] = "조상님들이 우리 둘을 보고 계시지, {name}. 내가 이걸 나누는 걸 보시게 하세."
L["From Mulgore to Feralas, {name}, the herd finds itself, and looks after itself."] = "멀고어에서 페랄라스까지, {name}, 무리는 서로를 찾고 서로를 돌보지."
L["Take this, {name}, and get behind me. There's room for the whole party."] = "이걸 받고 내 뒤로 오게, {name}. 일행 모두 들어갈 자리가 있네."
L["The herd moves together, {name}, blessed. Mind my hooves; the herd has learned."] = "무리는 함께 움직이지, {name}. 축복받은 채로. 내 발굽 조심하게. 무리는 이미 배웠다네."
L["Low ceilings ahead, {name}? I'll be the first to find out. Take this."] = "앞에 천장이 낮소, {name}? 제일 먼저 알게 될 건 나요. 받으시오."
L["Here, {name}. I'm slow to anger, but I hold a grudge for the whole party."] = "받게, {name}. 난 화가 더디 나지만, 원한은 일행 몫까지 다 품는다네."
L["Take this, {name}. Need a wall to hide behind? I'm most of one. Come on."] = "이걸 받게, {name}. 숨을 벽이 필요한가? 내가 거의 벽이지. 이리 오게."
L["That'll steady you, {name}. When I war stomp, everybody sit down anyway."] = "이거면 중심 잡을 걸세, {name}. 그래도 내가 전투 발구르기 하면 다들 앉게."
L["Everyone fed? Everyone blessed? Good, {name}. Tauren never lead a hungry herd."] = "다들 먹었소? 축복도 받았소? 좋소, {name}. 타우렌은 굶은 무리를 이끌지 않소."
L["That'll keep you warm, {name}. Tauren wade. If it's deep, you're riding on me."] = "이거면 따뜻할 걸세, {name}. 타우렌은 걸어서 건너지. 깊으면 내 등에 타게."
L["Take this and stay close, {name}. My ancestors walk with us, more quietly."] = "이걸 받고 붙어 있게, {name}. 조상님들도 함께 걸으시지. 더 조용히."
L["Here, {name}. If I fall, don't try to carry me. Drag me. Fondly."] = "받게, {name}. 내가 쓰러지면 업으려 하지 말게. 끌고 가게. 다정하게."
L["We move like a stampede, {name}, blessed together. Sorry about the flowers."] = "우린 우르르 몰려가지, {name}. 다 같이 축복받고. 꽃들한텐 미안하네."
L["Take this, {name}. Nobody walks alone at the rear; I'll be there, looming."] = "이걸 받게, {name}. 후미엔 아무도 혼자 안 가네. 내가 우뚝 서 있을 테니."
L["There, {name}. Say when to charge. Tauren are slow to start, slower to stop."] = "됐네, {name}. 돌격할 때 말하게. 타우렌은 출발이 느리고 멈추는 건 더 느리지."
L["Take this; nobody wander, {name}. The last who did in the Barrens still is."] = "이걸 받게. 아무도 흩어지지 말고, {name}. 불모의 땅에서 그런 놈은 아직도 헤매네."
L["Here, {name}. A herd is strongest when nobody wanders off to graze."] = "받게, {name}. 무리는 아무도 풀 뜯으러 안 빠질 때 제일 강하지."
L["Here, {name}; watch the ground. Quilboar dig traps; I find them hoof first."] = "받게, {name}. 땅을 잘 보게. 가시멧돼지가 함정을 파거든. 난 발굽으로 다 찾지."
L["Into the fight with a calm heart and this, {name}. The rage can come later."] = "차분한 마음과 이것을 품고 싸우게, {name}. 분노는 나중에 와도 되네."
L["May the Earth Mother keep this herd, {name}. I've done my part."] = "대지 어머니께서 이 무리를 지켜 주시길, {name}. 내 몫은 다했네."
L["An'she rises, {name}, and so do we, with this. Slower, in my case."] = "안셰가 떠오르네, {name}. 우리도 이걸 품고 일어나지. 난 좀 느리지만."
L["The sun is An'she's eye, {name}. He's watching, so let's look generous."] = "해는 안셰의 눈이지, {name}. 보고 계시니 너그러워 보이세."
L["Morning, {name}. The kodo are up, the grass is wet, and this is yours."] = "좋은 아침이오, {name}. 코도는 일어났고, 풀은 젖었고, 이건 그대 것이오."
L["I've greeted the sun, the wind, two plainstriders, {name}. Now you, with this."] = "해와 바람과 평원질주자 둘에게 인사했네, {name}. 이제 자네에게, 이걸로."
L["Dew on the grass, dew on my fur, {name}. This will dry you out from inside."] = "풀에도 이슬, 내 털에도 이슬이네, {name}. 이게 속부터 말려 줄 걸세."
L["Early, {name}. That mist over Mulgore? Kodo breath. Here's a cleaner one."] = "이른 시간이군, {name}. 멀고어의 저 안개? 코도 입김일세. 더 깨끗한 기운을 주지."
L["Mu'sha keeps the night watch, {name}. I'll keep an eye on you too. Here."] = "무샤께서 밤을 지키시지, {name}. 나도 자넬 지켜보겠네. 받게."
L["The moon's out, {name}. Mu'sha sees you and approves of this. I asked."] = "달이 떴네, {name}. 무샤께서 자넬 보시고 이걸 허락하셨지. 내가 여쭸다네."
L["Late, {name}. The kodo are asleep, and they snore like thunder. Take this."] = "밤이 깊었소, {name}. 코도들이 천둥처럼 코를 고는군. 받으시오."
L["Stars out, {name}. Each one's an ancestor. That one's winking at your blessing."] = "별이 떴네, {name}. 하나하나가 조상님이지. 저 별은 자네 축복에 윙크하는군."
L["Mulgore is so quiet at night you hear the grass argue, {name}. Here, quietly."] = "멀고어의 밤은 풀이 다투는 소리가 들릴 만큼 고요하지, {name}. 조용히 받게."
L["Quiet now, {name}. At this hour, even my hooves tiptoe. And give gifts."] = "이제 조용히, {name}. 이 시간엔 내 발굽도 살금살금 걷지. 선물도 주고."
L["The Earth Mother made you well, {name}. Walk with me."] = "대지 어머니께서 널 잘 빚으셨어, {name}. 함께 걷자."
L["Peace, {name}. The winds of Mulgore are gentle today."] = "평안하렴, {name}. 오늘 멀고어의 바람은 부드러워."
L["You and I were meant to share this road, {name}."] = "너와 난 이 길을 함께 걷도록 정해져 있었어, {name}."
L["Well done, {name}! The Earth Mother watches you with pride."] = "잘했어, {name}! 대지 어머니께서 자랑스럽게 보고 계셔."
L["Mighty, {name}. Your strength honors the ancestors."] = "대단해, {name}. 네 힘이 선조들을 기리는구나."
L["That was a great hunt, {name}. The plains will sing of it."] = "멋진 사냥이었어, {name}. 평원이 그 노래를 부를 거야."
L["Rest, {name}. The Earth Mother will heal what I cannot."] = "쉬어, {name}. 내가 못 고치는 건 대지 어머니께서 고치셔."
L["Be calm, {name}. The ancestors watch over you, and so do I."] = "진정해, {name}. 선조들이 지켜보고 계시고, 나도 그래."
L["Slowly, {name}. Breathe with the land. You are safe now."] = "천천히, {name}. 대지와 함께 숨 쉬어. 이제 안전해."
L["Ya too kind, {name}! This one's from me."] = "너무 친절한데, {name}! 이건 내가 주는 거다."
L["Thanks, mon! Da spirits smile on ya, {name}."] = "고맙다, 친구! 영혼들이 너한테 미소 짓는다고, {name}."
L["Ya gave me good mojo, {name}. Now ya get some back, extra spicy."] = "좋은 기운 줬으니, {name}, 매운맛으로 돌려준다고."
L["Death's gonna be real disappointed, {name}. Thanks, mon."] = "죽음이 아주 실망하겠는데, {name}. 고맙다, 친구."
L["Fine work, {name}. Almost as fine as me. Almost."] = "솜씨 좋은데, {name}. 거의 나만큼. 거의."
L["A troll can grow back a hand, {name}. Can't grow back honour. Here."] = "트롤은 손이 다시 자란다고, {name}. 명예는 안 자라. 자, 갚는다."
L["Ya just made a troll smile, {name}, and we got a lot of teeth."] = "트롤을 웃게 만들었네, {name}. 우리 이빨 많다고."
L["Da loa keep a tally, {name}. You're on the good side of it."] = "로아가 장부를 적는다고, {name}. 넌 좋은 쪽에 있어."
L["Beat me to it, {name}! Darkspear hate bein' second. Now we're even."] = "선수 쳤네, {name}! 검은창은 두 번째를 싫어한다고. 이제 비겼다."
L["I owe ya now, {name}, and trolls only like owin' da loa. Settled."] = "이제 빚졌네, {name}. 트롤은 로아한테만 빚지고 싶다고. 자, 청산."
L["I'll tell all of Sen'jin 'bout ya, {name}. Makes a change from crabs."] = "센진 마을에 네 얘기 쫙 퍼뜨릴 거라고, {name}. 맨날 게 얘기만 했거든."
L["My hair just stood up taller, {name}. Didn't know it could. Thanks, mon."] = "머리카락이 더 솟았다고, {name}. 이게 더 되는 줄 몰랐네. 고맙다, 친구."
L["The spirits say give it back, {name}. They nag, but they're right."] = "영혼들이 돌려주래, {name}. 잔소리꾼들이지만 맞는 말이라고."
L["Mojo for mojo, {name}: oldest trade in the jungle."] = "주술엔 주술, {name}. 정글에서 제일 오래된 거래라고."
L["Vol'jin said repay kindness quick, {name}. He said a lot. Dat one stuck."] = "볼진이 친절은 빨리 갚으랬어, {name}. 말이 많았지. 그건 기억난다고."
L["That deserves a dance, {name}. Lucky ya: {buff} instead."] = "춤출 일이다, {name}. 다행인 줄 알아. 대신 {buff} 준다고."
L["Jungle rule, {name}: what ya give comes back, often with teeth. Not this one."] = "정글 법칙이다, {name}. 준 건 돌아온다고. 대개 이빨 달고. 이건 안 물어."
L["A gift for a troll, {name}? We never forget a kindness."] = "트롤한테 선물이라고, {name}? 우린 친절은 절대 안 잊어."
L["Old Sen'jin said a gift is a promise, {name}. I keep mine. Here."] = "센진 어르신이 선물은 약속이랬어, {name}. 난 약속 지킨다고. 자."
L["Back on the Echo Isles that earned a feast, {name}. Here's the short version."] = "메아리 섬이었으면 잔치감이다, {name}. 짧은 버전으로 준다고."
L["That one's goin' in the stories by the fire, {name}. Ya get a good part."] = "이건 모닥불 이야기에 들어간다, {name}. 너 좋은 역 맡았다고."
L["Nice, {name}. Darkspear pay back quick. We got places to be. Mostly the beach."] = "좋아, {name}. 검은창은 빨리 갚는다고. 갈 데가 있거든. 대개 해변이지만."
L["Stranglethorn gives nothin' for free, {name}. Nice to see somebody does."] = "가시덤불 골짜기는 공짜가 없어, {name}. 공짜로 주는 녀석 보니 좋다고."
L["Zalazane would've kept that for himself, {name}. Good thing ya ain't him."] = "잘라제인이었으면 혼자 챙겼을 거다, {name}. 네가 그놈이 아니라 다행이라고."
L["Sure thing, {name}. Hold still; mojo hates a movin' target."] = "그래, {name}. 가만있어. 주술은 움직이는 과녁을 싫어한다고."
L["No trouble, {name}. Da loa like ya."] = "문제없어, {name}. 로아가 널 좋아해."
L["Stay away from da voodoo, {name}. Except this one. This one's fine."] = "부두는 가까이하지 마, {name}. 이것만 빼고. 이건 괜찮다고."
L["Close ya eyes, {name}. Mojo gets shy when people watch."] = "눈 감아, {name}. 주술이 누가 보면 부끄럼 탄다고."
L["Ya don't gotta ask twice, {name}. Ya barely gotta ask once."] = "두 번 말할 필요 없어, {name}. 한 번도 겨우 필요하다고."
L["Sure, {name}. A troll is mostly swagger. The rest is this."] = "그래, {name}. 트롤은 대부분 허세라고. 나머진 이거고."
L["Ya asked polite, {name}. Polite gets the good stuff."] = "예의 바르게 물었네, {name}. 예의 바르면 좋은 걸 받는다고."
L["Ya came to the right troll, {name}. The wrong one's over there, fishin'."] = "제대로 된 트롤한테 왔네, {name}. 잘못된 트롤은 저기서 낚시 중이라고."
L["Yes, {name}. The loa owe me a favour, and I'm spendin' it on you."] = "그래, {name}. 로아가 나한테 빚진 게 있는데, 너한테 쓴다고."
L["Got a pouch full of mojo, {name}. Don't touch the other pouch."] = "주머니에 주술이 가득하다고, {name}. 다른 주머니는 만지지 마."
L["Anything for ya, {name}. Not my hair, though. Hair is sacred."] = "뭐든 해 줄게, {name}. 머리카락만 빼고. 머리는 신성하다고."
L["Troll magic, {name}, served hot. Blow on it first."] = "트롤 주술 나왔다, {name}. 뜨거우니 호호 불어 먹어."
L["Right away, {name}. A Zandalari priest would make a week of this."] = "바로 간다, {name}. 잔달라 사제였으면 일주일은 걸렸다고."
L["Easy one, {name}. Hard one's gettin' a raptor to sit still."] = "쉬운 거지, {name}. 어려운 건 랩터 가만 앉히기라고."
L["Troll rule, {name}: never make a friend beg or a raptor wait. Here."] = "트롤 규칙이다, {name}. 친구는 조르게, 랩터는 기다리게 하지 말 것. 자."
L["Don't wiggle, {name}. Last one who did got the spell and a new haircut."] = "꼼지락대지 마, {name}. 지난번에 꼼지락댄 놈은 주문에 새 머리까지 받았다고."
L["No problem, {name}. Darkspear always got time for a friend. And a nap."] = "문제없어, {name}. 검은창은 친구 위한 시간은 늘 있다고. 낮잠 시간도."
L["Sure, {name}. Hold still, like a fisherman at Sen'jin waitin' on a bite."] = "그래, {name}. 가만있어. 센진에서 입질 기다리는 낚시꾼처럼."
L["Yes, {name}. Vol'jin says never turn away a friend, and he's usually right."] = "그래, {name}. 볼진이 친구는 절대 내치지 말랬어. 대개 맞는 말 한다고."
L["Sure thing, {name}. I'll hum a little. Witch doctors say it helps."] = "물론이지, {name}. 콧노래 좀 할게. 부두술사들이 그게 효과 있댔다고."
L["Da loa watch over ya, {name}. They're real nosy that way."] = "로아가 널 지켜본다고, {name}. 그쪽으론 참 오지랖이 넓어."
L["Stay sharp, {name}. Take this with ya."] = "정신 바짝 차려, {name}. 이거 갖고 가."
L["Ya look like somebody who appreciate quality, {name}. Here: quality."] = "품질 좀 알아보게 생겼네, {name}. 자, 품질."
L["Here, {name}. Walk like ya own the jungle. I do."] = "자, {name}. 정글 주인처럼 걸어. 난 그렇게 걷는다고."
L["Everybody need mojo, {name}. I make so much I gotta give it away."] = "누구나 주술 기운이 필요하다고, {name}. 난 너무 많아서 나눠 줘야 해."
L["A little somethin' for ya, {name}. Don't ask where da loa got it."] = "작은 선물이다, {name}. 로아가 어디서 났는지는 묻지 마."
L["Go on, {name}. Whatever tries to eat ya now gets indigestion."] = "가 봐, {name}. 이제 널 먹으려는 놈은 체할 거라고."
L["Ya look dangerous now, {name}. Almost as dangerous as a troll."] = "이제 좀 위험해 보이네, {name}. 거의 트롤만큼."
L["No charge, {name}. Ya don't owe the loa a thing. Probably."] = "공짜다, {name}. 로아한테 빚지는 거 없어. 아마도."
L["Raptors got bigger teeth than me, {name}. Now they got a problem."] = "랩터들은 나보다 이빨이 크다고, {name}. 이제 걔들이 큰일이지."
L["Troll hospitality, {name}: ya get mojo, ya get a smile, ya don't get my fish."] = "트롤식 대접이다, {name}. 주술 주고, 미소 주고, 내 생선은 안 줘."
L["Walk with mojo, {name}. Everybody else is just walkin'."] = "주술 두르고 가라고, {name}. 남들은 그냥 걷는 거고."
L["Free mojo, {name}! Quick, before the witch doctor finds out."] = "공짜 주술이다, {name}! 부두술사가 알기 전에 얼른."
L["The loa said give this to the next good soul, {name}. That's you."] = "로아가 다음 착한 영혼한테 주라더라, {name}. 그게 너다."
L["Here, {name}. Hakkar never shared. Look what happened to him."] = "자, {name}. 학카르는 나눌 줄 몰랐지. 그 꼴 봐라."
L["Jungle's got two kinds of folk, {name}: ready, and lunch. You're ready."] = "정글엔 두 부류가 있다고, {name}. 준비된 놈, 그리고 점심거리. 넌 준비됐고."
L["Easy, {name}. This one tickles. Don't laugh; it gets offended."] = "살살, {name}. 이건 간지럽다고. 웃지는 마. 삐친다."
L["Take this, {name}. Darkspear never send a friend off empty-handed."] = "받아, {name}. 검은창은 친구를 빈손으로 안 보내."
L["Darkspear know what it is to need a friend far from home, {name}. Here."] = "검은창은 고향 떠나 친구가 필요한 게 뭔지 안다고, {name}. 자."
L["Watch for the Bloodscalps, {name}. Same tusks as me, worse manners. Take this."] = "가시덤불 골짜기 트롤들 조심해, {name}. 엄니는 나랑 같은데 매너는 꽝이라고. 받아."
L["Walk easy, {name}, with this. Life's long if ya don't rush it, short if ya do."] = "이거 갖고 느긋하게 가, {name}. 안 서두르면 인생은 길고, 서두르면 짧아."
L["My granny was a witch doctor, {name}. Share, she said, and look scary doin' it."] = "우리 할머니가 부두술사였어, {name}. 나눠라, 무섭게 생긴 얼굴로. 그러셨다고."
L["From Sen'jin Village, {name}. Smells a bit like fish. Works fine, though."] = "센진 마을산이다, {name}. 생선 냄새가 좀 나. 효과는 좋다고."
L["Stay loose, {name}. Tense folk trip on roots. Take this, and relax."] = "힘 빼, {name}. 긴장하면 뿌리에 걸려 넘어진다고. 이거 받고 쉬어."
L["The spirits whisper ya name, {name}. Somebody's. They said give ya this."] = "영혼들이 네 이름을 속삭여, {name}. 누구 이름인진 몰라도. 이걸 주라더라."
L["We look after our own, {name}. Always, mon."] = "우린 우리 식구를 챙긴다고, {name}. 언제나, 친구."
L["Da rest of Azeroth stand straight, {name}. We got style. Now ya got mojo too."] = "아제로스 녀석들은 꼿꼿이 서지, {name}. 우린 멋이 있어. 이제 너한텐 주술도 있고."
L["Ya tusks look sharp, {name}. Mine too. Now the rest of ya does."] = "엄니가 날카롭네, {name}. 내 것도 그렇고. 이제 너 나머지도 그래."
L["Every troll's family, {name}, and family gets this. Even ones owin' me gold."] = "트롤은 다 가족이야, {name}. 가족은 이걸 받지. 나한테 금 빚진 놈들까지도."
L["One day we take the Echo Isles back, {name}. Till then, take this."] = "언젠가 메아리 섬을 되찾자, {name}. 그때까진 이거 받아."
L["Two trolls, {name}. Da room just got taller, more relaxed, and blessed."] = "트롤 둘이네, {name}. 방이 더 높아지고, 더 느긋해지고, 축복까지 받았어."
L["The loa got their eyes on both of us, {name}. Let 'em see me share."] = "로아가 우리 둘을 다 지켜보고 있어, {name}. 내가 나누는 걸 보라지."
L["Troll to troll, {name}: only we know how hard it is to buy boots. Here."] = "트롤끼리니까, {name}. 장화 사는 게 얼마나 힘든지 우리만 알지. 받아."
L["Our ancestors had empires, {name}. We got each other, and this. Fair trade."] = "조상들한텐 제국이 있었지, {name}. 우리한텐 서로랑 이게 있어. 공정한 거래야."
L["Stay close, {name}. Trolls regenerate; da rest of ya get this instead."] = "붙어 있어, {name}. 트롤은 재생하잖아. 나머지 너희는 대신 이걸 받아."
L["Crew's got style, {name}. Now it's got mojo too."] = "우리 패거리 멋있지, {name}. 이제 주술까지 갖췄다고."
L["We go in together, {name}, blessed, and come out together. That's the plan."] = "같이 들어가고, {name}, 축복받은 채로, 같이 나온다. 그게 계획이야."
L["Nobody fallin' today, {name}; ya got this. Death can wait for the next group."] = "오늘은 아무도 안 쓰러져, {name}. 너한텐 이게 있잖아. 죽음은 다음 일행이나 기다리라고."
L["Take this, {name}; keep ya head down. I keep mine up. Somebody gotta look good."] = "이거 받고, {name}, 고개 숙여. 난 들고 있을게. 누군가는 폼 나야지."
L["Raptor formation, {name}: fast, loud, blessed, and nobody look back."] = "랩터 대형이야, {name}. 빠르고, 시끄럽고, 축복받고, 아무도 뒤 안 돌아봐."
L["Take this, {name}. If a big snake shows up, don't run. Stand behind me."] = "이거 받아, {name}. 큰 뱀 나타나면 뛰지 마. 내 뒤에 서."
L["Need more mojo, {name}? Just shout. Not too loud; the loa are nappin'."] = "주술 더 필요해, {name}? 불러. 너무 크게는 말고. 로아 낮잠 중이다."
L["Sen'jin will hear of this one, {name}. With this, it gets a happy endin'."] = "센진에서 이 얘기 할 거야, {name}. 이거면 해피 엔딩이지."
L["My tusks can't be everywhere, {name}, but this can. Stay near."] = "내 엄니가 어디든 있을 순 없지, {name}. 근데 이건 돼. 가까이 있어."
L["Nobody panic, {name}. Panic is bad mojo. This here is good mojo."] = "쫄지 마, {name}. 공포는 나쁜 주술이야. 이건 좋은 주술이고."
L["Take this, {name}. See an idol with glowin' eyes? Don't touch it. Trust me."] = "이거 받아, {name}. 눈 빛나는 우상 보이지? 만지지 마. 믿어."
L["Stay loose, {name}, and take this. Fights go better when ya smilin'. Mostly."] = "긴장 풀어, {name}. 이것도 받고. 웃으면 싸움이 더 잘 풀려. 대체로."
L["Darkspear fight together or not at all, {name}, and share the mojo. Here."] = "검은창은 함께 싸우거나 아예 안 싸워, {name}. 주술도 나누고. 받아."
L["Ready, {name}? Take this. Any Gurubashi, let me talk first. Then ya hit 'em."] = "준비됐어, {name}? 이거 받아. 구루바시 놈들은 내가 먼저 말해 볼게. 그다음 네가 패."
L["Take this and watch for traps, {name}. Trolls built half the old temples."] = "이거 받고 함정 조심해, {name}. 옛 신전 절반은 트롤이 지었거든."
L["The loa are watchin' this group, {name}. Let's give 'em a show. Start here."] = "로아가 이 일행을 보고 있어, {name}. 볼거리 좀 주자고. 여기서부터."
L["I got ya back, {name}. Trolls got long arms for a reason."] = "등 뒤는 내가 맡는다, {name}. 트롤 팔이 괜히 긴 게 아니라고."
L["Night's the best time for mojo, {name}. Nobody sees where it's from."] = "주술엔 밤이 최고라고, {name}. 어디서 왔는지 아무도 못 보거든."
L["The jungle wakes at night, {name}. So do I. This one's fresh."] = "정글은 밤에 깨어난다고, {name}. 나도. 이건 갓 뽑은 거다."
L["High moon, {name}, restless spirits. This keeps 'em off ya."] = "달이 높다, {name}. 영혼들이 들썩인다고. 이게 막아 줄 거야."
L["Hir'eek the bat loa keeps late hours too, {name}. This is from us both."] = "박쥐 로아 히리크도 밤을 샌다고, {name}. 이건 우리 둘이 주는 거다."
L["This late, {name}, only trolls and trouble are up. I'm the nice one. Here."] = "이렇게 늦으면, {name}, 깨어 있는 건 트롤이랑 말썽뿐이야. 난 착한 쪽. 받아."
L["Stars out, {name}. Each one a loa, Granny said. They all saw me give ya this."] = "별이 떴네, {name}. 할머니가 다 로아라 했지. 내가 이거 주는 걸 다 봤을 거야."
L["Ya be da best friend dis troll ever had, {name}."] = "넌 이 트롤이 가져 본 최고의 친구다, {name}."
L["Easy, {name}. Da loa smile on us both today."] = "진정해, {name}. 오늘은 로아께서 우리 둘에게 미소 지어."
L["Stay close, {name}, mon. Dis jungle be ours."] = "가까이 있어, {name}, 친구. 이 정글은 우리 거야."
L["Dat be how we do it, {name}! Ya got da spirit of da loa!"] = "바로 그거다, {name}! 넌 로아의 혼을 가졌어!"
L["Haha! Fine huntin', {name}! Ya make me proud, mon."] = "하하! 멋진 사냥이다, {name}! 네가 자랑스럽다, 친구."
L["Ya strike like a raptor, {name}! Dey never see ya comin'."] = "넌 랩터처럼 덮치는구나, {name}! 놈들은 네가 오는 걸 못 봐."
L["Easy, {name}. Da spirits not be takin' ya today."] = "진정해, {name}. 오늘은 정령들이 널 데려가지 않아."
L["Rest, {name}. Dis troll got ya, mon. Breathe slow."] = "쉬어, {name}. 이 트롤이 있잖아, 친구. 천천히 숨 쉬어."
L["Shh, {name}. Ya be safe now. Da loa be watchin' over ya."] = "쉿, {name}. 이제 안전해. 로아께서 지켜보셔."
L["Such courtesy does you credit, {name}. Nearly as much as it does me."] = "그 예의, 그대를 빛내 주는군요, {name}. 날 빛내는 것만은 못해도."
L["How gracious, {name}. Allow me to return the favour."] = "품위 있는 행동이군요, {name}. 나도 호의로 답하지요."
L["Thank you, {name}. I haven't felt this radiant since... well, this morning."] = "고마워요, {name}. 이렇게 눈부신 기분은... 음, 오늘 아침 이후 처음이네요."
L["Kind of you, {name}. We sin'dorei never turn down free magic. Ask anyone."] = "친절하군요, {name}. 신도레이는 공짜 마법은 절대 사양 안 해요. 소문났죠."
L["Exquisite, {name}. I would know; I only accept the exquisite."] = "훌륭하군요, {name}. 난 훌륭한 것만 받으니 확실하죠."
L["Lovely, {name}. I'll be insufferable about this all day. More than usual."] = "근사하네요, {name}. 오늘 하루 종일 이걸로 으스댈 거예요. 평소보다 더."
L["Thank you, {name}. It even goes with my gold trim. You have an eye."] = "고마워요, {name}. 내 금장식과도 어울리네요. 안목이 있으시군요."
L["Returned in kind, {name}. A prettier kind, admittedly. I can't help it."] = "같은 걸로 보답하죠, {name}. 좀 더 예쁜 걸로요. 어쩔 수 없네요."
L["Thank you, {name}. Visit Silvermoon; I'll show you all of it but Murder Row."] = "고마워요, {name}. 실버문에 오면 살인자 골목만 빼고 다 보여 줄게요."
L["Returned, {name}. Unlike Kael'thas, I give things back."] = "갚았어요, {name}. 캘타스와 달리 난 받은 건 돌려주거든요."
L["Thank you, {name}. I felt that to the tips of my ears, and that's a long way."] = "고마워요, {name}. 귀 끝까지 전해졌어요. 꽤 먼 길인데."
L["Thank you, {name}. That was so kind my eyes nearly changed colour again."] = "고마워요, {name}. 너무 친절해서 눈 색깔이 또 바뀔 뻔했어요."
L["A gift, unasked? Farstriders would call that an ambush. A lovely one, {name}."] = "청하지도 않은 선물? 원정순찰대라면 매복이라 하겠군요. 근사한 매복이에요, {name}."
L["Better than a mana crystal, {name}, and I've given those up. Mostly. Thank you."] = "마나 수정보다 낫네요, {name}. 그건 끊었어요. 대체로요. 고마워요."
L["Quick of you, {name}. Elves live for centuries, and you still beat me to it."] = "빠르군요, {name}. 수백 년 사는 엘프보다 먼저라니."
L["Charming, {name}. The sun favours the generous, and so do I."] = "매력적이네요, {name}. 태양은 베푸는 이를 아끼죠. 나도 그렇고요."
L["Thank you, {name}. I'll mention you at court. Well, at a very exclusive picnic."] = "고마워요, {name}. 궁정에서 그대 얘길 할게요. 음, 아주 격조 높은 소풍에서요."
L["Thank you, {name}. Courtesy is rare outside Silvermoon. Yours shines."] = "고마워요, {name}. 실버문 밖에선 예의가 귀한데, 그대의 예의는 빛나네요."
L["Unasked kindness, {name}! Somebody tell Rommath; he'll want to study it."] = "청하지도 않은 친절이라니, {name}! 롬마스한테 알려요. 연구하고 싶어 할 테니."
L["Naturally, {name}. Only the finest for you."] = "당연하지요, {name}. 그대에겐 최고만 드리죠."
L["For you, {name}? Of course. The sun gives freely."] = "{name}, 그대에게요? 물론이죠. 태양은 아낌없이 베푸니."
L["Patience, {name}. Radiance can't be rushed, only admired."] = "서두르지 마요, {name}. 광채는 재촉하는 게 아니라 감상하는 거예요."
L["Of course, {name}. {buff}, delivered with impeccable posture."] = "물론이죠, {name}. 흠잡을 데 없는 자세로 {buff} 대령이에요."
L["You asked nicely, {name}. In Silvermoon that counts for everything."] = "정중하게 청하셨군요, {name}. 실버문에선 그게 전부죠."
L["One moment, {name}. I never cast anything without checking my hair."] = "잠시만요, {name}. 머리 모양을 확인하지 않고는 아무것도 시전 안 해요."
L["At once, {name}. Keeping someone waiting is so terribly unfashionable."] = "당장 하죠, {name}. 남을 기다리게 하는 건 너무 촌스러우니까."
L["Certainly, {name}. Stand back a step; my sleeves are enchanted and very wide."] = "물론이죠, {name}. 한 걸음 물러서요. 내 소매는 마법에 걸렸고 아주 넓거든요."
L["Magisters would bill you, {name}. Blood Knights would lecture. I merely glow."] = "마법학자는 청구서를, 피의 기사단은 설교를 주겠죠, {name}. 난 빛날 뿐."
L["At once, {name}. If it goes well, tell everyone. If not, blame the robe."] = "당장 하죠, {name}. 잘되면 내 덕, 못되면 로브 탓이에요."
L["At once, {name}. The dragonhawk can wait; it's used to waiting while I dress."] = "당장 하죠, {name}. 용매는 기다려도 돼요. 내가 옷 입을 때마다 기다리거든요."
L["Gladly, {name}. We once took the Light from a naaru. Asking is so much nicer."] = "기꺼이요, {name}. 한때 나루에게서 빛을 빼앗았죠. 부탁이 훨씬 낫네요."
L["Three centuries of casting, {name}, and you're the first to say please."] = "삼백 년을 시전했는데, {name}, '부탁해요'라고 한 건 그대가 처음이에요."
L["Gladly, {name}. Silvermoon's brooms sweep themselves, so my hands are free."] = "기꺼이요, {name}. 실버문 빗자루는 알아서 쓸거든요. 손이 한가해요."
L["Of course, {name}. I keep my other spells for the rude."] = "물론이죠, {name}. 다른 주문들은 무례한 자들 몫으로 아껴 두죠."
L["Anar'alah belore, {name}. May the sun guide you, and light your good side."] = "아나랄라 벨로레, {name}. 태양이 그대를 인도하고, 잘 나온 쪽을 비추기를."
L["Shorel'aran, {name}. Fight with elegance, and with this."] = "쇼렐아란, {name}. 우아하게 싸우세요. 이것과 함께."
L["Take this, {name}. Whatever happens out there is merely a setback."] = "받으세요, {name}. 밖에서 무슨 일이 생기든 잠깐의 후퇴일 뿐이에요."
L["Everyone deserves to shine, {name}. Only a little less than me, of course."] = "누구나 빛날 자격이 있죠, {name}. 물론 나보다 조금 덜."
L["The sun is with you, {name}. I simply held the door for it."] = "태양이 그대와 함께해요, {name}. 난 문만 열어 줬을 뿐이죠."
L["Go on, {name}, take it. The Sunwell's back; we can afford to be generous."] = "어서 받아요, {name}. 태양샘도 돌아왔으니 이 정도 인심은 쓰죠."
L["For you, {name}: {buff}, lightly scented with Silvermoon."] = "{name}, 그대에게. 실버문 향을 살짝 입힌 {buff}."
L["Here, {name}. Hand-cast in Silvermoon, so do try not to scuff it."] = "여기요, {name}. 실버문 수제 주문이니까 흠집 내지 않게 조심해요."
L["A little Sunwell for you, {name}. It's been through a lot; treat it kindly."] = "태양샘 한 조각이에요, {name}. 고생 많이 한 샘이니 살살 다뤄 줘요."
L["Be prepared, {name}. We weren't, once, and now we have a scar for a road."] = "대비하세요, {name}. 우린 못 했다가 죽음의 흉터를 길로 쓰게 됐거든요."
L["Here, {name}. I only give to the worthy. How convenient that you walked by."] = "여기요, {name}. 자격 있는 자에게만 줘요. 마침 그대가 지나가다니, 편리하네요."
L["Take this, {name}. It's been in my family for moments."] = "받아요, {name}. 우리 가문에 대대로 내려온 거예요. 몇 초 동안."
L["We sin'dorei have lost much, {name}. Never our generosity. Or our cheekbones."] = "우리 신도레이는 많은 걸 잃었죠, {name}. 너그러움만은 빼고요. 광대뼈도요."
L["Take this, {name}. Should a mana wyrm follow you, it's only jealous."] = "받아요, {name}. 마나 벌레가 따라오면, 그냥 질투하는 거예요."
L["Seven thousand years to perfect generosity, {name}. We started last week."] = "너그러움을 완성하는 데 칠천 년이죠, {name}. 우린 지난주에 시작했어요."
L["Take this, {name}. It came through the Undercity orb, so it's slightly dizzy."] = "받아요, {name}. 언더시티 구슬을 타고 와서 좀 어지러워해요."
L["For you, {name}. It matches everything. I checked, obviously."] = "그대에게요, {name}. 어디에나 어울려요. 당연히 확인했죠."
L["Take this, {name}. If a ghoul stops you, say Silvermoon's still standing."] = "이걸 받으세요, {name}. 구울이 막으면 실버문은 아직 건재하다고 하세요."
L["The Sunwell shines for us both, {name}. Let me share its light."] = "태양샘은 우리 둘을 위해 빛나죠, {name}. 그 빛을 나눠 드릴게요."
L["Two sin'dorei, {name}. The day just got twice as elegant, and you blessed."] = "신도레이 둘이네요, {name}. 하루가 두 배로 우아해졌고, 당신은 축복받았죠."
L["You too, {name}? Two sin'dorei, one mirror. Take this; now you look better."] = "당신도요, {name}? 신도레이 둘에 거울 하나. 이걸 받으세요. 더 멋져 보여요."
L["Like the phoenix, {name}, we keep rising. This helps you look good doing it."] = "불사조처럼, {name}, 우린 계속 일어서죠. 이건 그때 멋져 보이게 해 줘요."
L["Between sin'dorei, {name}: yes, the Horde is loud. This, at least, is quiet."] = "신도레이끼리 말인데요, {name}. 네, 호드는 시끄럽죠. 이건 적어도 조용해요."
L["Sin'dorei to sin'dorei, {name}: we never speak of the green eyes. Take this."] = "신도레이끼리니까요, {name}. 초록 눈 얘긴 절대 안 해요. 이걸 받으세요."
L["Magister or Farstrider, {name}, the sun rises for us all. Here's some of it."] = "마법학자든 원정순찰대든, {name}, 해는 모두에게 뜨죠. 조금 나눠 드릴게요."
L["We knew Quel'Thalas before the Scourge, {name}. Here; let's earn the after."] = "우린 스컬지 이전의 쿠엘탈라스를 알죠, {name}. 받으세요. 그 이후를 일궈 봐요."
L["Do keep pace, {name}; you're blessed now. We're known for arriving beautifully."] = "보조 맞추세요, {name}. 이제 축복받았잖아요. 우린 멋지게 도착하기로 유명하거든요."
L["Stand where the light is good, {name}. With this on you, we'll look splendid."] = "빛 좋은 데 서세요, {name}. 이걸 두른 당신이면 우리 다 근사해 보일 거예요."
L["A party at last, {name}. I did dress for one, and I brought gifts."] = "드디어 일행이네요, {name}. 차려입고, 선물도 챙겨 왔어요."
L["The sun shines on all of us, {name}. Mostly on me, but I share it. Here."] = "해는 우리 모두를 비추죠, {name}. 주로 저를요. 그래도 나눠 드릴게요."
L["One for you, {name}, and one for the party's image, which I've taken on myself."] = "하나는 그대에게, {name}. 하나는 파티 이미지를 위해서. 그건 내가 맡았어요."
L["Here, {name}. If I fall, arrange me nicely. The rest I leave to the priest."] = "받으세요, {name}. 제가 쓰러지면 예쁘게 눕혀 주세요. 나머진 사제에게 맡길게요."
L["Take this; touch no enchanted relics, {name}. Well, I may. I've had training."] = "이걸 받고, 마법 유물은 만지지 마세요, {name}. 전 돼요. 배웠거든요."
L["Every expedition needs a ranger, {name}. I'm not one, but I bless well."] = "원정대엔 순찰자가 필요하죠, {name}. 전 아니지만, 축복은 잘해요."
L["We fight together, {name}, blessed, then tell it beautifully. I'll tell it."] = "함께 싸우죠, {name}. 축복받은 채로. 그다음 멋지게 이야기하고요. 이야긴 제가 해요."
L["Whoever mends us is to be thanked, {name}. Whoever blesses you, admired. Me."] = "우릴 치유하는 이에겐 감사를, {name}. 당신을 축복하는 이에겐 찬사를. 저요."
L["Take this, {name}. If it goes badly, we blame the Scourge. It's traditional."] = "이걸 받으세요, {name}. 잘못되면 스컬지 탓하죠. 전통이에요."
L["Mana potions are for emergencies, {name}. This is for you. I've had eleven."] = "마나 물약은 비상용이죠, {name}. 이건 당신 거예요. 전 오늘 열한 번 비상이었어요."
L["We walked out of the ashes once, {name}. With this, we'll walk out of anything."] = "우린 한 번 잿더미에서 걸어 나왔죠, {name}. 이거면 뭐든 헤쳐 나갈 거예요."
L["The sun has risen, {name}, and so have I. We coordinate. Here's its light."] = "해가 떴어요, {name}. 저도 일어났고요. 우린 맞춰서 움직이죠. 그 빛을 드릴게요."
L["Dawn over Quel'Thalas is lovelier, {name}, but this blessing will do. Just."] = "쿠엘탈라스의 새벽이 더 아름답지만, {name}, 이 축복이면 돼요. 겨우요."
L["Morning light, {name}: the most flattering hour. This makes it more so."] = "아침 햇살이에요, {name}. 제일 잘 나오는 시간이죠. 이게 더 그렇게 해 줘요."
L["Breakfast in Eversong is fruit, tea and arcane, {name}. Skip to the arcane."] = "영원노래 숲의 아침은 과일, 차, 비전이죠, {name}. 비전부터 가요."
L["Dawn, {name}. Red and gold across the sky. Here's some of it, for you."] = "새벽이에요, {name}. 하늘 가득 붉은빛과 금빛. 조금 나눠 드릴게요."
L["Morning, {name}. Only Silvermoon's guardians are up this early. And me. Here."] = "좋은 아침, {name}. 이렇게 일찍 깬 건 실버문 수호자들뿐이죠. 그리고 저. 받으세요."
L["You are a credit to Quel'Thalas, {name}. Truly."] = "넌 쿠엘탈라스의 자랑이야, {name}. 진심으로."
L["Even the Sunwell's light can't outshine you, {name}."] = "태양샘의 빛조차 너보다 빛나진 못해, {name}."
L["Stay by me, {name}. Elegance suits us both."] = "곁에 있어, {name}. 우아함은 우리 둘에게 잘 어울려."
L["Splendid, {name}! Grace and fury, perfectly balanced."] = "훌륭해, {name}! 우아함과 분노가 완벽한 균형이야."
L["Well done, {name}. The rangers of Silvermoon would envy you."] = "잘했어, {name}. 실버문의 순찰자들도 널 부러워할 거야."
L["Exquisite, {name}. Not a single wasted motion."] = "절묘해, {name}. 군더더기 동작이 하나도 없어."
L["Be still, {name}. Let the sun's light find you."] = "가만히 있어, {name}. 햇빛이 널 찾아오게 둬."
L["Shh, {name}. Rest now; I'll stand watch."] = "쉿, {name}. 이제 쉬어. 내가 망을 볼게."
L["Easy, {name}. We're both still here, and that's enough."] = "진정해, {name}. 우리 둘 다 아직 여기 있어. 그거면 돼."
L["Your generosity is noted, {name}. In triplicate. Suramar remembers its friends."] = "그 아량, 기록해 두죠, {name}. 세 부로. 수라마르는 벗을 잊지 않으니."
L["Most gracious, {name}. Allow me to repay you in kind."] = "참으로 고상하시군요, {name}. 같은 것으로 보답하지요."
L["Thank you, {name}. Ten thousand years under a dome; I'm still practising that."] = "고마워요, {name}. 만 년을 보호막 아래 살아서, 이 말은 아직 연습 중이에요."
L["A gift with no favour owed? The court would faint. Thank you, {name}."] = "대가 없는 선물이라니요? 궁정이 기절하겠군요. 고마워요, {name}."
L["Returned, {name}. We keep careful accounts of kindness. And of slights."] = "갚았어요, {name}. 우린 친절을 꼼꼼히 장부에 적거든요. 모욕도요."
L["I'll mention you to First Arcanist Thalyssra, {name}. Favourably, even."] = "탈리스라 님께 그대 얘기를 하죠, {name}. 좋게 말이에요."
L["Most kind, {name}. In Suramar we'd hold a banquet. Consider it held."] = "친절하시군요, {name}. 수라마르라면 연회를 열었겠죠. 연 걸로 치세요."
L["I'd send a formal letter of thanks, {name}, but this seemed quicker."] = "정식 감사 서한을 보내려 했지만, {name}, 이게 더 빠르겠더군요."
L["In Elisande's court a gift hid a knife, {name}. Yours hides none. Thank you."] = "엘리산드의 궁정에선 선물에 칼이 숨어 있었죠, {name}. 그대 건 아니네요. 고마워요."
L["Thank you, {name}. My manasaber approves of you, and she approves of no one."] = "고마워요, {name}. 내 마나세이버가 그대를 인정했어요. 아무도 인정 안 하는 애가요."
L["Exquisite, {name}. Once I'd have said 'adequate'. The world has humbled me."] = "절묘하군요, {name}. 예전 같으면 '쓸 만하다' 했겠죠. 세상이 날 겸손하게 했어요."
L["You fed a mind that once went hungry, {name}. We never forget those who do."] = "한때 굶주렸던 정신을 채워 줬군요, {name}. 그런 이는 결코 잊지 않아요."
L["Centuries of court etiquette, {name}, and 'thank you' still says it best."] = "수백 년 궁정 예법을 익혔지만, {name}, 여전히 '고마워요'가 제일이네요."
L["Thank you, {name}. You're invited to the next masquerade. Masks mandatory."] = "고마워요, {name}. 다음 가면무도회에 초대할게요. 가면은 필수예요."
L["Thank you, {name}. Oculeth would open a portal to say so. I'll simply cast."] = "고마워요, {name}. 오큘레스라면 차원문부터 열었겠죠. 난 그냥 시전할게요."
L["Of course, {name}. A little arcane polish, just for you."] = "물론이죠, {name}. 그대만을 위한 비전의 광택을 살짝."
L["A reasonable request, {name}. Granted."] = "합당한 요청이군요, {name}. 들어드리죠."
L["Certainly, {name}. The short version; the long one takes a lunar cycle."] = "그러죠, {name}. 짧은 버전으로요. 긴 버전은 한 달이 걸리거든요."
L["A request, how refreshing. The court only ever made demands. Here, {name}."] = "부탁이라니, 신선하군요. 궁정은 요구만 했거든요. 여기요, {name}."
L["Done, {name}, and free. Elisande would have charged you a favour for it."] = "됐어요, {name}. 공짜로요. 엘리산드였다면 대가를 요구했을 거예요."
L["There, {name}. No need to bow. A small nod would be lovely, though."] = "됐어요, {name}. 절할 필요는 없어요. 가볍게 고개만 끄덕여 주면 좋겠지만."
L["Of course, {name}. I've perfected this since before most cities had walls."] = "물론이죠, {name}. 대부분의 도시에 성벽도 없던 시절부터 갈고닦았거든요."
L["Granted, {name}. I'd ask a favour back, but I'm trying to be less Suramar."] = "들어드리죠, {name}. 대가를 청하고 싶지만, 덜 수라마르스럽게 사는 중이라."
L["Certainly, {name}. Forgive the flourish. We can't cast plainly; we've tried."] = "그러죠, {name}. 손짓이 과해도 이해해요. 수수하게는 안 되더군요. 해 봤어요."
L["At once, {name}. Elisande once stopped time. I only need a second."] = "당장 하죠, {name}. 엘리산드는 시간을 멈췄지만, 난 1초면 돼요."
L["Of course, {name}. The ley lines here are shallow, but I'll make do."] = "물론이죠, {name}. 여기 지맥은 얕지만, 어떻게든 해 보죠."
L["Very well, {name}. Stand in the moonlight. Or by that lamp. Lamps will do."] = "좋아요, {name}. 달빛 아래 서요. 아니면 저 등불 옆에. 등불도 돼요."
L["Naturally, {name}. Suramar had a spell for everything. I remember several."] = "당연하죠, {name}. 수라마르엔 모든 일에 주문이 있었죠. 몇 개는 기억나요."
L["Take this, {name}. Arcane gifts are wasted on the idle."] = "받으세요, {name}. 비전의 선물은 게으른 자에겐 낭비니까요."
L["A spark of Suramar's arcana for you, {name}. Use it wisely."] = "수라마르 비전의 불꽃 한 점이에요, {name}. 현명하게 쓰시길."
L["I've gone without magic once, {name}. I don't recommend it. Take this."] = "마법 없이 지내 본 적이 있어요, {name}. 추천은 안 해요. 받으세요."
L["The world outside the dome is so large, {name}. And so under-enchanted. Here."] = "보호막 밖 세상은 참 넓네요, {name}. 마법은 너무 부족하고. 여기요."
L["Arcwine is traditional, {name}, but {buff} travels better."] = "비전술이 전통이지만, {name}, 들고 다니기엔 {buff} 쪽이 낫죠."
L["Do take this, {name}. It's rude to refuse Suramar's hospitality. Very rude."] = "받으세요, {name}. 수라마르의 환대를 거절하는 건 무례해요. 아주 무례하죠."
L["Here, {name}. I'm told this is how outsiders say hello. Charming custom."] = "여기요, {name}. 바깥에선 이렇게 인사한다더군요. 매력적인 풍습이에요."
L["Take this, {name}. Magic hoarded is magic spoiled, as Suramar learned."] = "받으세요, {name}. 쌓아 둔 마법은 썩는 법이죠. 수라마르가 배웠듯이."
L["Once, I'd have made you bow for this, {name}. We've all grown."] = "예전 같으면 이걸 주고 절을 받았을 거예요, {name}. 우리 모두 컸죠."
L["The Kirin Tor do this too, {name}, bless them. Quite nicely, for newcomers."] = "키린 토도 이걸 하죠, {name}. 기특하게도. 신참치곤 꽤 잘해요."
L["A gift from under the dome, {name}. Kept fresh for a very, very long time."] = "보호막 아래서 온 선물이에요, {name}. 아주, 아주 오래 신선하게 보관했죠."
L["Enjoy this, {name}. I used to cast it on nobility. You're an improvement."] = "즐겨요, {name}. 예전엔 귀족에게만 시전하던 거예요. 그대 쪽이 낫네요."
L["I packed for the outside world like a gala, {name}. Four capes. Take this."] = "바깥세상에 연회 가듯 짐을 쌌어요, {name}. 망토만 넷. 이거 받아요."
L["Here, {name}. Suramar work: overdesigned, overdecorated, and flawless."] = "여기요, {name}. 수라마르 솜씨죠. 과한 설계, 과한 장식, 그리고 완벽."
L["Here, {name}. In Suramar this came with a string quartet. Do hum something."] = "여기요, {name}. 수라마르에선 현악 사중주가 딸려 나왔죠. 콧노래라도 불러 줘요."
L["Suramar's children shine together again, {name}. Let me add to your glow."] = "수라마르의 자녀들이 다시 함께 빛나네요, {name}. 당신 빛을 더해 드릴게요."
L["Shal'dorei, {name}! You packed arcwine? No? Then take this instead."] = "샬도레이군요, {name}! 비전 포도주 챙겼어요? 아니라고요? 그럼 대신 이걸요."
L["Suramar's own, {name}. Take this; the rest of the world won't do it so well."] = "수라마르 사람이군요, {name}. 이걸 받아요. 다른 데선 이렇게 잘 못 하거든요."
L["We survived the Legion and the withering, {name}. We can spare this."] = "우린 군단과 시듦에서 살아남았죠, {name}. 이 정도는 나눌 수 있어요."
L["Our tailors made it out of Suramar too, {name}. Take this to go with the robes."] = "우리 재단사들도 수라마르를 빠져나왔죠, {name}. 로브에 어울리게 이걸 받아요."
L["We both remember going hungry, {name}. Never again; here, take what I have."] = "우리 둘 다 굶주림을 기억하죠, {name}. 다신 안 돼요. 제가 가진 걸 받아요."
L["Out from under the dome, {name}. The sky's so big. This helps."] = "돔 밖으로 나왔네요, {name}. 하늘이 너무 넓어요. 이게 도움이 될 거예요."
L["Two shal'dorei, {name}. The locals will think it's a gala. Gifts are expected."] = "샬도레이 둘이네요, {name}. 동네 사람들은 연회인 줄 알 거예요. 선물은 필수죠."
L["An expedition, {name}! In Suramar this blessing needed six permits."] = "원정이네요, {name}! 수라마르에선 이 축복에 허가증이 여섯 장 필요했어요."
L["The dome kept us safe, {name}. Now one another must. Gladly; here."] = "돔이 우릴 지켜 줬죠, {name}. 이젠 서로 지켜야 해요. 기꺼이요. 받으세요."
L["Arcane for everyone, {name}. The court would call it waste. I call it company."] = "모두에게 비전 마법을, {name}. 궁정은 낭비라 하겠지만, 난 동료애라 부르죠."
L["Take this, {name}, and follow my lead. Ten thousand years of walking in step."] = "이걸 받고 절 따라와요, {name}. 만 년 동안 발맞춰 걸었거든요."
L["In a party one shares one's magic, {name}. How novel. I rather like it."] = "파티에선 마법을 나누는군요, {name}. 참 새롭네요. 꽤 마음에 들어요."
L["An outing is a masquerade, {name}: smile, keep moving, and take a gift."] = "나들이는 가면무도회예요, {name}. 웃고, 계속 움직이고, 선물을 받으세요."
L["Stay in the light of my spells, {name}. It's the most flattering in the party."] = "내 주문 빛 안에 있어요, {name}. 이 파티에서 제일 잘 받는 조명이에요."
L["After Elisande's court, {name}, this is a holiday. Nobody poisons the gifts."] = "엘리산드 궁정에 비하면, {name}, 이건 휴가죠. 선물에 독을 타는 사람도 없고요."
L["Lost? Follow the one who glows, {name}. That's me. Here, now you glow too."] = "길을 잃었어요? 빛나는 사람을 따라와요, {name}. 저예요. 자, 이제 당신도 빛나요."
L["Take this, {name}. If I start lecturing on ley lines, do interrupt. Politely."] = "이걸 받으세요, {name}. 제가 지맥 강의를 시작하면 끊어 주세요. 정중하게요."
L["I watched my people wither, {name}. I won't watch friends fade. Nobody falls."] = "내 백성이 메말라 가는 걸 봤어요, {name}. 벗은 안 보내요. 아무도 안 쓰러져요."
L["Here, {name}. Tell me if I'm being grand. I lose track. It's the millennia."] = "받으세요, {name}. 제가 거들먹거리면 말해 줘요. 감을 잃거든요. 수천 년 탓이에요."
L["Night at last, {name}. Add this glow and some lanterns: nearly Suramar."] = "드디어 밤이네요, {name}. 이 빛에 등불 몇 개만 더하면 거의 수라마르예요."
L["Under the dome it was always night, {name}. I feel at home, and generous."] = "돔 아래는 늘 밤이었죠, {name}. 집에 온 기분이라 너그러워지네요."
L["The stars are out, {name}. We had better ones in Suramar. This will do too."] = "별이 떴네요, {name}. 수라마르 별이 더 좋았지만, 이것도 괜찮아요."
L["Nightborne, {name}, and here's the night. I'm dressed for it; now so are you."] = "나이트본이에요, {name}. 밤이 왔네요. 전 밤에 맞게 차려입었고, 이제 당신도요."
L["At this hour, {name}, Suramar dressed for dinner. Here's your finery."] = "이 시간이면, {name}, 수라마르는 만찬 준비로 차려입었죠. 당신 성장을 드릴게요."
L["Daylight, {name}. Ten thousand years under a dome, and it startles me. Here."] = "햇빛이네요, {name}. 만 년을 돔 아래 살았더니 깜짝 놀라요. 받으세요."
L["An early hour, {name}. The court never rose before noon. I'm reforming. Here."] = "이른 시간이네요, {name}. 궁정은 정오 전엔 안 일어났죠. 저는 고치는 중이에요. 받으세요."
L["Morning, {name}. The sun here is so very... unenchanted. Take this instead."] = "좋은 아침이에요, {name}. 여기 태양은 참... 마법이 없네요. 대신 이걸 받으세요."
L["Morning, {name}. We warded Suramar against all but the sun. I've warded you."] = "좋은 아침, {name}. 우린 해만 빼고 모든 것에서 수라마르를 지켰죠. 당신은 제가 지켰어요."
L["Dawn, {name}: when the court's gossip went to bed. Here's mine, and this."] = "새벽이에요, {name}. 궁정 소문이 잠자리에 들던 시간. 제 소문과 이걸 드릴게요."
L["You remind me there is more to life than arcwine, {name}."] = "삶엔 비전 포도주보다 소중한 게 있구나, {name}."
L["Stay with me, {name}. Suramar's beauty pales beside a friend."] = "곁에 있어, {name}. 수라마르도 친구 앞에선 빛바래."
L["How fortunate I am, {name}, to walk with one so loyal."] = "이렇게 충직한 존재와 함께 걷다니 난 행운아야, {name}."
L["Superb, {name}. Elisande's finest could not have done better."] = "훌륭해, {name}. 엘리산드의 정예도 이보단 못해."
L["Well done, {name}. That was as precise as a ley line."] = "잘했어, {name}. 지맥처럼 정확했어."
L["Remarkable, {name}. The Nightwell would glow for you."] = "대단해, {name}. 밤샘도 널 위해 빛날 거야."
L["Rest, {name}. I will not let the Withered take you."] = "쉬어, {name}. 시든 자들이 널 데려가게 두지 않을 거야."
L["Calm, {name}. Breathe slowly; the worst has passed."] = "진정해, {name}. 천천히 숨 쉬어. 최악은 지나갔어."
L["Hush, {name}. Let the stars keep you while you heal."] = "쉿, {name}. 낫는 동안 별들이 널 지켜 주게 둬."
L["A favour for a favour, {name}! Pleasure doing business."] = "호의엔 호의로, {name}! 거래 즐거웠다고!"
L["Thanks, {name}! Consider your account settled in full."] = "고마워, {name}! 이걸로 계산 끝, 완납이야!"
L["Aw, {name}. I'd invoice you, but I'm feeling sentimental. It'll pass."] = "아이고, {name}. 청구서 쓰려다 감성에 젖어서 참는다. 금방 깰 거야."
L["Thanks, {name}! I checked it for fine print. There wasn't any. Weird!"] = "고마워, {name}! 깨알 같은 약관 찾아봤는데 없더라. 이상하네!"
L["Returned with interest, {name}. Minus the interest. Don't get used to it."] = "이자까지 쳐서 갚는다, {name}. 이자는 빼고. 익숙해지진 마."
L["Much obliged, {name}! You've just been upgraded to preferred customer."] = "고마워, {name}! 방금 VIP 고객으로 승급됐어."
L["I'd name a rocket after you, {name}, but my rockets never last long. Thanks!"] = "네 이름 딴 로켓을 만들고 싶은데, {name}, 내 로켓은 오래 못 가서. 고마워!"
L["I'd have charged fifty gold for that, {name}. Let's call us even."] = "원래 50골드 받는 건데, {name}. 퉁치자고."
L["Thanks, {name}! Quick hands. You'd do well in Booty Bay."] = "고마워, {name}! 손 빠른데. 무법항에서도 잘 먹히겠어."
L["A deal where both sides profit, {name}! I'd heard of those. Never seen one."] = "양쪽 다 이득 보는 거래라니, {name}! 소문으로만 들었지. 실물은 처음이야."
L["First free gift since Kezan blew up, {name}. Returning it before I price it."] = "케잔 터진 뒤 첫 공짜 선물이다, {name}. 값 매기기 전에 돌려줄게."
L["Thanks, {name}! I appraised it at priceless. Here's one appraised the same."] = "고마워, {name}! 감정가는 '값을 매길 수 없음'. 같은 감정가로 돌려준다."
L["Kindness in, kindness out, {name}. Best returns since the kaja'mite boom."] = "친절 넣고 친절 받고, {name}. 카자마이트 호황 이후 최고 수익률이야."
L["Even trade, {name}? My accountant just fainted. He does that around fair deals."] = "공정 거래라고, {name}? 우리 회계사 방금 기절했다. 공정한 거래만 보면 저래."
L["Thanks, {name}! I'd shake on it, but I count my fingers after. Habit, not you."] = "고마워, {name}! 악수하고 싶은데, 하고 나면 손가락을 세거든. 습관이야, 너 때문 아니고."
L["Thanks, {name}! Gadgetzan could use a few more like you."] = "고마워, {name}! 가젯잔에 너 같은 사람이 몇 명만 더 있으면 좋겠다."
L["You got it, {name}! Time is money, friend!"] = "알았어, {name}! 시간은 금이라고, 친구!"
L["Deal, {name}! I'll put it on your tab. Kidding!"] = "거래 성사, {name}! 외상으로 달아 둘게. 농담이야!"
L["Right away, {name}! Satisfaction guaranteed or your {buff} back."] = "바로 간다, {name}! 불만족 시 {buff} 전액 환불!"
L["{buff}, {name}! Tips optional. Encouraged. Optional."] = "{buff} 나왔다, {name}! 팁은 선택. 권장. 선택."
L["Fast, cheap or good, {name}? Today you get all three. Don't spread it around."] = "빠르게, 싸게, 좋게 중 하나? {name}, 오늘은 셋 다야. 소문내지 마."
L["Sure thing, {name}! No explosions this time, I promise. Mostly promise."] = "물론이지, {name}! 이번엔 폭발 없어, 약속해. 거의 약속해."
L["For you, {name}? No charge. Put that in writing and I'll deny it."] = "너한텐 공짜야, {name}. 문서로 남기면 발뺌할 거지만."
L["Sure, {name}! Quote's zero gold. Lowest I've ever quoted. It stings a little."] = "좋아, {name}! 견적은 0골드. 내 평생 최저 견적이야. 좀 쓰리네."
L["Coming up, {name}! Full warranty included. Valid until it wears off."] = "나간다, {name}! 완전 보증 포함. 보증 기간은 효과 끝날 때까지."
L["Sure, {name}! I'd tinker with it, but you look in a hurry."] = "물론이지, {name}! 좀 손보고 싶은데, 바빠 보이네."
L["Easy, {name}. Steamwheedle rule: keep customers alive. They pay longer."] = "쉽지, {name}. 스팀휘들 규칙이야. 손님은 살려 둬라. 그래야 오래 내지."
L["Gadgetzan's got the water trade, {name}. I've got this. Better margins."] = "가젯잔은 물장사, {name}. 난 이 장사. 마진이 더 좋지."
L["Kezan standard, {name}: fast, loud, and done before you read the terms."] = "케잔 표준이야, {name}. 빠르고, 시끄럽고, 약관 읽기 전에 끝."
L["On it, {name}! Goblins never keep a customer waiting. Unless it pays."] = "바로 간다, {name}! 고블린은 손님을 안 기다리게 해. 그게 돈이 안 된다면."
L["This one's on the house, {name}. Don't tell the Trade Prince."] = "이건 서비스야, {name}. 무역왕한텐 비밀이다?"
L["Top-shelf stuff, zero fees, {name}. Today only!"] = "최고급 상품, 수수료 없음, {name}. 오늘만이야!"
L["Free sample, {name}! If you like it, you know where to find me."] = "무료 샘플이야, {name}! 마음에 들면 어디로 오면 되는지 알지?"
L["Here, {name}. If anything explodes near you today, that was unrelated."] = "자, {name}. 오늘 근처에서 뭐가 터지면, 이거랑은 무관한 거다."
L["Goodwill's an asset, {name}. Here's some {buff} for my books."] = "호감도 자산이지, {name}. 장부 채우는 셈 치고 {buff} 받아."
L["Take this, {name}. Safety first! Or third. It's on the list somewhere."] = "받아, {name}. 안전 제일! 아니, 제삼인가. 목록 어딘가엔 있어."
L["Cast in record time, {name}! The record's mine. I set it just now."] = "신기록으로 시전 완료, {name}! 기록 보유자는 나. 방금 세웠어."
L["Kaja'Cola gives you ideas, {name}. This does the rest. Take it!"] = "카자콜라는 아이디어를 주지, {name}. 나머진 이게 해 줘. 받아!"
L["Here, {name}. Go make your fortune. I'll want a cut."] = "자, {name}. 가서 한몫 잡아. 내 몫은 떼 주고."
L["Zeppelin's late again, {name}, so I've time to be generous."] = "비행선이 또 늦네, {name}. 덕분에 인심 쓸 시간이 생겼어."
L["Here, {name}. Patent pending. Try it out and tell your rich friends."] = "자, {name}. 특허 출원 중. 써 보고 부자 친구들한테 소문내."
L["Consider this an investment, {name}. In you. I expect heroic returns."] = "투자라고 생각해, {name}. 너한테. 영웅급 수익 기대한다."
L["Take it, {name}! My last shipment sank off Kezan, so everything's clearance."] = "받아, {name}! 지난 화물이 케잔 앞바다에 가라앉아서 전부 떨이야."
L["The Venture Company charges for this, {name}. I'm the competition. Here."] = "투자개발회사는 이거 돈 받아, {name}. 난 경쟁사고. 자."
L["Every goblin has a soft spot, {name}. Mine's small and guarded. You found it."] = "고블린도 약한 구석이 있어, {name}. 내 건 작고 경비도 삼엄한데. 네가 찾았네."
L["Take this, {name}. It's the only thing I own with no lien on it."] = "받아, {name}. 내 물건 중 유일하게 저당 안 잡힌 거야."
L["You'll be rich someday, {name}. I can tell. Remember who gave you this."] = "넌 언젠가 부자 될 거야, {name}. 딱 보여. 이거 누가 줬는지 기억해 둬."
L["Anything for a fellow entrepreneur, {name}!"] = "동료 사업가를 위해서라면 뭐든지, {name}!"
L["Kezan's finest, together again, {name}. Here, free. Keep a hand on your purse."] = "케잔 최고의 인재들이 다시 뭉쳤네요, {name}. 자, 공짜예요. 지갑은 꼭 쥐고요."
L["Fellow goblin, {name}? Then you know this is a very, very rare discount."] = "고블린이야, {name}? 그럼 이게 아주아주 드문 할인인 거 알지?"
L["Goblins look after goblins, {name}. It's cheaper than hiring guards."] = "고블린은 고블린끼리 챙겨, {name}. 경비 고용하는 것보다 싸거든."
L["Kezan's gone, {name}, but the greed made it out. Not today, though. Here."] = "케잔은 사라졌지만, {name}, 탐욕은 살아남았죠. 오늘만은 빼고요. 받으세요."
L["Between goblins, {name}, this never happened. I have a reputation."] = "고블린끼리니까, {name}, 이건 없던 일이다. 나도 체면이 있어."
L["Bilgewater or Steamwheedle, {name}, we float to the top. This helps."] = "빌지워터든 스팀휘들이든, {name}, 우린 늘 위로 떠오르죠. 이게 도움이 돼요."
L["Remember the volcano, {name}? We sold tickets. This one's free. Proud times."] = "화산 기억나요, {name}? 입장권 팔았죠. 이건 공짜예요. 자랑스러운 시절이었죠."
L["Group rate, {name}! Everybody here gets it half off. Of free."] = "단체 할인이야, {name}! 전원 반값. 공짜의 반값."
L["Nobody dies on my contract, {name}. Here's insurance. The paperwork's awful."] = "제 계약서엔 사망자가 없어요, {name}. 여기 보험이요. 서류 작업이 끔찍하거든요."
L["We split the take even, {name}. This is your share. I did the maths. Trust me."] = "몫은 공평하게 나눠요, {name}. 이게 당신 몫이에요. 계산은 제가 했어요. 믿어요."
L["There, {name}. Everyone's stronger, and everyone owes me. Invoices later."] = "됐다, {name}. 다들 세졌고, 다들 나한테 빚졌어. 청구서는 나중에."
L["Stick together, {name}. Mercenaries cost gold; friends only cost this."] = "뭉쳐 다니자, {name}. 용병은 골드가 들지만, 친구는 이거면 돼."
L["Everybody's covered, {name}. Not insured, mind. Covered. Different price."] = "전원 보호 완료, {name}. 보장은 아니고 보호야. 요금제가 달라."
L["The risk report on this outing says 'no', {name}. This lowers the risk."] = "이번 나들이 위험 보고서엔 '안 됨'이라고 적혀 있어요, {name}. 이게 위험을 줄여 줘요."
L["Take this, {name}. Nobody touches the big red lever. There's always one."] = "이걸 받아요, {name}. 아무도 큰 빨간 레버는 건드리지 마요. 꼭 하나씩 있거든요."
L["Here, {name}. If this goes south, I've got a rocket. Seats one. Working on it."] = "받아요, {name}. 일이 틀어지면 로켓이 있어요. 1인승이지만요. 개발 중이에요."
L["We're a company now, {name}. I'm treasurer. Here's your benefits package."] = "우린 이제 회사예요, {name}. 전 회계 담당이고요. 여기 복리후생이요."
L["Stay alive, {name}. Nobody sells resurrections yet, so take this. Free."] = "살아 있어요, {name}. 아직 부활은 아무도 안 팔거든요. 그러니 이걸 받아요. 공짜예요."
L["Take this, {name}, and stay close. I've already sold the story of this trip."] = "이걸 받고 붙어 있어요, {name}. 이번 여행 이야기는 벌써 팔아 버렸거든요."
L["Early bird gets the gold, {name}! Here's a freebie. Don't tell the other birds."] = "일찍 일어나는 새가 골드를 번다, {name}! 공짜 하나. 다른 새들한텐 비밀."
L["Morning, {name}! Markets open in an hour. Until then, I'm feeling generous."] = "좋은 아침, {name}! 한 시간 뒤 장 열린다. 그때까진 인심 좀 쓰지."
L["Up early, {name}? Smart. Time is money, and this is cheapest in the morning."] = "일찍 일어났네요, {name}? 똑똑하네. 시간은 돈이고, 이건 아침이 제일 싸요."
L["Dawn, {name}. Rich goblins sleep in. I'm not rich yet, so I'm handing out this."] = "새벽이에요, {name}. 부자 고블린은 늦잠 자죠. 전 아직 아니라서 이걸 나눠 줘요."
L["Fresh day, fresh ledger, {name}. You're the first entry. The good column."] = "새 날엔 새 장부지, {name}. 첫 줄은 너야. 수입 칸에."
L["You're worth more than a bank vault, {name}. And you don't charge interest."] = "넌 은행 금고보다 값져, {name}. 이자도 안 받고."
L["Best investment I ever made, {name}. Zero upkeep. Mostly."] = "내 최고의 투자야, {name}. 유지비 제로. 거의."
L["Stick with me, {name}. Partners split everything fifty-fifty."] = "나랑 붙어 있어, {name}. 동업자는 뭐든 반반이야."
L["Ka-ching! Nice work, {name}! That's a bonus for you."] = "짤랑! 잘했어, {name}! 보너스 줄게."
L["Now that's what I call a return on investment, {name}!"] = "이게 바로 투자 수익이지, {name}!"
L["Boom! Great job, {name}. I'll get you a raise."] = "쾅! 훌륭해, {name}. 월급 올려 줄게."
L["Whoa, easy, {name}. You're too valuable to lose."] = "워워, 진정해, {name}. 넌 잃기엔 너무 소중해."
L["Hold together, {name}. I'm not filing an insurance claim on you."] = "버텨, {name}. 너 때문에 보험금 청구는 안 할 거야."
L["Rest up, {name}. Take all the time you need. On the house."] = "푹 쉬어, {name}. 시간은 얼마든지. 이건 서비스야."
L["Thank you, {name}! The caravan always repays a kindness. Usually in string."] = "고마워요, {name}님! 대상단은 받은 친절을 꼭 갚아요. 주로 끈으로요."
L["How kind, {name}! You're on the caravan's good list now."] = "다정하셔라, {name}님! 대상단 좋은 친구 명단에 올렸어요."
L["Oh, I'll keep this, {name}! I keep everything. Here's one for you."] = "어머, 이건 간직할게요, {name}님! 전 뭐든 간직하거든요. 이건 드릴게요."
L["Thanks, {name}! Here's yours back. Well, a new one. Hardly used."] = "고마워요, {name}님! 돌려드릴게요. 아니, 새 거예요. 거의 안 썼어요."
L["My ears just went straight up, {name}. That means I'm very pleased."] = "방금 귀가 쫑긋 섰어요, {name}님. 아주 기쁘다는 뜻이에요."
L["By tonight's campfire, {name}, this story will have a sandworm in it. Thanks!"] = "오늘 밤 모닥불 앞에선, {name}님, 이 얘기에 모래벌레가 나올 거예요. 고마워요!"
L["I'd gift-wrap yours, {name}, but all my wrapping is somebody's old map."] = "포장해 드리고 싶은데, {name}님, 포장지가 전부 누군가의 옛 지도라서요."
L["The alpacas saw that, {name}. They'll tell everyone how nice you are. Thanks!"] = "알파카들이 봤어요, {name}님. 좋은 분이라고 여기저기 소문낼 거예요. 고마워요!"
L["Thank you, {name}! I'd give you my best button, but this is better. Slightly."] = "고마워요, {name}님! 제일 아끼는 단추를 드리려다, 이게 더 나아서요. 쪼끔."
L["Ooh, a present, {name}! I'll trade you one of mine."] = "우와, 선물이네요, {name}님! 제 것도 하나 바꿔 드릴게요."
L["Thanks, {name}! That goes in the good pouch. Not the rock pouch. The good one."] = "고마워요, {name}님! 이건 좋은 주머니에 넣을게요. 돌 주머니 말고 좋은 거요."
L["In Vol'dun that would've cost a whole waterskin, {name}. Thank you!"] = "볼던이었으면 물주머니 하나는 줘야 했을 거예요, {name}님. 고마워요!"
L["Thanks, {name}! Your name goes on the wagon. Between the alpaca and the dent."] = "고마워요, {name}님! 마차에 이름 새길게요. 알파카랑 찌그러진 자국 사이에."
L["Kindness is the one thing the desert never buried, {name}. Thank you."] = "사막도 친절만은 묻지 못했어요, {name}님. 고마워요."
L["Rakera says repay quick, {name}, before you forget which pocket it's in. Here!"] = "라케라가 그랬어요, {name}님. 어느 주머니에 뒀는지 잊기 전에 빨리 갚으라고. 여기요!"
L["Nobody's given me anything I didn't dig up first, {name}. Thank you!"] = "제가 먼저 파내지 않은 걸 받은 건 처음이에요, {name}님. 고마워요!"
L["Of course, {name}! Shake the sand out and hold still."] = "물론이죠, {name}님! 모래 좀 털고 가만히 있어요."
L["Coming right up, {name}! Caravan service, no waiting."] = "바로 갑니다, {name}님! 대상단 서비스, 대기 없음!"
L["Sure, {name}! Let me dig it out... rope, rocks, a nice rock... here it is!"] = "그럼요, {name}님! 잠깐 찾아볼게요... 밧줄, 돌, 예쁜 돌... 여기 있다!"
L["Hold on, {name}! Tail's in the way, one moment... there!"] = "잠깐만요, {name}님! 꼬리가 걸려서, 잠시만... 됐다!"
L["One {buff}, {name}! Only slightly sandy."] = "{buff} 하나요, {name}님! 모래가 살짝 묻었어요."
L["Ask a vulpera and you'll get something, {name}. Usually odd. Not today!"] = "불페라한테 부탁하면 뭐든 나와요, {name}님. 대개 이상한 게. 오늘은 빼고요!"
L["Yours, {name}! Vulpera love giving things. Almost as much as finding them."] = "받으세요, {name}님! 불페라는 주는 걸 좋아해요. 줍는 거 다음으로요."
L["Here, {name}! Patched it up myself. Holds better than it looks."] = "여기요, {name}님! 제가 직접 기웠어요. 보기보다 튼튼해요."
L["Sure, {name}! Stand upwind. Sandstorm last week; I'm still shedding it."] = "그럼요, {name}님! 바람 부는 쪽에 서요. 지난주 모래 폭풍이 아직 털에서 떨어져요."
L["YES! Sorry, {name}, too loud? The desert's very big. You have to shout in it."] = "좋아요! 앗, {name}님, 너무 컸죠? 사막은 넓어서 소리쳐야 들리거든요."
L["Of course, {name}. Caravan rule: nobody asks twice for water or for help."] = "물론이죠, {name}님. 대상단 규칙이에요. 물이든 도움이든 두 번 청하게 하지 않기."
L["On it, {name}! Small spell, big fox, bigger ears. Wait. Other way round."] = "바로요, {name}님! 작은 주문, 큰 여우, 더 큰 귀. 잠깐, 거꾸로다."
L["For you, {name}? Easy! Caravan folk never say no to a neighbour."] = "{name}님 부탁이면 쉽죠! 대상단 사람은 이웃 부탁을 거절 안 해요."
L["Every traveller needs something for the road, {name}. I checked: not a rock."] = "나그네라면 길에서 쓸 게 필요하죠, {name}님. 확인했어요, 돌 아니에요."
L["Keep this, {name}. The desert is long and the water is short."] = "챙겨 가요, {name}님. 사막은 길고 물은 부족하니까."
L["Found this lying around, {name}. Kidding! It's fresh. Take it!"] = "길에서 주웠어요, {name}님. 농담이에요! 새 거예요. 받으세요!"
L["Here, {name}. Best thing in my pack, and I've got a lot of pack."] = "여기요, {name}님. 제 짐 중에 최고예요. 짐이 엄청 많은데도요."
L["In the dunes you share your shade and your spells, {name}. Here."] = "사막에선 그늘도 주문도 나누는 법이에요, {name}님. 여기요."
L["Some {buff} for you, {name}. I'd haggle, but you look busy."] = "{name}님, {buff} 드릴게요. 흥정하고 싶지만 바빠 보이셔서."
L["A gift from the whole caravan, {name}! They'll never know."] = "대상단 모두가 드리는 선물이에요, {name}님! 다들 모르겠지만요."
L["For the road, {name}. Roads are the best part. Roads, and snacks."] = "가는 길에 쓰세요, {name}님. 여행은 길이 최고예요. 길이랑 간식이요."
L["Here, {name}! I swapped a hat for a thing, and the thing for this. Good trade!"] = "여기요, {name}님! 모자를 뭔가랑, 그 뭔가를 이거랑 바꿨어요. 남는 장사!"
L["Nobody walks past anybody in the dunes, {name}. Bad luck, and rude. Here."] = "사막에선 아무도 그냥 지나치지 않아요, {name}님. 재수 없고 무례하거든요. 여기요."
L["My nose says trouble's ahead of you, {name}. Take this. My nose is never wrong."] = "제 코가 앞에 말썽이 있대요, {name}님. 이거 받아요. 제 코는 틀린 적 없어요."
L["Too many spells in my pack, {name}. They jingle. Take one, please."] = "가방에 주문이 너무 많아요, {name}님. 짤랑거려요. 하나 가져가 주세요."
L["If you find anything shiny later, {name}, you know where my ears are. Here!"] = "나중에 반짝이는 거 찾으면, {name}님, 제 귀가 어디 있는지 아시죠? 여기요!"
L["Wait, {name}! You nearly left without this. Deserts eat people who do that."] = "잠깐요, {name}님! 이거 두고 갈 뻔했어요. 사막은 그런 사람을 잡아먹어요."
L["Stew's not ready yet, {name}, so this is the starter."] = "스튜가 아직이에요, {name}님. 그러니 이건 애피타이저예요."
L["A fellow wanderer! The caravan is never far, {name}, nor its gifts."] = "같은 방랑자네요! 대상단은 늘 가까이 있어요, {name}. 선물도요."
L["Ears up, {name}! Always nice to share a spell with a fellow fox."] = "귀 쫑긋, {name}님! 같은 여우랑 주문 나누는 건 언제나 좋아요."
L["Vulpera to vulpera, {name}: here's this. I've three spare spoons too."] = "불페라끼리니까요, {name}. 이거 받아요. 여분 숟가락도 세 개 있어요."
L["Vol'dun raised us both, {name}. Sand in the fur, luck in the pack. Have some."] = "볼더스가 우리 둘을 키웠죠, {name}. 털엔 모래, 배낭엔 행운. 좀 나눠 줄게요."
L["Ears to ears, {name}: I heard you needed this."] = "귀에서 귀로 들었어요, {name}. 이게 필요하다고요."
L["Remember the caravan fires, {name}? Everybody sang badly and shared. Here."] = "대상단 모닥불 기억나요, {name}? 다들 노래는 못했지만 나눠 먹었죠. 받아요."
L["Vol'dun's far behind us, {name}, half of it in our fur. This I brought for you."] = "볼더스는 멀어졌지만, {name}, 반은 우리 털에 남았죠. 이건 당신 주려고 가져왔어요."
L["Caravan rules, {name}: stick together, share water and this. Never the alpaca."] = "대상단 규칙이에요, {name}. 뭉쳐 다니고, 물이랑 이건 나누고. 알파카는 절대 안 돼요."
L["Anything shiny in there, {name}, I saw it first. This shiny bit is yours."] = "저 안에 반짝이는 건 다, {name}, 제가 먼저 봤어요. 이 반짝이는 건 당신 거예요."
L["One for the party, {name}! A caravan's only as fast as its slowest alpaca."] = "파티에 하나씩요, {name}님! 대상단은 제일 느린 알파카만큼만 빠르거든요."
L["Here, {name}. Keep your pack shut. I don't mean to take things. I give, too."] = "받아요, {name}. 배낭은 닫아 둬요. 일부러 가져가는 건 아니에요. 주기도 하고요."
L["Lost in a city, never in a cave, {name}. Caves are houses with no rent. Here."] = "도시에선 길을 잃어도, 동굴에선 절대 안 잃어요, {name}. 동굴은 월세 없는 집이죠. 받아요."
L["Take this, {name}. I'm small, so I'll check the tiny tunnels. You take the big."] = "이걸 받아요, {name}. 전 작으니까 작은 굴을 볼게요. 큰 건 당신이 맡아요."
L["Shout if you need more, {name}. I've probably got it. It's probably dented."] = "더 필요하면 불러요, {name}. 아마 있을 거예요. 아마 찌그러졌겠지만."
L["There, {name}. I'll take the back. Nobody gets left behind in a caravan."] = "됐어요, {name}. 뒤는 제가 맡을게요. 대상단에선 아무도 낙오 안 해요."
L["A caravan with no wagon, {name}! Fast, light, nowhere to nap. Here's a boost."] = "수레 없는 대상단이네요, {name}! 빠르고 가볍지만 낮잠 잘 곳이 없어요. 힘 좀 실어 줄게요."
L["Scouted ahead by nose, {name}: danger and old cheese. Take this first."] = "코로 앞을 정찰했어요, {name}. 위험이랑 오래된 치즈 냄새. 이것부터 받아요."
L["Everybody fed? Everybody watered? Good. Now this, {name}. Caravan order."] = "다들 밥 먹었죠? 물 마셨죠? 좋아요. 이제 이거요, {name}님. 대상단 순서예요."
L["We vulpera travel by night, {name}. Cool sand, sleepy scorpids, and this."] = "우리 불페라는 밤에 다녀요, {name}. 시원한 모래, 졸린 전갈, 그리고 이것."
L["Desert nights get cold, {name}. Here, something warm-ish."] = "사막의 밤은 추워요, {name}님. 여기, 따끈... 아니, 미지근한 거요."
L["Stars out, {name}. All signposts, and I can't read them. I can give you this."] = "별이 떴네요, {name}. 다 이정표인데 전 못 읽어요. 이건 드릴 수 있어요."
L["Good hour for foxes, {name}. The ears work best when it's quiet. So does this."] = "여우에게 좋은 시간이에요, {name}. 조용할 때 귀가 제일 잘 들리거든요. 이것도 그렇고요."
L["Past dark and I'm just waking up, {name}. First thing: this, for you."] = "해가 졌는데 전 이제 막 깼어요, {name}. 제일 먼저, 이걸 드릴게요."
L["I'll curl up in my tail later, {name}. Best blanket I own. First, this."] = "이따 꼬리 덮고 잘 거예요, {name}님. 제일 좋은 이불이죠. 그 전에 이거요."
L["Every caravan needs a friend like you, {name}."] = "모든 대상단엔 너 같은 친구가 필요해, {name}."
L["The desert's kinder with you beside me, {name}."] = "네가 곁에 있으면 사막도 다정해, {name}."
L["You and me against the sands, {name}. Always."] = "너와 나, 모래에 맞서서, {name}. 언제나."
L["Ha! Clever and quick, {name}! A true caravan guardian."] = "하! 영리하고 빠르구나, {name}! 진정한 대상단 수호자야."
L["Well done, {name}! The whole caravan will hear about this."] = "잘했어, {name}! 대상단 모두가 이 얘기를 듣게 될 거야."
L["Sharp work, {name}! Nobody messes with our camp."] = "날카로웠어, {name}! 아무도 우리 야영지를 못 건드려."
L["Easy, {name}. Curl up and rest. I'll keep watch."] = "진정해, {name}. 웅크리고 쉬어. 내가 지킬게."
L["There now, {name}. Every caravan stops to tend its own."] = "자, {name}. 대상단은 언제나 멈춰서 제 식구를 돌봐."
L["Breathe, {name}. The sand can wait. You come first."] = "숨 쉬어, {name}. 모래는 기다려도 돼. 네가 먼저야."
L["A kindness returned is a kindness doubled, {name}."] = "돌려준 친절은 두 배가 되는 법이라네, {name}."
L["Thank you, {name}. You have restored my balance."] = "고맙네, {name}. 덕분에 내 균형이 돌아왔다네."
L["Somewhere, a Sha just went hungry. Thank you, {name}."] = "어딘가에서 샤 하나가 굶게 됐구먼. 고맙네, {name}."
L["Thank you, {name}. Aysa would bow, Ji would cheer. I will do both, badly."] = "고맙네, {name}. 아이사는 절을, 지는 환호를 했겠지. 난 둘 다 하겠네. 서툴게."
L["Thank you, {name}. I will think of you at my next meal, and the one after."] = "고맙네, {name}. 다음 끼니 때 자넬 생각하겠네. 그다음 끼니 때도."
L["Chen always said: never refuse a gift. Or a drink. Thank you, {name}."] = "첸이 늘 말했지. 선물은 거절 말라고. 술도. 고맙네, {name}."
L["I was about to nap, {name}, but this is better. Slightly. Thank you."] = "막 낮잠 자려던 참이었네, {name}. 그런데 이게 더 좋군. 조금. 고맙네."
L["A hozen would have thrown something, {name}. I was raised better. Thank you."] = "호젠이었다면 뭘 던졌을 걸세, {name}. 난 제대로 배웠지. 고맙네."
L["That was very pandaren of you, {name}. All that's missing is a dumpling."] = "참 판다렌다운 일일세, {name}. 만두 하나만 곁들이면 완벽하겠군."
L["At Halfhill that earns a prize turnip, {name}. I left mine at home. Thank you."] = "언덕골이었다면 상으로 순무를 받았을 걸세, {name}. 내 건 집에 두고 왔네. 고맙네."
L["Grandmother kept a jar of kindnesses, {name}. Yours goes in; this comes out."] = "할머니는 친절을 항아리에 모으셨지, {name}. 자네 걸 넣고, 이걸 꺼내네."
L["Thank you, {name}. In the Jade Forest my door is open, and my pantry more so."] = "고맙네, {name}. 비취 숲에 오면 우리 집 문은 활짝, 찬장은 더 활짝일세."
L["You move like the Shado-Pan, {name}. I never saw that coming. Thank you."] = "음영파처럼 움직이는군, {name}. 오는 줄도 몰랐네. 고맙네."
L["Like rain on a rice paddy, {name}. The paddy never says thank you. I do."] = "논에 내린 단비 같군, {name}. 논은 고맙단 말을 안 하지만, 난 하네."
L["Thank you, {name}. Li Li would put this in her travel journal. With drawings."] = "고맙네, {name}. 리리라면 여행 일지에 적었을 걸세. 그림까지 그려서."
L["Thank you, {name}. The August Celestials are busy, so I thank you for all four."] = "고맙네, {name}. 천신들께서 바쁘시니, 네 분 몫까지 내가 인사하네."
L["Stormstout ale knocks a pandaren flat, {name}. So did that. Thank you."] = "스톰스타우트 술은 판다렌도 뻗게 하지, {name}. 자네 친절도 그렇군. 고맙네."
L["Now we are even, {name}. A pandaren never lets a kindness go cold."] = "이제 비겼네, {name}. 판다렌은 친절이 식게 두지 않는다네."
L["Of course, {name}. Patience, and it is done. Patience is the slow part."] = "물론이지, {name}. 조금만 참으면 다 된다네. 참는 게 느려서 그렇지."
L["With pleasure, {name}. A kind deed is never wasted."] = "기꺼이 하지, {name}. 선행은 결코 헛되지 않다네."
L["At once, {name}. Quick for a pandaren, which is not saying much."] = "당장 하지, {name}. 판다렌치고는 빠르게. 그래 봐야 별거 아니지만."
L["Master Shang Xi said: help whoever asks, {name}. I listened."] = "샹 시 사부께선 청하는 이는 누구든 도우라 하셨네, {name}. 난 그 말을 따랐지."
L["A Tushui master would make you meditate first, {name}. I will skip that part."] = "투슈이 사부라면 명상부터 시켰을 걸세, {name}. 그건 건너뛰세."
L["Anything for you, {name}. Except the last dumpling. Let us not be silly."] = "자네를 위해서라면 뭐든지, {name}. 마지막 만두만 빼고. 실없는 소린 말게."
L["One {buff}, {name}, brewed strong. The recipe stays a secret."] = "{buff} 한 잔, 진하게 우렸네, {name}. 비법은 비밀일세."
L["Stand like a crane, {name}: one leg, calm face. Two legs is also fine."] = "학처럼 서게, {name}. 한 다리로, 평온한 얼굴로. 두 다리도 괜찮네."
L["We never refuse a request, {name}. Or a second helping."] = "부탁은 절대 거절 안 하네, {name}. 한 그릇 더도."
L["The last to ask me for help, {name}, was an island-sized turtle. You're easier."] = "지난번에 도와 달라던 건 섬만 한 거북이었네, {name}. 자네가 훨씬 수월하군."
L["Pandaren help like we cook, {name}: slowly, generously, and far too much of it."] = "판다렌은 요리하듯 돕지, {name}. 천천히, 넉넉히, 그리고 지나치게 많이."
L["Certainly, {name}. Let me put down my bowl. ...There. That was the hard part."] = "물론이지, {name}. 그릇 좀 내려놓고... 됐네. 이게 제일 어려운 부분이었지."
L["Yes, {name}. Grandfather said never make guests ask twice. He said it twice."] = "그러지, {name}. 할아버지께선 손님이 두 번 청하게 하지 말라 하셨네. 두 번이나."
L["Hold still, {name}. I am calm, you are calm, the spell is calm. Nobody panic."] = "가만있게, {name}. 나도 평온, 자네도 평온, 주문도 평온. 아무도 당황 말게."
L["Take this, {name}. And perhaps a cup of tea afterward?"] = "받게, {name}. 그리고 끝나면 차 한잔 어떤가?"
L["Balance in all things, {name}. Take this, and go with a light heart."] = "만사에 균형을, {name}. 이걸 받고 가벼운 마음으로 가게나."
L["Take this, {name}. A grummle would sell it to you for a luckydo."] = "받게, {name}. 그러믈이었으면 행운 부적 받고 팔았을 걸세."
L["The jinyu say the waters foretold this, {name}. They say that a lot."] = "진유는 물이 이걸 예언했다 하더군, {name}. 늘 그 소리지만."
L["The Huojin say act first. The Tushui say think first. I say: here, {name}."] = "후오진은 행동 먼저, 투슈이는 생각 먼저. 난 이것 먼저일세. 받게, {name}."
L["A pandaren stood up to give you this, {name}. Treasure it."] = "판다렌이 일어나서까지 주는 걸세, {name}. 소중히 여기게."
L["Fight like a monk, {name}: calm, quick, blessed, and then a long lunch."] = "수도사처럼 싸우게, {name}. 차분하고, 빠르고, 축복받고, 그다음엔 긴 점심."
L["Go gently with this, {name}. The turtle got where it was going, unhurried."] = "이걸 지니고 천천히 가게, {name}. 거북은 서두르지 않고도 목적지에 닿았지."
L["A hug would be forward, {name}. This is next best, and less furry."] = "포옹은 실례겠지, {name}. 이게 그다음으로 좋은 걸세. 털도 덜 날리고."
L["Take this, {name}. If a fight finds you, roll away. Rolling is very underrated."] = "이걸 받게, {name}. 싸움이 찾아오면 굴러서 피하게. 구르기는 아주 과소평가됐어."
L["For you, {name}. It is warm, round and full of good intentions. Like me."] = "자네 주려고, {name}. 따뜻하고 둥글고 선의로 꽉 찼지. 나처럼."
L["Take this, {name}. My kite is stuck in a tree, so I have time for good deeds."] = "받게, {name}. 연이 나무에 걸려서 착한 일 할 시간이 생겼다네."
L["I carried this from Pandaria, {name}. Also a keg. The keg is mine."] = "판다리아에서부터 들고 왔네, {name}. 술통도 하나. 술통은 내 걸세."
L["The virmen stole my carrots, {name}, but this they will never get. Here."] = "토깽이들이 내 당근은 훔쳐 갔지만, {name}, 이건 못 가져가지. 받게."
L["On the Wandering Isle, {name}, strangers get soup. This travels better."] = "유랑도에선 나그네에게 국을 대접하지, {name}. 이건 들고 다니기 더 좋네."
L["Pandaren look soft, {name}. So does this, until it saves you."] = "판다렌은 물렁해 보이지, {name}. 이것도 그래. 자넬 살리기 전까진."
L["Chi-Ji says there is always hope, {name}. I say there is always a spare. Here."] = "치지께선 희망은 늘 있다 하셨지, {name}. 난 여분은 늘 있다 하네. 받게."
L["We must share a brew when the road allows, {name}! For now, share this."] = "길이 허락하면 술 한잔 나눠야지, {name}! 지금은 이걸 나누세."
L["Shen-zin Su would be proud of us, {name}, and of this. Or asleep. Hard to tell."] = "션진 수가 우릴 자랑스러워하겠군, {name}. 이것도. 아니면 자고 있거나. 알 수가 없지."
L["Two pandaren, {name}. An innkeeper just felt a chill. Here, it warms."] = "판다렌 둘이라니, {name}. 어디선가 여관 주인이 오싹했겠군. 자, 이건 따뜻하다네."
L["Liu Lang would approve, {name}: two of us far from home, sharing. Here."] = "리우 랑도 좋아하겠군, {name}. 고향 멀리서 둘이 나누고 있으니. 받게."
L["Tushui or Huojin, {name}, we both left the turtle. Here's a taste of home."] = "투슈이든 후오진이든, {name}, 우린 거북을 떠났지. 고향 맛 좀 보게."
L["Pandaren to pandaren, {name}: the brews out here are thin. This is not."] = "판다렌끼리 하는 말인데, {name}, 바깥 술은 싱겁지. 이건 안 그렇다네."
L["We both smell of rice wine and road dust, {name}. This smells of neither. Here."] = "우리 둘 다 쌀술과 길먼지 냄새가 나지, {name}. 이건 어느 쪽도 아니라네. 받게."
L["Pandaren look after pandaren, {name}. Mostly by feeding them. This comes first."] = "판다렌은 판다렌을 챙기지, {name}. 주로 먹여서. 이건 전채일세."
L["A gift, a fight, then a meal, {name}. That is the correct order."] = "선물, 싸움, 그다음 식사, {name}. 그게 올바른 순서라네."
L["Stay together, {name}, like dumplings in a steamer. Warm now, and ready."] = "찜통 속 만두처럼 뭉쳐 있게, {name}. 이제 따뜻하고, 준비됐지."
L["We move as one, {name}, and now blessed as one. Slowly, perhaps."] = "우린 하나로 움직이네, {name}. 이제 하나로 축복받았고. 좀 느릴지는 몰라도."
L["Balance, {name}: one fights, one heals, one carries snacks. And one gives this."] = "균형이라네, {name}. 하나는 싸우고, 하나는 치유하고, 하나는 간식 들고. 하나는 이걸 주지."
L["Take this, {name}. If we fall, we fall together, and then nap. Let us not."] = "이걸 받게, {name}. 쓰러지면 같이 쓰러지고, 그다음 낮잠이지. 그러지 마세."
L["Here, {name}. Stay behind me. I am soft, but I am very wide."] = "받게, {name}. 내 뒤에 있게. 난 물렁해도 아주 넓다네."
L["Take this, {name}. If we win, I will cook. If we lose, I will cook, but sadly."] = "이걸 받게, {name}. 이기면 내가 요리하지. 져도 요리하고. 슬프게."
L["Breathe, {name}. In, and out. Feel that? Now hit things, calmly."] = "숨 쉬게, {name}. 들이쉬고, 내쉬고. 느껴지나? 이제 차분하게 치게."
L["Quickly, {name}, take this. I am in a hurry. It happens about once a decade."] = "어서, {name}, 이걸 받게. 내가 바쁘다네. 십 년에 한 번쯤 있는 일이지."
L["A party is like a brew, {name}: odd ingredients. I've just added one more."] = "일행은 술 같다네, {name}. 재료가 별나지. 방금 하나 더 넣었네."
L["Here, {name}. If I fall, roll me somewhere safe. Carrying me is not an option."] = "받게, {name}. 내가 쓰러지면 안전한 데로 굴려 주게. 업는 건 불가능하네."
L["Pandaren fight like water, {name}. This flows into you: calm, then everywhere."] = "판다렌은 물처럼 싸우지, {name}. 이게 자네 안으로 흘러들지. 고요하다가, 어디에나."
L["Up before the tea, {name}? Brave. Here, instead of the tea."] = "차보다 먼저 일어났나, {name}? 용감하군. 자, 차 대신 이걸 받게."
L["Morning, {name}. First this, then breakfast, then more breakfast."] = "좋은 아침일세, {name}. 먼저 이거, 그다음 아침, 그다음 또 아침."
L["A new day, {name}, and nobody has spilled anything. Let us begin with this."] = "새날이네, {name}. 아직 아무도 뭘 엎지르지 않았지. 이것부터 시작하세."
L["Halfhill's farmers have been up for hours, {name}. I just rose, but with this."] = "언덕골 농부들은 몇 시간 전에 일어났네, {name}. 난 방금 일어났지만, 이걸 들고."
L["Morning mist, {name}. Just like home, until a kobold walked by. Have this."] = "아침 안개라네, {name}. 고향 같았는데 코볼트가 지나가더군. 이걸 받게."
L["Good morning, {name}. My stomach woke first and ordered me to give you this."] = "좋은 아침이네, {name}. 배가 먼저 깨어나서는 이걸 주라고 명령하더군."
L["Past my first nap, {name}, before my second. Take this while I'm awake."] = "첫 낮잠 뒤, 두 번째 낮잠 전이라네, {name}. 깨어 있을 때 이걸 받게."
L["Late, {name}. The brewmasters sleep. The brews don't, and nor does this."] = "늦었네, {name}. 양조사들은 자고 있지. 술은 안 자고, 이것도 안 잔다네."
L["Midnight snack time, {name}. This is the appetiser."] = "야식 시간일세, {name}. 이건 전채 요리고."
L["Dark already, {name}? Grandfather's stories would start now. Take this first."] = "벌써 어두워졌나, {name}? 할아버지 이야기가 시작될 시간이군. 이것부터 받게."
L["The moon is round and full tonight, {name}, as I am. Here, from both of us."] = "오늘 밤 달이 둥글고 꽉 찼네, {name}. 나처럼. 우리 둘이 주는 거라네."
L["Patience and friendship, {name}. You have both."] = "인내와 우정, {name}. 넌 둘 다 가졌어."
L["Sit with me a moment, {name}. The road will wait."] = "잠시 나랑 앉아 있자, {name}. 길은 기다려 줄 거야."
L["Life is better with good company, {name}. And good tea."] = "좋은 벗이 있으면 삶이 즐거워, {name}. 좋은 차도 있으면 더."
L["Well done, {name}! Balance and strength, together."] = "잘했어, {name}! 균형과 힘이 하나로."
L["Wonderful, {name}! That deserves a feast. Maybe two."] = "멋져, {name}! 잔치감이야. 두 번쯤은."
L["Ha! Swift as a monk's fist, {name}."] = "하! 수도사의 주먹처럼 빠르구나, {name}."
L["Rest, {name}. Breathe deep. Find your balance again."] = "쉬어, {name}. 깊이 숨 쉬고, 다시 균형을 찾아."
L["Easy, {name}. The wounds will heal; the spirit endures."] = "진정해, {name}. 상처는 아물고, 정신은 견뎌 내."
L["Quiet now, {name}. Let the pain drift away like mist."] = "조용히, {name}. 아픔이 안개처럼 흩어지게 둬."
L["Your kindness is noted, {name}. Dragons do not forget."] = "그대의 친절, 새겨 두겠소, {name}. 용은 잊지 않소."
L["Thank you, {name}. Returned on swift wings."] = "고맙구려, {name}. 날랜 날갯짓으로 갚겠소."
L["Wings, fire and scales, {name}, and still you thought I needed help. Touching."] = "날개도 불도 비늘도 있는데, {name}, 그래도 도와주다니. 감동이구려."
L["I would bow, {name}, but last time my wings cleared a table. Thank you."] = "절이라도 하고 싶소, {name}. 지난번엔 날개로 식탁을 쓸어 버렸지만. 고맙소."
L["That goes straight into my hoard, {name}. Kind deeds are the only gold I keep."] = "곧장 내 보물 더미에 넣겠소, {name}. 내가 모으는 금은 선행뿐이오."
L["I was made to be a weapon, {name}. I much prefer this part. Thank you."] = "난 무기로 만들어졌소, {name}. 이쪽이 훨씬 마음에 드오. 고맙소."
L["Thank you, {name}. Wrathion would have made a speech of it. I will not."] = "고맙소, {name}. 래시온이었다면 연설을 했을 거요. 난 안 하겠소."
L["Returned with a little fire in it, {name}. Only a little. I am practising."] = "불기를 살짝 담아 돌려드리오, {name}. 아주 살짝. 연습 중이라."
L["A mortal gift, {name}: small, brief and kind. I am learning to like all three."] = "필멸자의 선물이구려, {name}. 작고, 짧고, 다정하오. 셋 다 좋아지는 중이오."
L["Thank you, {name}. Mortal customs are new to me. Do I pay you? No? Then this."] = "고맙소, {name}. 필멸자 풍습은 낯설구려. 값을 치러야 하오? 아니오? 그럼 이걸로."
L["Thank you, {name}. I have scales where most have feelings. That got through."] = "고맙소, {name}. 마음 대신 비늘이 있는 몸인데, 그걸 뚫고 들어왔소."
L["You're on my list of favourite mortals, {name}. It was empty until today."] = "그대는 '아끼는 필멸자' 명단에 올랐소, {name}. 오늘까지 비어 있던 명단이오."
L["The red in me is grateful, {name}. The black in me is suspicious. The red wins."] = "내 안의 붉은 용은 고맙다 하고, {name}, 검은 용은 수상하다 하오. 붉은 용 승."
L["Thank you, {name}. Dragons are not used to receiving. I find I like it."] = "고맙소, {name}. 용은 받는 데 익숙지 않소. 헌데 마음에 드는구려."
L["A dragon's thanks comes with a roar, {name}. I will spare the neighbours."] = "용의 감사엔 포효가 따르는 법이오, {name}. 이웃을 생각해 생략하리다."
L["Very well, {name}. Stand still, I would hate to singe you."] = "알겠소, {name}. 가만히 계시오. 그을리게 하고 싶진 않으니."
L["Granted, {name}. A dragon keeps its word."] = "들어주겠소, {name}. 용은 약속을 지키는 법."
L["Certainly, {name}. Stand clear of the tail."] = "그러겠소, {name}. 꼬리에서 떨어져 계시오."
L["Of course, {name}. Is this still how it is done? I was asleep for a while."] = "물론이오, {name}. 요즘도 이렇게 하는 거요? 잠깐 눈 좀 붙였더니만."
L["Gladly, {name}. All five dragonflights are in me, and all five say yes."] = "기꺼이, {name}. 내 안의 다섯 용군단이 만장일치로 찬성이오."
L["Right away, {name}. Dragon-sized help, in a conveniently smaller form."] = "당장 하리다, {name}. 용만 한 도움을, 들고 다니기 좋은 크기로."
L["Of course, {name}. Neltharion only gave orders. A request is much nicer."] = "물론이오, {name}. 넬타리온은 명령만 했지. 부탁이 훨씬 낫구려."
L["Right away, {name}. Stand back a little; I am still learning how big I am."] = "당장 하리다, {name}. 조금 물러서시오. 내 덩치를 아직 익히는 중이라."
L["Certainly, {name}. Claws are not ideal for spellwork, but I manage."] = "그러겠소, {name}. 발톱으로 주문 외기가 쉽진 않지만, 해내리다."
L["Of course, {name}. Dragons usually demand tribute. I'm waiving it, this once."] = "물론이오, {name}. 원래 용은 공물을 받소. 이번 한 번은 면제해 드리리다."
L["Of course, {name}. Please don't scream. Mortals often do. It's the horns."] = "물론이오, {name}. 비명은 참아 주시오. 필멸자들이 자주 지르더군. 뿔 때문이오."
L["My breath is fire, {name}, so we will do this the other way."] = "내 숨결은 불이오, {name}. 그러니 이건 손으로 하겠소."
L["Gladly, {name}. Mortals so rarely ask a dragon for anything but mercy."] = "기꺼이, {name}. 필멸자가 용에게 자비 말고 다른 걸 청하는 일은 드물지."
L["A small magic, {name}, but I cast it with enormous dignity."] = "작은 마법이오, {name}. 하지만 엄청난 위엄을 담아 시전하오."
L["Take this, {name}. Even a dragon needs allies. Especially one this size."] = "이걸 받으시오, {name}. 용에게도 동료는 필요하오. 이리 아담한 용이면 더더욱."
L["A gift from the Dragon Isles, {name}. Fly well."] = "용의 섬에서 온 선물이오, {name}. 멋지게 날기를."
L["Alexstrasza says every life is precious, {name}. I am starting with yours."] = "알렉스트라자께선 모든 생명이 소중하다 하셨소, {name}. 그대부터 시작하리다."
L["I slept through ten thousand years of good deeds, {name}. Catching up now."] = "만 년 치 선행을 자느라 놓쳤소, {name}. 지금 몰아서 하는 중이오."
L["Tell them a dragon did this, {name}. It sounds far grander than it was."] = "용이 해 줬다고 전하시오, {name}. 실제보다 훨씬 그럴싸하게 들리니."
L["Scalecommander's orders, {name}: take this. I'm no Scalecommander, but still."] = "비늘사령관의 명령이오, {name}. 이걸 받으시오. 내가 비늘사령관은 아니지만."
L["Take this, {name}. Ancient dragon magic, only slightly out of date."] = "받으시오, {name}. 고대 용의 마법이오. 유통기한이 살짝 지났지만."
L["A dragon giving, {name}, not taking. I am trying something new."] = "용이 빼앗지 않고 베푸는 거요, {name}. 새로운 시도랄까."
L["In visage form I look harmless, {name}. So did Lady Prestor. I give, not take."] = "사람 모습일 땐 무해해 보이오, {name}. 프레스터 여공도 그랬지. 난 빼앗지 않고 주오."
L["A gift from above, {name}. I landed specially. It took two tries."] = "하늘에서 온 선물이오, {name}. 일부러 내려앉았소. 두 번 만에."
L["Here, {name}. Every dragon should guard something. I have chosen you, for now."] = "받으시오, {name}. 용이라면 지킬 보물이 있어야 하오. 당분간은 그대로 정했소."
L["Take this, {name}. It's from five dragonflights, so it clashes with everything."] = "받으시오, {name}. 다섯 용군단 합작이라 무슨 옷과도 색이 안 맞소."
L["I'd fly you there myself, {name}, but dracthyr carry no riders. Take this."] = "직접 태워 가고 싶소만, {name}, 드랙티르는 사람을 태우지 않소. 이걸 받으시오."
L["Dragons gifted the world at its dawn, {name}. Mine is smaller, and later."] = "용들은 세상이 열릴 때 선물을 주었소, {name}. 내 건 좀 작고, 좀 늦었소."
L["A little essence for you, {name}. It is what I'm made of, so handle it gently."] = "정수를 조금 드리오, {name}. 내 몸을 이루는 거니 살살 다뤄 주시오."
L["Take this, {name}. It will feel warm. Most things do, after I touch them."] = "받으시오, {name}. 따뜻할 거요. 내 손이 닿으면 대개 그렇소."
L["The Forbidden Reach is far behind us, {name}. What we learned there, I share."] = "금지된 섬은 먼 뒤에 있소, {name}. 거기서 배운 걸 나누겠소."
L["Two dracthyr, {name}. Mind the wings; no room for four. Take this."] = "드랙티르 둘이오, {name}. 날개 조심하시오. 네 장 펼 자리는 없소. 받으시오."
L["Remember when the world was new to us, {name}? This still feels new."] = "세상이 우리에게 새로웠던 때 기억하오, {name}? 이건 아직도 새롭소."
L["In visage form nobody can tell, {name}. Between us: this suits scales best."] = "사람 모습이면 아무도 모르오, {name}. 우리끼리 얘기지만, 이건 비늘에 제일 어울리오."
L["Made for war, {name}, and look at us: sharing. Somebody's plans went wrong."] = "전쟁용으로 빚어진 우리가, {name}, 나눔이라니. 누군가의 계획이 망했구려."
L["Visage or scales, {name}, I'd know one of us anywhere. So here is yours."] = "사람 모습이든 비늘이든, {name}, 우리 동족은 어디서든 알아보오. 그러니 그대 몫이오."
L["Mortals always ask if we'll fly them, {name}. Still no. But this, yes."] = "필멸자들은 늘 태워 달라고 하지, {name}. 여전히 안 되오. 하지만 이건 되오."
L["Between dracthyr, {name}: the horns never get easier with hats. This helps."] = "드랙티르끼리 말이오, {name}. 뿔에 모자는 절대 쉬워지지 않소. 이게 도움이 되오."
L["Take this, {name}. Then tell me when to breathe fire. And when not to."] = "이걸 받으시오, {name}. 그다음 언제 불을 뿜을지 말해 주시오. 언제 말지도."
L["I woke in a cave of strangers, {name}. Now I give gifts to company. Better."] = "낯선 이들 가득한 동굴에서 깨어났소, {name}. 이젠 동료에게 선물을 주지. 훨씬 낫소."
L["Neltharion made us to fight alone, {name}. We improved on him. Here."] = "넬타리온은 우릴 홀로 싸우게 만들었소, {name}. 우린 그를 넘어섰지. 받으시오."
L["Here, {name}. Stay clear of my tail. It hasn't learned whose side it's on."] = "받으시오, {name}. 내 꼬리는 피하시오. 아직 누구 편인지 모르거든."
L["A flight of our own, {name}, sharing its gifts. So this is what dragons meant."] = "우리만의 용군단이오, {name}. 선물을 나누는. 용들이 말한 게 이거였구려."
L["Take this, {name}. If I say 'take cover', I mean behind my wings."] = "이걸 받으시오, {name}. 내가 '엄폐'라 하면 내 날개 뒤라는 뜻이오."
L["That's for you, {name}. Stand beside me, never in front. I can't aim my breath."] = "그대 몫이오, {name}. 옆에 서시오, 절대 앞엔 말고. 내 숨결은 조준이 안 되오."
L["Take this, {name}; leave the big ones to me. Well, the ones smaller than me."] = "이걸 받고, {name}, 큰 놈은 내게 맡기시오. 뭐, 나보다 작은 놈들 말이오."
L["Stay close, {name}, blessed. I can glide us all down. Up is your problem."] = "축복받았으니 붙어 있으시오, {name}. 다 같이 활강해 내려갈 수 있소. 올라가는 건 그대 몫이오."
L["Keep moving, {name}. A dragon in a hurry gives gifts. One waiting is just big."] = "계속 가시오, {name}. 서두르는 용은 선물을 주지. 기다리는 용은 그냥 크기만 하고."
L["Here, {name}. Now tell me the plan slowly. I was made for battles, not plans."] = "받으시오, {name}. 이제 작전을 천천히 말해 주시오. 난 전투용이지 작전용이 아니오."
L["Mortals live so briefly, {name}. This should make today a little longer."] = "필멸자는 참 짧게 사오, {name}. 이게 오늘을 조금 늘려 줄 거요."
L["You're a good companion, {name}. Better than most dragons."] = "넌 좋은 동료야, {name}. 웬만한 용보다 낫지."
L["Stay near, {name}. I'll keep you warm when the wind turns."] = "가까이 있어, {name}. 바람이 바뀌면 내가 따뜻하게 해 줄게."
L["I slept for ten thousand years, {name}, and woke to find you."] = "만 년을 잠들었다가, {name}, 깨어나 너를 만났어."
L["Excellent, {name}. You fight like a true dragonflight."] = "훌륭해, {name}. 진정한 용군단처럼 싸우는구나."
L["Impressive, {name}. Not even a black dragon could do better."] = "인상적이야, {name}. 검은용도 이보다 잘하진 못해."
L["Well done, {name}! The Dragon Isles have a new champion."] = "잘했어, {name}! 용의 섬에 새 용사가 생겼어."
L["Easy, {name}. I've weathered storms; we'll weather this."] = "진정해, {name}. 폭풍도 견뎠어. 이것도 견뎌 낼 거야."
L["Rest, {name}. I'll shield you with my wings."] = "쉬어, {name}. 내 날개로 널 감싸 줄게."
L["Stay calm, {name}. The flames are mine to bear, not yours."] = "침착해, {name}. 불꽃은 내가 짊어질게, 네가 아니라."
L["Thank you, {name}. Where I come from, a kindness is tended like a root."] = "고맙소, {name}. 내 고향에선 친절을 뿌리처럼 가꾸오."
L["Thank you, {name}. Hagar sent me to see the goddess's work. You're her best."] = "고맙소, {name}. 하가르께서 여신의 작품을 보고 오라 하셨소. 그대가 최고 작품이오."
L["Kindness echoes, {name}, and I grew up in a cavern. Here it comes back to you."] = "친절은 메아리치는 법이오, {name}. 동굴에서 자란 내가 잘 알지. 자, 돌려드리오."
L["My Legacy Stone showed who I'd stand beside, {name}. It forgot you. Thank you."] = "내 유산석이 함께 설 이들을 보여 줬소, {name}. 그대를 빠뜨렸더군. 고맙소."
L["We read lives in a root's rings, {name}. Yours just grew a kind one."] = "우린 뿌리의 나이테로 삶을 읽소, {name}. 그대 삶에 다정한 테가 하나 늘었구려."
L["The Shul'ka gave up everything to guard us, {name}. I can give this much."] = "술카는 우릴 지키려 모든 걸 버렸소, {name}. 나도 이 정도는 줄 수 있지."
L["The world is more than Harandar, the Song said, {name}. Thanks for proving it."] = "세상은 하란다르보다 넓다고 여신의 노래가 일렀소, {name}. 증명해 줘서 고맙소."
L["Thank you, {name}. Orweyna said outsiders had much to teach us. I'm learning."] = "고맙소, {name}. 이방인에게 배울 게 많다고 오르웨냐가 그랬지. 배우는 중이오."
L["Our oaths forbid speaking to outsiders, {name}. I'll risk a thank you."] = "우리 맹세는 이방인과 말 섞는 걸 금하오, {name}. 고맙다는 말 한마디는 무릅쓰겠소."
L["My people lived up here once, {name}. Thanks to you, I can see why."] = "우리 종족도 한때 지상에 살았소, {name}. 그대 덕에 그 이유를 알겠구려."
L["We're raised on dedication and humility, {name}, so I'll just say thank you."] = "우린 헌신과 겸손을 배우며 자라오, {name}. 그러니 고맙다는 말만 하겠소."
L["Back home I'd dance for that, {name}. Up here people stare, so: thank you."] = "고향이었으면 춤이라도 췄을 거요, {name}. 여기선 다들 쳐다보니, 그냥 고맙소."
L["Thank you, {name}. You've left me glowing like a moth back in Harandar."] = "고맙소, {name}. 덕분에 하란다르의 나방처럼 빛나는 기분이오."
L["Har'mara is the Village of Balance, {name}. I'd hate to go home lopsided."] = "하르마라는 균형의 마을이오, {name}. 한쪽으로 기운 채 집에 갈 순 없지."
L["If Aln'hara can hear anything where she is, {name}, I hope she heard that."] = "알른하라께서 어디 계시든 들으실 수 있다면, {name}, 방금 그 말도 들으셨기를."
L["Of course, {name}. Protect, tend and serve, my people say. This is the serving."] = "물론이오, {name}. 지키고, 가꾸고, 섬기라는 게 우리 가르침이오. 이건 섬기는 쪽이오."
L["Of course, {name}. I answered the goddess's call. Yours is far easier to hear."] = "물론이오, {name}. 여신의 부름에도 응했는데, 그대 부름은 훨씬 잘 들리는구려."
L["Of course, {name}. Dalnir would call this a distraction. Dalnir isn't here."] = "물론이오, {name}. 달니르라면 한눈판다고 나무라겠지. 달니르는 여기 없소."
L["Of course, {name}. The roots never ask for anything. It's nice to be asked."] = "물론이오, {name}. 뿌리는 뭘 청하는 법이 없지. 부탁을 받으니 좋구려."
L["Gladly, {name}. Back home I'd have had to pretend I never saw you."] = "기꺼이, {name}. 고향이었다면 그대를 못 본 척해야 했을 거요."
L["Of course, {name}. Mind the quills; they're friendlier than they look."] = "물론이오, {name}. 가시는 조심하시오. 보기보단 순하오."
L["Gladly, {name}. Don't stand still too long; in Harandar you'd sprout mushrooms."] = "기꺼이, {name}. 너무 오래 가만히 있진 마시오. 하란다르였으면 버섯이 돋았을 거요."
L["Of course, {name}. I was raised to do exactly as I was told. For once, I will."] = "물론이오, {name}. 시키는 대로만 하라고 배우며 자랐소. 이번만은 그대로 하리다."
L["No alndust in this one, {name}. Nothing will come to life and bite you."] = "이번 건 알른가루가 안 들었소, {name}. 갑자기 살아나서 물 일은 없소."
L["Of course, {name}. Half the names up here are new to me. Yours I'll keep."] = "물론이오, {name}. 지상 이름은 절반이 처음 듣는 거요. 그대 이름은 기억해 두리다."
L["{buff}, {name}, grown under the World Trees and picked fresh."] = "{buff}, {name}. 세계수 아래서 길러 갓 따 온 거요."
L["Of course, {name}. Hagar is handling things at home; I'll handle them up here."] = "물론이오, {name}. 고향 일은 하가르께서 맡으셨으니, 지상 일은 내가 맡겠소."
L["At my initiation I was asked who I really am, {name}. Someone who says yes."] = "입문식에서 나는 진정 누구냐는 질문을 받았소, {name}. 답은, 부탁을 들어주는 사람이오."
L["Take this, {name}, from a long way below. The roots send their regards."] = "받으시오, {name}. 저 깊은 아래에서 온 거요. 뿌리들이 안부를 전하오."
L["Take this, {name}, and may Aln'hara be with you."] = "받으시오, {name}. 알른하라께서 함께하시길."
L["The sky has no ceiling, {name}. Anything could fall on you. Take this."] = "하늘엔 천장이 없소, {name}. 뭐가 떨어질지 모르지. 받으시오."
L["Follow the visions, Hagar said, {name}. Today they pointed at you. Take this."] = "환영을 따르라고 하가르께서 말씀하셨소, {name}. 오늘은 그대를 가리키더군. 받으시오."
L["My people would have watched you from the brush, {name}. I'd rather do this."] = "우리 종족이었다면 덤불에 숨어 지켜보기만 했을 거요, {name}. 난 이게 낫소."
L["Harandar stayed out of the world's wars, {name}. You weren't so lucky. Here."] = "하란다르는 세상의 전쟁을 비껴갔소, {name}. 그대는 그리 운이 좋진 않았지. 받으시오."
L["The Zur'ashar paint every tale worth telling, {name}. Here; make yours long."] = "주르아샤르는 전할 만한 이야기를 다 그리오, {name}. 받으시오. 그대 이야기를 길게 하시오."
L["Take this, {name}. The goddess's world is a garden, and gardens have thorns."] = "이걸 받으시오, {name}. 여신의 세상은 정원이고, 정원엔 가시가 있소."
L["We tend roots in Harandar, {name}. You look as if you could use some tending."] = "하란다르에선 뿌리를 돌보오, {name}. 그대도 좀 돌봄이 필요해 보이는구려."
L["My ancestors grew restless and sought a purpose, {name}. I've found mine. Here."] = "선조들은 좀이 쑤셔 사명을 찾아 나섰소, {name}. 난 내 사명을 찾았지. 받으시오."
L["Har'mara lives at peace with its neighbours, {name}. This is how it begins."] = "하르마라는 이웃과 평화롭게 지내오, {name}. 이렇게 시작하는 거요."
L["The first outsiders I met were fighting off a saptor, {name}. Best take this."] = "내가 처음 만난 이방인들은 샙터와 싸우고 있었소, {name}. 이걸 받아 두는 게 좋겠소."
L["My people have kept hope alive for ages on very little, {name}. Have some."] = "우리 종족은 가진 것 없이도 오랜 세월 희망을 지켜 왔소, {name}. 그대도 좀 가지시오."
L["I'm still learning what to say to strangers, {name}. This seemed safest."] = "낯선 이에게 무슨 말을 할지 아직 배우는 중이오, {name}. 이게 제일 무난해 보였소."
L["My people live beside a wound that never heals, {name}. Here; come back whole."] = "우리 종족은 아물지 않는 상처 곁에 사오, {name}. 받으시오. 성히 돌아오시오."
L["Two haranir out in the world, {name}. The elders would fret. I'll help instead."] = "하라니르 둘이 세상에 나왔구려, {name}. 장로들은 걱정하겠지. 난 돕겠소."
L["Did the Song call you up as well, {name}? It called me to give you this."] = "그대도 노래의 부름을 받았소, {name}? 난 이걸 주라는 부름을 받았소."
L["Keep to the brush, they told us, {name}. We're both bad at it. Take this."] = "덤불에 숨어 있으라 했지, {name}. 우리 둘 다 영 못하오. 이걸 받으시오."
L["Harandar's roots run under all this, {name}. Some of their strength, for you."] = "하란다르의 뿌리는 이 모든 땅 밑으로 뻗어 있소, {name}. 그 힘을 조금 드리겠소."
L["Looking for the goddess too, {name}? Two pairs of eyes, then, and this."] = "그대도 여신을 찾고 있소, {name}? 그럼 눈이 두 쌍이고, 이것도 있소."
L["Told to give up childish adventures, {name}? Me too. Here, for the next one."] = "유치한 모험은 그만두라는 말 들었소, {name}? 나도요. 다음 모험에 쓰시오."
L["Nobody up here speaks Hara'ni, {name}. So I'll just say it with this."] = "지상엔 하라니 말을 아는 이가 없소, {name}. 그러니 이걸로 말하겠소."
L["Outsiders ask where we're from, {name}. I point down. Here's a bit of down."] = "이방인들이 어디서 왔냐 묻지, {name}. 난 아래를 가리키오. 아래의 기운을 좀 주겠소."
L["Stay close, {name}. A haranir needs something to guard, and today it's you."] = "가까이 있으시오, {name}. 하라니르에겐 지킬 대상이 필요한데, 오늘은 그대요."
L["We once mastered every beast on our mountain, {name}. With this, these won't."] = "우린 한때 우리 산의 모든 짐승을 다스렸소, {name}. 이거면 저것들도 못 버티오."
L["Word from Harandar, {name}: the haranir join the fight. This is my part."] = "하란다르에서 소식이오, {name}. 하라니르가 싸움에 나서오. 이게 내 몫이오."
L["My people's oldest shame is fighting each other, {name}. Here; together, then."] = "우리 종족의 가장 오랜 수치는 서로 싸운 거요, {name}. 받으시오. 그러니 함께 싸웁시다."
L["Here, {name}. Mind your step; where I'm from, the floor is mostly roots."] = "받으시오, {name}. 발밑 조심하시오. 내 고향 바닥은 거의 뿌리요."
L["Take this, {name}. If anything crawls up from below, leave it to me."] = "이걸 받으시오, {name}. 아래서 뭐가 기어오르면 내게 맡기시오."
L["Dangerous, {name}? My ancestors went into the deep with less than this."] = "위험하냐고, {name}? 내 조상들은 이것보다 못한 걸 들고 심연에 들어갔소."
L["Do not fear the dark, {name}. Orweyna's words, and my gift, go with you."] = "어둠을 두려워 마시오, {name}. 오르웨냐의 말과 내 선물이 함께 가오."
L["Take this, {name}. I'll take the ledges. Clawed feet were made for them."] = "이걸 받으시오, {name}. 난 절벽 턱을 맡겠소. 발톱 달린 발은 그러라고 있는 거요."
L["The goddess's world is worth fighting for, {name}. This bit too. Here."] = "여신의 세상은 싸울 가치가 있소, {name}. 이 구석도 그렇고. 받으시오."
L["I've cleared weeds, mud skippers and fungi, {name}. You I'll just bless."] = "잡초, 진흙뜀이, 버섯까지 다 치워 봤소, {name}. 그대는 축복만 하겠소."
L["The Zur'ashar won't paint this fight, {name}. Take this; let's win it anyway."] = "주르아샤르는 이 싸움을 그리지 않을 거요, {name}. 이걸 받으시오. 그래도 이깁시다."
L["Easy, {name}. Back in Harandar we tend friends like roots: gently."] = "진정해, {name}. 하란다르에선 친구를 뿌리처럼 돌봐. 살살."
L["You're the best thing the surface has given me, {name}."] = "넌 지상이 내게 준 최고의 선물이야, {name}."
L["Stay close, {name}. Up here the sky goes on forever."] = "가까이 있어, {name}. 여기 위에선 하늘이 끝이 없어."
L["Well done, {name}! Aln'hara would have smiled at that."] = "잘했어, {name}! 알른하라님도 미소 지으셨을 거야."
L["Protect, tend and serve, {name}. You did all three just now."] = "지키고, 돌보고, 섬겨라, {name}. 방금 셋 다 했어."
L["Fierce as the Shul'ka, {name}. I'm proud of you."] = "슐카처럼 사납구나, {name}. 네가 자랑스러워."
L["Rest, {name}. Let the roots hold you while you heal."] = "쉬어, {name}. 낫는 동안 뿌리가 널 붙잡아 줄 거야."
L["Easy, {name}. You glow a little dimmer, but you're still here."] = "진정해, {name}. 빛은 좀 흐려졌어도 넌 아직 여기 있어."
L["Breathe, {name}. Every root grows back stronger."] = "숨 쉬어, {name}. 모든 뿌리는 더 튼튼하게 다시 자라."
L["It is good to see one of our own, {name}. This is how we greet them."] = "동족을 만나니 반갑군요, {name}. 우린 이렇게 맞이하죠."
L["Our people are few, {name}. That makes each of us worth this."] = "우리 종족은 수가 적죠, {name}. 그래서 한 명 한 명이 이걸 받을 만해요."
L["Thank you, {name}. The Alliance looks after its own, and today that's me."] = "고맙소, {name}. 얼라이언스는 동료를 챙기는 법이오. 오늘은 나였구려."
L["Kindness answered, {name}. For the Alliance!"] = "호의에 보답하오, {name}. 얼라이언스를 위하여!"
L["Thank you, {name}. Stormwind has a statue for every hero. I'll put in a word."] = "고맙습니다, {name}. 스톰윈드엔 영웅마다 동상이 있죠. 제가 말 좀 넣어 둘게요."
L["The Alliance way, {name}: you help me, I help you, a dwarf buys the drinks."] = "얼라이언스 방식이오, {name}. 그대가 돕고, 내가 돕고, 술은 드워프가 사고."
L["Bolvar would bow, Magni would hug, {name}. I'll just return it."] = "볼바르라면 절을, 마그니라면 와락 포옹을. 난 그냥 갚겠소, {name}."
L["If the Alliance gave medals for manners, {name}, you'd need a second tabard."] = "얼라이언스가 예의 훈장을 준다면, {name}, 휘장이 하나 더 필요하겠구려."
L["Returned in full, {name}. An ally who gives first is worth a whole garrison."] = "고스란히 갚았소, {name}. 먼저 베푸는 동료는 수비대 하나와 맞먹소."
L["Thank you, {name}. I'll mention you in my letter home. Mother reads them aloud."] = "고맙소, {name}. 집에 보낼 편지에 쓰겠소. 어머니가 온 동네에 읽어 주시거든."
L["Thank you, {name}. Even the Stormwind guards would smile at that."] = "고맙소, {name}. 스톰윈드 경비병들도 이건 보고 웃겠구려."
L["The Alliance at its finest, {name}: nobody asked, somebody helped. Thanks."] = "이게 얼라이언스의 참모습이오, {name}. 아무도 청하지 않았는데 누군가 도왔지. 고맙소."
L["I'll tell everyone on the Deeprun Tram, {name}. It's a long tram. Thank you."] = "깊은굴 지하철 승객 모두에게 말하겠소, {name}. 아주 긴 열차요. 고맙소."
L["Most gallant, {name}. If I had a lion on my tabard, it would be purring."] = "참으로 기사답구려, {name}. 내 휘장에 사자가 있었다면 가르랑거렸을 거요."
L["Our kings bicker, {name}, but their people get on splendidly. Thank you."] = "왕들은 티격태격해도, {name}, 백성끼리는 사이가 참 좋소. 고맙소."
L["The Alliance was forged by folk keeping their word, {name}. Here's mine."] = "얼라이언스는 약속을 지킨 이들이 세웠소, {name}. 내 약속은 이렇게 지키오."
L["Of course, {name}. Allies help each other. It's practically in the name."] = "당연하오, {name}. 동맹은 서로 돕는 법. 이름부터 얼라이언스 아니오."
L["At once, {name}. The Alliance does not leave a friend wanting."] = "곧바로 하겠소, {name}. 얼라이언스는 벗을 외면하지 않소."
L["Of course, {name}. It's in the Alliance charter. Somewhere near the back."] = "물론이오, {name}. 얼라이언스 헌장에 있는 조항이오. 한참 뒤쪽 어딘가에."
L["By order of the Alliance, {name}: one {buff}, effective at once."] = "얼라이언스 명령이오, {name}. {buff} 1건, 즉시 발효."
L["Anything for an ally, {name}. Within reason. This is well within reason."] = "동맹을 위해선 뭐든 하오, {name}. 상식선에서. 이건 충분히 상식선이오."
L["Right away, {name}. SI:7 knew you would ask. I only just found out."] = "당장 하겠소, {name}. SI:7은 그대가 부탁할 줄 알았다더군. 난 방금 알았소."
L["Straight away, {name}. The Alliance marches on requests like yours. And bread."] = "곧바로 하겠소, {name}. 얼라이언스는 이런 부탁을 먹고 진군하오. 빵도 먹고."
L["Yes, {name}. From Stormwind to Ironforge, 'please' opens every gate."] = "그러겠소, {name}. 스톰윈드부터 아이언포지까지, '부탁'이면 모든 성문이 열리오."
L["Right away, {name}. I've worn the blue all day hoping somebody would ask."] = "당장 하겠소, {name}. 누가 부탁하길 바라며 온종일 파란 옷 입고 기다렸소."
L["Hold still, {name}. I learned this faster than the Alliance anthem."] = "가만히 계시오, {name}. 이건 얼라이언스 찬가보다 빨리 익혔소."
L["Of course, {name}. Armies win wars; small favours win allies. Here's one."] = "물론이오, {name}. 전쟁은 군대가 이기고, 동맹은 작은 친절이 얻소. 여기 하나."
L["For the Alliance, {name}! Stay strong out there. Stronger, now."] = "얼라이언스를 위하여, {name}! 굳건히 버티시오. 이제 더 굳건히."
L["Onward, {name}, and take this. The Alliance is with you."] = "전진하세요, {name}. 이것도 받고요. 얼라이언스가 함께합니다."
L["Take this, {name}. Had a gnome made it, it would come with twelve levers."] = "받으시오, {name}. 노움이 만들었다면 레버가 열두 개는 달렸을 거요."
L["Compliments of the Alliance, {name}. We've done these since the Second War."] = "얼라이언스가 드리는 거요, {name}. 2차 대전쟁 때부터 해 온 일이지."
L["Chin up, {name}; take this. Somewhere in Stormwind, a bard writes about you."] = "힘내세요, {name}. 이걸 받고요. 스톰윈드 어딘가에서 음유시인이 당신 얘길 쓰고 있어요."
L["Every ally counts, {name}. Today, you count double."] = "동료 하나하나가 소중하오, {name}. 오늘 그대는 두 배로."
L["Anduin would want me to share, {name}, and I'd hate to disappoint him."] = "안두인이라면 나누라 했을 거요, {name}. 그분을 실망시킬 순 없지."
L["Take this, {name}. Stormwind's walls can't follow you, so this will have to."] = "받으시오, {name}. 스톰윈드 성벽은 따라갈 수 없으니, 이게 대신 가오."
L["Here, {name}. The gryphons get you there; this gets you back."] = "받으시오, {name}. 가는 건 그리핀이, 돌아오는 건 이게 책임지오."
L["Alliance rule, {name}: keep your word, your walls, your friends. Here, friend."] = "얼라이언스 규칙이오, {name}. 약속도, 성벽도, 벗도 지킬 것. 받으시오, 벗이여."
L["Every ally deserves a lion at their back, {name}. I'm the nearest lion."] = "동료라면 등 뒤에 사자 하나쯤 있어야지, {name}. 제일 가까운 사자가 나요."
L["A gift from the Alliance, {name}. Signed, sealed and hand-delivered."] = "얼라이언스의 선물이오, {name}. 서명하고, 봉인하고, 직접 전해 드리오."
L["The Alliance never forgets the brave, {name}. Here; give it something to keep."] = "얼라이언스는 용감한 이를 잊지 않아요, {name}. 받으세요. 기억할 거리를 남겨 주세요."
L["Together we stand, {name}, and share. For the Alliance!"] = "함께라면 버티고, {name}, 나눕니다. 얼라이언스를 위하여!"
L["Right, {name}: take this, shields up, and nobody charges before the plan does."] = "좋아요, {name}. 이걸 받고, 방패 들고, 작전보다 먼저 돌격하는 사람 없기."
L["The finest company the Alliance ever fielded, {name}. Best equipped, too, now."] = "얼라이언스 역사상 최고의 부대예요, {name}. 이제 장비도 최고고요."
L["Together, {name}, we're practically a regiment. A small, well-blessed regiment."] = "함께라면, {name}, 거의 연대죠. 작지만 축복 잘 받은 연대요."
L["That's me watching your back, {name}. The Alliance was built by people who did."] = "이렇게 당신 등을 지켜요, {name}. 얼라이언스는 그렇게 한 사람들이 세웠죠."
L["Shields together, {name}, and take this. The Alliance never won in single file."] = "방패를 맞대요, {name}. 이것도 받고요. 얼라이언스는 한 줄로 서서 이긴 적이 없어요."
L["If this goes in the history books, {name}, let it say I blessed you first."] = "이게 역사책에 남는다면, {name}, 제가 먼저 축복했다고 적히길."
L["Take this, {name}. Whoever carries the banner gets painted looking noble."] = "이걸 받으세요, {name}. 깃발 드는 사람은 고귀하게 그려지거든요."
L["Dwarven nerve, elven patience, human stubbornness, {name}, and a gift. Recipe."] = "드워프의 배짱, 엘프의 인내, 인간의 고집, {name}, 그리고 선물. 그게 비법이죠."
L["Keep the lion roaring, {name}, with this in you. Softly, mind. We're sneaking."] = "사자가 포효하게 하세요, {name}. 이걸 품고요. 조용히요. 몰래 가는 중이니까."
L["Strength and honour, {name}. And kindness, it turns out. Repaid in full."] = "힘과 명예, {name}. 알고 보니 친절도 있구려. 고스란히 갚았소."
L["The Horde takes care of its own, {name}."] = "호드는 제 식구를 챙기는 법이오, {name}."
L["Strength given, strength returned, {name}. That's all of Horde diplomacy."] = "힘을 받았으면 힘으로 갚소, {name}. 호드 외교는 그게 전부요."
L["I'd carve your name on Orgrimmar's gates, {name}, but they're full. Thanks."] = "오그리마 성문에 그대 이름을 새기고 싶지만, {name}, 빈자리가 없소. 고맙소."
L["A goblin would've sent you an invoice, {name}. I'm sending this instead."] = "고블린이었다면 청구서를 보냈을 거요, {name}. 난 대신 이걸 보내오."
L["You did not have to do that, {name}. That is why the Horde remembers it."] = "안 해도 될 일이었소, {name}. 그래서 호드는 이걸 기억하오."
L["In the Horde we do not say thank you twice, {name}. So: once, and meant."] = "호드는 고맙단 말을 두 번 하지 않소, {name}. 그러니 한 번, 진심으로."
L["In the Horde a debt is carried like an axe, {name}: openly, and not for long."] = "호드에선 빚도 도끼처럼 들고 다니오, {name}. 드러내 놓고, 오래 들지 않고."
L["Thanks, {name}. The gate grunts will hear of it. They'll grunt. Means respect."] = "고맙다, {name}. 성문 경비병들한테 전하지. 으르렁댈 거다. 그게 존경이야."
L["The Horde keeps two lists, {name}: grudges and favours. Yours is the short one."] = "호드는 명단이 둘이오, {name}. 원한과 은혜. 그대는 짧은 쪽이오."
L["Honour says repay you, {name}. Manners say smile. I'm working on the smile."] = "명예는 갚으라 하고, {name}, 예의는 웃으라 하오. 웃는 건 연습 중이오."
L["That landed softer than any zeppelin I've ridden, {name}. Thank you."] = "내가 탄 어느 비행선보다 부드럽게 내려앉았소, {name}. 고맙소."
L["Thanks, {name}, in Orcish, Taur-ahe, Zandali and Gutterspeak. Pick one."] = "고맙소, {name}. 오크어, 타우라히어, 잔달라어, 저속어로. 골라 들으시오."
L["Thrall taught the Horde honour, {name}. Nobody had to teach you. Thank you."] = "스랄은 호드에 명예를 가르쳤소, {name}. 그대는 배울 필요도 없었구려. 고맙소."
L["You gave first, {name}. In the Horde that earns first cut of the roast. Here."] = "먼저 베풀었구려, {name}. 호드에선 그러면 고기 첫 점이 그대 거요. 여기."
L["The Warchief can't thank everyone himself, {name}. He's delegated it to me."] = "대족장이 모두에게 직접 인사할 순 없소, {name}. 그래서 내게 위임했소."
L["Consider it done, {name}. For the Horde, and for anyone who asks nicely."] = "맡겨 두시오, {name}. 호드를 위하여, 그리고 예의 바른 모두를 위하여."
L["You only had to ask, {name}. The Horde answers."] = "말만 하면 되오, {name}. 호드는 응답하오."
L["The Horde usually helps with axes, {name}. Today, {buff}."] = "호드는 보통 도끼로 돕소, {name}. 오늘은 도끼 대신 {buff}."
L["Done, {name}. No speeches. The Horde has plenty of those already."] = "됐소, {name}. 연설은 생략하오. 호드엔 이미 차고 넘치니."
L["You asked, {name}. In Orgrimmar, that counts as a formal treaty."] = "청했으니 됐소, {name}. 오그리마에선 그게 정식 조약이오."
L["Asking is no weakness, {name}. Refusing an ally would be."] = "청하는 건 약함이 아니오, {name}. 동료를 거절하는 게 약함이지."
L["No need to bang a war drum, {name}. You asked; it's done."] = "전쟁 북까지 칠 필요 없소, {name}. 청했으니 된 거요."
L["Of course, {name}. In the Horde, 'please' outranks everyone but the Warchief."] = "물론이오, {name}. 호드에서 '부탁'보다 높은 건 대족장뿐이오."
L["In Orgrimmar we'd have argued about it first, {name}. Tradition. Here."] = "오그리마였으면 먼저 한바탕 싸웠을 거요, {name}. 전통이지. 여기."
L["Consider it requisitioned, {name}. The quartermaster needn't hear about it."] = "징발한 걸로 치시오, {name}. 병참장교는 몰라도 되오."
L["Done, {name}. If anyone asks, I scowled the whole time. I've a reputation."] = "됐소, {name}. 누가 물으면 내내 인상 쓰고 있었다 하시오. 내 평판이 있어서."
L["Of course, {name}. Horde hospitality: rough edges, full helpings."] = "물론이오, {name}. 호드식 환대요. 투박해도 양은 푸짐하지."
L["The Horde came together because somebody always said yes, {name}. Yes."] = "호드는 누군가 늘 승낙했기에 뭉쳤소, {name}. 나도 승낙하오."
L["For the Horde, {name}! Go with strength. I've just handed you some."] = "호드를 위하여, {name}! 힘이 함께하기를. 방금 좀 넣어 드렸소."
L["Go with honour, {name}, and with this. Victory awaits."] = "명예롭게 가라, {name}. 이것도 갖고. 승리가 기다린다."
L["Take this, {name}; do something worth a song. Loud songs. The Horde likes loud."] = "이걸 받아라, {name}. 노래로 남길 일을 해. 시끄러운 노래로. 호드는 시끄러운 걸 좋아하지."
L["Walk tall, {name}. The Horde made room for those the world turned away. Here."] = "당당히 걸어라, {name}. 호드는 세상이 내친 자들에게 자리를 내줬다. 받아라."
L["Take this, {name}, and a word of Horde wisdom: hit first, apologise never."] = "받으시오, {name}. 호드의 지혜도 하나. 먼저 치고, 사과는 하지 마시오."
L["Victory or death, {name}. I'd prefer victory, so take this."] = "승리 아니면 죽음이오, {name}. 난 승리가 좋으니, 이걸 받으시오."
L["Blood and thunder, {name}! Here's your thunder. Go and be it."] = "피와 천둥이다, {name}! 네 천둥을 받아라. 가서 천둥이 되어라."
L["For the Horde, {name}, and for you. The Horde's big; you're closer."] = "호드를 위하여, {name}, 그리고 그대를 위하여. 호드는 크고, 그대는 가깝소."
L["Here, {name}. Stronger together, they say, and I've just done my half."] = "받으시오, {name}. 뭉치면 강하다지. 내 몫은 방금 했소."
L["Carry this, {name}. It weighs less than a Horde banner and flies just as proud."] = "이걸 지니시오, {name}. 호드 깃발보다 가볍고, 휘날림은 똑같이 당당하오."
L["Here, {name}. The Horde feeds its own, arms its own, and now enchants them."] = "받으시오, {name}. 호드는 제 식구를 먹이고, 무장시키고, 이제 마법까지 걸어 주오."
L["Take this, {name}. Whatever's out there is about to meet the Horde."] = "받으시오, {name}. 저 밖에 뭐가 있든 곧 호드를 만나게 될 거요."
L["Here, {name}. Wherever you're headed, arrive looking like the Horde sent you."] = "받으시오, {name}. 어디로 가든 호드가 보낸 사람처럼 도착하시오."
L["The Crossroads never turned a traveller away, {name}. Nor do I. This is free."] = "크로스로드는 나그네를 내친 적이 없다, {name}. 나도 마찬가지고. 이건 공짜다."
L["The Horde raises you tough, {name}. This is for the days tough isn't enough."] = "호드는 강하게 키우오, {name}. 이건 강한 걸로 모자란 날을 위한 거요."
L["Take this, {name}. A Horde gift: no ribbon, no speech, no refunds."] = "받으시오, {name}. 호드식 선물이오. 리본 없음, 연설 없음, 환불 없음."
L["Stand tall, {name}, with this. Taller. The Horde has tauren to keep up with."] = "똑바로 서라, {name}. 이걸 받고. 더 똑바로. 호드엔 타우렌을 따라잡아야 하거든."
L["Our strength is each other, {name}. Here's some of mine. For the Horde!"] = "우리의 힘은 서로다, {name}. 내 힘을 좀 나눠 주지. 호드를 위하여!"
L["Forward, {name}, and take this. The Horde advances together. Retreats... never."] = "전진이다, {name}. 이걸 받아라. 호드는 함께 나아간다. 후퇴는... 절대 없다."
L["Together we're a war band, {name}. Apart, we're just loud. Take this."] = "함께면 전투부대다, {name}. 흩어지면 그냥 시끄러울 뿐이지. 받아라."
L["Shoulder to shoulder, {name}, and blessed. Whoever charges first buys the grog."] = "어깨를 나란히, {name}, 축복받고. 먼저 돌격하는 놈이 술 산다."
L["Nobody gets left behind, {name}, or left out. I've counted us twice. Here."] = "아무도 뒤처지지 않고, {name}, 빠지지도 않는다. 두 번 셌다. 받아라."
L["Rule of the warband, {name}: nobody eats until everybody's back, and blessed."] = "전투부대 규칙이다, {name}. 다 돌아와서 축복받기 전엔 아무도 안 먹는다."
L["Drums up, {name}, and take this. If we can't be quiet, we'll be terrifying."] = "북 들어라, {name}. 이것도 받고. 조용할 수 없으면 무시무시하게 가자."
L["The Horde never won a thing alone, {name}. Take this; let's not start now."] = "호드는 혼자서 이긴 적이 없다, {name}. 이걸 받아라. 이제 와서 시작하지 말자."
L["We fight like the Horde, {name}: all at once, nobody waits. So take this now."] = "우린 호드답게 싸운다, {name}. 한꺼번에, 기다리는 놈 없이. 그러니 지금 이걸 받아라."
L["Right, {name}. Spoils shared, blame shared, this shared. Glory to the loudest."] = "좋다, {name}. 전리품도, 책임도, 이것도 나눈다. 영광은 제일 시끄러운 놈 몫."
L["Look at us, {name}, all blessed. The Warchief would be proud. From a distance."] = "우릴 봐라, {name}. 다 축복받았다. 대족장도 자랑스러워하겠지. 멀리서."
L["Tusks, horns, long ears, bare bone, {name}, all blessed. Finest warband going."] = "엄니, 뿔, 긴 귀, 맨뼈, {name}, 다 축복받았다. 최고의 전투부대지."
L["The war stories get bigger after, {name}. With this, give them a head start."] = "전쟁 이야기는 나중에 부풀지, {name}. 이걸로 미리 앞서 나가자."
L["Thank you, {name}. Good hearts turn up on every side, and apparently here."] = "고맙소, {name}. 선한 마음은 어느 편에나 있다더니, 여기도 있구려."
L["Thank you, {name}. No side, no title, just kindness. Legends start like this."] = "고맙소, {name}. 편도 직함도 없이 친절 하나. 전설은 이렇게 시작하오."
L["Thank you, {name}. Kindness has no faction, which is handy, since I have none."] = "고맙소, {name}. 친절엔 진영이 없소. 마침 나도 없으니 잘됐구려."
L["Thank you, {name}. Whichever side gets you is getting a bargain."] = "고맙소, {name}. 어느 편이 그대를 데려가든 횡재하는 거요."
L["Whoever claims me in the end, {name}, I'll remember you first. Thank you."] = "결국 어느 편에 서든, {name}, 그대를 제일 먼저 기억하리다. 고맙소."
L["Strictly neutral, {name}, but gratitude doesn't count. Thank you."] = "철저히 중립이오, {name}. 하지만 감사는 예외지. 고맙소."
L["Thank you, {name}. I carry no banner, so both hands are free to return this."] = "고맙소, {name}. 깃발을 안 드니 두 손 다 비어서 갚기 좋소."
L["The Steamwheedle stay neutral for gold, {name}. I return favours for free."] = "스팀휘들은 돈 때문에 중립이죠, {name}. 전 호의는 공짜로 갚아요."
L["Neither side has taught me their thanks yet, {name}, so here's the plain kind."] = "어느 편도 아직 감사 인사법을 안 알려 줬소, {name}. 그러니 담백하게, 고맙소."
L["Thank you, {name}. I stand between two great banners, and still you noticed me."] = "고맙소, {name}. 두 거대한 깃발 사이에 선 나를 알아봐 주다니."
L["Two sides at war, {name}, and us being lovely right in the middle. Thank you."] = "두 진영은 전쟁 중인데, {name}, 우린 한복판에서 훈훈하구려. 고맙소."
L["Gladly, {name}, whatever banner you fly. I don't even own a banner."] = "기꺼이, {name}. 그대가 어느 깃발 아래 있든. 난 깃발도 없지만."
L["Certainly, {name}. I help everyone. It's the one thing I've decided."] = "물론이오, {name}. 난 누구든 돕소. 그거 하나는 정했소."
L["Everyone asks me which side I'm on, {name}. Much nicer to be asked for help."] = "다들 어느 편이냐고만 묻더군, {name}. 도와 달란 말이 훨씬 반갑소."
L["Of course, {name}. No war council to ask; just me, and I say yes."] = "물론이오, {name}. 물어볼 전쟁 회의도 없소. 나 혼자고, 난 찬성이오."
L["Here you are, {name}. No oath, no colours, no fee."] = "여기 있소, {name}. 맹세도, 깃발도, 수수료도 없이."
L["I can't pick a side yet, {name}, but I can pick a good cause. This is one."] = "아직 편은 못 고르오, {name}. 하지만 좋은 일은 고를 수 있지. 이게 그거요."
L["At once, {name}. I have no side to be on, so for now I am entirely on yours."] = "당장 하겠소, {name}. 설 편이 없으니, 지금은 온전히 그대 편이오."
L["Of course, {name}. Nobody pays me to take sides, so I take requests instead."] = "물론이오, {name}. 돈 받고 편드는 일은 없으니, 부탁이나 들어주오."
L["Neutral does not mean unwilling, {name}. It means I help first and argue never."] = "중립이 무심하단 뜻은 아니오, {name}. 먼저 돕고 절대 안 따진단 뜻이지."
L["Friends can come from any side, {name}. Or from none, like me. Here."] = "친구는 어느 편에서든 올 수 있죠, {name}. 저처럼 어느 편도 아니어도요. 받으세요."
L["Soon they'll hand us tabards, {name}. Until then, we look after each other."] = "곧 우리도 휘장을 받겠지, {name}. 그때까진 서로 챙깁시다."
L["I haven't chosen a side yet, {name}, so I'm being kind to both. Take this."] = "아직 편을 안 골랐소, {name}. 그래서 양쪽 다 잘해 주는 중이오. 받으시오."
L["A gift with no strings, {name}. I don't even have a faction to tie them to."] = "아무 조건 없는 선물이오, {name}. 조건 걸 진영도 없는 몸이라."
L["Go on, {name}, with this. Two whole factions are waiting to argue over us."] = "가세요, {name}. 이것도 갖고요. 두 진영이 우릴 두고 다투려고 기다리고 있어요."
L["No quartermaster yet, {name}, so nobody's counting. Have plenty."] = "아직 병참장교가 없어 아무도 안 세오, {name}. 넉넉히 받으시오."
L["Take this, {name}. Neutral ground travels with me; you're standing on some."] = "받으시오, {name}. 난 중립 지대를 달고 다니오. 그대는 지금 그 위에 서 있소."
L["The Argent Dawn helps whoever needs it, {name}. I'm learning from the best."] = "은빛 여명회는 필요한 이라면 누구든 돕소, {name}. 최고에게 배우는 중이오."
L["Booty Bay's rule: no fighting on the docks, {name}. Mine: no refusing a gift."] = "무법항 규칙은 부두에서 싸움 금지요, {name}. 내 규칙은 선물 거절 금지."
L["The one thing both factions agree on, {name}. They just don't know it yet."] = "두 진영이 유일하게 뜻을 모을 물건이오, {name}. 본인들만 아직 모르지."
L["This goes with any tabard, {name}. I made sure by giving it no colours at all."] = "어느 휘장에도 어울리오, {name}. 확실히 하려고 색을 아예 안 넣었소."
L["For you, {name}. Neither Orgrimmar nor Stormwind sent it. It works anyway."] = "받으시오, {name}. 오그리마도 스톰윈드도 안 보낸 거요. 그래도 효과는 좋소."
L["Here, {name}. I belong to no nation yet, so I practise belonging to everyone."] = "받으시오, {name}. 아직 속한 나라가 없어서, 모두의 편이 되는 연습 중이오."
L["Side by side, {name}, whatever comes. Take this."] = "무슨 일이 와도 나란히, {name}. 이걸 받으세요."
L["No flag over this party, {name}, just us, and this. That's plenty."] = "이 일행엔 깃발이 없어요, {name}. 우리와 이것뿐. 그거면 충분하죠."
L["One day we'll pick sides, {name}. Today we share this and pick fights together."] = "언젠가는 편을 고르겠죠, {name}. 오늘은 이걸 나누고, 같이 싸움을 고르죠."
L["Whatever side the rest of the world is on, {name}, I'm on yours. Here."] = "세상이 어느 편이든, {name}, 전 당신 편이에요. 받으세요."
L["Neutral in the war, {name}, but generous to this group. Take this."] = "전쟁에선 중립이지만, {name}, 이 일행에겐 후하죠. 받으세요."
L["They call us a neutral party, {name}. Nobody said it couldn't give gifts."] = "우릴 중립 일행이라 하죠, {name}. 선물 주지 말란 법은 없잖아요."
L["Take this, {name}. Whatever we fight today, it's nothing personal. Thorough."] = "이걸 받으세요, {name}. 오늘 뭘 상대하든 사적인 감정은 없어요. 철저할 뿐."
L["One side in this party, {name}: ours. Smallest faction, best perks. Here."] = "이 일행엔 한 편뿐이에요, {name}. 우리 편. 제일 작은 진영, 최고의 혜택. 받으세요."
L["No orders from any capital, {name}. We choose our road, and our gifts. Here."] = "어느 수도의 명령도 없죠, {name}. 길도, 선물도 우리가 골라요. 받으세요."
L["No war to win today, {name}, just this one fight. And you've got this for it."] = "오늘은 이길 전쟁이 없어요, {name}. 이 싸움 하나뿐. 그걸 위해 이걸 드려요."
L["One good turn deserves another, {name}."] = "은혜는 은혜로 갚는 법이오, {name}."
L["Have some {buff} in return, {name}."] = "답례로 {buff} 받으시오, {name}."
L["Kindness should go both ways, {name}. Thank you."] = "친절은 오가야 하는 법, {name}. 고맙소."
L["You went first, {name}, so I'll go second and we'll call it friendship."] = "그대가 먼저 했으니, {name}, 내가 이어받으면 그게 우정이오."
L["I'd write you a song, {name}, but {buff} is less off-key."] = "노래라도 지어 드리고 싶소만, {name}, {buff} 쪽이 음정은 덜 틀리오."
L["A gift for a gift, {name}. At this rate we'll be unstoppable by supper."] = "선물엔 선물로, {name}. 이 기세면 저녁때쯤엔 천하무적이겠소."
L["All square, {name}. Unless you'd like to make it best of three."] = "이걸로 비겼소, {name}. 삼세판으로 가자면 몰라도."
L["You started it, {name}. I'm only finishing it."] = "먼저 시작한 건 그대요, {name}. 난 마무리만 하는 거고."
L["That was kind, {name}. The day just got noticeably better. Here's my half."] = "고마운 일이오, {name}. 하루가 확 나아졌소. 이건 내 쪽 답례요."
L["I was about to do that for you, {name}. Honestly. Here's proof."] = "막 그대에게 해 주려던 참이었소, {name}. 진짜로. 여기 증거요."
L["Thank you, {name}. I'll sleep better tonight, and I sleep in a ditch."] = "고맙소, {name}. 오늘 밤은 더 푹 자겠소. 도랑에서 자는 몸이지만."
L["Two good things today, {name}: your kindness, and the chance to return it."] = "오늘 좋은 일이 둘이오, {name}. 그대의 친절, 그리고 그걸 갚을 기회."
L["You had me in your debt for all of three seconds, {name}. There."] = "내가 그대에게 빚진 시간은 고작 3초였소, {name}. 자, 갚았소."
L["Gratitude is best served quickly, {name}. Here it is, still warm."] = "감사는 식기 전에 내야 제맛이오, {name}. 여기, 아직 따끈하오."
L["Well, {name}, now I have to be a better person all day. Thanks for that."] = "이런, {name}, 이제 온종일 착하게 살아야 하잖소. 고맙구려."
L["Returned with a bow, {name}. A figurative one. My back isn't what it was."] = "허리 숙여 답례하오, {name}. 마음으로만. 허리가 예전 같지 않아서."
L["Thank you, {name}. Somebody had to go first, and I'm glad it was you."] = "고맙소, {name}. 누군가 먼저 해야 했는데, 그게 그대라 기쁘오."
L["Thank you, {name}. You've rescued a day I'd written off at breakfast."] = "고맙소, {name}. 아침 먹다 포기한 하루를 그대가 살렸소."
L["You asked, {name}, and here it is."] = "청하신 대로요, {name}. 여기 있소."
L["{buff}, coming right up, {name}."] = "{name}, {buff} 바로 대령하오."
L["Gladly, {name}. One moment."] = "기꺼이 하리다, {name}. 잠시만 기다리시오."
L["Asked and answered, {name}. Next question?"] = "묻는 말에 답했소, {name}. 다음 질문?"
L["Say the word and it's yours, {name}. You said several. Here."] = "말 한마디면 그대 것이오, {name}. 몇 마디나 했으니, 여기."
L["For you, {name}? Gladly. I was hoping someone would ask."] = "그대를 위해서라면, {name}, 기꺼이. 누가 부탁하길 기다렸소."
L["Of course, {name}. Easiest yes I'll say all day."] = "물론이오, {name}. 오늘 이보다 쉬운 대답은 없을 거요."
L["Right away, {name}. Finally, a question I know the answer to."] = "바로 하리다, {name}. 드디어 답을 아는 질문이 나왔구려."
L["Of course, {name}. Nicely asked, gladly given."] = "물론이오, {name}. 정중히 청했으니 기꺼이 드리오."
L["Hold still, {name}. It works best on people who aren't fidgeting. So, nobody."] = "가만히 계시오, {name}. 꼼지락대지 않는 사람에게 잘 듣소. 그런 사람은 없지만."
L["Here you are, {name}. I'd make you wait for effect, but that seems rude."] = "여기 있소, {name}. 뜸 들이면 극적이겠지만, 그건 실례라."
L["Yes, {name}. I'd have said it sooner if you'd asked sooner."] = "좋소, {name}. 더 일찍 물었으면 더 일찍 답했을 거요."
L["Say no more, {name}. Done before you finished asking."] = "두말하면 잔소리요, {name}. 말 끝나기도 전에 다 됐소."
L["There, {name}. Next time, don't ask; just stand near me looking hopeful."] = "됐소, {name}. 다음엔 묻지 말고 내 옆에서 초롱초롱한 눈빛만 보내시오."
L["Coming up, {name}. This is the one part of my day that goes to plan."] = "바로 가오, {name}. 오늘 하루 중 계획대로 되는 건 이것뿐이오."
L["Asking nicely works, {name}. Tell everyone. The world could use the news."] = "좋게 부탁하면 통하오, {name}. 널리 알리시오. 세상에 필요한 소식이오."
L["At once, {name}. Stay put, or this lands on your shadow instead."] = "당장 하리다, {name}. 가만있으시오. 안 그러면 그림자가 대신 받소."
L["Safe travels, {name}. {buff} packs lighter than a sword."] = "무사히 가시오, {name}. {buff}만큼 가벼운 짐도 없소."
L["A small blessing for the road, {name}."] = "가는 길에 작은 축복을, {name}."
L["Go well, {name}, and take this. Come back in one piece."] = "잘 다녀오세요, {name}. 이것도 받고요. 무사히 돌아오세요."
L["No reason, {name}. It just felt like a {buff} sort of day."] = "이유는 없소, {name}. 그냥 {buff} 기분인 날이오."
L["Don't mind me, {name}. Just passing, with a spare {buff}."] = "신경 쓰지 마시오, {name}. 남는 {buff} 들고 지나가던 길이오."
L["Consider it a gift, {name}. I'd wrap it, but it glows through the paper."] = "선물이라 생각하시오, {name}. 포장하려 했는데 종이 너머로 빛이 새서."
L["Here, {name}. Pass it on when you meet someone who needs it."] = "여기, {name}. 필요한 이를 만나면 그대도 건네주시오."
L["Whatever brings you here, {name}, this should help it go better than planned."] = "무슨 일로 왔든, {name}, 이게 계획보다 잘 풀리게 해 줄 거예요."
L["Just being neighbourly, {name}. Very, very temporary neighbours."] = "이웃사촌끼리 정 나누는 거요, {name}. 아주아주 잠깐 이웃이지만."
L["You looked about to do something brave, {name}. Here, for that."] = "뭔가 용감한 일을 벌일 얼굴이구려, {name}. 그 일에 보태 쓰시오."
L["No need to stop, {name}. It works while you walk."] = "멈출 필요 없소, {name}. 걸으면서도 잘 듣소."
L["Nothing asked, nothing owed, {name}. Nothing to do but go and be splendid."] = "청한 것도, 갚을 것도 없소, {name}. 남은 건 가서 멋지게 구는 것뿐."
L["Call it a wager, {name}, that you'll do something worthwhile with it."] = "내기라 칩시다, {name}. 그대가 이걸로 뭔가 해낸다는 쪽에 걸었소."
L["A gift from a passing stranger, {name}. The best kind, the old stories say."] = "지나가던 나그네의 선물이오, {name}. 옛이야기에선 그게 최고의 선물이라오."
L["It's rude to pass someone without a greeting, {name}. This is mine."] = "인사도 없이 지나치는 건 실례요, {name}. 이게 내 인사요."
L["Same road as me, {name}? Then take this for the journey."] = "나와 같은 길이오, {name}? 그럼 가는 길에 이걸 가져가시오."
L["Take this, {name}. If today goes well, remember me. If badly, I was never here."] = "이걸 받으세요, {name}. 오늘 잘 풀리면 절 기억하고, 안 풀리면 전 여기 없었던 거예요."
L["Hold still a moment, {name}. There. Best-prepared person in sight."] = "잠깐 가만히, {name}. 됐소. 이 근방에서 제일 준비된 사람이오."
L["Everyone ready? You are now, {name}."] = "모두 준비됐소? 이제 {name}도 준비됐소."
L["A little something for the party, {name}."] = "파티를 위한 작은 선물이오, {name}."
L["Stay close, {name}. We go further together, and further still with this."] = "가까이 있어요, {name}. 함께면 더 멀리 가고, 이거면 더더욱 멀리 가요."
L["House rules, {name}: nobody dies, nobody sulks, everybody gets one of these."] = "우리 규칙이에요, {name}. 아무도 안 죽고, 아무도 안 삐치고, 다들 하나씩 받기."
L["There, {name}. Now if this goes badly, it won't be my fault."] = "됐소, {name}. 이제 잘못돼도 내 탓은 아니오."
L["All set, {name}. I'd give a speech, but we'd be here all day."] = "준비 끝이오, {name}. 연설도 하고 싶지만 그러다 해 지겠소."
L["Look after that, {name}. It's the only one I brought for you."] = "잘 챙기시오, {name}. 그대 몫으로 가져온 건 그거 하나뿐이오."
L["Now we look the part, {name}. Let's go and be it."] = "이제 겉모습은 영웅이오, {name}. 가서 속까지 채웁시다."
L["Fresh {buff} all round, {name}. The rest is luck and elbows."] = "{buff}도 새로 돌렸소, {name}. 나머진 운과 팔꿈치 싸움이오."
L["Anyone have a plan, {name}? No? Mine was this. Wonderful. Onward."] = "누구 작전 있어요, {name}? 없어요? 제 작전은 이거였어요. 좋아요. 출발."
L["One each, {name}. Don't swap; they're fitted."] = "한 사람에 하나씩이오, {name}. 맞춤이니 바꿔 입지 마시오."
L["Take this, {name}. Whoever starts the fight has to tell the story afterwards."] = "이걸 받으세요, {name}. 싸움을 먼저 거는 사람이 나중에 이야기도 해야 해요."
L["Good friends, sharp steel, {buff}. What else is there, {name}?"] = "좋은 벗, 날 선 강철, 그리고 {buff}. 뭐가 더 필요하오, {name}?"
L["For you, {name}. Stay where I can see you. I can't help what I can't find."] = "당신 몫이에요, {name}. 제 눈에 보이는 데 있어요. 못 찾으면 못 도와요."
L["If this ends up a legend, {name}, I want a line in it: the one giving you this."] = "이게 전설이 되면, {name}, 한 줄은 제 거예요. 이걸 드리는 장면이요."
L["Brace yourselves, {name}. This helps. And each other, if it comes to that."] = "마음 단단히 먹어요, {name}. 이게 도움이 될 거예요. 필요하면 서로도 붙잡고요."
L["Chin up, {name}, and take this. Whatever's ahead has never met this lot before."] = "힘내요, {name}. 이것도 받고요. 앞에 뭐가 있든 이 일행은 처음 만나 볼 거예요."
L["Here, {name}, to keep you in one piece. I'm only equipped for small repairs."] = "받으세요, {name}. 성히 버티라고요. 전 작은 수리만 할 줄 알거든요."
L["Well, {name}, with this on you we look ready. Let's go before we learn more."] = "자, {name}, 이걸 두르니 준비된 것 같네요. 더 알게 되기 전에 출발하죠."
L["Take this, {name}. If we get lost, we're exploring. Nobody scolds an explorer."] = "이걸 받으세요, {name}. 길을 잃으면 탐험 중인 거예요. 탐험가를 혼내는 사람은 없죠."
L["Thank you, {name}. I'd conjure a gift in return, but it would only be water."] = "고맙소, {name}. 답례를 창조하려 해도 나오는 건 물빵뿐이라."
L["Much obliged, {name}. I'll write it up properly later. Several pages."] = "신세 졌소, {name}. 나중에 제대로 기록해 두겠소. 몇 장에 걸쳐."
L["Thank you, {name}. They never taught gratitude at Dalaran. I'm self-taught."] = "고맙소, {name}. 달라란에선 감사를 안 가르쳐서, 독학했소."
L["Kind of you, {name}. Everyone assumes mages need no help. We do."] = "친절하구려, {name}. 다들 마법사는 도움이 필요 없다 여기지만, 필요하오."
L["Thank you, {name}. I nearly Counterspelled that on reflex. So glad I didn't."] = "고맙소, {name}. 반사적으로 마법 차단할 뻔했소. 참길 잘했지."
L["Even a frost mage would thaw at that, {name}. Thank you."] = "냉기 마법사도 녹겠구려, {name}. 고맙소."
L["Thank you, {name}. Noted in my spellbook, between Frost Nova and lunch."] = "고맙소, {name}. 마법책에 적어 두겠소. 얼음 회오리와 점심 사이에."
L["Repaid at once, {name}, before I pass a bookshop. I've lost weeks that way."] = "바로 갚겠소, {name}. 책방 앞을 지나면 몇 주씩 사라지는 몸이라."
L["Twenty years in the library, {name}, and no book said how to thank you. This."] = "도서관에서 이십 년, {name}. 당신께 감사하는 법은 어느 책에도 없더군요. 이걸로."
L["Arcane theory says nothing comes free, {name}. Theory was wrong. Thank you."] = "비전 이론상 공짜는 없다 했소, {name}. 이론이 틀렸구려. 고맙소."
L["Of course, {name}. And yes, I suppose you'll want water as well."] = "물론이오, {name}. 그리고 그래, 물도 달라는 거겠지."
L["As requested, {name}. I'll find my page again later."] = "요청하신 대로요, {name}. 읽던 쪽은 나중에 다시 찾겠소."
L["At once, {name}. Carefully, too; I've blinked into two walls today."] = "당장 하겠소, {name}. 조심해서. 오늘만 점멸로 벽에 두 번 박았소."
L["Gladly, {name}. Knowledge should be shared. The Kirin Tor say so, reluctantly."] = "기꺼이, {name}. 지식은 나눠야 하오. 키린 토도 그러더군. 마지못해."
L["Certainly, {name}. I'll cast it slowly. The hand movements are the best part."] = "물론이오, {name}. 천천히 시전하겠소. 손동작이 백미거든."
L["Of course, {name}. Think of it as homework, and I've done it for you."] = "물론이오, {name}. 숙제라 치시오. 내가 대신 해 뒀소."
L["Of course, {name}. Antonidas taught me this. He also taught me to duck."] = "물론이오, {name}. 안토니다스께 배웠소. 몸 숙이는 법도 함께."
L["At once, {name}. Arcane, not fire. I did check."] = "당장 하겠소, {name}. 화염 말고 비전이오. 확인했소."
L["Certainly, {name}. It's this or a lecture on ley lines, and you've been kind."] = "물론이오, {name}. 이거 아니면 지맥 강의인데, 그대는 착하니 이걸로."
L["You asked a mage, {name}. The spell is instant; the explanation is not."] = "마법사한테 청했구려, {name}. 주문은 즉시 시전, 설명은 긴 정신 집중이오."
L["I've cast this a thousand times, {name}. Nine hundred and ninety went well."] = "천 번은 시전해 봤소, {name}. 그중 구백구십 번은 멀쩡했소."
L["Certainly, {name}. Stand still. Fidgeters have been known to end up woolly."] = "물론이오, {name}. 가만히. 꼼지락대다 털이 복슬복슬해진 이들이 있었소."
L["Here, {name}. I had a spare thought and nowhere to put it."] = "여기, {name}. 생각이 하나 남는데 둘 데가 없어서."
L["Take this, {name}. I'd add bread, but conjured bread tastes of nothing."] = "받으시오, {name}. 빵도 얹고 싶지만, 마법으로 만든 빵은 아무 맛이 안 나오."
L["{buff} for you, {name}. No charge, unlike the portals."] = "{name}, {buff} 받으시오. 차원문과 달리 공짜요."
L["Here, {name}. Most folk I point at turn into sheep. Today's your lucky day."] = "여기, {name}. 내가 가리키면 대개 양이 되는데, 오늘은 운 좋은 날이오."
L["Nothing on fire, nothing frozen, {name}. I'm branching out."] = "아무것도 안 태우고 안 얼렸소, {name}. 새 분야를 개척 중이오."
L["For you, {name}. I was practising, and you happened to be the nearest head."] = "받으시오, {name}. 연습 중이었는데 그대 머리가 제일 가까웠소."
L["Here, {name}. Freshly cast, and hardly crackling at all."] = "여기, {name}. 갓 시전한 거라 거의 안 지직거리오."
L["Kings once hired Dalaran for this, {name}. You get it for nothing."] = "옛날엔 왕들이 달라란에 돈 주고 맡기던 거요, {name}. 그대는 공짜요."
L["Take this, {name}. It wears off, unlike my last experiment."] = "받으시오, {name}. 효과가 사라지긴 하오. 지난번 실험과 달리."
L["For you, {name}: everything I learned in Dalaran, minus the essays."] = "{name}, 달라란에서 배운 걸 몽땅 드리오. 과제 보고서만 빼고."
L["Here, {name}. Arcane magic is best shared, before it gets ideas of its own."] = "여기, {name}. 비전 마법은 나눠야 좋소. 딴마음 먹기 전에."
L["Evocation takes an age, {name}, so I spend my mana where it counts. Here."] = "환기는 한세월 걸리오, {name}. 그러니 마나는 쓸 데에만 쓰오. 여기."
L["Here, {name}. A mage who walks past without helping is just a very tall hat."] = "여기, {name}. 돕지 않고 지나치는 마법사는 그냥 아주 높은 모자요."
L["Now that you're clever, {name}, stand between me and the angry things."] = "이제 똑똑해졌으니, {name}, 나와 화난 놈들 사이에 서 주시오."
L["Take this, {name}. For the record, I only blink away when it's tactical."] = "이걸 받으세요, {name}. 참고로, 전 전술적일 때만 점멸해요."
L["This first, {name}. Water's on me after; please don't ask for it mid-fight."] = "먼저 이거요, {name}. 물은 나중에 제가 드릴게요. 싸움 중엔 달라고 하지 마세요."
L["Minds sharpened, {name}. I'll handle the fire, the frost and the panicking."] = "머리는 맑아졌소, {name}. 화염, 냉기, 호들갑은 내가 맡지."
L["Here, {name}. If I say 'Frost Nova', run. If I say 'run', also run."] = "받으세요, {name}. 제가 '얼음 회오리'라 하면 뛰세요. '뛰어'라 해도 뛰고요."
L["Take this, {name}. Pyroblast takes a while; interrupt it and it's personal."] = "이걸 받으세요, {name}. 불덩이 작렬은 오래 걸려요. 끊으면 개인적인 감정으로 받아들일 거예요."
L["Yours, {name}. If I ice-block, I'm not frozen with fear. It's on purpose."] = "당신 거예요, {name}. 제가 얼음 방패를 쓰면 겁에 질린 게 아니라 일부러예요."
L["This now, {name}; portals home after. Getting there alive is on all of us."] = "지금은 이거요, {name}. 귀환 차원문은 나중에. 살아서 가는 건 우리 모두의 몫이고요."
L["Take this, {name}. Anything you'd rather not fight, point at. Wool by teatime."] = "이걸 받으세요, {name}. 싸우기 싫은 놈은 가리키세요. 차 마실 때쯤 양털이 될 거예요."
L["Here, {name}. I'll drop a Blizzard on them. Watch, but from outside it."] = "받으세요, {name}. 저놈들한테 눈보라를 내릴게요. 구경은 밖에서 하세요."
L["Take this, {name}. Keep them off me, and I'll keep them on fire."] = "이걸 받으세요, {name}. 놈들을 제게서 떼어 놓으면, 전 계속 불태울게요."
L["That's for you, {name}. If I go quiet, it's Evocation, not sulking. Usually."] = "당신 몫이에요, {name}. 제가 조용해지면 환기 중이지 삐친 게 아니에요. 대개는요."
L["Take this, {name}. If it goes badly, I've a teleport home. I'd never use it."] = "이걸 받으세요, {name}. 잘못되면 귀환 순간이동이 있어요. 절대 안 쓰겠지만요."
L["How thoughtful, {name}. The Light keeps accounts; I settle mine early."] = "사려 깊구려, {name}. 빛은 장부를 적으니, 난 미리 갚아 두리다."
L["Thank you, {name}. I'll put in a good word with the Light. It owes me several."] = "고맙소, {name}. 빛께 좋게 말해 두리다. 빛이 내게 빚이 좀 있거든."
L["Thank you, {name}. A small miracle, and I didn't even have to pray for it."] = "고맙소, {name}. 작은 기적이구려. 기도도 안 했는데."
L["Thank you, {name}. My faith in people is restored. It was only resting."] = "고맙소, {name}. 사람을 향한 믿음이 돌아왔소. 잠깐 쉬고 있었을 뿐이오."
L["Thank you, {name}. You're in tonight's prayers. Near the top."] = "고맙소, {name}. 오늘 밤 기도에 넣겠소. 꽤 앞쪽에."
L["Healers are rarely on this end of it, {name}. I'd forgotten how nice it is."] = "힐러가 받는 쪽에 설 일은 드물지, {name}. 이리 좋은 걸 잊고 있었소."
L["Thank you, {name}. You've saved me a prayer, and I'm always one short."] = "고맙소, {name}. 덕분에 기도 하나 아꼈소. 늘 하나씩 모자라던 참이오."
L["Thank you, {name}. I'd give a sermon on generosity, but you've just given it."] = "고맙소, {name}. 베풂에 대해 설교하려 했는데, 그대가 방금 몸소 했구려."
L["Thank you, {name}. I'll light a candle for you. Two. I'm feeling reckless."] = "고맙소, {name}. 그대를 위해 촛불을 켜겠소. 두 개. 오늘은 좀 과감하오."
L["Even my shadowy side is smiling, {name}. It has no face, so take my word."] = "내 어둠의 면모도 웃고 있소, {name}. 얼굴이 없으니 내 말을 믿으시오."
L["Of course, {name}. The Light keeps no hours, and neither, sadly, do I."] = "물론이오, {name}. 빛엔 퇴근이 없소. 슬프게도 나도 없고."
L["Straight away, {name}. Most prayers take longer; you've found a shortcut."] = "바로 하리다, {name}. 기도는 보통 오래 걸리는데, 지름길을 찾았구려."
L["Certainly, {name}. The Light shines on those who ask. I just aim it."] = "물론이오, {name}. 빛은 구하는 이를 비추오. 난 조준만 할 뿐."
L["With pleasure, {name}. Faith moves mountains; I'm starting smaller."] = "기꺼이, {name}. 믿음은 산도 옮긴다지만, 난 작은 것부터 하겠소."
L["Of course, {name}. Confessions are extra, and I'd rather not hear them."] = "물론이오, {name}. 고해는 별도 요금이오. 되도록 안 듣고 싶고."
L["Of course, {name}. Nobody who asks goes without. The Light's rule, and mine."] = "물론이오, {name}. 청하는 이는 빈손으로 보내지 않소. 빛의 규칙이자 내 규칙이오."
L["Certainly, {name}. A warm glow means the Light. A cold one, tell me at once."] = "물론이오, {name}. 따스하게 빛나면 빛이오. 차갑게 빛나면 당장 말하시오."
L["Of course, {name}. I'll pray it lasts. I'm told I have an in."] = "물론이오, {name}. 오래가게 기도하리다. 내가 위쪽에 연줄이 좀 있소."
L["Certainly, {name}. I heal, I smite, I do funerals. This is the cheerful bit."] = "물론이오, {name}. 치유, 징벌, 장례까지 하오. 이건 그중 즐거운 일이오."
L["Bless you, {name}. No, you didn't sneeze; I'm simply thorough."] = "축복을, {name}. 재채기는 안 했소? 그럼 다음 재채기 몫으로 미리."
L["Here, {name}. Think of it as a prayer that arrived early."] = "여기, {name}. 일찍 도착한 기도라 생각하시오."
L["The Light asked me to pass this along, {name}. I'm paraphrasing."] = "빛께서 이걸 전하라 하셨소, {name}. 대충 그런 뜻이었소."
L["Take this, {name}. It saves us both an awkward resurrection later."] = "받으시오, {name}. 나중에 어색한 부활 장면을 서로 피할 수 있소."
L["Freely given, {name}. Faith costs nothing. The robes, sadly, did."] = "거저 드리오, {name}. 믿음은 공짜요. 이 로브는 아니었지만."
L["Here, {name}. Think of me as a small, walking temple. No steps to climb."] = "여기, {name}. 걸어 다니는 작은 사원이라 생각하시오. 계단도 없소."
L["A blessing for a stranger, {name}. The Light insists there's no such thing."] = "낯선 이에게 축복을, {name}. 빛은 낯선 이란 없다고 우기지만."
L["Take this, {name}. No collection plate follows. Look: empty hands."] = "받으시오, {name}. 헌금 접시는 안 돌리오. 보시오, 빈손이오."
L["Here, {name}. I'd preach, but you look like somebody with somewhere to be."] = "여기, {name}. 설교하고 싶지만, 갈 길 바빠 보이는구려."
L["Small mercies are my speciality, {name}. Here's one."] = "작은 자비가 내 특기요, {name}. 여기 하나 드리오."
L["Here, {name}. I'd float over properly, but levitating in public draws a crowd."] = "여기, {name}. 우아하게 떠서 가고 싶지만, 공중 부양은 구경꾼이 몰려서."
L["Your turn, {name}. Now, I beg you all: make my job boring."] = "그대 차례요, {name}. 다들 제발, 내 일을 지루하게 만들어 주시오."
L["Everyone near me, {name}; the Light has a limited range. You're in it now."] = "다들 제 곁으로, {name}. 빛은 닿는 거리가 정해져 있거든요. 이제 당신도 그 안이에요."
L["There, {name}. If anyone falls, I'll be very disappointed, then fix it."] = "됐소, {name}. 누가 쓰러지면 몹시 실망할 거요. 그다음에 살리고."
L["Done, {name}. I'll be at the back, praying loudly."] = "끝났소, {name}. 난 맨 뒤에서 큰 소리로 기도하겠소."
L["Here, {name}. If I scream, it's a spell and everything runs. Don't join in."] = "받으세요, {name}. 제가 비명을 지르면 주문이라 다 도망쳐요. 같이 지르진 마세요."
L["That's for you, {name}. If I Fade, I haven't gone. I'm just very uninteresting."] = "당신 몫이에요, {name}. 제가 소실을 쓰면 사라진 게 아니라, 아주 시시해진 거예요."
L["This one's on me, {name}. Shields come later, one each. Pace yourselves."] = "이건 제가 드리는 거예요, {name}. 보호막은 나중에 한 명당 하나씩. 아껴 쓰세요."
L["Take this, {name}. Let's all come back from this the usual way: walking."] = "이걸 받으세요, {name}. 다들 평소처럼 돌아와요. 두 발로 걸어서."
L["That's me keeping you alive, {name}. You keep me from saying 'I told you so'."] = "이렇게 당신을 살려 두는 거예요, {name}. 당신은 제가 '내가 뭐랬어'를 안 하게 해 주세요."
L["I prayed over this group, {name}. The Light said 'good luck'. I'll take it."] = "이 파티를 두고 기도했소, {name}. 빛께서 '행운을 빈다' 하셨소. 그거라도 받겠소."
L["Thank you, {name}. I'd offer you berries, but I ate them all."] = "고맙소, {name}. 산딸기라도 드리고 싶지만 내가 다 먹었소."
L["Thanks, {name}. Like rain in a dry season."] = "고맙소, {name}. 가뭄에 단비 같구려."
L["Much obliged, {name}. My cat form wants to bring you a rabbit. I've said no."] = "신세 졌소, {name}. 표범 모습의 내가 토끼를 물어다 주겠다는 걸 말렸소."
L["Thank you, {name}. I'll plant a tree in your honour. Give it a century."] = "고맙소, {name}. 그대를 기려 나무를 심겠소. 백 년만 기다리시오."
L["Thank you, {name}. May your road stay green and your water sweet."] = "고맙소, {name}. 그대 가는 길은 늘 푸르고, 물은 늘 달기를."
L["Kindly done, {name}. I felt that right down to my roots."] = "고맙소, {name}. 뿌리까지 와닿았소."
L["Nature returns everything eventually, {name}. I'm quicker. Thank you."] = "자연은 결국 모든 걸 돌려주오, {name}. 난 좀 더 빠르지. 고맙소."
L["Barkskin keeps most things out, {name}. Kindness got straight through. Thanks."] = "나무껍질은 웬만한 건 다 막는데, {name}, 친절은 곧장 뚫고 들어오는구려."
L["Thank you, {name}. As a bear this would be a hug. Be glad I'm in this shape."] = "고맙소, {name}. 곰 모습이었으면 와락 끌어안았을 거요. 이 모습이라 다행이지."
L["Certainly, {name}. Give me a moment to remember which shape has hands."] = "물론이오, {name}. 어느 모습에 손이 있었는지 잠깐 떠올려 보고."
L["Of course, {name}. Hold still, like an oak. Oaks are wonderful at it."] = "물론이오, {name}. 참나무처럼 가만히. 참나무는 그걸 기막히게 잘하오."
L["Gladly, {name}. The wild shares everything. Well, not the bears."] = "기꺼이, {name}. 야생은 뭐든 나누오. 곰만 빼고."
L["Right away, {name}. The wild's had a good season; it can spare this."] = "바로 하리다, {name}. 올해 야생은 풍년이라 이 정도는 내줄 수 있소."
L["Of course, {name}. Nature doesn't take requests, but I do."] = "물론이오, {name}. 자연은 주문을 안 받지만, 난 받소."
L["Gladly, {name}. Ask a tree and you'll wait a year. Ask a druid and it's now."] = "기꺼이, {name}. 나무한테 부탁하면 일 년 걸리오. 드루이드는 지금 당장이고."
L["Of course, {name}. The balance tips a little your way. Don't tell the balance."] = "물론이오, {name}. 균형이 그대 쪽으로 살짝 기울었소. 균형한텐 비밀이오."
L["I'd have run over, {name}, but as a cheetah, and you'd have screamed. Here."] = "달려오려다 말았소, {name}. 치타가 덮치면 비명부터 지를 테니. 여기."
L["Of course, {name}. The wild is kind to all who ask. Midges excepted."] = "물론이오, {name}. 야생은 청하는 누구에게나 너그럽소. 날파리만 빼고."
L["Fresh from the Emerald Dream, {name}. Sorry if I yawn."] = "에메랄드의 꿈에서 막 나온 거요, {name}. 하품하면 미안하오."
L["Take this, {name}. Nature provides, and I'm its errand runner today."] = "받으시오, {name}. 자연이 베푸는 거고, 오늘 난 심부름꾼이오."
L["The wild calls you friend now, {name}. Handy, since most of it has teeth."] = "이제 야생이 그대를 벗이라 부르오, {name}. 다행이오. 대개 이빨이 있으니."
L["I'd have picked you flowers, {name}, but this keeps better."] = "꽃이라도 꺾어 드릴까 했소, {name}. 헌데 이게 더 오래가오."
L["Here, {name}. Cenarius would want you to have it. I'm nearly sure."] = "여기, {name}. 세나리우스께서도 그러길 바라셨을 거요. 아마 거의."
L["Here, {name}. For cold nights, sharp claws and long roads."] = "여기, {name}. 추운 밤, 날카로운 발톱, 먼 길에 대비하시오."
L["Take this, {name}. The wild has been watching you, and it's decided you'll do."] = "받으시오, {name}. 야생이 그대를 지켜보다가 쓸 만하다고 결론 냈소."
L["There, {name}. Walk lightly, and the forest will walk with you."] = "됐소, {name}. 사뿐히 걸으면 숲도 그대와 함께 걸을 거요."
L["For you, {name}. The Moonglade sends its regards. It sends very few."] = "받으시오, {name}. 달의 숲에서 안부를 전하오. 좀처럼 안 전하는 곳인데."
L["Nature is cruel, lovely and damp, {name}. This helps with two of those."] = "자연은 잔혹하고, 아름답고, 축축하오, {name}. 이건 그중 둘에 도움이 되오."
L["I tie strangers up in roots most days, {name}. This is the nicer part."] = "평소엔 낯선 이를 뿌리로 묶는 게 일이오, {name}. 이건 좋은 쪽 일이오."
L["Ready, {name}? Take this. Now, whatever happens, nobody startle the bear."] = "준비됐어요, {name}? 이걸 받으세요. 무슨 일이 있어도 곰은 놀라게 하지 마세요."
L["There, {name}. I'll be the cat, the bear or, if we must swim, the seal."] = "됐소, {name}. 난 표범도, 곰도, 헤엄칠 일 생기면 바다표범도 되겠소."
L["Take this, {name}. I've one rebirth in me. Please, nobody make me choose."] = "이걸 받으세요, {name}. 제게 환생은 한 번뿐이에요. 제발 고르게 만들지 마세요."
L["Close ranks, {name}, and take this. The forest is watching, and rooting for us."] = "대열을 좁혀요, {name}. 이것도 받고요. 숲이 지켜보며 우릴 응원하고 있어요."
L["Here, {name}. I'll heal or I'll maul. Tell me which before it's urgent."] = "받으세요, {name}. 치유할지 물어뜯을지, 급해지기 전에 말해 줘요."
L["This is free, {name}. My one Innervate goes to the most desperate. No acting."] = "이건 공짜예요, {name}. 정신 자극은 하나뿐이라 제일 절박한 사람 몫이에요. 연기 금지."
L["Take this, {name}. If I start glowing and hooting, that's moonkin. Serious."] = "이걸 받으세요, {name}. 제가 빛나며 부엉부엉하면 달빛야수예요. 진지한 거예요."
L["For you, {name}. If it gets crowded, I'll call a Hurricane. Hold your hats."] = "당신 몫이에요, {name}. 북적이면 허리케인을 부를게요. 모자 꽉 잡으세요."
L["We move like a herd, {name}, all blessed. Mixed herd. One is sometimes a bear."] = "우린 무리처럼 다니죠, {name}. 다 축복받았고. 섞인 무리예요. 하나는 가끔 곰이고요."
L["Kindness, {name}? My favourite virtue. Just ahead of polishing."] = "친절이라, {name}? 내가 가장 아끼는 미덕이오. 갑옷 광내기를 근소하게 앞서지."
L["For that, {name}, my best blessing. Not the second best. The best."] = "그 보답으로, {name}, 최고의 축복을. 두 번째 말고, 최고로."
L["Virtue rewarded on the spot, {name}! I do love it when that happens."] = "선행이 즉석에서 보답받는구려, {name}! 이런 순간이 참 좋소."
L["Thank you, {name}. My oath says to repay kindness. I'd do it anyway."] = "고맙소, {name}. 내 맹세가 친절엔 보답하라 하오. 맹세 없어도 했겠지만."
L["I'll judge you favourably, {name}. I judge most things harshly. Thank you."] = "그대는 너그럽게 심판하겠소, {name}. 대개는 가혹하게 하는데. 고맙소."
L["Thank you, {name}. My aura just brightened. It does that when I'm touched."] = "고맙소, {name}. 오라가 환해졌소. 감동하면 이러오."
L["A kindness, {name}! I'll have it engraved on my shield, beside the dents."] = "친절이라니, {name}! 방패에 새겨 두겠소. 찌그러진 자국 옆에."
L["Much obliged, {name}. My warhorse sends thanks as well. He's more reserved."] = "신세 졌소, {name}. 내 군마도 고맙다 하오. 그 녀석은 좀 내성적이라."
L["I swore to protect the good, {name}. You've just gone to the top of the list."] = "선한 이를 지키겠노라 맹세했소, {name}. 방금 그대가 명단 맨 위로 올랐소."
L["By the Light, {name}, of course! I've been hoping somebody would ask."] = "빛의 이름으로, {name}, 물론이오! 누가 부탁하길 고대했소."
L["You have my blessing, {name}, in every sense."] = "내 축복을 받으시오, {name}. 모든 의미에서."
L["Certainly, {name}. Kneel if you like. I won't insist. I'll be delighted."] = "물론이오, {name}. 원하면 무릎 꿇으시오. 강요는 않소. 기뻐는 하겠지만."
L["Gladly, {name}. I never run short of blessings. Mana, now and then."] = "기꺼이, {name}. 축복은 절대 안 모자라오. 마나는 가끔 모자라지만."
L["Certainly, {name}. Hold still. My aim is righteous; my gauntlets are clumsy."] = "물론이오, {name}. 가만히. 조준은 의롭지만 건틀릿이 둔하오."
L["Gladly, {name}. Helping is the oath. Shining while I do it is a bonus."] = "기꺼이, {name}. 돕는 건 맹세고, 번쩍이는 건 덤이오."
L["Of course, {name}. Stand fast, chin up, and look deserving. There. You do."] = "물론이오, {name}. 바로 서서, 고개 들고, 받을 만한 표정을. 됐소. 딱 그거요."
L["Of course, {name}. You'd be amazed how rarely anyone asks the tin can for help."] = "물론이오, {name}. 깡통한테 도움 청하는 사람이 얼마나 드문지 알면 놀랄 거요."
L["Of course, {name}. A moment while I pick the blessing. I do have favourites."] = "물론이오, {name}. 축복 좀 고르겠소. 나도 아끼는 게 있어서."
L["The Light asks nothing in return, {name}. I, however, accept thanks."] = "빛은 대가를 바라지 않소, {name}. 난 감사 인사 정도는 받지만."
L["Go with the Light, {name}. I'll be right behind you, clanking."] = "빛과 함께 가시오, {name}. 난 바로 뒤에서 철컹거리며 따라가겠소."
L["The blessing's free, {name}. You've been spared the sermon. This time."] = "축복은 공짜요, {name}. 설교는 봐 드리리다. 이번만."
L["There, {name}. It won't last forever, so be heroic while it does."] = "됐소, {name}. 영원하진 않으니, 효과 있을 때 영웅답게 구시오."
L["Stand tall, {name}. The Light walks with you, and it has excellent posture."] = "허리를 펴시오, {name}. 빛이 함께 걷는데, 빛은 자세가 아주 바르오."
L["Take this, {name}. I'd give you my hammer too, but it's very attached to me."] = "받으시오, {name}. 망치도 드리고 싶지만, 이 녀석이 나한테 애착이 심하오."
L["Blessings are for handing out, {name}. Hoarding them is frowned upon. By me."] = "축복은 나누라고 있는 거요, {name}. 쌓아 두면 눈총받소. 나한테."
L["Justice for the wicked, blessings for the rest, {name}. You're the rest."] = "악인에겐 정의를, 나머지에겐 축복을, {name}. 그대는 나머지요."
L["Take this, {name}. My libram says to share. It says a lot; this bit I like."] = "받으시오, {name}. 내 성서가 나누라 하오. 말이 많은 책인데, 이 대목은 좋소."
L["Chivalry isn't dead, {name}. It's in heavy armour, and it brought you this."] = "기사도는 죽지 않았소, {name}. 판금 갑옷을 입고 이걸 가져왔지."
L["Wear it with pride, {name}. Pride's a sin, but only in large amounts."] = "자부심을 가지시오, {name}. 너무 가지면 교만이지만, 조금은 괜찮소."
L["You're blessed, {name}. Keep behind my shield and we'll do fine."] = "축복을 내렸소, {name}. 내 방패 뒤에 있으면 다 잘될 거요."
L["Stand fast, {name}, blessed. We have the Light, and I have a very large hammer."] = "굳건히 서시오, {name}, 축복받았으니. 우리에겐 빛이, 내겐 아주 큰 망치가 있소."
L["One blessing each, {name}. The Light is generous, but it insists on turns."] = "한 사람에 축복 하나씩이오, {name}. 빛은 너그럽지만 줄은 서야 하오."
L["Splendid, {name}, you're blessed. Don't look at me. I'm rather bright today."] = "훌륭하오, {name}, 축복받았소. 날 보지 마시오. 오늘은 꽤 눈부시니."
L["That's my blessing, {name}. Stay inside my aura too. It's warmer than it looks."] = "내 축복이오, {name}. 내 오라 안에도 있으시오. 보기보다 따뜻하오."
L["Take this, {name}. If I stun something, hit it while it's thinking things over."] = "이걸 받으시오, {name}. 내가 기절시키면, 그놈이 생각하는 동안 치시오."
L["Blessed, {name}. The glowing ground is mine too; stand in it. It bites them."] = "축복받았소, {name}. 빛나는 바닥도 내 거요. 들어서시오. 놈들만 무니까."
L["Take this blessing, {name}. I judge them, you sentence them. Efficient court."] = "이 축복을 받으시오, {name}. 난 심판하고, 그대는 선고하시오. 효율적인 법정이지."
L["Blessed, {name}. If I shout 'for the Light', it means charge. Or pray. Or both."] = "축복받았소, {name}. 내가 '빛을 위하여'라 외치면 돌격이오. 아니면 기도. 아니면 둘 다."
L["Armour polished, hammer blessed, {name}, and now you too. My horse is sulking."] = "갑옷은 광내고, 망치는 축복하고, {name}, 이제 그대도. 내 말은 삐쳐 있소."
L["That's your blessing, {name}. Mine is Righteous Fury. Let them come to me."] = "그대의 축복이오, {name}. 내 건 정의의 격노지. 놈들이 내게 오라 하시오."
L["How kind, {name}. My imp says thank you too. He's lying, but I'm not."] = "친절하구려, {name}. 내 임프도 고맙다 하오. 그놈은 거짓말이지만 난 진심이오."
L["Thank you, {name}. It's been ages since anyone gave me something uncursed."] = "고맙소, {name}. 저주 안 걸린 걸 받아 본 게 얼마 만인지."
L["Thank you, {name}. I'll repay you with something I didn't find in a crypt."] = "고맙소, {name}. 지하 묘지에서 주운 게 아닌 걸로 갚겠소."
L["Most gracious, {name}. I've asked the voidwalker to stop looming at you."] = "고맙소, {name}. 공허방랑자한테 그대 곁에서 어른대지 말라 일러 뒀소."
L["Thank you, {name}. Most folk cross the road when they see me."] = "고맙소, {name}. 다들 날 보면 길을 건너 피하는데."
L["No blood, no bargain, no binding, {name}? What a strange way to trade. Thanks."] = "피도, 계약도, 속박도 없이, {name}? 참 희한한 거래구려. 고맙소."
L["Thank you, {name}. Should anything haunt you, send it my way."] = "고맙소, {name}. 뭐든 그대를 괴롭히거든 내게 보내시오."
L["How thoughtful, {name}. Everything I'm given, I return. Except souls. Here."] = "사려 깊구려, {name}. 받은 건 다 돌려주오. 영혼만 빼고. 여기."
L["Of course, {name}. No soul required. This time."] = "물론이오, {name}. 영혼은 필요 없소. 이번엔."
L["You asked a warlock for help, {name}. Bold. I like you already."] = "흑마법사한테 도움을 청하다니, {name}. 대담하군. 벌써 마음에 드오."
L["Of course, {name}. The imp offered to help, and I said no, for all our sakes."] = "물론이오, {name}. 임프가 돕겠다길래 말렸소. 우리 모두를 위해서."
L["Certainly, {name}. Of all my spells, this is the one I can do at parties."] = "물론이오, {name}. 내 주문 중 잔치에서 써도 되는 건 이거 하나요."
L["Gladly, {name}. A good deed on my record; the Shadow Council would be appalled."] = "기꺼이, {name}. 선행 기록이 하나 늘었군. 어둠의 의회가 기겁하겠소."
L["Of course, {name}. Please don't read the book I'm holding. For your own sake."] = "물론이오, {name}. 내가 든 책은 읽지 마시오. 그대를 위해서요."
L["Certainly, {name}. Feel watched? That's only the Eye of Kilrogg. Hold still."] = "물론이오, {name}. 누가 보는 것 같소? 킬로그의 눈일 뿐이오. 가만히."
L["Of course, {name}. I only curse people who don't ask nicely. You're quite safe."] = "물론이오, {name}. 저주는 무례한 이에게만 거오. 그대는 안전하오."
L["Yes, {name}, it's the one without screaming. Hold still."] = "그렇소, {name}. 비명 안 나오는 쪽 주문이오. 가만히."
L["Of course, {name}. Going somewhere wet? I won't ask. Warlocks never ask."] = "물론이오, {name}. 물 많은 데 가오? 안 묻겠소. 흑마법사는 원래 안 묻소."
L["Here, {name}. Don't ask where it came from. Really, don't."] = "여기, {name}. 어디서 났는지는 묻지 마시오. 정말로."
L["Fall in a lake someday, {name}, and you'll think of me fondly."] = "언젠가 호수에 빠지면, {name}, 날 좋게 떠올릴 거요."
L["Breathe easy, {name}. I'd hate to lose you to anything as dull as water."] = "편히 숨 쉬시오, {name}. 물 따위 시시한 걸로 그대를 잃긴 싫소."
L["Here, {name}. You'll want a soulstone too, but that's a bigger conversation."] = "여기, {name}. 영혼석도 필요하겠지만, 그건 긴 얘기가 될 거요."
L["Take this, {name}. It's the only spell of mine the priests approve of."] = "받으시오, {name}. 사제들이 인정하는 내 주문은 이거 하나요."
L["Take this, {name}. My mother still thinks I'm a mage. Let's keep it that way."] = "받으시오, {name}. 어머니는 아직 내가 마법사인 줄 아오. 비밀로 해 주시오."
L["Here, {name}. It isn't green, it doesn't whisper, and it won't follow you home."] = "여기, {name}. 초록색도 아니고, 속삭이지도 않고, 집까지 따라가지도 않소."
L["Here, {name}. Dark magic, used for good. Do tell my old tutor; he'll hate it."] = "여기, {name}. 좋은 일에 쓴 흑마법이오. 옛 스승께 꼭 일러 주시오. 질색할 거요."
L["Here, {name}. I keep the darker spells for people who've earned them."] = "여기, {name}. 더 어두운 주문은 그럴 만한 자들 몫으로 아껴 두오."
L["Here, {name}. I'm not all curses and fear. Mostly, but not all."] = "여기, {name}. 내가 저주랑 공포뿐인 건 아니오. 대부분이긴 해도."
L["My grimoire has a chapter on kindness, {name}. It's short, but I've read it."] = "내 마법서에도 친절 편이 있소, {name}. 짧지만 읽긴 읽었소."
L["Everyone ready, {name}? Souls intact? Take this; let's keep it that way."] = "다들 준비됐소, {name}? 영혼 멀쩡하고? 이걸 받으시오. 계속 그렇게 지킵시다."
L["Take this and stay close, {name}. The voidwalker takes hits; I take the credit."] = "이걸 받고 붙어 있으시오, {name}. 공허방랑자가 맞고, 공은 내가 챙기지."
L["Swim all you like, {name}. If anyone drifts off, I'll summon them back."] = "마음껏 헤엄치시오, {name}. 누가 떠내려가면 소환해 오겠소."
L["Do pet the felhunter, {name}. Just take your spells off first."] = "지옥사냥개 쓰다듬어도 되오, {name}. 몸에 걸린 주문은 먼저 떼고."
L["For you, {name}. If I fear something, don't chase it. It comes back angrier."] = "그대 몫이오, {name}. 내가 공포를 걸면 쫓지 마시오. 더 화나서 돌아오니까."
L["I trade blood for mana, {name}, and mana for this. It looks worse than it is."] = "피를 마나로 바꾸고, {name}, 마나를 이걸로 바꾸지. 보기보다 괜찮소."
L["This now, {name}; healthstones after. For a crisis, mind, not as a snack."] = "지금은 이거요, {name}. 생명석은 나중에. 위급할 때 쓰시오, 간식 말고."
L["Take this, {name}, and keep clear when I cast Hellfire. I burn too. Tragic."] = "이걸 받고, {name}, 지옥의 불길 쓸 땐 떨어지시오. 나도 타거든. 비극이지."
L["That's from me, {name}, not the imp. He's on fire, and ours. Don't douse him."] = "이건 내가 주는 거요, {name}, 임프가 아니라. 그놈은 불타지만 우리 편이오. 끄지 마시오."
L["Take this, {name}. If something green falls from the sky, that's mine. Cheer."] = "이걸 받으시오, {name}. 하늘에서 초록색 뭔가 떨어지면 내 거요. 환호하시오."
L["Thank you, {name}! Sorry, was that loud? I only have the one volume."] = "고맙소, {name}! 아, 시끄러웠소? 내 목소린 볼륨이 하나뿐이라."
L["Much obliged, {name}. No spells to give back, but I do a very sincere shout."] = "신세 졌소, {name}. 돌려줄 주문은 없지만, 진심 어린 외침은 있소."
L["Thanks, {name}. Now I'm twice as angry. In the good way."] = "고맙소, {name}. 덕분에 분노가 두 배요. 좋은 쪽으로."
L["Thanks, {name}. You've earned a place right behind me. Safest spot there is."] = "고맙소, {name}. 내 바로 뒷자리를 내드리리다. 세상에서 제일 안전한 곳이오."
L["Thank you, {name}. Kindness makes me soft. Luckily I've plenty of armour."] = "고맙소, {name}. 친절에 마음이 물러지오. 다행히 갑옷은 두껍소."
L["Thank you, {name}. My armourer thanks you too. I paid for his house."] = "고맙소, {name}. 대장장이도 고맙다 하오. 그 집, 내 수리비로 지었거든."
L["Thanks, {name}. I'd bandage something for you, but you look annoyingly fine."] = "고맙소, {name}. 붕대라도 감아 주고 싶은데, 얄밉게도 멀쩡하구려."
L["Thank you, {name}. I switched to my grateful stance for that. It's rarely used."] = "고맙소, {name}. 이걸 위해 감사 태세로 바꿨소. 거의 안 쓰는 태세요."
L["You've given me magic, {name}. No idea where to keep it. I'll wear it. Thanks."] = "마법을 받았구려, {name}. 둘 데를 모르겠으니 입고 다니겠소. 고맙소."
L["Owing folk makes me restless, {name}, and restless makes me charge things."] = "빚지면 좀이 쑤시오, {name}. 좀이 쑤시면 아무 데나 돌진하고."
L["You want a shout, {name}? I was going to shout anyway."] = "외쳐 달라고, {name}? 어차피 외칠 참이었소."
L["Of course, {name}. A fighter who asks for courage already has some."] = "물론이오, {name}. 용기를 청하는 전사라면 이미 용기가 있는 거요."
L["Right away, {name}. Square your shoulders. There, that's half of it."] = "당장 하리다, {name}. 어깨 펴시오. 됐소, 그게 반이오."
L["Happily, {name}! Go hit something for me."] = "기꺼이, {name}! 가서 나 대신 한 대 치시오."
L["Right, {name}. Deep breath. Not you. Me."] = "좋소, {name}. 숨 크게 들이쉬고. 그대 말고. 나."
L["Happy to, {name}. First request today that didn't involve lifting something."] = "기꺼이, {name}. 뭘 들어 올려 달라는 게 아닌 부탁은 오늘 처음이오."
L["Coming up, {name}. Plant your feet. This one has a kick to it."] = "곧 나가오, {name}. 발 단단히 디디시오. 이건 좀 세오."
L["Of course, {name}. Most folk only ask me to stop. This is a nice change."] = "물론이오, {name}. 다들 그만 좀 하라는 부탁만 하는데, 모처럼 좋구려."
L["Of course, {name}. Took me years to learn. Years of yelling at trees, mostly."] = "물론이오, {name}. 배우는 데 몇 년 걸렸소. 주로 나무한테 고함치면서."
L["Consider yourself shouted at, {name}. Affectionately."] = "방금 그대에게 외쳤소, {name}. 애정을 담아서."
L["No incense, no prayers, {name}. Just me, shouting encouragingly."] = "향도 기도도 없소, {name}. 그냥 내가 응원 삼아 소리칠 뿐."
L["Chin up, {name}, and take this! If anything bothers you, I'll charge it."] = "힘내, {name}. 이거 받아! 뭐든 거슬리면 내가 돌진해 주지."
L["There, {name}! Anything that doesn't feel braver now wasn't listening."] = "됐소, {name}! 주변에 아직 겁먹은 게 있다면 못 들은 거요."
L["Here, {name}, some courage. Spend it freely; I've plenty more."] = "여기 용기요, {name}. 마음껏 쓰시오. 아직 많소."
L["Here, {name}. Something sharper than a whetstone: morale."] = "여기, {name}. 숫돌보다 날을 잘 세워 주는 것, 사기요."
L["Take this, {name}. Warriors don't carry spells, so we carry each other."] = "받으시오, {name}. 전사는 주문을 못 지니니, 서로를 짊어지오."
L["Here, {name}. You look about to walk into something big. Walk in harder."] = "여기, {name}. 뭔가 큰일에 뛰어들 얼굴이구려. 더 세게 뛰어드시오."
L["Here, {name}. No magic in it. Just a warrior believing in you, very firmly."] = "여기, {name}. 마법은 없소. 그대를 아주 굳게 믿는 전사 하나뿐이오."
L["Take this, {name}. It's loud, it's free, and I mean it."] = "받으시오, {name}. 시끄럽고, 공짜고, 진심이오."
L["Here, {name}. Tell whatever you fight that a warrior vouched for you."] = "여기, {name}. 누구랑 싸우든 전사가 보증했다고 전하시오."
L["That one was for you, {name}. The next one's for whatever's in your way."] = "이건 그대 몫이오, {name}. 다음 건 그대 앞길 막는 놈 몫이고."
L["Listen up, {name}! That's it. That was the whole speech."] = "잘 들으시오, {name}! 끝. 이게 연설 전부요."
L["Take this, {name}. Where's the danger? Never mind, I'll find it. Face first."] = "이거 받아, {name}. 위험이 어디 있냐고? 됐어, 내가 찾지. 얼굴부터 들이밀고."
L["Right, {name}! Take this. I go first, shout loudest; nobody touches the healer."] = "좋아, {name}! 이거 받아. 내가 앞장서고, 제일 크게 외치고, 힐러는 아무도 못 건드려."
L["Everybody angrier? Good. Onward, {name}, and mind my backswing."] = "다들 화났소? 좋소. 전진이오, {name}. 내 휘두르는 반경은 조심하고."
L["Here, {name}. I need hitting before I'm useful. Don't panic when it happens."] = "받아, {name}. 난 맞아야 쓸모가 생겨. 그때 당황하지 마."
L["This first, {name}. Bandages are in my pack too; I tied the knots. Very secure."] = "먼저 이거, {name}. 붕대도 배낭에 있어. 매듭은 내가 묶었지. 아주 단단해."
L["Right, {name}: take this. I take hits, you take credit, we split the repairs."] = "좋아, {name}. 이거 받아. 난 맞고, 넌 공을 챙기고, 수리비는 나누자."
L["For you, {name}. If I go red and quiet, that's Berserker Rage. Loud is fine."] = "너 줄 거, {name}. 내가 시뻘게지고 조용해지면 광전사의 격노야. 시끄러우면 괜찮은 거고."
L["Take this, {name}. My shield's seen worse than this. So has my face. Onward."] = "이거 받아, {name}. 내 방패는 이보다 험한 꼴도 봤어. 내 얼굴도. 가자."
L["The living rarely lend me much, {name}. I'll be prompt, in case it catches on."] = "산 자들은 내게 뭘 잘 빌려주지 않소, {name}. 유행이 되라고 얼른 갚겠소."
L["Thank you, {name}. I owe you one fight at your side, on a day of your choosing."] = "고맙소, {name}. 그대 곁에서 한 번 싸워 드리리다. 날은 그대가 정하시오."
L["The skulls came with the armour, {name}. The gratitude is all my own."] = "해골은 갑옷에 딸려 온 거요, {name}. 고마운 마음은 온전히 내 것이고."
L["My one healing spell only mends the dead, {name}. Do stay healthy. Thank you."] = "내 유일한 치유 주문은 죽은 자만 고치오, {name}. 부디 건강하시오. 고맙소."
L["Your kindness is safe with me, {name}. Very little else is. Thank you."] = "그대의 친절은 내게 맡기면 안전하오, {name}. 다른 건 대개 아니지만. 고맙소."
L["I've stood at the runeforge all night for less than that, {name}. Thank you."] = "이보다 못한 걸 받고도 룬가열로 앞에서 밤을 새운 적이 있소, {name}. 고맙소."
L["The Ebon Blade answers courtesy in kind, {name}, and insults with the blade."] = "칠흑의 기사단은 예의엔 예의로, {name}, 모욕엔 칼날로 답하오."
L["Tonight's watch will pass quicker for that, {name}, and I keep a great many."] = "덕분에 오늘 밤 불침번이 금방 지나가겠소, {name}. 난 불침번을 숱하게 서는 몸이오."
L["Thank you, {name}. Ride with me a while, if your horse will stand next to mine."] = "고맙소, {name}. 잠시 함께 달립시다. 그대 말이 내 말 곁에 서 준다면."
L["Thank you, {name}. I'll have the dead salute you. Badly, but with feeling."] = "고맙소, {name}. 망자들더러 그대에게 경례하라 하겠소. 엉망이겠지만 진심으로."
L["Very well, {name}. Stand fast; the horn is loud, and the cold follows it."] = "좋소, {name}. 버티고 서 있으시오. 뿔피리 소리가 크고, 냉기가 뒤따르니."
L["Of course, {name}. Most of what I do is quick or final. This is the quick kind."] = "물론이오, {name}. 내 일은 대개 빠르거나 끝장이오. 이건 빠른 쪽이오."
L["You have my horn and my word, {name}. One is louder; the other lasts longer."] = "내 뿔피리와 내 약속을 드리오, {name}. 하나는 더 시끄럽고, 하나는 더 오래가오."
L["Of course, {name}. Mind the runeblade. It doesn't know you yet."] = "물론이오, {name}. 룬검 조심하시오. 아직 그대를 모르니."
L["Gladly, {name}. I'd far rather sound a horn for a friend than a dirge."] = "기꺼이, {name}. 장송곡보다야 벗을 위해 뿔피리를 부는 게 훨씬 낫소."
L["At once, {name}. A knight who makes an ally wait isn't worth their runes."] = "당장 하리다, {name}. 동료를 기다리게 하는 기사는 룬값도 못 하오."
L["Yes, {name}. Step into view; this helm was made for glaring, not for looking."] = "그러겠소, {name}. 눈앞으로 오시오. 이 투구는 보라고가 아니라 노려보라고 만든 거요."
L["The Ebon Blade serves the living now, {name}. Even the impatient ones."] = "칠흑의 기사단은 이제 산 자를 섬기오, {name}. 성미 급한 이들까지도."
L["Of course, {name}. Pay no mind to the frost on your boots. It brushes off."] = "물론이오, {name}. 장화에 낀 서리는 신경 쓰지 마시오. 털면 떨어지오."
L["The paladins at Light's Hope ask far more stiffly, {name}. They still get it."] = "희망의 빛 예배당 성기사들은 훨씬 뻣뻣하게 청하오, {name}. 그래도 받아 가지."
L["Hear that, {name}? Winter, on your side for once."] = "들리오, {name}? 웬일로 겨울이 그대 편이오."
L["The horn sounds for you, {name}. It used to sound only for the Scourge."] = "뿔피리가 그대를 위해 울리오, {name}. 예전엔 스컬지를 위해서만 울렸지."
L["Take this, {name}, and advice from a death knight: never fight fair, nor alone."] = "이걸 받으시오, {name}. 죽음의 기사의 조언도. 절대 정정당당하게도, 혼자서도 싸우지 마시오."
L["Acherus floats over the Plaguelands, {name}. It's good to come down and help."] = "아케루스는 역병지대 위에 떠 있소, {name}. 내려와 돕는 것도 좋구려."
L["The road's dark, {name}; I'm usually the darkest thing on it. Take this along."] = "길이 어둡소, {name}. 대개 그 길에서 제일 어두운 건 나지만. 이걸 가져가시오."
L["You looked a little short of an army, {name}. A horn is the next best thing."] = "군대 하나쯤 모자라 보였소, {name}. 그럴 땐 뿔피리가 차선책이오."
L["Here, {name}. My ghoul wanted to say hello. I've spared you that."] = "여기, {name}. 내 구울이 인사하고 싶어 했소. 그건 면하게 해 드렸지."
L["Take this, {name}. Cold, loud and well meant, like most of my order."] = "받으시오, {name}. 차갑고 시끄럽지만 선의요. 우리 기사단 대부분처럼."
L["Whatever waits out there, {name}, I've likely killed its cousin. Take this."] = "저 밖에 뭐가 기다리든, {name}, 그놈 사촌쯤은 내가 죽였을 거요. 받으시오."
L["Take this and keep moving, {name}. Trouble tends to follow death knights about."] = "받고 계속 가시오, {name}. 말썽은 죽음의 기사를 졸졸 따라다니는 법이오."
L["Take this, {name}. If I raise an army, be civil. They didn't ask to be here."] = "이걸 받으시오, {name}. 내가 군대를 일으키면 예의 바르게 대하시오. 그들도 원해서 온 게 아니니."
L["That's for you, {name}. Walk where I walk; the frost holds us up over any lake."] = "그대 몫이오, {name}. 내가 걷는 데로 걸으시오. 서리가 어떤 호수 위에서도 받쳐 주니."
L["For you, {name}. If I look hurt, let me hit something. That's how I mend."] = "그대 몫이오, {name}. 내가 다쳐 보이면 뭐든 치게 두시오. 난 그렇게 낫소."
L["Take this, {name}. My ghoul goes in first. He won't mind. Long past minding."] = "이걸 받으시오, {name}. 내 구울이 먼저 들어가오. 신경 안 쓰지. 오래전부터."
L["Here, {name}, to keep up. The dead don't tire, and I forget the living do."] = "받으시오, {name}, 따라오라고. 죽은 자는 안 지치는데, 산 자가 지친다는 걸 잊곤 하오."
L["Take this and don't fall, {name}. I can bring you back, but it's unsettling."] = "이걸 받고 쓰러지지 마시오, {name}. 되살릴 순 있지만, 섬뜩한 방법이오."
L["That's for you, {name}. Leave the fevers to me; they spread on their own."] = "그대 몫이오, {name}. 열병은 내게 맡기시오. 알아서 퍼지니까."
L["The horn has sounded, {name}. Whatever heard it knows we're coming."] = "뿔피리가 울렸소, {name}. 들은 놈들은 우리가 가는 걸 알 거요."
L["Take this, {name}. Whatever we kill today stays dead. I'll see to it myself."] = "이걸 받으시오, {name}. 오늘 죽인 건 죽은 채로 있을 거요. 내가 직접 챙기지."
L["Take this, pick a target, {name}, and I'll pick it too. Shorter arguments."] = "이걸 받고 목표를 고르시오, {name}. 나도 같은 걸 고르지. 말다툼이 줄어드오."
L["Take a gift with both hands, my master said, {name}. And return it with both."] = "사부께선 선물은 두 손으로 받으라 하셨소, {name}. 갚을 때도 두 손으로."
L["Thank you, {name}. I feel light enough to run up a waterfall. I may try."] = "고맙소, {name}. 폭포라도 뛰어오를 만큼 몸이 가볍소. 해 볼지도 모르겠소."
L["I meditated on generosity for years, {name}. You skipped to the end. Thank you."] = "너그러움을 몇 년이나 명상했소, {name}. 그대는 끝으로 바로 건너뛰었구려. 고맙소."
L["I came out into the world to find good people, {name}. That's one. Thank you."] = "좋은 사람을 찾으러 세상에 나왔소, {name}. 하나 찾았군. 고맙소."
L["The masters at the Peak of Serenity would bow to that, {name}. So do I."] = "평온의 봉우리 사부들도 이 앞에선 고개를 숙일 거요, {name}. 나도 그렇소."
L["Kindly done, {name}. The next brigand who jumps me gets one kick fewer."] = "친절하구려, {name}. 다음에 날 덮치는 강도는 발차기 한 대 덜 맞을 거요."
L["A kindness is like a strike, {name}: it's all in the timing. Yours was perfect."] = "친절은 타격과 같소, {name}. 타이밍이 전부지. 그대 건 완벽했소."
L["Thank you, {name}. These hands were trained to strike. Today they get to give."] = "고맙소, {name}. 이 손은 치라고 단련됐지만, 오늘은 베풀 수 있구려."
L["Thank you, {name}. Answered the monk's way: no wasted motion, no wasted words."] = "고맙소, {name}. 수도사답게 답하리다. 헛동작도, 헛말도 없이."
L["Gratitude makes even a monk clumsy, {name}. Forgive the elbows. Thank you."] = "고마운 마음에 수도사도 허둥대는구려, {name}. 팔꿈치는 용서하시오. 고맙소."
L["Of course, {name}. My master took a year to teach me this. I'll take a moment."] = "물론이오, {name}. 사부께선 이걸 가르치는 데 일 년 걸리셨소. 난 잠깐이면 되오."
L["One of the old legacies, {name}, handed down to me and now to you."] = "옛 유산 중 하나요, {name}. 내게 전해졌고, 이제 그대에게 전하오."
L["Nothing calms the mind like being useful, {name}. You've done me a favour."] = "쓸모 있는 것만큼 마음을 다스리는 건 없소, {name}. 오히려 내가 신세를 졌구려."
L["Of course, {name}. My hands know this one by heart. I just tell them who."] = "물론이오, {name}. 손이 이건 외우고 있소. 누구한테인지만 일러 주면 되지."
L["At once, {name}. The fist is for foes; the open palm is for friends."] = "당장 하리다, {name}. 주먹은 적에게, 펼친 손바닥은 벗에게."
L["Of course, {name}, one moment. Mid-form; bad luck to stop on the left foot."] = "물론이죠, {name}, 잠깐만요. 품새 도중인데 왼발에서 멈추면 재수가 없거든요."
L["Gladly, {name}. I was only standing still to see what it felt like."] = "기꺼이, {name}. 가만히 서 있으면 어떤 기분인지 보려던 참이었소."
L["At once, {name}. If you blinked, you missed it. That's fine; it's on you now."] = "바로 하겠소, {name}. 눈 깜빡했으면 놓쳤을 거요. 괜찮소. 이미 그대 몸에 있으니."
L["Of course, {name}. It costs me a breath and a moment, and I've plenty of both."] = "물론이오, {name}. 숨 한 번, 잠깐이면 되오. 둘 다 넉넉하오."
L["Of course, {name}. Ask me every day, if you like. Monks love a routine."] = "물론이오, {name}. 원하면 매일 청하시오. 수도사는 규칙적인 걸 좋아하오."
L["I passed you twice on my morning run, {name}. The third time, I stopped. Here."] = "아침 달리기 중에 그대를 두 번 지나쳤소, {name}. 세 번째엔 멈췄지. 여기."
L["Your stance says long day, {name}. Monks notice. Take this."] = "자세를 보니 긴 하루였군요, {name}. 수도사는 그런 걸 알아채죠. 이걸 받아요."
L["A monk gives before being asked, {name}. It saves us both the bowing."] = "수도사는 청하기 전에 주오, {name}. 그래야 서로 절을 덜 하지."
L["Take this, {name}. My master said one kind act before every meal. I'm hungry."] = "받으시오, {name}. 사부께선 끼니마다 선행 하나 먼저 하라 하셨소. 배가 고프오."
L["Kindness is the hardest stance to hold, {name}. I'm practising. Here."] = "친절은 가장 버티기 힘든 자세요, {name}. 수련 중이오. 여기."
L["I practised patience by not giving you this, {name}. I lasted three heartbeats."] = "이걸 안 주는 걸로 인내를 수련했소, {name}. 심장이 세 번 뛰는 동안 버텼소."
L["Take this, {name}, and be gentle out there. Unless a hozen starts it."] = "이걸 받고, {name}, 밖에선 부드럽게 굴어요. 호젠이 먼저 시비 걸면 몰라도."
L["A calm mind finds the road, {name}. This should keep you steady on it."] = "고요한 마음이 길을 찾소, {name}. 이게 그 길에서 그대를 든든히 받쳐 줄 거요."
L["The Last Emperor left Pandaria a legacy, {name}. I'm leaving you a small one."] = "마지막 황제는 판다리아에 유산을 남겼소, {name}. 난 그대에게 작은 걸 남기오."
L["For you, {name}. No lesson attached. My masters would be appalled."] = "그대에게 주오, {name}. 교훈은 안 붙였소. 사부들이 기겁하시겠군."
L["For your feet, {name}. Stay light on them; a heavy step is an easy target."] = "발을 위한 거예요, {name}. 가볍게 디뎌요. 무거운 걸음은 쉬운 표적이에요."
L["Take this, {name}. If they surround us, I'll spin. Stand back; I'm not tidy."] = "이걸 받아요, {name}. 포위당하면 회전할게요. 물러서요. 깔끔하진 않거든요."
L["Fight from your centre, {name}. If you can't find yours, borrow mine."] = "중심에서부터 싸우시오, {name}. 그대 중심을 못 찾겠거든 내 걸 빌려 가시오."
L["Take this, {name}. If one freezes mid-swing, that's me. Leave it till last."] = "이걸 받아요, {name}. 한 놈이 휘두르다 굳으면 제 짓이에요. 그놈은 마지막에."
L["That's for you, {name}. You go high, I'll go low. Nobody guards both at once."] = "당신 몫이에요, {name}. 당신은 위로, 전 아래로. 둘 다 막는 놈은 없어요."
L["Ready, {name}? Take this. Loose shoulders, soft knees, firm intentions."] = "준비됐어요, {name}? 이걸 받아요. 어깨는 풀고, 무릎은 부드럽게, 마음은 굳게."
L["Take this, {name}. Any weapon I take off them stays taken. They held it badly."] = "이걸 받아요, {name}. 제가 뺏은 무기는 돌려주지 않아요. 잘못 쥐고 있었거든요."
L["Here, {name}. Leave the runners to me. Nothing outruns a monk with a grudge."] = "받아요, {name}. 도망치는 놈은 제게 맡겨요. 원한 품은 수도사한테선 아무도 못 도망쳐요."
L["Take this, {name}. If I end a fight with one touch, don't ask. It took years."] = "이걸 받아요, {name}. 제가 손끝 하나로 싸움을 끝내도 묻지 마요. 수년이 걸렸거든요."
L["This steadies the temper, {name}. Anger opens a door, and the Sha walk in."] = "이건 성미를 가라앉혀요, {name}. 분노는 문을 열고, 샤가 들어오죠."
L["That was well cast, {name}. I would know. Thank you."] = "잘 시전했구려, {name}. 이 방면엔 내가 좀 아오. 고맙소."
L["I have studied fire, time and the Dream, {name}. You still surprised me."] = "불, 시간, 에메랄드의 꿈까지 공부했소, {name}. 그런데도 그대에겐 놀랐소."
L["Dragons give big gifts slowly, {name}. Yours was small and quick. I prefer it."] = "용은 큰 선물을 느릿느릿 주오, {name}. 그대 건 작고 빨랐소. 난 그쪽이 좋소."
L["I'll dip a wing to you when I next fly over, {name}. Watch for it."] = "다음에 위로 날아갈 때 날개를 까딱해 보이겠소, {name}. 잘 보시오."
L["I've known dragons with worse manners, {name}, and some of them were Aspects."] = "그대보다 예의 없는 용도 알았소, {name}. 그중 몇은 위상이었지."
L["Thank you, {name}. I answer in kind, with magic older than your kingdoms."] = "고맙소, {name}. 그대 왕국들보다 오래된 마법으로 답례하겠소."
L["Thank you, {name}. I'm delighted. You can tell by the faint smoke."] = "고맙소, {name}. 무척 기쁘오. 연기가 살짝 나는 걸 보면 알 거요."
L["Generous, {name}, and not a trace of showing off. I must learn that part."] = "너그러우면서, {name}, 뽐내는 기색은 전혀 없구려. 그 부분은 배워야겠소."
L["Thank you, {name}. Returned at once. My aim is perfect; my patience is not."] = "고맙소, {name}. 바로 돌려드리오. 조준은 완벽한데 인내심은 영 아니라서."
L["Thank you, {name}. I shall cite you, should I ever write a treatise on manners."] = "고맙소, {name}. 언젠가 예법에 관한 논문을 쓰면 그대를 인용하겠소."
L["Gladly, {name}. Help from a dragon once took a quest. Things have improved."] = "기꺼이, {name}. 예전엔 용의 도움을 받으려면 시련을 넘어야 했소. 세상 좋아졌지."
L["Hold still, {name}. Or hover, if you are able. No? Standing will do."] = "가만히 계시오, {name}. 떠 있을 수 있으면 떠 있든가. 못 하오? 서 있어도 되오."
L["Watch closely, {name}. My casting is said to be a joy to watch. Mostly by me."] = "잘 보시오, {name}. 내 시전은 보는 맛이 있다고들 하오. 주로 내가 하는 말이지만."
L["It would be my pleasure, {name}. Truly. I don't say 'truly' lightly."] = "기쁘게 하리다, {name}. 진심이오. '진심'이란 말은 함부로 안 쓰오."
L["Of course, {name}. Magic this old ought to be spent kindly, and you qualify."] = "물론이오, {name}. 이리 오래된 마법은 좋은 데 써야 하오. 그대는 자격이 있소."
L["Of course, {name}. Ask again tomorrow; I'll have improved it overnight."] = "물론이오, {name}. 내일 또 청하시오. 밤사이 더 다듬어 두겠소."
L["You need only ask, {name}. I am curious how it will look on you."] = "청하기만 하면 되오, {name}. 그대에게 어떻게 어울릴지 궁금하구려."
L["Certainly, {name}. Think of something calm. Not dragons."] = "그러겠소, {name}. 차분한 걸 떠올리시오. 용 말고."
L["On the Forbidden Reach we practised on rocks, {name}. You are an improvement."] = "금지된 해안에선 바위에 대고 연습했소, {name}. 그대가 훨씬 낫구려."
L["Of course, {name}. You're standing exactly where I'd have put you. Well done."] = "물론이오, {name}. 내가 세웠을 바로 그 자리에 서 있구려. 잘했소."
L["Take this, {name}. I meant to explain the spell first. Too late now."] = "받으시오, {name}. 주문을 먼저 설명하려 했는데. 이미 늦었군."
L["For you, {name}. Unasked, unearned and entirely deserved. Draconic logic."] = "그대 거요, {name}. 청하지도, 벌지도 않았지만 마땅히 받을 만하오. 용의 논리지."
L["I spotted you from afar, {name}. Evokers have sharp eyes and little restraint."] = "멀리서 그대를 봤소, {name}. 기원사는 눈은 밝고 참을성은 없소."
L["Evokers study for years to cast this well, {name}. You need only stand there."] = "기원사는 이걸 잘 걸려고 수년을 공부하오, {name}. 그대는 서 있기만 하면 되고."
L["You'll be glad of this soon, {name}. Don't ask how I know. Bronze business."] = "곧 이게 고마울 거요, {name}. 어떻게 아냐고는 묻지 마시오. 청동용군단 일이오."
L["I could be flying right now, {name}, and instead I'm helping you. Do take note."] = "지금 날고 있을 수도 있었소, {name}. 그런데 그대를 돕고 있지. 꼭 기억해 두시오."
L["Here, {name}. Old magic, new caster. We're both doing rather well."] = "여기, {name}. 오래된 마법에 새내기 시전자. 둘 다 꽤 잘하고 있소."
L["Not my grandest spell, {name}, but the one I'd most like to be known for."] = "가장 웅장한 주문은 아니오, {name}. 그래도 이걸로 가장 기억되고 싶소."
L["I have read about heroes, {name}. You look like the early chapters. Take this."] = "영웅에 대해 읽어 봤소, {name}. 그대는 초반 장 같구려. 이걸 받으시오."
L["Magic can't stay up in the sky, {name}. Sooner or later it lands on somebody."] = "마법은 하늘에만 머물 수 없소, {name}. 언젠가는 누군가에게 내려앉지."
L["Take this, {name}. If I seize you and fly, it is a rescue, not an abduction."] = "이걸 받으시오, {name}. 내가 그대를 붙잡고 날면 구출이지 납치가 아니오."
L["That's for you, {name}. I fight from a little way back. The view is better."] = "그대 몫이오, {name}. 난 좀 뒤에서 싸우오. 전망이 더 좋거든."
L["Take this, {name}, and leave their spellcasters to me. Their technique offends."] = "이걸 받고, {name}, 놈들 주문시전자는 내게 맡기시오. 기술이 거슬리오."
L["Hold the line, {name}, with this. I'll be the bright thing over your shoulder."] = "이걸 지니고 전열을 지키시오, {name}. 난 그대 어깨 너머의 밝은 것이 되겠소."
L["Take this, {name}. Dragons fight in three dimensions; enemies rarely look up."] = "이걸 받으시오, {name}. 용은 삼차원으로 싸우오. 적들은 위를 잘 안 보지."
L["I've made you all a little more than you were, {name}. The rest is up to you."] = "그대들 모두를 조금 더 나은 존재로 만들었소, {name}. 나머진 그대들 몫이오."
L["Here, {name}. If I take a long breath, do not startle me. It is still growing."] = "받으시오, {name}. 내가 숨을 길게 들이쉬면 놀라게 하지 마시오. 아직 커지는 중이오."
L["Fight well with this, {name}. I am taking notes on how mortals do it. Loudly."] = "이걸로 잘 싸우시오, {name}. 필멸자들이 어떻게 싸우나 적는 중이오. 지금까진 시끄럽게."
L["Time is on our side, {name}. I have checked with it, and borrowed some for you."] = "시간은 우리 편이오, {name}. 직접 확인했고, 그대 몫으로 좀 빌려 왔소."
L["Take this, {name}, and try to keep up. Not showing off; flying is just quicker."] = "이걸 받고 따라오시오, {name}. 자랑이 아니라, 나는 게 그냥 더 빠르오."
L["Rain, fire and a rockslide this week, {name}. That was the first gentle thing."] = "이번 주엔 비, 불, 산사태까지 겪었소, {name}. 이게 처음 받은 다정함이오."
L["The fifth element is spirit, {name}, and yours is a generous one. Thank you."] = "다섯 번째 원소는 영혼이라오, {name}. 그대 영혼은 참 너그럽구려. 고맙소."
L["Thank you, {name}. The rain can wash everything off me today but that."] = "고맙소, {name}. 오늘 비가 다 씻어 가도 이건 못 씻어 갈 거요."
L["Earth is patient and fire is not, {name}. My thanks takes after fire."] = "대지는 참을성이 있고 불은 없소, {name}. 내 감사는 불을 닮았소."
L["Most days I speak for the elements, {name}. Today's thanks are my own."] = "대개는 정령을 대신해 말하오, {name}. 오늘 감사는 내 몫이오."
L["Thank you, {name}. The elements answer need, not rank. So, it seems, do you."] = "고맙소, {name}. 정령은 계급이 아니라 필요에 응하오. 그대도 그런 듯하구려."
L["The Earthen Ring mends the world a crack at a time, {name}. You've mended one."] = "대지 고리회는 세상을 한 틈씩 메우오, {name}. 그대가 하나 메웠소."
L["Water carves canyons by never giving up, {name}. I'll repay you the same way."] = "물은 포기를 몰라서 협곡을 깎소, {name}. 나도 그렇게 갚겠소."
L["Lightning is quick, {name}, but never thoughtful. You were both. Thank you."] = "번개는 빠르지만 사려 깊진 않소, {name}. 그대는 둘 다였소. 고맙소."
L["Thank you, {name}. The ground felt steadier under me for that."] = "고맙소, {name}. 덕분에 발밑 땅이 더 든든해졌소."
L["Of course, {name}. I'll ask the sky. It rarely says no to me."] = "물론이오, {name}. 하늘에 청해 보겠소. 내겐 거절을 잘 안 하오."
L["Feet on the earth, eyes on the sky, {name}. What you asked for, they give."] = "발은 땅에, 눈은 하늘에, {name}. 그대가 청한 것을 그들이 내리오."
L["Gladly, {name}. Thunder takes a moment to arrive. I don't."] = "기꺼이, {name}. 천둥은 좀 늦게 오지만 난 안 그렇소."
L["Gladly, {name}. A shaman who won't share the storm has no business calling it."] = "기꺼이, {name}. 폭풍을 나누지 않을 주술사라면 부를 자격도 없소."
L["Of course, {name}. Lightning can be gentle. It just prefers not to be."] = "물론이오, {name}. 번개도 순할 수 있소. 그러기 싫어할 뿐이지."
L["Of course, {name}. Let me apologise to the wind for borrowing it. There."] = "물론이오, {name}. 바람을 빌려 쓰니 사과부터 하고. 됐소."
L["Gladly, {name}. Calling the wind is easy. Steering it is the trick."] = "기꺼이, {name}. 바람을 부르기는 쉽소. 모는 게 어렵지."
L["We serve the elements and they serve the world, {name}. You're in it."] = "우린 정령을 섬기고 정령은 세상을 섬기오, {name}. 그대도 세상에 있잖소."
L["Gladly, {name}. Mind your hair; the air gets lively."] = "기꺼이, {name}. 머리 조심하시오. 공기가 좀 들썩일 거요."
L["Of course, {name}. You'll smell of rain for an hour. Everyone I help does."] = "물론이오, {name}. 한 시간쯤 비 냄새가 날 거요. 내가 도운 이는 다 그렇소."
L["The sky has a little fury to spare, {name}. Take some."] = "하늘에 격노가 좀 남아도오, {name}. 좀 가져가시오."
L["Take this, {name}. The storm doesn't know you yet, but I've introduced you."] = "받으시오, {name}. 폭풍은 아직 그대를 모르지만, 내가 소개해 뒀소."
L["A storm at your back for once, {name}, instead of in your face."] = "웬일로 폭풍이 그대 등을 밀어 주는구려, {name}. 얼굴을 때리는 대신."
L["Here, {name}. I don't hand storms to just anyone. You've the shoulders for it."] = "여기, {name}. 폭풍은 아무한테나 안 주오. 그대는 감당할 어깨가 있구려."
L["Rain for the crops, storm for the fight, {name}. You look more like a fight."] = "농사엔 비, 싸움엔 폭풍, {name}. 그대는 싸움 쪽 얼굴이오."
L["Here, {name}. If you hear thunder later, it isn't weather. It's encouragement."] = "여기, {name}. 이따 천둥이 들리면 날씨가 아니오. 응원이오."
L["From four elements and one shaman, {name}. The shaman did the walking."] = "네 정령과 주술사 하나가 보낸 거요, {name}. 걸어온 건 주술사고."
L["Walk well with this, {name}. The earth holds up everybody, but it likes you."] = "이걸 지니고 잘 가시오, {name}. 대지는 모두를 받치지만, 그대를 좋아하오."
L["I'd give you fair weather, {name}, but the sky only lends me the stormy kind."] = "맑은 날씨를 드리고 싶지만, {name}, 하늘이 내게 빌려주는 건 궂은 날씨뿐이오."
L["Here, {name}. Thank the next clean stream you drink from. It's listening."] = "여기, {name}. 다음에 맑은 시냇물을 마시거든 고맙다 하시오. 듣고 있으니."
L["Take this, {name}. If I fall, wait. The spirits sometimes send me back."] = "이걸 받으시오, {name}. 내가 쓰러지면 기다리시오. 영혼들이 가끔 돌려보내 주오."
L["Earth below, sky above, {name}, us between, and this on you. Keep that order."] = "아래엔 땅, 위엔 하늘, {name}, 그 사이에 우리, 그리고 그대에겐 이것. 그 순서를 지킵시다."
L["Take this, {name}. If I call up an elemental, be polite. They hold grudges."] = "이걸 받으시오, {name}. 내가 정령을 부르면 공손하시오. 뒤끝이 길거든."
L["That's for you, {name}. Let them bunch together. Lightning loves a crowd."] = "그대 몫이오, {name}. 놈들이 뭉치게 두시오. 번개는 무리를 좋아하오."
L["This is a taste, {name}. When I call the storm into your blood, you'll know it."] = "이건 맛보기요, {name}. 내가 그대 피에 폭풍을 부르면, 알게 될 거요."
L["The wind picked our side today, {name}, and asked me to give you this."] = "오늘은 바람이 우리 편이오, {name}. 그대에게 이걸 주라 하더군."
L["The elements favour the polite, {name}, and gave you this. Thank the rain."] = "정령은 공손한 이를 좋아하오, {name}. 그래서 이걸 줬소. 비에게 감사하시오."
L["Take this, {name}. We're a small storm. Small storms still knock down fences."] = "이걸 받으시오, {name}. 우린 작은 폭풍이오. 작은 폭풍도 울타리는 쓰러뜨리지."
L["That's from me, {name}, not the totems. Don't kick them. The fire one sulks."] = "이건 내가 주는 거요, {name}, 토템이 아니라. 차지 마시오. 불 토템이 삐치니까."
L["Take this, {name}. A river in the way? Don't go round. I'll have us walk on it."] = "이걸 받으시오, {name}. 강이 가로막는다고? 돌아가지 마시오. 그 위를 걷게 해 주지."
L["A sharper mind for you, {name}. Mine cost me an eyebrow in Dalaran."] = "더 예리한 머리를 드리오, {name}. 난 달라란에서 눈썹 한쪽을 대가로 치렀소."
L["A clearer head for you, {name}. What you fill it with is your own affair."] = "머리를 맑게 해 드렸소, {name}. 뭘 채울지는 그대 마음이오."
L["Thoughts humming, {name}? Normal. If they hum back, come and find me."] = "머릿속이 웅웅거리오, {name}? 정상이오. 생각이 말대꾸하면 날 찾아오시오."
L["A little arcane for your thoughts, {name}. Keep the change."] = "그대 생각에 비전 한 스푼, {name}. 거스름돈은 넣어 두시오."
L["Brilliance, bottled, {name}. The Kirin Tor would charge you for the bottle."] = "총명함을 병에 담았소, {name}. 키린 토라면 병값까지 받았을 거요."
L["Sharper wits, {name}. Spend them on spells, locks or riddles; I won't judge."] = "머리가 좋아졌소, {name}. 주문에 쓰든 자물쇠든 수수께끼든, 참견 않겠소."
L["On loan from the Violet Citadel, {name}. Late returns are fined in sheep."] = "보랏빛 성채 대출품이오, {name}. 연체하면 양이 되오."
L["Clever enough to spot the trap now, {name}. Avoiding it is a separate spell."] = "이제 함정은 알아볼 만큼 똑똑해졌소, {name}. 피하는 건 다른 주문이오."
L["There, {name}. Wiser already: look, you're standing further from me."] = "됐소, {name}. 벌써 현명해졌군. 보시오, 나한테서 멀찍이 서 있잖소."
L["The one spell of mine that's never set anything alight, {name}. Enjoy."] = "내 주문 중 뭘 태워 먹은 적 없는 건 이거 하나요, {name}. 즐기시오."
L["A gnome's instructions make sense now, {name}. Still don't follow them."] = "이제 노움 설명서도 이해될 거요, {name}. 그래도 따라 하진 마시오."
L["Fortitude, {name}: a priest's polite way of saying 'stand in front'."] = "인내란, {name}, '앞에 서시오'를 사제가 공손하게 하는 말이오."
L["Every bit of stamina is one less panicked prayer from me, {name}."] = "체력이 늘 때마다 내 다급한 기도가 하나씩 준다오, {name}."
L["Tougher already, {name}. Please don't take that as a dare."] = "벌써 튼튼해졌소, {name}. 그렇다고 시험해 보진 마시오."
L["There are other Power Words, {name}. 'Shield', and in emergencies, 'Run'."] = "신의 권능은 더 있소, {name}. '보호막', 급할 땐 '튀어'."
L["Sturdier now, {name}. Falls, bears and bad decisions all hurt a bit less."] = "더 단단해졌소, {name}. 낙하도, 곰도, 잘못된 선택도 덜 아플 거요."
L["{buff}, {name}. Three words where 'be tougher' would do."] = "{buff}, {name}. '버텨' 두 글자면 될 걸 참 길게도 부르오."
L["A little more of you to go round, {name}. Spend it slowly."] = "그대가 조금 더 늘었소, {name}. 아껴 쓰시오."
L["Harder to knock down now, {name}. The ground will miss you."] = "이제 쉽게 안 쓰러질 거요, {name}. 땅바닥이 그대를 그리워하겠구려."
L["Stubbornness, really, {name}. Dwarves are born with it; the rest of us pray."] = "사실은 고집이오, {name}. 드워프는 타고나고, 우린 기도로 얻소."
L["The only armour that never needs repairing, {name}. The smiths hate it."] = "수리비 안 드는 유일한 갑옷이오, {name}. 대장장이들이 질색하오."
L["Consider your spirits lifted, {name}. Divinely, as it happens."] = "정신 번쩍 들게 해 드렸소, {name}. 천상의 방식으로."
L["Like a good night's sleep, {name}, without all the lying down."] = "푹 자고 난 것 같을 거요, {name}. 누울 필요도 없이."
L["A second helping of spirit, {name}. The Light always insists on seconds."] = "정신 한 그릇 더, {name}. 빛은 할머니처럼 늘 더 먹으라 하오."
L["Keep your spirit where it is, {name}. Loose ones wander off."] = "영혼은 제자리에 두시오, {name}. 풀린 영혼은 떠돌아다니오."
L["Cheer up, {name}. That's not advice this time; it's a spell."] = "기운 내시오, {name}. 이번엔 충고가 아니라 주문이오."
L["Recover faster, {name}, from long fights and longer walks."] = "더 빨리 회복하시오, {name}. 긴 싸움에서도, 더 긴 행군에서도."
L["A deep breath's worth of calm, {name}, without having to take one."] = "심호흡 한 번 한 만큼 차분해지오, {name}. 심호흡은 생략하고."
L["The Light's own second wind, {name}. Don't waste it on arguments."] = "빛이 불어넣는 새 기운이오, {name}. 말싸움에 낭비하진 마시오."
L["Proof against shadow, {name}. I know its tricks; I've borrowed a few."] = "암흑을 막아 줄 거요, {name}. 수법은 잘 아오. 몇 개 빌려 써 봤으니."
L["Should the Void call, {name}, you can now pretend you're out."] = "공허가 부르거든, {name}, 이제 부재중인 척하면 되오."
L["For when the dark gets personal, {name}. It usually does."] = "어둠이 사적으로 덤빌 때를 위해서요, {name}. 대개 그렇게 덤비오."
L["The shadows will have to knock first now, {name}."] = "이제 그림자도 노크부터 해야 할 거요, {name}."
L["The dark still bites, {name}, but now it has to chew."] = "어둠이 여전히 물긴 하오, {name}. 이젠 꼭꼭 씹어야 하지만."
L["A lining against the dark, {name}. Like a cloak, only on the inside."] = "어둠을 막는 안감이오, {name}. 망토인데 안쪽에 입는 거지."
L["Curses slide right off you now, {name}. The cultists will take it personally."] = "이제 저주가 미끄러져 나갈 거요, {name}. 광신도들이 서운해하겠구려."
L["Priests study the Shadow to guard against it, {name}. Mostly."] = "사제가 암흑을 공부하는 건 막기 위해서요, {name}. 대체로는."
L["For crypts, cults and Scholomance, {name}. The dark gets chatty in all three."] = "지하묘지, 광신도, 스칼로맨스용이오, {name}. 셋 다 어둠이 수다스럽지."
L["It won't keep off gloom, {name}. For that you want company. Here I am."] = "우울함까진 못 막소, {name}. 그건 말동무가 있어야지. 여기 있잖소."
L["Marked by the wild, {name}. The deer will tip their antlers as you pass."] = "야생의 징표요, {name}. 지나가면 사슴들이 뿔을 까딱여 인사할 거요."
L["You may smell faintly of moss, {name}. That's how you know it's working."] = "이끼 냄새가 살짝 날 거요, {name}. 효과가 있다는 증거지."
L["Mark of the Wild, {name}. The wolves will still bite, but they'll feel bad."] = "야생의 징표요, {name}. 늑대가 물긴 하겠지만 미안해할 거요."
L["The wild's own seal of approval, {name}. The squirrels were consulted."] = "야생이 보증하는 도장이오, {name}. 다람쥐들과도 협의했소."
L["A little of the wild in you now, {name}. Resist the urge to howl."] = "이제 그대 안에 야생이 좀 깃들었소, {name}. 울부짖고 싶어도 참으시오."
L["Hide, claw and a thick coat, {name}. The wild packs light but thorough."] = "질긴 가죽, 날카로운 발톱, 두툼한 털. 야생은 짐을 가볍고 꼼꼼히 싸오, {name}."
L["Cenarius signs every one of these, {name}. Well, a tree does, on his behalf."] = "하나하나 세나리우스가 서명한 거요, {name}. 뭐, 나무가 대필했지만."
L["The forest's own armour, {name}. It doesn't clank, and it smells of rain."] = "숲이 지은 갑옷이오, {name}. 철컹대지 않고 비 냄새가 나오."
L["A tougher hide in seconds, {name}. The oaks took centuries and are furious."] = "몇 초 만에 질긴 가죽이오, {name}. 수백 년 걸린 참나무들이 분개하오."
L["It's a loan from the wild, {name}. Try not to bring it back chewed."] = "야생에서 빌린 거요, {name}. 물어뜯긴 채로 돌려주진 마시오."
L["Anything that bites you now gets a mouthful, {name}."] = "이제 그대를 무는 놈은 입안 가득 가시를 머금을 거요, {name}."
L["Let the boar charge, {name}. It'll leave with regrets and splinters."] = "멧돼지더러 돌진하라 하시오, {name}. 후회와 가시를 잔뜩 안고 갈 테니."
L["Like a rose, {name}: lovely to look at, a mistake to grab."] = "장미 같구려, {name}. 보기엔 곱지만 움켜쥐면 큰일 나오."
L["Thorns, {name}. I grew them myself, so do be polite to them."] = "가시요, {name}. 내가 직접 키웠으니 예쁘게 대해 주시오."
L["A hedge you can wear, {name}. Neatly trimmed; I'm not a barbarian."] = "입는 산울타리요, {name}. 단정히 다듬었소. 난 야만인이 아니니."
L["Nature never turns the other cheek, {name}. It grows spikes on it."] = "자연은 다른 뺨을 내밀지 않소, {name}. 거기 가시를 기르지."
L["Raptors learn slowly, {name}. This teaches them one bite at a time."] = "랩터는 배우는 게 느리오, {name}. 이건 한 입씩 가르쳐 주지."
L["Prickly on the outside, {name}. What's inside is your own business."] = "겉은 까칠하게 해 드렸소, {name}. 속은 그대 사정이고."
L["Mind your cloak, {name}. Wool and brambles never did get along."] = "망토 조심하시오, {name}. 양털과 가시덤불은 늘 앙숙이오."
L["Blessing of Kings, {name}. No crown, no throne, no taxes owed."] = "왕의 축복이오, {name}. 왕관도, 옥좌도, 세금도 없소."
L["Long may you reign, {name}. For the next while, anyway."] = "{name} 만세! 효과가 끝날 때까지만."
L["A little more of everything, {name}. Kings never did settle for less."] = "모든 게 조금씩 더, {name}. 왕들은 원래 덜 받는 법이 없었지."
L["A king's blessing, {name}. Worn by better heads than mine, and some worse."] = "왕의 축복이오, {name}. 나보다 나은 머리들이 썼던 거요. 못한 머리도 좀 있었고."
L["Every strength a little higher, {name}. Kings like to hedge their bets."] = "모든 능력치를 조금씩 올렸소, {name}. 왕들은 분산 투자를 좋아하거든."
L["Crown not included, {name}. Everything else is, a little."] = "왕관은 별매요, {name}. 나머진 조금씩 다 들어 있소."
L["All of you, only more so, {name}. Wear it well."] = "그대 전부가 한층 더, {name}. 잘 어울리길."
L["A blessing fit for royalty, {name}. You'll have to do your own waving."] = "왕족에게나 어울릴 축복이오, {name}. 손 흔드는 건 직접 하시오."
L["Stronger, cleverer, hardier, {name}. Kings had advisers for that; you have me."] = "더 세고, 똑똑하고, 튼튼하게, {name}. 왕에겐 신하가, 그대에겐 내가 있소."
L["Royal treatment, {name}, minus the courtiers and the poisoned wine."] = "왕실 대접이오, {name}. 아첨꾼과 독 탄 술은 빼고."
L["Might doesn't make right, {name}, but it does help the argument."] = "힘이 정의는 아니오, {name}. 그래도 주먹은 법보다 가깝지."
L["A firmer swing for you, {name}. The Light loves a good follow-through."] = "휘두르는 힘을 더해 드리오, {name}. 빛은 끝까지 휘두르는 걸 좋아하오."
L["Stronger arms, {name}. Kindly point them at something that deserves it."] = "팔 힘이 세졌소, {name}. 부디 맞을 만한 놈에게만 쓰시오."
L["Blessing of Might, {name}. It'll surprise you. It'll surprise them far more."] = "힘의 축복이오, {name}. 그대도 놀라겠지만, 적은 훨씬 더 놀랄 거요."
L["Swing away, {name}. The Light will take the credit if it goes well."] = "마음껏 휘두르시오, {name}. 잘되면 빛 덕, 못되면 조상 탓이오."
L["Hit harder, {name}. Them, I mean. Not me. Never the paladin."] = "더 세게 치시오, {name}. 적 말이오. 나 말고. 성기사는 절대 아니고."
L["More weight behind every swing, {name}. The Light calls it conviction."] = "휘두를 때마다 힘이 실릴 거요, {name}. 빛은 그걸 신념이라 부르오."
L["Doors, crates and ogres will all give way easier now, {name}."] = "문짝, 궤짝, 오우거 모두 이제 쉽게 넘어갈 거요, {name}."
L["Your weapon will feel lighter, {name}. It isn't. You're just holier."] = "무기가 가벼워진 느낌일 거요, {name}. 아니오. 그대가 거룩해진 거지."
L["The Light's own elbow grease, {name}. Put it somewhere useful."] = "빛이 보태는 팔심이오, {name}. 쓸 데 쓰시오."
L["Wisdom for you, {name}. I kept a little back for myself. Very little."] = "지혜를 드리오, {name}. 내 몫도 조금 남겨 뒀소. 아주 조금."
L["Wisdom for your mana, {name}. The other kind still comes from bad decisions."] = "마나에 지혜를, {name}. 다른 지혜는 여전히 쓴맛을 봐야 생기오."
L["Your mana creeps back on its own now, {name}, like a cat that's forgiven you."] = "이제 마나가 알아서 돌아오오, {name}. 삐졌다 풀린 고양이처럼."
L["Fewer sips between fights, {name}. The innkeepers will be heartbroken."] = "전투 사이에 물 마실 일이 줄 거요, {name}. 여관 주인들이 울겠구려."
L["Drink less, cast more, {name}. The Light's own budget advice."] = "덜 마시고 더 시전하시오, {name}. 빛이 알려 주는 절약 비법이오."
L["Blessing of Wisdom, {name}: the one blessing that pays for itself."] = "지혜의 축복이오, {name}. 본전 뽑는 유일한 축복이지."
L["A steadier well to draw from, {name}. Draw deep."] = "더 마르지 않는 샘이오, {name}. 깊이 길어 쓰시오."
L["Wisdom usually comes with age, {name}. This comes with a paladin. Quicker."] = "지혜는 보통 나이 따라 오오, {name}. 이건 성기사 따라 오지. 더 빨리."
L["May you know when to fight and when to sit down, {name}."] = "싸울 때와 앉아 쉴 때를 알기를, {name}."
L["A wise blessing for a wise choice, {name}: keeping a paladin around."] = "현명한 선택엔 지혜의 축복을, {name}. 성기사를 곁에 둔 선택 말이오."
L["A blessing of quiet, {name}. Monsters will forget whose fault it was."] = "고요의 축복이오, {name}. 괴물들이 누구 탓이었는지 잊을 거요."
L["Blessing of Salvation, {name}. You are now somebody else's problem."] = "구원의 축복이오, {name}. 이제 그대 문제는 남의 문제요."
L["Saved, {name}. Not your soul, mind. Just your hide."] = "구원받았소, {name}. 영혼은 말고, 몸뚱이만."
L["Hit hard, {name}. If anything turns round, look innocent. The Light will."] = "세게 치시오, {name}. 누가 돌아보면 모르는 척. 빛도 그럴 거요."
L["The monsters will find you forgettable now, {name}. Today, that's a compliment."] = "이제 괴물들이 그대를 금세 잊을 거요, {name}. 오늘만은 칭찬이오."
L["Go on, hit it, {name}. It'll blame whoever's wearing the most plate."] = "어서 치시오, {name}. 원망은 판금 제일 많이 입은 자가 듣소."
L["The art of being in the fight, {name}, and out of the argument."] = "싸움엔 끼되 시비엔 안 끼는 기술이오, {name}."
L["The Light's kindest alibi, {name}. Use it often."] = "빛이 서 주는 제일 다정한 알리바이요, {name}. 자주 쓰시오."
L["The Light will find you easier now, {name}. Try not to squint."] = "이제 빛이 그대를 더 쉽게 찾을 거요, {name}. 눈부셔도 찡그리지 마시오."
L["Holy Light lands harder on you now, {name}. Please don't make me prove it."] = "이제 성스러운 빛이 더 잘 들을 거요, {name}. 증명할 일은 없게 해 주시오."
L["You'll heal easier, {name}. The Light appreciates a willing patient."] = "치유가 잘 먹힐 거요, {name}. 빛은 협조적인 환자를 좋아하오."
L["Blessing of Light, {name}. Saving you is simpler now. Not that you'll need it."] = "빛의 축복이오, {name}. 이제 살리기 쉬워졌소. 그럴 일은 없겠지만."
L["The Light knows the way to you now, {name}. Let's keep its visits social."] = "이제 빛이 그대 집을 아오, {name}. 왕진 말고 마실만 오게 합시다."
L["A blessing that makes my job easier, {name}. Generous and lazy all at once."] = "내 일을 덜어 주는 축복이오, {name}. 너그러우면서 게으르기까지."
L["Holy Light fits you better now, {name}, like a well-cut tabard."] = "이제 성스러운 빛이 그대에게 착 붙소, {name}. 맞춤 휘장처럼."
L["Mending you just got cheaper, {name}. Not that I'd ever send a bill."] = "그대 고치는 값이 싸졌소, {name}. 청구서를 보낼 것도 아니지만."
L["Block a blow now, {name}, and the Light hits back for you. It's petty."] = "이제 공격을 막아 내면 빛이 대신 되갚아 주오, {name}. 뒤끝 있는 빛이지."
L["Every blow lands softer now, {name}. Complaints go to the Light."] = "이제 모든 타격이 약해질 거요, {name}. 불만은 빛에게 접수하시오."
L["All the shelter of a temple, {name}, and none of the roof repairs."] = "사원만큼 든든하오, {name}. 지붕 수리비는 없이."
L["Claim sanctuary, {name}. It's easier when you bring your own."] = "성역을 누리시오, {name}. 들고 다니니 훨씬 편하오."
L["Every blow is a little less rude now, {name}. The Light teaches manners."] = "이제 모든 타격이 조금 덜 무례할 거요, {name}. 빛이 예절을 가르치거든."
L["Nobody can evict you from this sanctuary, {name}. I checked the deeds."] = "이 성역에선 아무도 그대를 못 쫓아내오, {name}. 등기부까지 확인했소."
L["An ogre's club lands like a pillow now, {name}. A heavy, angry pillow."] = "이제 오우거 몽둥이도 베개처럼 맞을 거요, {name}. 무겁고 성난 베개."
L["Instructions, {name}: hit things harder. There is no page two."] = "지시 사항이오, {name}. 더 세게 칠 것. 2쪽은 없소."
L["Your sword arm is sorted, {name}. For the rest of you, see a priest."] = "칼 쥔 팔은 해결됐소, {name}. 나머지는 사제한테 가 보시오."
L["Battle Shout, {name}. Not a spell, really. A strongly worded suggestion."] = "전투의 외침이오, {name}. 주문이라기보단 아주 강력한 권유지."
L["RAAAGH! That one was for you, {name}. Everyone else just overheard."] = "으아아아! 이건 그대한테 한 거요, {name}. 다른 이들은 엿들은 거고."
L["Priests pray, mages study, {name}. I clear my throat, and you stand taller."] = "사제는 기도하고, 마법사는 공부하지, {name}. 난 목청을 가다듬고, 넌 더 꼿꼿해지고."
L["Words matter, {name}. Mostly the loud ones. That one was for you."] = "말은 중요하지, {name}. 특히 큰 소리는. 방금 건 너를 위한 거였어."
L["The shout lasts a few minutes, {name}. The ringing in your ears, rather longer."] = "외침은 몇 분 가오, {name}. 귀울림은 좀 더 가고."
L["There were words in that shout once, {name}. They slowed it down."] = "원래 그 외침엔 가사가 있었소, {name}. 느려서 뺐지."
L["A little breath from the damned, {name}. They weren't using it."] = "망자들의 숨을 좀 빌렸소, {name}. 어차피 안 쓰더군."
L["Unending Breath, {name}. The fish will have so many questions."] = "숨이 끝없이 이어질 거요, {name}. 물고기들이 물어볼 게 많겠구려."
L["Stay down as long as you like, {name}. The air's on me."] = "물속에 얼마든지 있으시오, {name}. 숨은 내가 쏘겠소."
L["Swim deep, {name}. If a murloc asks, you're only visiting."] = "깊이 헤엄치시오, {name}. 멀록이 물으면 잠깐 놀러 왔다 하시오."
L["Air from a place where air isn't strictly air, {name}. Breathe it anyway."] = "공기가 딱히 공기가 아닌 곳에서 온 공기요, {name}. 그래도 들이쉬시오."
L["The Vile Reef awaits, {name}. Breathe easy down there; I've seen to it."] = "심해가 기다리오, {name}. 그 아래서 편히 숨 쉬시오. 내가 손써 두었소."
L["Dropped something in a lake, {name}? Now's your chance."] = "호수에 도끼 빠뜨렸소, {name}? 산신령 말고 직접 건지시오."
L["No gills, {name}. I read the small print; gills were extra."] = "아가미는 없소, {name}. 약관 읽어 봤소. 아가미는 유료 옵션이더군."
L["An order, {name}: stay standing. Your bones heard it, even if you didn't."] = "명령이오, {name}. 쓰러지지 말 것. 그대는 못 들었어도 뼈는 들었소."
L["Grit is a habit, {name}. I've lent you a few years of mine."] = "근성은 습관이오, {name}. 내 몇 년 치를 빌려 드렸소."
L["I command, you endure, {name}. The shortest chain of command in any army."] = "내가 명하고 그대는 버티오, {name}. 어느 군대보다 짧은 지휘 체계지."
L["Officers order from the back, {name}. I shout from the front, so you hold on."] = "장교들은 뒤에서 명령하지, {name}. 난 앞에서 외친다. 네가 버티도록."
L["A good shout can hold a line together, {name}. A line of one is easy."] = "좋은 외침은 전열을 붙들어 두오, {name}. 한 사람짜리 전열쯤이야 쉽지."
L["I learned this drilling recruits, {name}. They hated me, and they all lived."] = "신병 훈련하면서 배운 거요, {name}. 다들 날 미워했지만 다 살아남았소."
L["One shout's for hitting, {name}. This one's for being hit and not minding."] = "외침 하나는 때리는 용이오, {name}. 이건 맞고도 개의치 않는 용이고."
L["Most fights go to whoever lasts longest, {name}. Today, that's you."] = "싸움은 대개 오래 버티는 쪽이 이기오, {name}. 오늘은 그대요."
L["This horn once sounded for a worse master, {name}. It much prefers you."] = "이 뿔피리는 한때 더 못된 주인을 위해 울렸소, {name}. 그대를 훨씬 좋아하오."
L["I can't runeforge your weapon, {name}, but the horn comes close."] = "그대 무기에 룬을 벼려 줄 순 없지만, {name}, 뿔피리면 거의 비슷하오."
L["All Northrend's cold in a single note, {name}. Swing while it's still ringing."] = "노스렌드의 냉기를 한 음에 담았소, {name}. 울림이 남았을 때 휘두르시오."
L["I'd play something cheerful, {name}, but this horn only knows the one note."] = "신나는 걸 불어 드리고 싶지만, {name}, 이 뿔피리는 아는 음이 하나뿐이오."
L["Winter took me once, {name}. Now it comes when I call, and it comes for you."] = "겨울이 한때 날 데려갔소, {name}. 이젠 내가 부르면 오지. 그대를 위해서."
L["The Ebon Blade charges when this sounds, {name}. Today you charge with us."] = "이게 울리면 칠흑의 기사단이 돌격하오, {name}. 오늘은 그대도 함께요."
L["Cold enough to wake the dead, {name}. I would know. It'll wake you up, too."] = "죽은 자도 깨울 만큼 차갑소, {name}. 내가 잘 알지. 그대도 깨워 줄 거요."
L["No warm words from me, {name}. Cold ones carry further, and carry strength."] = "내게 따뜻한 말은 없소, {name}. 차가운 말이 더 멀리 가고, 힘도 실어 나르지."
L["Shaohao cast out his doubt and fear, {name}. What he kept, I pass to you."] = "샤오하오는 의심과 두려움을 떨쳐 냈소, {name}. 그가 간직한 걸 그대에게 전하오."
L["Shoulders down and jaw loose, {name}. Now it can settle in properly."] = "어깨 내리고 턱에 힘 빼시오, {name}. 이제 제대로 스며들 거요."
L["An open palm for friends, {name}. The fist is kept for everyone else."] = "벗에겐 펼친 손바닥을, {name}. 주먹은 나머지 모두의 몫이오."
L["I swept temple steps for a year to learn this, {name}. The steps stayed dusty."] = "이걸 배우려고 일 년간 사원 계단을 쓸었소, {name}. 계단은 여전히 먼지투성이였지."
L["Strength, grace and a clear head, {name}: the emperors' gifts. Now yours."] = "힘, 우아함, 맑은 머리, {name}. 황제들의 선물이지. 이제 그대 것이오."
L["A gift from a land that hid in the mists, {name}. Use it out in the open."] = "안개 속에 숨었던 땅의 선물이오, {name}. 탁 트인 데서 쓰시오."
L["Harmony is hard to find, {name}. Hold on to this bit of it."] = "조화는 찾기 어렵소, {name}. 이 한 조각은 꼭 붙드시오."
L["Nothing in it you didn't have already, {name}. I've only woken it up."] = "그대에게 없던 건 하나도 없소, {name}. 난 깨웠을 뿐이오."
L["Strength is better shown than talked about, {name}. So I'll say no more."] = "힘은 말보다 보여 주는 게 낫소, {name}. 그러니 더는 말 않겠소."
L["Strike where the guard is thin, {name}. The Tiger's eyes will show you where."] = "방어가 얇은 곳을 치시오, {name}. 백호의 눈이 어딘지 알려 줄 거요."
L["Xuen never strikes by halves, {name}. Now neither do you."] = "쉬엔은 어설프게 치는 법이 없소, {name}. 이제 그대도 그렇소."
L["You don't get the stripes, {name}. Only the nerve that goes with them."] = "줄무늬는 안 생기오, {name}. 거기 딸린 배짱만 생기지."
L["I trained in Kun-Lai's snow for this, {name}. Your feet stay warm, at least."] = "이걸 위해 쿤라이 봉우리 눈밭에서 수련했소, {name}. 그대 발은 따뜻하겠지만."
L["The Tiger's blessing isn't gentle, {name}, but it's on your side."] = "백호의 축복은 순하지 않소, {name}. 하지만 그대 편이오."
L["Fierce, not angry, {name}. Xuen taught me the difference. Now it's yours."] = "사납되 성내지는 마시오, {name}. 쉬엔께 그 차이를 배웠소. 이제 그대 것이오."
L["Wait, watch, then pounce, {name}. With the tiger's gift, you'll need one try."] = "기다리고, 지켜보고, 덮치시오, {name}. 호랑이의 선물이면 한 번이면 되오."
L["Dark Intent, {name}. A grim name for a kind act. Warlocks name things badly."] = "검은 의도요, {name}. 다정한 일에 음침한 이름이지. 흑마법사는 작명에 소질이 없소."
L["Thank the demon who taught me this, {name}. On second thoughts, don't."] = "이걸 가르쳐 준 악마에게 고마워하시오, {name}. 아니, 다시 생각해 보니 하지 마시오."
L["You'll feel no different, {name}. Your enemies will. That's rather the point."] = "그대는 달라진 걸 못 느낄 거요, {name}. 적들은 느끼지. 그게 요점이오."
L["A little fel, well filtered, {name}. You'll barely smell the sulphur."] = "지옥 마력 조금, 잘 걸러 냈소, {name}. 유황 냄새는 거의 안 날 거요."
L["A spark of the Nether rides with you now, {name}. I've trained it to sit."] = "뒤틀린 황천의 불씨가 이제 그대와 함께하오, {name}. '앉아'는 가르쳐 뒀소."
L["Don't feel guilty about the power, {name}. I've done the guilty part already."] = "그 힘에 죄책감 갖지 마시오, {name}. 죄책감은 내가 이미 다 느꼈소."
L["Darkness suits you, {name}. I mean that kindly."] = "어둠이 잘 어울리는구려, {name}. 좋은 뜻이오."
L["I'd wish you luck, {name}, but warlocks prefer to arrange it."] = "행운을 빌어 주고 싶지만, {name}, 흑마법사는 직접 꾸미는 쪽을 좋아하오."
L["The sky lends you its temper, {name}. Strike once, and the storm follows it in."] = "하늘이 성미를 빌려주오, {name}. 한 번 치면 폭풍이 뒤따라 들이치지."
L["The earth keeps you steady, {name}. Now the sky wants a turn."] = "땅이 그대를 붙들어 주었소, {name}. 이제 하늘이 나설 차례요."
L["The storm rides with you now, {name}. Do warn it before you go indoors."] = "이제 폭풍이 그대와 함께 다니오, {name}. 실내에 들어갈 땐 미리 일러 주시오."
L["If your hair stands on end, {name}, that's the storm agreeing with me."] = "머리카락이 곤두서거든, {name}, 폭풍이 내 말에 맞장구치는 거요."
L["I asked the sky to stand behind you, {name}. It's very tall and easily annoyed."] = "하늘더러 그대 뒤를 봐 달라 했소, {name}. 키가 아주 크고 성질이 급하오."
L["Lightning never strikes twice, they say, {name}. Mine just struck you. Fury."] = "벼락은 두 번 안 친다고들 하오, {name}. 내 벼락은 방금 그대를 쳤소. 격노를."
L["I listen to the wind, {name}. Today it asked me to bless you. Done."] = "난 바람의 말을 듣소, {name}. 오늘은 그대를 축복하라더군. 다 했소."
L["Thunder in your arms, {name}. Let the next fool who blocks your way hear it."] = "그대 팔에 천둥을 실었소, {name}. 다음에 길 막는 바보에게 들려주시오."
L["A few borrowed moments from the bronze, {name}. Nozdormu keeps careful count."] = "청동용군단에게서 빌린 순간 몇 개요, {name}. 노즈도르무가 꼼꼼히 세고 있소."
L["Time won't wait for you, {name}, but for the next while it'll dawdle."] = "시간은 그대를 기다려 주지 않소, {name}. 그래도 당분간은 좀 꾸물댈 거요."
L["Not all help arrives in time, {name}. This kind brings its own."] = "모든 도움이 제시간에 오진 않소, {name}. 이건 시간을 들고 오지."
L["Should you need to slip away, {name}, time will cover for you."] = "슬쩍 빠져나가야 할 때면, {name}, 시간이 그대를 감싸 줄 거요."
L["Bronze magic, {name}. You'll arrive a breath before you're needed."] = "청동용의 마법이오, {name}. 그대가 필요해지기 한 호흡 전에 도착할 거요."
L["Time is a river, {name}. I've found you a quicker current."] = "시간은 강이오, {name}. 그대에게 더 빠른 물살을 찾아 줬소."
L["Time heals all wounds, {name}. I'd rather it helped you dodge them."] = "세월이 약이라지만, {name}, 난 시간이 상처를 피하게 도와줬으면 하오."
L["The bronze say I learned this tomorrow, {name}. I've stopped arguing with them."] = "청동용들 말로는 내가 이걸 내일 배웠다더군, {name}. 따지는 건 그만뒀소."
L["My spare magic is yours now, {name}. Every spell I overcharge spills your way."] = "남는 내 마력은 이제 그대 거요, {name}. 넘치게 건 주문마다 그대 쪽으로 흘러가오."
L["Only one of you gets this, {name}. I chose. Try to look modest about it."] = "이건 딱 한 사람만 받소, {name}. 내가 골랐소. 겸손한 척이라도 하시오."
L["I'd give you my patience as well, {name}, but I've barely enough for me."] = "내 인내심도 드리고 싶지만, {name}, 내 쓸 것도 겨우 있소."
L["We're linked for the hour, {name}. Don't worry, it only runs one way."] = "한 시간 동안 우린 이어져 있소, {name}. 걱정 마시오. 한쪽으로만 흐르니."
L["I've seen how hard you work, {name}. Let me carry a little of it."] = "그대가 얼마나 애쓰는지 봤소, {name}. 조금은 내가 짊어지겠소."
L["My magic runs hot, {name}. By the time it reaches you, it's cooled nicely."] = "내 마력은 뜨겁소, {name}. 그대에게 닿을 즈음엔 알맞게 식어 있을 거요."
L["Cast freely, {name}. Your mana is partly my concern now."] = "마음껏 시전하시오, {name}. 이제 그대 마나는 내 소관이기도 하오."
L["If you run dry, {name}, it means I've been idle. Do say so."] = "그대가 바닥나면, {name}, 내가 놀았다는 뜻이오. 꼭 말해 주시오."
L["The earth stands between you and harm now, {name}. Every blow mends you."] = "{name}, 대지가 그대를 지켜요. 맞을 때마다 낫죠."
L["Stone has your back, {name}. Each hit they land patches you up a little."] = "{name}, 바위가 등을 받쳐요. 맞아도 조금씩 아물죠."
L["The spirits of earth owed me a favour, {name}. I've spent it on you."] = "대지의 정령에게 받을 빚을 {name}에게 썼어요."
L["Hold the line, {name}. The ground itself is holding you."] = "버텨요, {name}. 땅이 직접 붙잡아 줘요."
L["You take the hits, {name}, and the stone takes them personally."] = "{name}, 얻어맞아요. 바위가 대신 화낼 테니."
L["Charge in, {name}. What they break, the earth puts back."] = "{name}, 돌격해요. 부서진 건 대지가 채워요."
L["You're my Beacon, {name}. Every heal I give the others shines on you too."] = "{name}, 그대는 내 봉화예요. 치유가 함께 닿아요."
L["The Light will find you wherever you stand, {name}. I've made sure of it."] = "{name}, 어디 서 있든 빛이 그대를 찾아요."
L["Stand tall, {name}. When I mend the others, you get the echo."] = "{name}, 당당히 서요. 치유의 메아리가 가요."
L["A lighthouse for the whole group, {name}. Try not to stand in the dark."] = "{name}, 모두의 등대예요. 어둠엔 서지 말아요."
L["Wherever I heal, {name}, a little of it reaches you."] = "{name}, 내 치유가 닿는 곳마다 그대에게도 가요."
L["I swear it, {name}: while this oath holds, my Light finds you first."] = "맹세해요, {name}. 내 빛이 그대를 먼저 찾아요."
L["An oath sworn to you alone, {name}. Don't make me regret it."] = "{name}, 그대에게만 바친 맹세예요. 후회시키지 말아요."
L["My word is yours for a while, {name}. Paladins keep their word."] = "{name}, 내 약속은 그대 것이에요. 성기사는 지켜요."
L["I've sworn to keep you standing, {name}. I take oaths seriously."] = "{name}, 그대를 지키기로 맹세했어요. 진심이에요."
L["A little of you, a little of me, {name}. Nature loves a fair trade."] = "{name}, 그대 조금 나 조금. 자연은 공평한 게 좋대요."
L["We're bound for the hour, {name}. Borrow my gifts; I'll borrow yours."] = "{name}, 한 시간 동안 하나예요. 서로 재주를 빌려요."
L["Every living thing leans on another, {name}. Today we lean on each other."] = "{name}, 생명은 서로 기대요. 오늘은 우리가 그래요."
L["Lend me a trick, {name}, and I'll lend you one of mine."] = "{name}, 재주 하나 빌려줘요. 나도 하나 빌려줄게요."
L["The Dream calls this a partnership, {name}. I call it common sense."] = "{name}, 꿈은 동반이라 하고 나는 상식이라 해요."
L["Scales off my own back, {name}. Let them hit you and see what happens."] = "{name}, 내 등에서 뗀 비늘이에요. 맞아 보면 알아요."
L["Wear these, {name}. Anything that bites you will regret its teeth."] = "{name}, 이걸 입어요. 무는 놈은 이빨을 후회해요."
L["Dragonscale armour, freshly shed, {name}. It bites back."] = "{name}, 갓 벗은 용비늘 갑옷이에요. 되물어요."
L["These scales burst when struck, {name}. Do let them strike."] = "{name}, 이 비늘은 맞으면 터져요. 맞게 두세요."
L["A dragon's hide for an hour, {name}. Stand in front and enjoy it."] = "{name}, 한 시간짜리 용가죽이에요. 앞에서 즐겨요."
L["Run at the front of the pack, {name}. The wolf spirit makes them all chase you."] = "{name}, 앞장서요. 늑대 영혼이 적을 전부 끌어올 거예요."
L["Lead the hunt, {name}. Every beast in here will want your throat, not ours."] = "{name}, 사냥을 이끌어요. 짐승들은 다 당신 목을 노려요."
L["The alpha's spirit is yours now, {name}. Howl, and they'll all turn your way."] = "우두머리의 영혼은 이제 당신 거예요, {name}. 울부짖어요."
L["First through the door, {name}. The pack follows, and so does everything else."] = "{name}, 문으로 먼저 들어가요. 무리가 따라가요."
L["My second Beacon, {name}. Whatever I give the others, you share in it too."] = "두 번째 봉화예요, {name}. 내 치유는 당신도 받아요."
L["Two lights to steer by tonight, {name}, and you're one of them."] = "오늘 밤 길잡이 빛은 둘, {name} 당신도 그중 하나예요."
L["The Light has room for two, {name}. Keep shining over there."] = "빛은 둘도 품어요, {name}. 거기서 계속 빛나요."
L["Faith marks you as well, {name}. My heals will find both of you."] = "신앙이 당신도 택했어요, {name}. 치유가 둘 다 찾아가요."
L["We're bonded for the hour, {name}. When I mend myself, you mend too."] = "잠시 하나로 묶였어요, {name}. 내가 나으면 당신도 나아요."
L["Roots in the same soil, {name}. What heals one of us helps the other."] = "같은 흙에 뿌리내렸어요, {name}. 한쪽 치유가 둘을 도와요."
L["A bond of the grove, {name}. Look after yourself and you look after me."] = "숲의 인연이에요, {name}. 자신을 챙기면 나도 챙기는 거예요."
L["Nature pairs us up for a while, {name}. Try not to make me regret it."] = "자연이 우릴 짝지었어요, {name}. 후회하게 하진 말아요."
L["Now you'll see what creeps up on us, {name}. Try not to scream."] = "다가오는 게 보일 거요, {name}. 비명은 참으시오."
L["A warlock's sight, {name}, lent for a while. Some shadows stare back."] = "흑마법사의 눈을 빌려주오, {name}. 마주 보는 그림자도 있소."
L["Eyes open, {name}. Whatever hides near us is about to be found."] = "눈을 뜨시오, {name}. 숨은 것이 곧 드러나오."
L["Folk will think we're duelling, {name}. Thanks for the {gift}."] = "주고받는 걸 보면 결투하는 줄 알겠소, {name}. {gift} 고맙소."
L["{gift} for {buff}. No auctioneer's cut, {name}."] = "{gift} 받고 {buff} 드리오. 경매 수수료는 없소, {name}."
L["Beaten to it, {name}! Your {gift} was quicker than my manners."] = "선수를 뺏겼구려, {name}! 그대의 {gift}, 내 예의보다 빨랐소."
L["{gift} in, {buff} out. Finest economy in all Azeroth."] = "{gift} 들어오고 {buff} 나가고. 아제로스 최고의 경제요."
L["{gift}, for me? All I have is this, {name}, but it's heartfelt."] = "{gift}, 날 위해? 줄 건 이것뿐이오, {name}. 그래도 진심이오."
L["Your {gift} fits perfectly, {name}. Did you measure me?"] = "그대의 {gift}, 몸에 꼭 맞소, {name}. 치수라도 재 갔소?"
L["A treaty in spells, {name}: {gift} for {buff}."] = "주문 조약을 맺읍시다, {name}. {gift} 대 {buff}."
L["{gift}! I feel taller already. Have some {buff}."] = "{gift}! 벌써 키가 큰 기분이오. {buff}도 받으시오."
L["I was about to ask for {gift}, {name}. You read my mind."] = "막 {gift} 부탁하려던 참이오, {name}. 내 마음을 읽었구려."
L["Your {gift} still fizzes, {name}. Here's some fizz back."] = "그대의 {gift}, 아직 톡톡 튀는구려, {name}. 나도 톡 쏘는 걸로 답하리다."
L["Such a kind {gift}, {name}. I'll tell the whole inn. Twice."] = "다정하기도 하지, {name}. 이 {gift} 얘기, 여관에 다 퍼뜨리겠소. 두 번씩."
L["You cast {gift} first, {name}? My mother would despair of me."] = "그대가 먼저 {gift} 시전을? 어머니가 아시면 한숨 쉬시겠소, {name}."
L["I'll remember your {gift} fondly, {name}. Until it wears off."] = "그대의 {gift}, 두고두고 기억하리다, {name}. 효과가 끝날 때까지는."
L["{gift} for {buff}, free. Somewhere, a goblin weeps."] = "{gift} 받고 {buff} 드리오. 공짜로. 어디선가 고블린이 우는구려."
L["Your {gift}, my {buff}. We'll be unbearable now."] = "그대의 {gift}, 나의 {buff}. 이제 우리 못 말리겠구려."
L["Thanks for the {gift}, {name}. I'll earn it before it fades."] = "{gift} 고맙소, {name}. 효과 끝나기 전에 밥값은 하겠소."
L["For {gift} I'd hand you both moons, {name}. This'll have to do."] = "{gift} 보답으론 달 두 개라도 따 드리고 싶소만, {name}. 이걸로 참으시오."
L["You brought {gift}, I brought {buff}. Now it's a party."] = "그대는 {gift}, 나는 {buff}. 이제 제대로 잔치구려."
L["{gift} means 'good luck'. {buff} means 'you too'."] = "{gift}, 그 뜻은 '행운을 비오'. {buff}, 그 뜻은 '그대도'."
L["Your {gift} came first; my {buff} tries twice as hard."] = "그대의 {gift}, 먼저 왔소. 내 {buff}, 두 배로 애쓰리다."
L["If anyone asks, {buff} came before {gift}. Deal?"] = "누가 물으면 {buff} 먼저, {gift} 나중이오. 약조하오?"
L["{gift} made my day; {buff} should make your hour."] = "{gift} 덕에 내 하루가 빛났소. {buff}, 그대 한 시간은 책임지리다."
L["Saved my {buff} for someone worthy. Then came {gift}."] = "자격 있는 이에게 주려고 {buff} 아껴 뒀소. 그런데 {gift} 들고 그대가 왔지."
L["Your {gift} went to my head; my {buff} goes to yours."] = "그대의 {gift}에 취했소. 이번엔 내 {buff}에 취해 보시오."
L["{gift} on me, {buff} on you. We wear each other's work."] = "내겐 {gift}, 그대에겐 {buff}. 서로의 솜씨를 걸치고 다니는구려."
L["{gift} and {buff} fade. Kindness lasts. Well, longer."] = "{gift}도 {buff}도 사라지오. 친절은 남지. 뭐, 좀 더 오래."
L["You shared {gift}; I share {buff}. Ale's next."] = "그대는 {gift}, 나는 {buff}. 다음엔 맥주요."
L["{gift} caught me empty-handed. Not any more: {buff}."] = "{gift} 받을 땐 빈손이었소. 이젠 아니지. 자, {buff}."
L["{gift}, best thing all day. {buff}, my bid for second."] = "{gift}, 오늘 최고의 일이오. {buff}, 2등에 도전하오."
L["{gift} deserves a statue. I'm no sculptor, so: {buff}."] = "{gift}, 동상감이오. 난 조각가가 아니니, 대신 {buff}."
L["{gift} for {buff}? Keep this up and we'll draw a queue."] = "{gift} 받고 {buff} 드리고. 계속 이러면 줄 서겠구려."
L["{gift} was kind. {buff} is kind back, and competitive."] = "{gift}, 친절했소. {buff}, 친절로 답하오. 지기 싫어서."
L["{gift} came like good news. {buff}, by return post."] = "{gift}, 반가운 편지 같았소. {buff}, 빠른우편 답장이오."
L["{gift}, meet {buff}. Do get along, you two."] = "{gift}, 인사하시오. 이쪽은 {buff}. 둘이 사이좋게 지내시오."
L["Trade you {buff} for {gift}? Ah, you've already paid."] = "{gift} 주면 {buff} 드리리다. 아, 이미 냈구려."
L["{gift} and {buff}. The inn will say we rehearsed."] = "{gift}에 {buff}까지. 여관에선 짜고 친 줄 알겠소."
L["{gift}! I just had three clever thoughts, {name}. This was one."] = "{gift}! 방금 똑똑한 생각이 세 개나 났소, {name}. 이게 그중 하나요."
L["With {gift}, {name}, I finally understand my own notes. Thanks."] = "{gift} 덕에, {name}, 드디어 내 메모를 알아보겠소. 고맙소."
L["Cleverer already, {name}. Clever enough to know I owe you one. Here."] = "벌써 똑똑해졌소, {name}. 신세 진 걸 알 만큼은. 여기."
L["Your {gift} found me the word for this, {name}: 'thanks'."] = "그대의 {gift} 덕에 딱 맞는 말을 찾았소, {name}. '고맙소'."
L["{gift}! I understood a goblin contract, {name}. I'm appalled."] = "{gift}! 고블린 계약서가 이해되오, {name}. 경악스럽구려."
L["Thank you, {name}. My thoughts are lining up politely."] = "고맙소, {name}. 생각들이 얌전히 줄을 서는구려."
L["I'll use your {gift} for more than arguing, {name}. Probably."] = "그대의 {gift}, 말싸움 말고도 쓰겠소, {name}. 아마도."
L["Thank you, {name}. My next spell gets three extra syllables, just to show off."] = "고맙소, {name}. 다음 주문엔 괜히 세 음절 더 붙이겠소. 뽐내려고."
L["{gift}, {name}? I'll stand at the front for once. Briefly."] = "{gift}, {name}? 이번만은 앞에 서 보겠소. 잠깐만."
L["Knees, elbows and pride, {name}: all fortified. Thank you."] = "무릎, 팔꿈치, 자존심까지 다 튼튼해졌소, {name}. 고맙소."
L["Hit me now, {name}. Actually, don't. But thank you; I'd survive it."] = "이제 날 쳐 보시오, {name}. 아니, 치진 마시오. 그래도 버틸 거요. 고맙소."
L["Nigh unbreakable now, {name}. Let's never test the 'nigh'. Thank you."] = "이제 거의 안 깨지오, {name}. '거의'는 시험하지 맙시다. 고맙소."
L["{gift}! My healer owes you a letter, {name}. I owe you this."] = "{gift}! 우리 힐러가 감사 편지를 써야겠소, {name}. 난 이걸로 갚고."
L["Every bruise I don't get today, {name}, I owe to your {gift}."] = "오늘 안 드는 멍은 다, {name}, 그대의 {gift} 덕이오."
L["I could lose an argument with an ogre now and live, {name}. Thank you."] = "이젠 오우거랑 말싸움에 져도 살아남겠소, {name}. 고맙소."
L["Thank you, {name}. I feel like a castle wall. A grateful one."] = "고맙소, {name}. 성벽이 된 기분이오. 감사할 줄 아는 성벽."
L["Thank you, {name}. The next boar to charge me is in for a long afternoon."] = "고맙소, {name}. 다음에 날 들이받는 멧돼지는 오후 내내 고생하겠소."
L["{gift}! I feel ten years younger, {name}. Thank you."] = "{gift}! 십 년은 젊어진 기분이오, {name}. 고맙소."
L["I feel twice as calm and half as grumpy, {name}. Thank you."] = "두 배로 차분하고 절반만 투덜대게 됐소, {name}. 고맙소."
L["Your {gift} nearly made me sing, {name}. Take this. It's kinder."] = "그대의 {gift}에 노래할 뻔했소, {name}. 이걸로 대신하오. 그게 자비지."
L["{gift}, {name}? I've forgiven three people already. Thank you."] = "{gift}, {name}? 벌써 세 명이나 용서했소. 고맙소."
L["I was on fumes, {name}. Your {gift} was a hot meal and a hearth."] = "바닥나기 직전이었소, {name}. 그대의 {gift}, 따끈한 밥에 아랫목 같았소."
L["I've stopped counting mana between fights, {name}. Thank you."] = "전투 사이에 마나 셀 일이 없어졌소, {name}. 고맙소."
L["My spirit's topped up, {name}, and the rest of me is grateful too."] = "정신이 가득 찼소, {name}. 나머지 몸도 고마워하오."
L["Shadow-proof, thanks to you, {name}. The whispers are furious."] = "덕분에 암흑이 안 통하오, {name}. 속삭임들이 잔뜩 성났소."
L["Nothing dark gets in now, {name}. Here's something bright going the other way."] = "이제 어둠은 못 들어오오, {name}. 대신 밝은 걸 내보내리다."
L["{gift}! Shadowfang Keep can keep its shadows, {name}. Thank you."] = "{gift}! 그림자송곳니 성채는 그림자나 끼고 살라지, {name}. 고맙소."
L["The next shadow bolt's in for a letdown, {name}. Thank you."] = "다음 어둠의 화살은 실망하겠구려, {name}. 고맙소."
L["On your {gift} I'll brave Duskwood tonight, {name}. Or tomorrow."] = "그대의 {gift} 믿고 오늘 밤 그늘숲에 가 보겠소, {name}. 아니면 내일."
L["{gift}! A squirrel just nodded at me, {name}. Here's yours."] = "{gift}! 방금 다람쥐가 내게 고개를 까딱했소, {name}. 이건 그대 몫이오."
L["Tougher hide, sharper senses, {name}. I may have to fight the urge to forage."] = "가죽은 질기고 감각은 예리해졌소, {name}. 도토리 줍고 싶은 걸 참아야겠구려."
L["I feel all wild and leafy, {name}. Thank you. Sorry if I shed bark."] = "온몸에 잎이 돋는 기분이오, {name}. 고맙소. 나무껍질 떨어지면 미안하오."
L["Thicker skin from your {gift}, {name}. Arrows and insults both."] = "그대의 {gift} 덕에 낯가죽이 두꺼워졌소, {name}. 화살도 욕도 끄떡없소."
L["{gift}! A bird tried to nest on me, {name}. Thanks, I think."] = "{gift}! 새가 내 머리에 둥지를 틀려 했소, {name}. 고마운 거겠지?"
L["Thanks for the {gift}, {name}. The woods feel like home now."] = "{gift} 고맙소, {name}. 이제 숲이 집처럼 느껴지오."
L["Thank you, {name}. I've an urge to stand in the rain and grow. I'll resist."] = "고맙소, {name}. 빗속에 서서 자라고 싶소. 참겠지만."
L["Every bramble in the Barrens will think twice now, {name}. Thank you."] = "이제 불모의 땅 가시덤불도 날 보면 망설이겠소, {name}. 고맙소."
L["Thank you, {name}. Rain, cold and wolves: let them all try."] = "고맙소, {name}. 비든 추위든 늑대든, 덤벼 보라지."
L["{gift}, {name}! Nobody's hugging me today. Have this instead."] = "{gift}, {name}! 오늘은 아무도 날 못 안겠구려. 대신 이거라도."
L["Prickly now, thanks to you, {name}. More than usual, I mean."] = "덕분에 가시가 돋쳤소, {name}. 평소엔 말에만 있었는데."
L["Your {gift}, {name}! Let the next kobold try for my candle."] = "그대의 {gift}, {name}! 다음 코볼트, 내 양초에 손대 보라지."
L["{gift}! I'm a thicket with opinions now, {name}. Thank you."] = "{gift}! 이제 난 할 말 많은 덤불이오, {name}. 고맙소."
L["Thank you, {name}. The next thing that bites me will need a moment to reflect."] = "고맙소, {name}. 날 무는 놈은 반사당하고 반성하겠구려."
L["{gift} from you, {name}? I'll try not to found a dynasty."] = "{gift}, 그대가 주는 거요, {name}? 왕조는 안 세우도록 조심하리다."
L["A little better at everything, {name}. Is this how kings feel? No wonder."] = "모든 게 조금씩 나아졌소, {name}. 왕들은 이런 기분이었구려. 어쩐지."
L["Your {gift}! My first decree, {name}: thank you."] = "그대의 {gift}! 첫 칙령이오, {name}. '고맙소.'"
L["{gift} on a commoner, {name}? I'll try to look regal."] = "평민에게 {gift}, {name}? 위엄 있어 보이도록 애써 보겠소."
L["With your {gift} I could rule a small kingdom, {name}. Westfall."] = "그대의 {gift} 덕에 작은 왕국 하나는 다스리겠소, {name}. 서부 몰락지대쯤."
L["Thank you, {name}. Every bit of me is grateful, and they rarely agree."] = "고맙소, {name}. 온몸 구석구석이 고마워하오. 웬일로 의견이 맞는구려."
L["Stronger arms already, {name}. I'll try not to hug anyone. Thank you."] = "벌써 팔 힘이 세졌소, {name}. 아무도 안 안도록 조심하리다. 고맙소."
L["With {gift} I could lift a kodo, {name}. I won't, but thank you."] = "{gift} 덕에 코도도 들겠소, {name}. 안 들겠지만, 고맙소."
L["Your {gift} has my arms very confident, {name}. Thank you."] = "그대의 {gift}에 내 팔이 아주 기고만장하오, {name}. 고맙소."
L["{gift}! Opened a jar I've fought since Stranglethorn, {name}."] = "{gift}! 가시덤불 골짜기 때부터 씨름한 병뚜껑을 땄소, {name}."
L["Thank you, {name}. My next swing is dedicated to you. So is the dent."] = "고맙소, {name}. 다음 일격은 그대에게 바치오. 찌그러진 자국까지."
L["{gift} from you, {name}, and my first wise act is this."] = "그대의 {gift}, 고맙소, {name}. 지혜로워진 내 첫 행동이 바로 이거요."
L["Wiser already, {name}. Wise enough to know a kindness when I see one."] = "벌써 지혜로워졌소, {name}. 친절을 알아볼 만큼은."
L["My mana thanks you for {gift}, {name}. It's the shy one of us."] = "내 마나가 {gift} 고맙다 하오, {name}. 우리 중 제일 수줍은 녀석이라."
L["Your {gift} refills me faster than I spend, {name}. Nearly."] = "그대의 {gift}, 쓰는 것보다 빨리 채워 주오, {name}. 거의."
L["Your {gift}, {name}: mana back, and an urge to give advice."] = "그대의 {gift}, {name}. 마나는 돌아오고, 훈수 두고 싶어지오."
L["{gift}! The monsters forgot me at once, {name}. I won't."] = "{gift}! 괴물들은 날 바로 잊었소, {name}. 난 안 잊겠지만."
L["Nothing wants to fight me now, {name}. It's lovely. Thank you."] = "이제 아무도 나랑 안 싸우려 하오, {name}. 참 좋구려. 고맙소."
L["{gift}! Nothing's glared at me in minutes, {name}. Thank you."] = "{gift}! 몇 분째 아무도 날 안 노려보오, {name}. 고맙소."
L["{gift}! A mouse at a dragon's feast, {name}: unseen, well fed."] = "{gift}! 용의 잔칫상 밑 생쥐 꼴이오, {name}. 안 들키고 배부르지."
L["Thanks to {gift} I'm just a rumour in a fight, {name}."] = "{gift} 덕에 전투에선 그저 소문일 뿐이오, {name}."
L["The Light finds me easier now, {name}. I'll try to deserve it."] = "이제 빛이 날 더 쉽게 찾소, {name}. 그럴 자격이 있도록 애쓰리다."
L["Easier to heal now, {name}. Whoever patches me up thanks you too."] = "이제 치유가 잘 먹히오, {name}. 날 고쳐 줄 이도 고마워할 거요."
L["With your {gift}, {name}, mending feels like coming home."] = "그대의 {gift} 덕에, {name}, 치유받을 때마다 집에 온 기분이오."
L["{gift}! The Light and I are on first-name terms now, {name}."] = "{gift}! 이제 빛하고 말 놓는 사이요, {name}."
L["With {gift} the Light hears me first, {name}. No need to shout."] = "{gift} 덕에 빛이 내 말부터 듣소, {name}. 소리칠 필요도 없지."
L["Blows land softer on me now, {name}. My bruises thank you, and so do I."] = "이제 맞아도 덜 아프오, {name}. 멍들도 고맙다 하고, 나도 고맙소."
L["Every hit gentler, thanks to you, {name}. I'll make sure they notice."] = "덕분에 타격이 한결 부드럽소, {name}. 놈들도 알아채게 해 주리다."
L["Your {gift} softens every blow, {name}. I'm upholstered."] = "그대의 {gift}에 모든 타격이 푹신하오, {name}. 온몸을 솜으로 누볐소."
L["{gift}! Now the Light takes every hit personally, {name}."] = "{gift}! 이제 날 치면 빛이 제 일처럼 발끈하오, {name}."
L["With your {gift} I'm half fortress, half chapel, {name}."] = "그대의 {gift} 덕에 반은 요새, 반은 예배당이 됐소, {name}."
L["You shouted at me, {name}, and I've never felt so encouraged. Here."] = "그대가 내게 소리쳤는데, {name}, 이렇게 힘이 난 적은 처음이오. 여기."
L["My ears are ringing, {name}, and my arms feel twice as strong. Thank you!"] = "귀는 멍멍하고 팔 힘은 두 배요, {name}. 고맙소!"
L["{gift}, {name}! I felt that in my teeth. In a good way."] = "{gift}, {name}! 이가 다 울렸소. 좋은 쪽으로."
L["I'll answer your {gift} quietly, {name}. Somebody should."] = "그대의 {gift}엔 조용히 답하리다, {name}. 누군가는 그래야지."
L["Your {gift} nearly had me charging a wall, {name}. Here, calmly."] = "그대의 {gift}에 벽으로 돌진할 뻔했소, {name}. 자, 차분하게."
L["All Azeroth heard your {gift}, {name}. Thank you for my share."] = "그대의 {gift}, 아제로스가 다 들었소, {name}. 내 몫도 고맙소."
L["That shout put iron in my spine, {name}. Thank you."] = "그 외침에 등뼈가 강철처럼 곧아졌소, {name}. 고맙소."
L["I didn't catch the words, {name}, but my arms did. Thank you!"] = "무슨 말인지 못 알아들었소, {name}. 팔은 알아들었지만. 고맙소!"
L["Thank you, {name}. I'll hit the next thing twice as hard and blame you."] = "고맙소, {name}. 다음 놈은 두 배로 세게 치고 그대 탓을 하겠소."
L["I can breathe underwater, {name}! I may never need to, but thank you."] = "물속에서 숨을 쉴 수 있소, {name}! 쓸 일은 없을지 몰라도, 고맙소."
L["Lungs like a murloc, thanks to you, {name}. I'll try not to gurgle."] = "덕분에 폐활량이 멀록급이오, {name}. 꾸르륵대지 않게 조심하리다."
L["With {gift} I'll raid every sunken wreck, {name}. Half's yours."] = "{gift} 덕에 가라앉은 난파선을 다 털겠소, {name}. 반은 그대 몫이오."
L["I won't ask where {gift} gets its air, {name}. Just: thanks."] = "{gift}, 그 공기가 어디서 오는지는 안 묻겠소, {name}. 그냥, 고맙소."
L["With {gift} I'll cross Lordamere Lake, {name}. Underneath."] = "{gift} 덕에 로다미어 호수를 건너겠소, {name}. 물밑으로."
L["If I fall, {name}, I'll be back to thank you properly."] = "내가 쓰러지면, {name}, 돌아와서 제대로 감사하리다."
L["A spare life in my pocket, {name}. I'll try not to spend it. Thank you."] = "주머니에 목숨 하나가 더 생겼소, {name}. 쓰지 않도록 애써 보리다. 고맙소."
L["Thank you, {name}. Death can knock now; I've a key to the back door."] = "고맙소, {name}. 죽음이 문을 두드려도 괜찮소. 뒷문 열쇠가 있으니."
L["Dying's only a delay with your {gift}, {name}. Thank you."] = "{gift} 덕에 죽음도 잠깐 미뤄질 뿐이오, {name}. 고맙소."
L["Thank you, {name}. If the worst happens, I'll get up and say it twice."] = "고맙소, {name}. 최악의 일이 생겨도 일어나서 두 번 감사하리다."
L["Let the next thing roar at me, {name}. I'm not running this time. Thank you."] = "다음 녀석이 포효해도 좋소, {name}. 이번엔 도망치지 않으리다. 고맙소."
L["{gift}! One fright, already dealt with, {name}. Thank you."] = "{gift}! 공포 하나는 미리 해결됐구려, {name}. 고맙소."
L["Thank you, {name}. The next scream I hear won't be mine."] = "고맙소, {name}. 다음에 들릴 비명은 내 것이 아닐 거요."
L["No running in circles for me, {name}. Not the first time, anyway. Thank you."] = "빙글빙글 도망칠 일은 없겠소, {name}. 적어도 처음엔. 고맙소."
L["Brave on credit, thanks to you, {name}. I'll spend it wisely."] = "외상으로 얻은 용기요, {name}. 현명하게 쓰리다."
L["Thank you, {name}. Lakes, rivers, puddles: all floors now."] = "고맙소, {name}. 호수, 강, 웅덩이: 이제 다 바닥이오."
L["{gift}! The short way across it is, {name}. Dry boots and all."] = "{gift}! 그럼 곧장 건너가겠소, {name}. 장화도 젖지 않고."
L["Walking on water, {name}. Folk will start a religion. Thank you."] = "물 위를 걷다니, {name}. 누가 종교라도 세우겠소. 고맙소."
L["The murlocs will be furious, {name}. Thank you for the shortcut."] = "멀록들이 길길이 뛰겠구려, {name}. 지름길 고맙소."
L["Thank you, {name}. I'll be across before it fades. Probably."] = "고맙소, {name}. 풀리기 전에 건너편에 닿을 거요. 아마도."
L["{gift}! Whatever hid round here, {name}, hides no more."] = "{gift}! 여기 숨어 있던 것들, {name}, 이제 다 보이오."
L["I can see what's hiding now, {name}. Some of it should stay hidden. Thanks."] = "이제 숨은 게 보이오, {name}. 어떤 건 계속 숨어 있는 게 나았겠소. 고맙소."
L["Thank you, {name}. Every lurker around just lost their only trick."] = "고맙소, {name}. 숨어 있던 녀석들이 유일한 재주를 잃었구려."
L["Thank you, {name}. Now I can see what your imp gets up to."] = "고맙소, {name}. 이제 그대 임프가 뭘 하는지 보이오."
L["My eyes see more than my wits can handle, {name}. Thank you."] = "내 눈이 머리가 감당할 수 있는 것보다 더 많이 보오, {name}. 고맙소."
L["I'll be the last one standing, {name}, just to hear you shout again."] = "끝까지 서 있겠소, {name}. 그대 외침을 또 들으려고라도."
L["You ordered me to live, {name}. I mean to follow it to the letter. Thanks."] = "그대가 살라고 명했소, {name}. 토씨 하나 안 틀리고 따르겠소. 고맙소."
L["Thank you, {name}. Every sinew I have just closed ranks."] = "고맙소, {name}. 내 힘줄이 모조리 대열을 맞췄소."
L["Never been shouted into good health before, {name}. Thank you."] = "고함 듣고 건강해진 건 처음이오, {name}. 고맙소."
L["Yes, Sergeant {name}! Your shout brings out the recruit in me. Thank you."] = "예, {name} 하사님! 그 외침에 신병 시절이 되살아나오. 고맙소."
L["{gift}! That voice could turn a stampede, {name}. Thanks."] = "{gift}! 그 목소리면 짐승 떼의 질주도 돌려세우겠소, {name}. 고맙소."
L["That horn froze my breath and fired my arms, {name}. Thank you."] = "그 뿔피리에 숨은 얼고 팔엔 불이 붙었소, {name}. 고맙소."
L["Most folk hear that horn from the wrong end of a battle, {name}. Thank you."] = "그 뿔피리를 적으로서 듣는 이가 대부분이오, {name}. 고맙소."
L["I heard your horn and swung harder, {name}. Nobody had to tell me twice."] = "그대 뿔피리를 듣고 더 세게 휘둘렀소, {name}. 두 번 말할 필요도 없었지."
L["Thank you, {name}. I'll be humming that note for the rest of the day."] = "고맙소, {name}. 오늘 종일 그 음을 흥얼거리겠구려."
L["Thanks to you, {name}, I'll never grumble about winter again."] = "그대 덕에, {name}, 다시는 겨울 불평 안 하겠소."
L["{gift}! I won't ask what the horn's made of, {name}. Thank you."] = "{gift}! 그 뿔피리가 뭘로 만든 건지는 안 묻겠소, {name}. 고맙소."
L["An emperor's legacy, {name}. I'll try to leave it no worse than I found it."] = "황제의 유산이라, {name}. 받았을 때보다 나빠지지 않게 하겠소."
L["Like a month of training before breakfast, {name}. Thank you."] = "아침 먹기 전에 한 달 치 수련을 한 기분이오, {name}. 고맙소."
L["Thank you, {name}. I feel calm enough to brew tea in a thunderstorm."] = "고맙소, {name}. 천둥번개 속에서도 차를 우릴 만큼 마음이 고요하오."
L["Thank you, {name}. I bowed without thinking. Is that part of it?"] = "고맙소, {name}. 나도 모르게 절을 했소. 이것도 효과 중 하나요?"
L["{gift}! Pandaria's finest, {name}. Don't tell the brewmasters."] = "{gift}! 판다리아 최고의 명품이오, {name}. 양조사들한텐 비밀이오."
L["Stronger, quicker and steadier at once, {name}. My teachers never managed that."] = "단번에 더 세고 빠르고 굳건해졌소, {name}. 내 스승들도 못 해낸 일이오."
L["{gift}, {name}! Even my mistakes will look deliberate now."] = "{gift}, {name}! 이젠 내 실수도 일부러 한 것처럼 보이겠소."
L["I feel a tiger pacing in my chest, {name}. It wants to hunt. Thank you."] = "가슴속에서 호랑이가 서성이오, {name}. 사냥하고 싶어 하오. 고맙소."
L["Thank you, {name}. I'll be very polite to cats from now on."] = "고맙소, {name}. 앞으로 고양이한텐 아주 깍듯하겠소."
L["I could out-stare a tiger now, {name}. Not Xuen. A small one."] = "이젠 호랑이와 눈싸움해도 이기겠소, {name}. 쉬엔 말고. 작은 놈이랑."
L["Every strike I throw now has claws in it, {name}. Thank you."] = "이제 내 일격마다 발톱이 돋쳤소, {name}. 고맙소."
L["I'd thank Xuen as well, {name}, but he answers thanks with a sparring match."] = "쉬엔께도 감사드리고 싶지만, {name}, 그분은 감사 인사에 대련으로 답하시오."
L["{gift}! I feel sharper and slightly sinister, {name}. Thanks."] = "{gift}! 머리는 더 날카롭고 살짝 음흉해진 기분이오, {name}. 고맙소."
L["Dark but generous, {name}, like a good stout. Thank you."] = "어둡지만 넉넉하구려, {name}. 좋은 흑맥주처럼. 고맙소."
L["Thank you, {name}. If I start cackling in a fight, you'll know why."] = "고맙소, {name}. 싸우다 내가 음흉하게 낄낄대거든 이유는 알 거요."
L["Bound to a warlock for the hour, {name}. My family would faint. Thank you."] = "한 시간 동안 흑마법사와 묶였구려, {name}. 우리 가족이 알면 기절하겠소. 고맙소."
L["Like borrowing a sharp knife from a stranger in an alley, {name}. Thanks."] = "골목에서 낯선 이한테 잘 드는 칼을 빌린 기분이오, {name}. 고맙소."
L["More dangerous today and worse sleep tonight, {name}. A fair trade. Thanks."] = "오늘은 더 위험해지고 밤엔 잠을 설치겠구려, {name}. 공정한 거래요. 고맙소."
L["Thank you, {name}. Now I know why shamans always look so windswept."] = "고맙소, {name}. 주술사들 머리가 왜 늘 바람에 헝클어져 있는지 이제 알겠소."
L["{gift}! Swift as the wind, {name}, and as hard to argue with."] = "{gift}! 바람만큼 빠르고, {name}, 바람만큼 말이 안 통하겠소."
L["Your {gift} has me crackling, {name}. Shake hands carefully."] = "그대의 {gift}에 몸이 지직거리오, {name}. 악수는 조심해서 하시오."
L["My weapon keeps hitting things twice, {name}. Thank you, and thank the storm."] = "내 무기가 자꾸 두 번씩 치오, {name}. 그대와 폭풍에게 고맙소."
L["The sky's on my side now, {name}. I'll try not to stand on any hilltops."] = "이제 하늘이 내 편이오, {name}. 언덕 꼭대기엔 안 서 있도록 하겠소."
L["I'm half thunderstorm now, {name}. Thank you, and sorry about the rain."] = "이제 반쯤은 뇌우요, {name}. 고맙소. 비 오는 건 미안하오."
L["{gift}! A step ahead of everything, {name}, myself included."] = "{gift}! 모든 것보다 한발 앞서오, {name}. 나 자신보다도."
L["Thank you, {name}. I'll be out of trouble before trouble notices."] = "고맙소, {name}. 말썽이 눈치채기 전에 빠져나가겠소."
L["Thank you, {name}. I can feel the sands shifting in my favour."] = "고맙소, {name}. 모래시계가 내 쪽으로 흐르는 게 느껴지오."
L["Thank you, {name}. Even my running away will look dignified now."] = "고맙소, {name}. 이제 도망쳐도 품위 있어 보이겠소."
L["Haven't I thanked you already, {name}? Time's gone odd. Thanks again."] = "내가 이미 고맙다 하지 않았소, {name}? 시간이 이상해졌군. 다시 고맙소."
L["Thank you, {name}. Nozdormu won't miss the moments; he has all of them."] = "고맙소, {name}. 노즈도르무는 이 순간들 없어도 모를 거요. 모든 순간을 가졌으니."
L["Thank you, {name}. Your magic and mine get on surprisingly well."] = "고맙소, {name}. 그대 마력과 내 마력이 의외로 잘 맞는구려."
L["Of everyone here, {name}, you chose me? I'm flattered and refreshed."] = "여기 이 많은 이들 중에, {name}, 날 골랐소? 영광이고 개운하구려."
L["{gift}! I'll be the last one here to run dry, {name}. Thank you."] = "{gift}! 여기서 제일 마지막까지 안 마르겠소, {name}. 고맙소."
L["I could cast till sundown now, {name}. Please keep breathing fire."] = "이젠 해 질 때까지 시전하겠소, {name}. 부디 계속 불을 뿜으시오."
L["Thank you, {name}. Everyone I help today owes you a little too."] = "고맙소, {name}. 오늘 내가 돕는 이들 모두 그대에게도 조금씩 빚진 셈이오."
L["Your leftovers beat my best, {name}. Most humbling. Thank you."] = "그대가 남긴 게 내 최선보다 낫구려, {name}. 겸허해지오. 고맙소."
L["Thank you, {name}. With the earth at my back, I'll stand anything."] = "고마워요, {name}. 대지가 받쳐 주니 뭐든 버텨요."
L["{gift}! Let them hit me now, {name}. I'll only get better."] = "{gift}! {name}, 이제 때려 봐요. 더 강해져요."
L["Thank you, {name}. I'll try to deserve every pebble."] = "고마워요, {name}. 조약돌 하나하나 값하겠어요."
L["A Beacon, for me? I'll shine where the hits land, {name}. Thank you."] = "봉화를 내게? {name}, 맞는 곳에서 빛날게요."
L["Thank you, {name}. Every heal of yours has my address on it now."] = "고마워요, {name}. 이제 치유마다 내 주소가 적혔네요."
L["{gift}! I'll lead, {name}, and your Light can follow."] = "{gift}! {name}, 내가 앞장서면 그대의 빛이 따라와요."
L["An oath, sworn to me? Thank you, {name}. I'll try to be worth keeping."] = "나에게 맹세를? 고마워요, {name}. 값하도록 할게요."
L["Thank you, {name}. I'll stand in front; you keep your word."] = "고마워요, {name}. 난 앞에 서고 그대는 약속을 지켜요."
L["Thank you, {name}. I'll take good care of your trick, and you of mine."] = "고마워요, {name}. 그대 재주 잘 쓸게요."
L["{gift}! We're a matched pair now, {name}. Let's not waste it."] = "{gift}! {name}, 우린 이제 한 쌍이에요. 낭비 말아요."
L["Your own scales, {name}? I'll wear them proudly. Thank you."] = "그대의 비늘을, {name}? 자랑스레 입을게요."
L["{gift}! Let them swing at me now, {name}. They'll regret it."] = "{gift}! {name}, 덤벼 보라죠. 후회할 거예요."
L["Thank you, {name}. I'll lead the pack and keep their eyes on me."] = "고마워요, {name}. 무리를 이끌고 시선은 내가 받을게요."
L["{gift}! Let them all come for me now, {name}. I am the alpha."] = "{gift}! 다 덤벼요, {name}. 내가 우두머리예요."
L["Thank you, {name}. I'll try to be a light worth following."] = "고마워요, {name}. 따라올 만한 빛이 되어 볼게요."
L["{gift}! Two lights on me now, {name}. I will keep mine lit."] = "{gift}! 빛이 둘이네요, {name}. 내 빛은 지킬게요."
L["Thank you, {name}. Whatever I mend in myself, I'll send your way."] = "고마워요, {name}. 내가 나을 때마다 당신에게도 보낼게요."
L["{gift}! Bonded, then, {name}. I'll take good care of us both."] = "{gift}! 이어졌네요, {name}. 둘 다 챙길게요."
L["We have to stop meeting like this, {name}. Actually, no. Here's another one."] = "우리 이렇게 그만 만나야 하는데, {name}. 아니, 사실 아니에요. 하나 더 받아요."
L["Again, {name}? Splendid. I've been practising since last time."] = "또 만났소, {name}? 좋구려. 지난번 이후로 연습해 뒀소."
L["You again, {name}? Another one for you, then. People will say we're friends."] = "또 당신이네요, {name}? 그럼 하나 더요. 사람들이 우리 친구라고 하겠어요."
L["Same face, same spell, {name}. I do love a tradition."] = "같은 얼굴, 같은 주문이오, {name}. 난 전통이 참 좋소."
L["Another round, {name}? I'm keeping score, and we're both winning."] = "한 판 더, {name}? 점수를 세고 있는데, 둘 다 이기는 중이오."
L["Ah, {name}! My favourite repeat customer."] = "아, {name}! 내가 제일 아끼는 단골손님."
L["Our paths keep crossing, {name}, and I keep having one of these for you."] = "우리 길이 자꾸 겹치네요, {name}. 그리고 전 늘 이걸 하나씩 갖고 있죠."
L["Once more, {name}. Do stop me if you've heard this one."] = "한 번 더 하오, {name}. 이 얘기 들은 적 있으면 말리시오."
L["I kept some aside, {name}, in case you came back. Good instinct, mine."] = "그대가 다시 올까 봐 좀 남겨 뒀소, {name}. 내 감이 좋았구려."
L["Back already, {name}? The day's improving. Here, same as last time."] = "벌써 돌아왔어요, {name}? 하루가 좋아지네요. 자, 지난번처럼요."
L["Again, {name}? At this rate I'll learn your middle name. Have another."] = "또요, {name}? 이러다 당신 중간 이름까지 외우겠어요. 하나 더 받아요."
L["Once is kindness, twice is a habit, {name}. I've never broken a habit yet."] = "한 번은 친절, 두 번은 버릇이오, {name}. 버릇은 여든까지 간다지."
L["An encore, {name}, for my most faithful audience."] = "앙코르요, {name}. 가장 충실한 관객을 위해."
L["One more of these, {name}, and we'll have to draw up a guild charter."] = "한 번만 더 하면, {name}, 길드 헌장에 서명해야겠소."
L["I'll remember your face now, {name}, and I'm terrible with faces. Here."] = "이제 당신 얼굴은 기억할게요, {name}. 전 얼굴을 정말 못 외우는데. 받아요."
L["Us again, {name}. The world must be short of people to bless. Here."] = "또 우리네요, {name}. 세상에 축복할 사람이 바닥났나 봐요. 받아요."
L["Last time went so well, {name}, I've changed nothing."] = "지난번이 워낙 좋아서, {name}, 하나도 안 바꿨소."
L["Good to see someone I know, {name}. Rarer than you'd think. Have this."] = "아는 얼굴을 보니 반갑네요, {name}. 생각보다 드물거든요. 이걸 받아요."
L["Oh, it's you, {name}. Good. I hate giving these to strangers."] = "아, 그대였구려, {name}. 다행이오. 낯선 이한테 주는 건 질색이라."
L["{name}, at this point we should just share a reagent pouch."] = "{name}, 이쯤 되면 재료 주머니를 같이 써야겠소."
L["Same time tomorrow, {name}? I'll bring {buff}. You bring you."] = "내일 이 시간에, {name}? 난 {buff}, 그대는 그대만 가져오시오."
L["I've lost count of these, {name}, and I've decided that's a compliment."] = "이걸 몇 번 드렸는지 잊었어요, {name}. 그게 칭찬이라고 생각하기로 했죠."
L["Keep this up, {name}, and the bards will write a dull song about our favours."] = "이렇게 계속하면, {name}, 음유시인들이 우리 호의로 지루한 노래를 쓰겠어요."
L["I could do this one in my sleep by now, {name}. I may have."] = "이젠 자면서도 하겠소, {name}. 이미 그랬을지도."
L["The usual, {name}? Of course the usual."] = "늘 하던 걸로, {name}? 물론 늘 하던 걸로."
L["We should have a secret handshake by now, {name}. Until then, this."] = "이쯤이면 비밀 악수라도 있어야죠, {name}. 그때까진 이걸로."
L["By now, {name}, I think we've built a small economy between us."] = "이쯤 되니, {name}, 우리 둘이 작은 경제를 이룬 것 같소."
L["Old friends by now, {name}. Old acquaintances, at least, with this habit."] = "이제 오랜 친구네요, {name}. 적어도 이 버릇이 있는 오랜 지인이죠."
L["Let the record show: {name} and I, undefeated at being prepared."] = "기록해 두시오. {name}하고 나, 준비성 부문 무패."
L["My spellbook opens to your page on its own now, {name}."] = "이제 내 주문책이 알아서 그대 쪽을 펼치오, {name}."
L["If you stopped turning up, {name}, who would I give these to? The guards?"] = "당신이 안 나타나면, {name}, 이걸 누구한테 주죠? 경비병한테요?"
L["We keep this up, {name}, and one of us owes the other a drink."] = "이대로 가면, {name}, 둘 중 하나는 술 한잔 사야겠소."
L["We're a local landmark now, {name}: the pair who bless each other. Here."] = "우린 이제 명소예요, {name}. 서로 축복해 주는 두 사람. 받아요."
L["Regular as the tides, {name}, and twice as welcome. As is this."] = "조수처럼 꼬박꼬박, {name}, 두 배로 반가워요. 이것도 그렇고요."
L["I'd trust you with my last potion, {name}. For now, take this."] = "마지막 물약도 맡길 수 있어요, {name}. 지금은 이걸 받아요."
L["Next time we share a fire, {name}. This time, take this."] = "다음엔 모닥불을 함께 나눠요, {name}. 이번엔 이걸 받고요."
L["I'd miss this if it stopped, {name}. So let's not stop."] = "이게 끊기면 서운할 거요, {name}. 그러니 끊지 맙시다."
L["There's nobody I'd rather keep blessing, {name}."] = "계속 축복하고 싶은 사람은 당신뿐이에요, {name}."
L["You always turn up at the right moment, {name}, and I'm always ready. Here."] = "당신은 늘 딱 맞을 때 나타나죠, {name}. 전 늘 준비돼 있고요. 받아요."
L["Safe walls, warm beds, and now {buff}. You're spoiled, {name}."] = "튼튼한 성벽, 따뜻한 침대, 이제 {buff}까지. 호강하는구려, {name}."
L["The guards have it covered, {name}, but I like to be thorough."] = "경비병이 지켜 주겠지만, {name}, 난 꼼꼼한 게 좋소."
L["Careful, {name}. Look this capable in town and folk will ask you favours."] = "조심하시오, {name}. 마을에서 이리 유능해 보이면 다들 부탁하러 올 거요."
L["Not a monster for miles, {name}. Still, take this. One never knows the cooking."] = "몇 리 안에 괴물 하나 없죠, {name}. 그래도 이걸 받아요. 요리는 모르는 거니까."
L["For the crowds, {name}. In town, they're the real danger."] = "인파 대비용이오, {name}. 도시에선 그게 진짜 위험이지."
L["Rest easy, {name}. I'll count that my good deed and go find a pint."] = "편히 쉬시오, {name}. 이걸로 오늘 선행은 했으니 한잔하러 가겠소."
L["Even in town, {name}, a dragon has been known to drop in. Better safe."] = "도시에도 가끔 용이 들이닥친다오, {name}. 조심해서 나쁠 건 없지."
L["Best do it in here, {name}. Out there, nobody stands still long enough."] = "여기서 하는 게 낫소, {name}. 밖에선 아무도 가만있질 않으니."
L["Mind the pickpockets, {name}. This is the one thing on you they can't lift."] = "소매치기 조심하시오, {name}. 이것만은 못 털어 가오."
L["City rules, {name}: no blades drawn, no spells thrown. This one's allowed."] = "도시 규칙이오, {name}. 칼 뽑기 금지, 주문 던지기 금지. 이건 허용이오."
L["Nothing to fight here but stray cats, {name}. Take this anyway."] = "여기서 싸울 거라곤 길고양이뿐이오, {name}. 그래도 받으시오."
L["For the walk to the bank, {name}. It's always further than it looks."] = "은행 가는 길에 쓰시오, {name}. 늘 보기보다 멀지."
L["Enjoy a warm hearth while you can, {name}, and take this for the road."] = "따뜻한 난롯가를 즐길 수 있을 때 즐겨요, {name}. 길 떠날 땐 이걸 챙기고요."
L["The watch has the walls, {name}. I'll see to you."] = "성벽은 경비대가 지키오, {name}. 그대는 내가 챙기리다."
L["For the stairs, {name}. Whoever built this place never met a short way up."] = "계단용이오, {name}. 여길 지은 자는 지름길을 몰랐나 보오."
L["Everything else in town has a price, {name}. This slipped past the merchants."] = "도시에선 뭐든 값이 붙소, {name}. 이건 상인들 눈을 피했지."
L["Buy nothing from anyone who calls you 'friend', {name}. Except me. It's free."] = "당신을 '친구'라 부르는 사람한테선 아무것도 사지 마요, {name}. 저만 빼고요. 공짜예요."
L["Out here everything wants to eat you, {name}. Now it'll need a bigger fork."] = "여기선 뭐든 그대를 먹으려 드오, {name}. 이제 더 큰 포크가 필요할 거요."
L["No guards for miles, {name}, and the boars know it. Take this."] = "근방에 경비병 하나 없소, {name}. 멧돼지들도 그걸 알지. 받으시오."
L["Nobody out here but us and the wildlife, {name}. With this, we're tougher."] = "여기엔 우리와 짐승들뿐이죠, {name}. 이거면 우리가 더 질겨요."
L["If a bear asks, {name}, you were like this when I found you."] = "곰이 물으면, {name}, 원래부터 이랬다고 하시오."
L["The wolves have been eyeing you, {name}. This should give them pause."] = "늑대들이 그대를 노리던데, {name}. 이러면 좀 망설이겠지."
L["Wild country, {name}. Best not to meet it armed with good intentions alone."] = "험한 땅이오, {name}. 좋은 뜻만 들고 맞서긴 곤란하오."
L["Map, canteen, {buff}. Now you can get lost properly, {name}."] = "지도, 물통, {buff}. 이제 제대로 길을 잃어도 되오, {name}."
L["Camp's a long way off, {name}. Consider this a roof you can carry."] = "야영지는 한참 멀었소, {name}. 들고 다니는 지붕이라 생각하시오."
L["Out past the last farm, {name}, you're on your own. Nearly."] = "마지막 농장을 지나면, {name}, 그대 혼자요. 거의."
L["Nearest inn's a day's walk, {name}; the nearest teeth, closer. Take this."] = "제일 가까운 여관은 하루 거리예요, {name}. 제일 가까운 이빨은 더 가깝고요. 이걸 받아요."
L["Two hills and a swamp to the next town, {name}. Here; the swamp has opinions."] = "다음 마을까진 언덕 둘에 늪 하나예요, {name}. 받아요. 늪이 말이 많거든요."
L["Take this; camp carefully, {name}. Every nice clearing has an owner with claws."] = "이걸 받고 조심해서 야영해요, {name}. 좋은 빈터마다 발톱 달린 주인이 있어요."
L["Fresh air, open sky, {name}, and this. Enjoy it while nothing's chasing you."] = "맑은 공기, 탁 트인 하늘, {name}, 그리고 이것. 아무것도 안 쫓아올 때 즐겨요."
L["Something's following you, {name}. Probably a boar. This is in case it isn't."] = "뭔가 따라오오, {name}. 아마 멧돼지겠지. 아닐 때를 대비해서요."
L["Take this and stay on the road, {name}. The road has guards. Some of the time."] = "이걸 받고 길로만 다녀요, {name}. 길엔 경비병이 있거든요. 가끔은요."
L["Rain's coming, {name}, and so are the wolves. One of those I can help with."] = "비가 오고, 늑대도 오오, {name}. 둘 중 하나는 내 소관이오."
L["A villain in here rehearses a speech, {name}. Take this, then let's interrupt."] = "이 안 어딘가에서 악당이 연설 연습 중이에요, {name}. 이걸 받고, 끊으러 가요."
L["Whatever waits at the end of this place, {name}, this will make it regret it."] = "이곳 끝에 뭐가 기다리든, {name}, 이게 후회하게 만들 거예요."
L["Nobody leaves here alive, they say, {name}. Take this; let's prove them wrong."] = "여기선 아무도 살아 나가지 못한다죠, {name}. 이걸 받아요. 틀렸다는 걸 보여 주죠."
L["Our host had years to prepare, {name}. We have {buff}."] = "이곳 주인은 몇 년을 준비했소, {name}. 우리에겐 {buff}."
L["Nobody builds a dungeon with a back door, {name}. Take this instead."] = "뒷문 달린 던전은 없소, {name}. 대신 이걸 받으시오."
L["Dark halls, old traps, worse tempers. At least you're ready, {name}."] = "어두운 복도, 낡은 함정, 더 고약한 성질머리. 적어도 그대는 준비됐소, {name}."
L["Better I hand you this now, {name}, than a eulogy later."] = "나중에 추도사를 바치느니, {name}, 지금 이걸 드리는 게 낫소."
L["There's treasure in here, {name}, and something large sat on it. This first."] = "여기 보물이 있어요, {name}. 뭔가 큰 게 깔고 앉아 있지만. 이것부터요."
L["If a door slams shut behind us, {name}, that's tradition. Take this first."] = "뒤에서 문이 쾅 닫히면, {name}, 그게 전통이오. 이것부터 받으시오."
L["Take this, {name}, and mind the patrols. They walk the same loop and resent it."] = "이걸 받고, {name}, 순찰대 조심해요. 같은 길만 도느라 잔뜩 성나 있거든요."
L["Whoever built this place spent it all on skulls, {name}. Here's a little light."] = "여길 지은 놈은 해골에 다 썼나 봐요, {name}. 빛을 좀 드릴게요."
L["The last lot through here were never seen again, {name}. They lacked this."] = "먼저 온 일행은 다신 못 봤다더군, {name}. 이게 없었던 거요."
L["Take this, {name}; check the ceiling. In places like this, something drops in."] = "이걸 받고, {name}, 천장 확인해요. 이런 데선 꼭 뭐가 떨어지거든요."
L["Take this, {name}. If we meet a talking skull, let me do the talking."] = "이걸 받아요, {name}. 말하는 해골을 만나면 제가 얘기할게요."
L["Here, {name}. If the walls start whispering, don't answer. It encourages them."] = "받아요, {name}. 벽이 속삭이기 시작하면 대답하지 마요. 신나서 더 하거든요."
L["Touch nothing that glows, pull nothing that clicks, {name}. Wear this."] = "빛나는 건 만지지 말고, 딸깍하는 건 당기지 마시오, {name}. 이걸 걸치고."
L["Take this and stick together in here, {name}. Echoes carry, and so do grudges."] = "이걸 받고 안에선 뭉쳐 있어요, {name}. 메아리도 멀리 가고, 원한도 그렇거든요."
L["Flags, towers, graveyards, {name}. Whatever we're fighting over, take this."] = "깃발, 탑, 무덤, {name}. 뭘 두고 싸우든, 이걸 받으시오."
L["Win or lose, {name}, nobody will say you went in unprepared."] = "이기든 지든, {name}, 준비 없이 갔단 말은 안 나올 거요."
L["The graveyard's just over there, {name}. Take this; let's both not visit it."] = "무덤은 바로 저기예요, {name}. 이걸 받아요. 둘 다 가지 말자고요."
L["Honour's on the line, {name}. So is the flag. Here's something for both."] = "명예가 걸려 있어요, {name}. 깃발도요. 둘 다를 위한 걸 드릴게요."
L["Take this and stay with the group, {name}. Lone heroes make short songs."] = "이걸 받고 일행과 함께 있어요, {name}. 외톨이 영웅은 노래가 짧아요."
L["Our banner looks better with you under it, {name}, and blessed. Stand tall."] = "우리 깃발은 당신이 아래 있을 때 더 멋져요, {name}. 축복받았으니 당당히 서요."
L["Take this, {name}. Keep your head down and your colours up."] = "이걸 받아요, {name}. 고개는 낮추고 깃발은 높이."
L["Hold the line with this, {name}. The songs are about the ones who stood."] = "이걸로 전열을 지켜요, {name}. 노래는 버틴 사람들 이야기거든요."
L["Take this and come back in one piece, {name}. That's all I ask."] = "이걸 받고 무사히 돌아와요, {name}. 바라는 건 그것뿐이에요."
L["Drums are for courage, {name}. This is for everything else."] = "용기는 북이 채우고, {name}, 나머진 이게 채우오."
L["Some fight for glory, {name}. I fight for whoever's beside me, and bless them."] = "누군 영광을 위해 싸우죠, {name}. 전 곁에 있는 사람을 위해 싸우고, 축복해요."
L["Take this, {name}. Fight for the banner, come back for the singing. It's awful."] = "이걸 받아요, {name}. 깃발을 위해 싸우고, 노래하러 돌아와요. 끔찍하지만요."
L["Early bird, {name}? Here's something better than a worm."] = "일찍 일어난 새구려, {name}. 벌레보다 나은 걸 드리리다."
L["Good morning, {name}. Consider this your first cup of something strong."] = "좋은 아침이오, {name}. 오늘의 첫 진한 차 한 잔이라 치시오."
L["Early start, {name}. The day hasn't gone wrong yet, and this should keep it so."] = "이른 출발이네요, {name}. 하루가 아직 안 틀어졌죠. 이게 계속 그렇게 해 줄 거예요."
L["Not even lunch yet, {name}, and you're already better prepared than I am."] = "점심도 안 됐는데, {name}, 벌써 나보다 준비가 잘됐구려."
L["Morning, {name}. The monsters are still yawning. Take this before they stop."] = "좋은 아침, {name}. 괴물들은 아직 하품 중이에요. 그치기 전에 이걸 받아요."
L["A fresh day and a fresh {buff}, {name}. Let's not waste either."] = "새 하루에 새 {buff}, {name}. 둘 다 허투루 쓰지 맙시다."
L["Up with the sun, {name}? Show-off. Here; the sun doesn't get one."] = "해와 함께 기상이라니, {name}. 잘난 척은. 옜소, 해한텐 안 주는 거요."
L["Rise and shine, {name}. This is the shine; breakfast can wait."] = "일어나서 빛나요, {name}. 이게 그 빛이에요. 아침밥은 나중에."
L["Everything's golden and nobody's shouted yet, {name}. Add this to it."] = "온통 금빛이고 아직 아무도 소리 안 질렀어요, {name}. 여기에 이것도 더해요."
L["Too early for heroics, {name}? Nonsense. Here; heroics go best before lunch."] = "영웅 노릇 하기엔 너무 이르다고요, {name}? 무슨 소리. 받아요. 점심 전이 제일 잘돼요."
L["The birds are singing, {name}. They haven't seen what's out there. Take this."] = "새들이 노래하네요, {name}. 밖에 뭐가 있는지 아직 못 봤나 봐요. 이걸 받아요."
L["First good deed of the day, {name}. It's all downhill from here."] = "오늘의 첫 선행이오, {name}. 여기서부턴 내리막이오."
L["Still yawning, {name}? This works faster than tea."] = "아직 하품 중이오, {name}? 이건 차보다 빨리 듣소."
L["Early, {name}. The dawn patrol thinks we're mad, handing out blessings now."] = "이른 시간이네요, {name}. 새벽 순찰대가 이 시간에 축복 나눠 준다고 미쳤대요."
L["Out this late, {name}? The night is hungrier than the day. Take this."] = "이 늦은 시간에, {name}? 밤은 낮보다 굶주렸소. 받으시오."
L["Past bedtime, {name}. The sensible folk are asleep, so you get this."] = "잘 시간이 지났어요, {name}. 분별 있는 사람들은 자니까, 이건 당신 거예요."
L["Can't sleep either, {name}? Then let me be useful. Here."] = "당신도 잠이 안 와요, {name}? 그럼 제가 쓸모 있게 굴게요. 받아요."
L["Mind the dark, {name}, and take this. Not everything out there is as friendly."] = "어둠을 조심해요, {name}. 이걸 받고요. 밖에 있는 게 다 이렇게 친절하진 않아요."
L["It's late, {name}. This should keep you going till the sun remembers us."] = "늦었소, {name}. 해가 우릴 기억해 낼 때까진 이걸로 버티시오."
L["Only the owls and us awake, {name}, and the owls get no {buff}."] = "깨어 있는 건 부엉이와 우리뿐이오, {name}. 부엉이한텐 {buff} 없소."
L["The inns have locked up, {name}. This is the only thing still being served."] = "여관은 다 문을 닫았소, {name}. 아직 영업 중인 건 이것뿐이오."
L["It's the hour for ghost stories, {name}. Take this, in case one is true."] = "괴담 들을 시간이오, {name}. 하나쯤 진짜일지 모르니 받으시오."
L["Candles low, stars high, {name}. A good hour for small kindnesses."] = "촛불은 낮고 별은 높소, {name}. 작은 친절에 좋은 시간이오."
L["Quiet hour, {name}. Every creak sounds like an ambush. This helps with that."] = "고요한 시간이에요, {name}. 삐걱 소리마다 매복 같죠. 이게 도움이 될 거예요."
L["This late, {name}, even the guards talk to themselves. I'd rather bless you."] = "이렇게 늦으면, {name}, 경비병들도 혼잣말을 해요. 전 차라리 당신을 축복할래요."
L["This is the hour things climb out of graves, {name}. Take this; walk briskly."] = "무덤에서 뭔가 기어 나오는 시간이오, {name}. 이걸 받고 걸음을 재촉하시오."
L["Tomorrow you'll wonder why you stayed up, {name}. This is one good reason."] = "내일이면 왜 밤을 새웠나 싶을 거요, {name}. 이게 그럴싸한 이유 하나요."
L["Takes one to know one, {name}. Takes one to do it properly, too."] = "알아보는 건 같은 직업이지, {name}. 제대로 챙기는 것도 같은 직업이고."
L["From one of our trade to another, {name}. No need to check my work."] = "동업자끼리 드리는 거요, {name}. 검수는 필요 없소."
L["Professional courtesy, {name}. We don't charge each other."] = "동업자 예우요, {name}. 우리끼린 돈 안 받소."
L["Two of a kind, {name}. We could write the manual. This is chapter one."] = "같은 부류네요, {name}. 우리가 교본을 쓸 수도 있겠어요. 이게 1장이에요."
L["Don't look so surprised, {name}. Same trainer, I expect. Same blessing too."] = "그렇게 놀라지 마요, {name}. 같은 교관이었겠죠. 같은 축복이기도 하고요."
L["I'd critique your technique, {name}, but mine looks the same. Here."] = "당신 기술을 지적하고 싶지만, {name}, 제 것도 똑같네요. 받아요."
L["Don't tell the others, {name}: ours is the finest calling. Proof: this."] = "다른 사람들한텐 비밀이에요, {name}. 우리 직업이 최고예요. 증거는 이거고요."
L["Look at us, {name}. Two experts, making this look easy. It isn't, is it?"] = "우릴 봐요, {name}. 전문가 둘이 이걸 쉬워 보이게 하네요. 쉽진 않죠?"
L["Between colleagues, {name}: I don't know how half of it works. This half, I do."] = "동료끼리 얘기지만, {name}, 반은 어떻게 되는지 몰라요. 이 반은 알지만."
L["We walked the same road to get here, {name}. Take this for the next stretch."] = "우린 같은 길을 걸어왔죠, {name}. 다음 구간엔 이걸 가져가요."
L["If anyone asks, {name}, we trained each other. Starting with this."] = "누가 물으면, {name}, 우린 서로 가르친 거예요. 이것부터요."
L["Calling to calling, {name}. We should compare notes. Here's mine."] = "같은 길을 걷는 사이죠, {name}. 노트 좀 비교해 봐요. 이게 제 거예요."
L["Colleague, {name}. We look after our own."] = "동업자구려, {name}. 우린 우리끼리 챙기오."
L["Good to see the old craft in steady hands, {name}. Steadier with this."] = "옛 기술이 든든한 손에 있으니 좋네요, {name}. 이거면 더 든든하죠."
L["I'd shout some encouragement, {name}, but you do that far better. Here instead."] = "응원의 함성을 질러 주고 싶지만, {name}, 그건 당신이 훨씬 잘하죠. 대신 이걸요."
L["Charge in as usual, {name}. I'll simply feel better about it now."] = "늘 하던 대로 돌진하시오, {name}. 이제 내 마음이 좀 놓이겠소."
L["For the one who goes in first, {name}. Somebody has to, and it's never me."] = "맨 먼저 뛰어드는 이에게, {name}. 누군가는 해야 하고, 그게 난 아니지."
L["You take the hits so the rest of us don't, {name}. It's the least I can do."] = "우리 대신 맞아 주는 그대요, {name}. 이 정도는 해야지."
L["Take this, {name}, and charge. I'll be right behind you."] = "이걸 받고 돌격해요, {name}. 제가 바로 뒤에 있을게요."
L["For the one who fixes every problem by hitting it, {name}. It usually works."] = "모든 문제를 때려서 푸는 그대에게, {name}. 대개 통하더군."
L["I'd shake your hand, {name}, but both are holding something sharp. Take this."] = "악수하고 싶지만, {name}, 두 손 다 날붙이를 쥐고 있네요. 이걸 받아요."
L["A little help for a lot of armour, {name}. I hope it fits under there."] = "산더미 같은 갑옷에 작은 도움 하나, {name}. 안에 들어갈 틈이 있으려나."
L["You'll charge something enormous soon, {name}. I'm just helping it lose."] = "곧 뭔가 거대한 놈에게 돌진할 테지, {name}. 난 그놈이 지게 거들 뿐이오."
L["Save your Light for later, {name}. This one's from me."] = "그대의 빛은 아껴 두시오, {name}. 이번 건 내가 드리오."
L["You bless everyone else all day, {name}. Here's one going the other way."] = "종일 남들만 축복하잖소, {name}. 이번엔 거꾸로 드리오."
L["The Light already favours you, {name}. Here's a little more of it."] = "빛은 이미 그대를 아끼오, {name}. 여기 조금 더 드리오."
L["Even the Light's own champion needs a hand now and then, {name}."] = "빛의 용사에게도 가끔 도움은 필요하오, {name}."
L["I'd ask for a blessing back, {name}, but then we'd be here all day."] = "축복을 돌려 달라 하고 싶지만, {name}, 그럼 하루가 다 가겠소."
L["For the one who carries a hammer and a conscience, {name}. Heavy load."] = "망치와 양심을 함께 짊어진 그대에게, {name}. 짐이 무겁겠소."
L["Don't thank the Light for this one, {name}. This was me."] = "이번엔 빛에 감사하지 마시오, {name}. 내가 했소."
L["No need to kneel, {name}. I know it's a habit. Take this standing."] = "무릎 꿇을 필요 없어요, {name}. 습관인 거 알아요. 서서 받으세요."
L["One for you, {name}, and a pat on the head for your companion."] = "그대에게 하나, {name}. 그대 야수에겐 머리 쓰다듬기 한 번."
L["You watch everyone's back from range, {name}. I've got yours."] = "멀리서 모두의 등을 지켜 주잖소, {name}. 그대 등은 내가 맡지."
L["Hunter's Mark for them, {buff} for you, {name}. Much nicer."] = "적에겐 사냥꾼의 징표, 그대에겐 {buff}, {name}. 훨씬 낫지."
L["Take this and aim true, {name}. If it charges anyway, run to the rest of us."] = "이걸 받고 잘 조준해요, {name}. 그래도 달려들면 우리 쪽으로 뛰어요."
L["Keen eye, steady hand, {name}. Here's something for the long hunt."] = "예리한 눈, 흔들림 없는 손이구려, {name}. 긴 사냥에 보태시오."
L["Nothing for the pet this time, {name}. It's already had three of my sandwiches."] = "이번엔 야수 몫은 없소, {name}. 벌써 내 샌드위치를 셋이나 먹었으니."
L["I'd have brought arrows, {name}, but I never know which kind you like."] = "화살을 가져올까 했소, {name}. 어떤 걸 좋아하는지 몰라서."
L["You can track anything, {name}, but you never saw this one coming."] = "무엇이든 추적하는 그대도, {name}, 이건 못 봤겠지."
L["Quick hands, quiet feet, {name}. Here's luck to go with them."] = "재빠른 손, 조용한 발이구려, {name}. 행운도 곁들여 드리오."
L["Quick, {name}, before you vanish again."] = "얼른, {name}. 또 사라지기 전에."
L["Poison on the blades, {buff} on you. Very thorough, {name}."] = "칼날엔 독, 몸엔 {buff}. 아주 철저하구려, {name}."
L["I'd slip it in your pocket, {name}, but you'd notice. You always notice."] = "주머니에 슬쩍 넣어 두려 했소, {name}. 하지만 알아채겠지. 늘 알아채니까."
L["For the one who opens every locked box, {name}. This one comes unlocked."] = "잠긴 상자는 다 여는 그대에게, {name}. 이건 처음부터 열려 있소."
L["Nobody sees you coming, {name}. Now it's even worse news when they do."] = "그대가 오는 건 아무도 못 보지, {name}. 이젠 보는 순간 더 큰일이겠구려."
L["Take this, {name}. Very discreet. It even walks quietly."] = "받으시오, {name}. 아주 은밀한 거요. 발소리도 안 나오."
L["I'd have wrapped it, {name}, but you'd only pick the knot."] = "포장하려다 말았소, {name}. 어차피 매듭을 따 버릴 테니."
L["Keep this one, {name}. You don't even have to steal it."] = "이건 가지시오, {name}. 훔칠 필요도 없소."
L["For once, {name}, somebody's looking after the priest."] = "이번만큼은, {name}, 누군가 사제를 챙기는구려."
L["Save your prayers for the rest of us, {name}. This one's already answered."] = "기도는 우리 몫으로 아껴 두시오, {name}. 이 기도는 이미 응답받았소."
L["Light or Shadow, {name}, I don't ask which. This suits both."] = "빛이든 암흑이든, {name}, 묻지 않겠소. 둘 다 어울리니."
L["Sit down after this fight, {name}. That's an order. Take this, from a patient."] = "이 싸움 끝나면 좀 앉아요, {name}. 명령이에요. 환자가 드리는 이것도 받고요."
L["You keep us all standing, {name}. Here's a little of it coming back."] = "그대 덕에 우리가 버티잖소, {name}. 그중 조금을 돌려드리오."
L["You've knelt beside all of us, {name}. Stand tall a minute, and take this."] = "우리 모두 곁에서 무릎 꿇어 줬죠, {name}. 잠시 당당히 서서 이걸 받아요."
L["Something that needed no prayer, {name}. You've said plenty of those today."] = "기도 없이 오는 거요, {name}. 오늘 기도는 충분히 했잖소."
L["No voice in your head comes with this one, {name}. Refreshing, isn't it?"] = "이건 머릿속 목소리가 딸려 오지 않소, {name}. 개운하지 않소?"
L["The Ebon Blade asks no favours, {name}. I'm giving one anyway."] = "칠흑의 기사단은 호의를 청하지 않지, {name}. 그래도 드리겠소."
L["A little warmth, {name}. I know you don't feel the cold. It's the thought."] = "온기 좀 드리오, {name}. 추위를 못 느끼는 건 알지만, 마음이오."
L["You came back from the dead, {name}. The least I can do is help you stay back."] = "죽음에서 돌아왔으니, {name}, 다시 안 가게 거드는 게 도리지."
L["Runes, plague and frost, {name}. Take this too; it completes the set."] = "룬, 역병, 냉기, {name}. 이것도 받으시오. 세트 완성이오."
L["A skeletal horse and a sword that talks back, {name}. Here's something normal."] = "해골 말에 말대꾸하는 검이라, {name}. 평범한 것도 하나 드리오."
L["No need to drag me over on a chain, {name}. I was coming anyway. With this."] = "사슬로 끌어당길 필요 없어요, {name}. 어차피 가는 중이었어요. 이걸 들고."
L["Welcome back to the land of the living, {name}. Its general direction. Here."] = "산 자들의 땅에 다시 온 걸 환영해요, {name}. 그쪽 방향이라도요. 받아요."
L["The elements look after you, {name}, but they don't make house calls."] = "정령들이 그대를 돌보지만, {name}, 왕진은 안 오잖소."
L["Tell the spirits I said hello, {name}, and showed them this."] = "영혼들한테 안부 전해 줘요, {name}. 이것도 보여 주고요."
L["Plant a totem in my honour, {name}, for this. A small one. I'm modest."] = "이 보답으로 제 이름 걸고 토템 하나 세워 줘요, {name}. 작은 걸로요. 전 겸손하니까."
L["Earth, fire, water, air and me, {name}. Admittedly the least of the five."] = "대지, 화염, 물, 바람, 그리고 나, {name}. 다섯 중 제일 약한 건 인정하오."
L["Totems up already, {name}? Then this goes with them."] = "벌써 토템을 세웠소, {name}? 그럼 이것도 곁들이시오."
L["The wind would have brought you this, {name}, but it's flighty. I'm reliable."] = "바람 편에 보낼 수도 있었소, {name}. 헌데 바람은 바람기가 있어서. 난 한결같소."
L["You speak for the land, {name}. I hope this makes it speak kindly of me."] = "당신은 대지를 대변하죠, {name}. 이걸로 대지가 절 좋게 말해 주길 바라요."
L["The spirits said you'd earned this, {name}. I didn't ask; they volunteered."] = "영혼들이 그대가 받을 만하다더군, {name}. 묻지도 않았는데 먼저 말하더이다."
L["A gift for a mage, {name}. Hard to find one you can't conjure."] = "마법사에게 줄 선물이라, {name}. 그대가 창조 못 할 걸 찾기가 어렵구려."
L["You solve most problems with sheep, {name}. This covers the rest."] = "대부분의 문제는 양으로 해결하잖소, {name}. 나머진 이걸로."
L["You could teleport out of any trouble, {name}. This is for the trouble first."] = "어떤 곤경이든 순간이동으로 빠지겠지만, {name}, 이건 빠지기 전 몫이오."
L["For the clever one, {name}. Please don't thank me by making me a sheep."] = "똑똑한 그대에게, {name}. 감사 인사로 날 양으로 만들진 마시오."
L["Blink wherever you like, {name}. This comes too."] = "어디로 점멸하든, {name}, 이건 따라가오."
L["Stand a little back from the fire you're about to start, {name}. Here."] = "곧 지를 불에서 한 발 물러서시오, {name}. 자, 이거."
L["You keep us all fed and watered, {name}. Your turn to be looked after."] = "늘 물빵으로 우릴 먹여 살리잖소, {name}. 이번엔 그대가 챙김받을 차례요."
L["Portal fees are steep, {name}. Call this a down payment on my next one."] = "차원문 삯이 비싸잖소, {name}. 이건 다음 차원문 계약금이오."
L["Entirely demon-free, {name}. I checked."] = "악마 성분 0%요, {name}. 직접 확인했소."
L["Your imp may be jealous, {name}. Tell it there's plenty to go round."] = "그대 임프가 샘낼지도 모르오, {name}. 넉넉하다고 전해 주시오."
L["No contract, no fine print, {name}. Just a gift."] = "계약서도, 깨알 같은 약관도 없소, {name}. 그냥 선물이오."
L["For the one who hands out healthstones, {name}. Nobody ever thanks you."] = "생명석 나눠 주는 그대에게, {name}. 고맙단 말 한 번 못 들었을 테니."
L["Here, {name}. Summon the rest of us later and we'll call it even."] = "여기, {name}. 나중에 우리 소환해 주면 퉁칩시다."
L["Your voidwalker can stop hovering, {name}. I mean well."] = "그대 공허방랑자더러 그만 맴돌라 하시오, {name}. 난 좋은 뜻이오."
L["Your felhunter eats magic, {name}. Keep it off this one; it's for you."] = "그대 지옥사냥개는 마법을 먹지, {name}. 이건 먹이지 마시오. 그대 거요."
L["For the one who reads what nobody else dares, {name}."] = "아무도 감히 못 읽는 걸 읽는 그대에게, {name}."
L["Carrying a bag of souls all day, {name}? Your shoulders must need this."] = "종일 영혼 주머니를 메고 다니니, {name}, 어깨가 이걸 원하겠구려."
L["Roll wherever you like, {name}. This rolls with you."] = "어디로 구르든, {name}, 이것도 같이 구르오."
L["Brew first or fight first, {name}? Either way, take this."] = "술이 먼저요, 싸움이 먼저요, {name}? 어느 쪽이든 받으시오."
L["Inner peace for you, {name}, and outer peace too, as long as this lasts."] = "그대에게 내면의 평화를, {name}. 이게 지속되는 동안은 바깥 평화도."
L["Chi flows better with a little help, {name}. Or so a monk once told me."] = "기의 흐름엔 도움이 좀 필요하오, {name}. 어느 수도사가 그러더군."
L["Kick, flip, roll, {name}. I'll just stand here and do this bit."] = "차고, 뒤집고, 구르고, {name}. 난 여기 서서 이것만 하겠소."
L["Teach me to flip without spilling my drink, {name}, and we're even."] = "술 안 쏟고 공중제비 도는 법을 가르쳐 주면, {name}, 퉁칩시다."
L["Tea, meditation and this, {name}. The three pillars of a good day."] = "차, 명상, 그리고 이것, {name}. 좋은 하루의 세 기둥이오."
L["Tell the bear this is for them too, {name}."] = "곰에게도 전해 주시오, {name}. 이건 곰 몫이기도 하다고."
L["Hold still, {name}. I've never once managed to catch you as a cheetah."] = "가만있으시오, {name}. 치타일 땐 한 번도 못 잡았으니."
L["Nature looks after you already, {name}. Today she sent me to help."] = "이미 자연이 그대를 돌보지만, {name}, 오늘은 날 보냈구려."
L["Whatever shape you're in next, {name}, this goes with you."] = "다음에 무슨 모습이 되든, {name}, 이건 함께 가오."
L["For the forest's friend, {name}. Give my regards to the trees."] = "숲의 벗에게, {name}. 나무들에게 안부 전해 주시오."
L["Cenarion work is never done, {name}. Here's a little help."] = "세나리온의 일은 끝이 없지, {name}. 작은 도움이오."
L["I'd give it to the cat, {name}, but the cat would pretend not to care."] = "표범한테 줄까 했소, {name}. 헌데 관심 없는 척할 테지."
L["Take this, {name}. Say hello to your moonkin form; it always looks so startled."] = "이걸 받아요, {name}. 달빛야수 모습한테도 안부 전해요. 늘 깜짝 놀란 얼굴이잖아요."
L["You were not prepared, {name}. Now you are."] = "'아직 준비가 안 됐다'더니, {name}. 이제 됐소."
L["Years in a Warden's cell, {name}. You've earned a small kindness."] = "감시자의 감옥에서 수년이라, {name}. 작은 친절쯤은 받을 만하오."
L["You gave up so much to fight the Legion, {name}. Here's a little back."] = "군단과 싸우려 많은 걸 버렸잖소, {name}. 조금 돌려드리오."
L["For the one who leaps first, {name}. Do land somewhere friendly."] = "맨 먼저 뛰어드는 그대에게, {name}. 착지는 부디 우리 편 쪽에."
L["Fel and fury, {name}, and now a little kindness. It'll balance out."] = "지옥 마력과 분노, {name}, 이제 친절도 조금. 균형이 맞을 거요."
L["I'd ask if you saw this coming, {name}, but you see everything."] = "올 줄 알았냐 묻고 싶지만, {name}, 그대는 눈 가리고도 다 보지."
L["You can see souls, {name}. Mine's the one being generous."] = "영혼이 보이잖소, {name}. 지금 베푸는 게 내 영혼이오."
L["Illidan never let anyone help him, {name}. You're wiser than your teacher."] = "일리단은 누구의 도움도 받지 않았지, {name}. 그대가 스승보다 현명하오."
L["A demon inside and a Legion outside, {name}. Here's one thing on your side."] = "안엔 악마, 밖엔 군단이라, {name}. 그대 편도 하나쯤은 있어야지."
L["For you, {name}. Please don't breathe on it."] = "그대에게, {name}. 부디 입김은 불지 마시오."
L["A little help for a dragon, {name}. I'll be telling my grandchildren."] = "용에게 도움을 주다니, {name}. 손주들한테 두고두고 자랑하겠소."
L["The Aspects sent you out into the world, {name}. I'm making it friendlier."] = "위상들이 그대를 세상에 보냈소, {name}. 난 세상을 좀 다정하게 만드는 중이오."
L["Take to the skies after this, {name}. I'll wave from down here."] = "이걸 받고 하늘로 날아오르시오, {name}. 난 여기서 손 흔들겠소."
L["A dragon on our side, {name}. I've never felt safer being generous."] = "용이 우리 편이라, {name}. 이렇게 안심하고 베풀어 본 적이 없소."
L["A gift for a dragon, {name}. Normally folk bring gold and hope to leave again."] = "용에게 선물이라, {name}. 보통은 금을 바치고 살아 나가길 빌 텐데."
L["For the one who could fly me to the next town, {name}. Not asking. Hinting."] = "옆 마을까지 태워 줄 수 있는 그대에게, {name}. 부탁 아니오. 눈치 주는 거지."
L["I've met a few dragons, {name}. You're the first I didn't run from. Here."] = "용을 몇 번 만나 봤죠, {name}. 도망 안 친 건 당신이 처음이에요. 받아요."
L["For the world's youngest ancient, {name}."] = "세상에서 제일 어린 고룡에게, {name}."
L["{buff} for a mage, {name}. Like lending a library a book."] = "마법사에게 {buff}, {name}. 도서관에 책 빌려주는 격이오."
L["Mage to mage, {name}: I won't ask you for water if you won't. Take this."] = "마법사끼리 약속해요, {name}. 당신이 물 달라고 안 하면 저도 안 해요. 이걸 받아요."
L["Two mages, {name}. We can portal anywhere and still be late. Take this."] = "마법사 둘이네요, {name}. 어디든 차원문을 열 수 있는데도 늦죠. 이걸 받아요."
L["A mage for a mage, {name}. Our old masters would approve."] = "마법사가 마법사에게, {name}. 옛 스승들도 흐뭇해하실 거요."
L["A mage enchanting a mage, {name}. We'll both pretend we needed it."] = "마법사가 마법사에게 마법을, {name}. 둘 다 필요했던 척합시다."
L["We'd never admit which spells we still read off the page, {name}. Not this one."] = "아직 책 보고 외는 주문이 뭔지 우린 절대 말 안 하죠, {name}. 이건 아니에요."
L["One mage is a scholar, {name}. Two is an argument. Here's my opening point."] = "마법사 하나는 학자, {name}, 둘이면 논쟁이오. 이게 내 첫 논거요."
L["We both know this spell by heart, {name}. Humour me."] = "이 주문은 둘 다 외우고 있지, {name}. 그래도 받아 주시오."
L["More mana for you, {name}. Try not to spend it all on one fireball."] = "마나를 더 드리오, {name}. 화염구 한 방에 다 쓰진 마시오."
L["Priest to priest, {name}: who blesses the blessers? Today, me."] = "사제끼리 묻겠소, {name}. 축복하는 이는 누가 축복하오? 오늘은 나요."
L["Between us, {name}, we'll pretend the warriors listen. Take this."] = "우리끼리 얘긴데, {name}, 전사들이 말을 듣는 척해 주자고요. 이걸 받아요."
L["A priest looking after a priest, {name}. It feels almost forbidden."] = "사제가 사제를 챙기다니, {name}. 왠지 금기 같구려."
L["Two priests, {name}. Twice the praying, half the panic. Here's my share."] = "사제 둘이네요, {name}. 기도는 두 배, 공포는 절반. 제 몫을 드려요."
L["If it all goes wrong, {name}, we two are the last ones standing. Take this."] = "다 틀어지면, {name}, 마지막까지 서 있는 건 우리 둘이에요. 이걸 받아요."
L["Rest your prayers a while, {name}. Mine can keep watch."] = "그대 기도는 좀 쉬게 하시오, {name}. 내 기도가 지키고 있겠소."
L["I'd preach to you, {name}, but you've heard it. You've probably given it. Here."] = "설교라도 하고 싶지만, {name}, 다 들어 봤겠죠. 직접 해 봤을지도. 받아요."
L["Same vows and same sore knees, {name}. Here's something for yours."] = "서약도 같고 시린 무릎도 같소, {name}. 그대 무릎에 이걸 드리오."
L["If I fall, {name}, you know the words. If you fall, so do I. Here, so neither."] = "제가 쓰러지면, {name}, 당신이 주문을 알죠. 당신이 쓰러지면 저도요. 둘 다 안 쓰러지게 이걸."
L["Two druids, {name}. The Cenarion Circle would call this a quorum. Take this."] = "드루이드 둘이네요, {name}. 세나리온 의회라면 정족수라 하겠죠. 이걸 받아요."
L["Druid to druid, {name}: bear or cat, you'll have this, and leaves in your hair."] = "드루이드끼리, {name}. 곰이든 고양이든 이건 받아요. 머리엔 나뭇잎도 있겠지만."
L["From one shapeshifter to another, {name}: this one fits every shape."] = "변신술사끼리 드리오, {name}. 이건 어느 모습에나 맞소."
L["No handshake, {name}. Two druids, neither the right shape. Take this instead."] = "악수는 패스예요, {name}. 드루이드 둘인데 둘 다 맞는 모습이 아니네요. 대신 이걸요."
L["Between us, {name}, we've a shape for every problem, and this for the rest."] = "우리 둘이면, {name}, 문제마다 맞는 모습이 있죠. 나머진 이거고요."
L["Fellow druid, {name}? The trees told me you were coming, so I had this ready."] = "같은 드루이드네요, {name}? 나무들이 당신 온다고 해서 이걸 준비해 뒀어요."
L["Take this, {name}. If you see me as a cat later, pretend you don't know me."] = "이걸 받아요, {name}. 나중에 제가 고양이로 보이면 모르는 척해요."
L["Paladin to paladin, {name}: heavy hammer, light heart, and this blessing."] = "성기사끼리, {name}. 무거운 망치, 가벼운 마음, 그리고 이 축복."
L["A blessing for a paladin, {name}. Now we're both insufferably radiant."] = "성기사에게 축복을, {name}. 이제 둘 다 못 봐줄 만큼 눈부시오."
L["Two paladins, {name}. Somewhere, a priest is relieved. Take this."] = "성기사 둘이네요, {name}. 어딘가의 사제는 안도하겠죠. 이걸 받아요."
L["One of us should be humble about this, {name}. Neither of us will be."] = "둘 중 하나는 겸손해야 할 텐데, {name}. 둘 다 안 그럴 거요."
L["Same oath, different polish, {name}. Yours is shinier. Take this to match."] = "같은 맹세, 다른 광택이네요, {name}. 당신 게 더 반짝여요. 거기 맞춰 이걸 받아요."
L["Between us, {name}, we could light a cathedral. This lights you, for a start."] = "우리 둘이면 대성당도 밝히겠죠, {name}. 우선 이걸로 당신부터 밝혀요."
L["Two suits of plate, {name}. Nobody hears us sneak up. Take this anyway."] = "판금 갑옷 두 벌이네요, {name}. 아무도 우리 몰래 다가가는 소릴 못 듣죠. 그래도 이걸 받아요."
L["Your libram and mine agree on this one, {name}. Rare, that."] = "그대 성서와 내 성서가 이번엔 뜻이 같소, {name}. 드문 일이지."
L["Warlock to warlock, {name}: take this, and keep your imp away from mine."] = "흑마법사끼리, {name}. 이걸 받고, 당신 임프는 제 임프랑 떨어뜨려 놔요."
L["Fellow warlock, {name}? Then you'll know this one's harmless."] = "흑마법사 동지요, {name}? 그럼 이게 무해한 거 알겠구려."
L["Two warlocks, {name}. Let's not compare soul shards in public. Take this."] = "흑마법사 둘이네요, {name}. 영혼의 조각은 남들 앞에서 비교하지 말죠. 이걸 받아요."
L["Between us, {name}, the demons do all the work. This bit I do myself."] = "우리끼리 얘기지만, {name}, 일은 악마들이 다 하지. 이건 내가 직접 하오."
L["Another warlock, {name}. Let's be polite; I've seen what you summon. Here."] = "또 흑마법사네요, {name}. 예의 지켜요. 당신이 뭘 소환하는지 봤거든요. 받아요."
L["A spell from one warlock to another, {name}. Check it for curses. I would."] = "흑마법사가 주는 주문이오, {name}. 저주 들었나 살펴보시오. 나라면 그러겠소."
L["Fellow warlock, {name}. The only one who won't ask where this came from."] = "흑마법사 동지여, {name}. 이게 어디서 났냐고 안 물을 유일한 분이구려."
L["Two warlocks, one kind deed, {name}. The Burning Legion must be livid."] = "흑마법사 둘에 선행 하나라, {name}. 불타는 군단이 길길이 뛰겠소."
L["I'd summon you a drink, {name}, but you know how summoning goes. Have this."] = "술 한잔 소환해 드리고 싶지만, {name}, 소환이 어떻게 되는지 알잖아요. 이걸 받아요."
L["Two warriors, {name}. Somewhere, a healer just sighed. Take this."] = "전사 둘이네, {name}. 어딘가의 힐러가 방금 한숨 쉬었을 거다. 받아."
L["Warrior to warrior, {name}: first into the fight buys the drinks. I'm buying."] = "전사끼리 규칙이오, {name}. 먼저 뛰어든 자가 술 사기. 내가 사겠소."
L["Shout for shout, {name}. We'll deafen the whole place together."] = "외침엔 외침으로, {name}. 같이 이 동네 귀를 먹게 합시다."
L["No plan, {name}? Perfect. Take this; we'll get along."] = "계획이 없다고, {name}? 완벽해. 이거 받아. 우린 잘 맞겠다."
L["Warriors, {name}: the only folk who think shouting is a spell. We're right."] = "전사란, {name}, 외침도 주문이라 믿는 유일한 족속이오. 그리고 우리가 옳소."
L["Warrior to warrior, {name}: take this. Shield up, temper hot."] = "전사끼리, {name}. 이거 받아. 방패는 높이, 성질은 뜨겁게."
L["You know this one, {name}. You've probably shouted it at me already."] = "이건 그대도 알지, {name}. 아마 벌써 내게 외쳐 줬을 거요."
L["Our trainer would be proud, {name}. He'd shout it, but he'd be proud."] = "교관님이 뿌듯해하실 거요, {name}. 고함을 치시겠지만, 뿌듯해는 하실 거요."
L["Fellow warrior? Then you know the blacksmith's name too, {name}. Here."] = "같은 전사라고? 그럼 대장장이 이름도 알겠네, {name}. 받아."
L["We both served the Scourge, {name}. I won't ask what you did. Just take this."] = "우리 둘 다 스컬지를 섬겼지, {name}. 뭘 했는지 묻지 않겠소. 그냥 이걸 받으시오."
L["Two death knights, {name}. We've died twice between us. Take this; stop there."] = "죽음의 기사 둘이오, {name}. 둘이 합쳐 두 번 죽었지. 이걸 받으시오. 거기까지만."
L["Between us, {name}, we can drop the echoing voice. Just take this."] = "우리끼린, {name}, 울리는 목소리는 그만둬도 되오. 그냥 이걸 받으시오."
L["Mograine would approve of this, {name}. Grimly; he approves of all grimly."] = "모그레인도 이건 인정하겠지, {name}. 음울하게. 그는 뭐든 음울하게 인정하니까."
L["Two horns and one winter, {name}. Mine sounds today; yours can have tomorrow."] = "뿔피리는 둘인데 겨울은 하나요, {name}. 오늘은 내 것이 울리고, 그대 건 내일 부시오."
L["The living keep their distance from us, {name}. I won't. Here."] = "산 자들은 우리와 거리를 두지, {name}. 난 안 그러오. 받으시오."
L["We both broke free at Light's Hope, {name}. Every gift since is our own choice."] = "우린 둘 다 희망의 빛에서 풀려났지, {name}. 그 뒤로 주는 선물은 다 우리 선택이오."
L["Do you still dream, {name}? I only ask our own kind. Take this either way."] = "아직 꿈을 꾸시오, {name}? 우리 같은 이에게만 묻는 거요. 어쨌든 이걸 받으시오."
L["Walk with me after dark, {name}. With eyes like ours, and this, no lantern."] = "어두워지면 나와 걸으시오, {name}. 우리 같은 눈에 이것까지 있으면 등불은 필요 없소."
L["Fellow monk, {name}? Take this; we'll spar later and both pretend we held back."] = "같은 수도사네요, {name}? 이걸 받아요. 나중에 대련하고 둘 다 봐준 척하죠."
L["Two monks and one teapot, {name}. Whoever pours is the humbler, so I'll pour."] = "수도사 둘에 찻주전자 하나라, {name}. 따르는 쪽이 더 겸손한 법이니, 내가 따르리다."
L["Compare masters, {name}? Mine was the hardest. Everyone's was. Here."] = "스승 비교해 볼까요, {name}? 제 스승이 제일 혹독했죠. 다들 그렇지만. 받아요."
L["Take this, {name}. Meditate with me later. If one of us snores, the other did."] = "이걸 받아요, {name}. 나중에 같이 명상해요. 누가 코 골면 다른 쪽이 그런 거예요."
L["Monk to monk, {name}: I won't tell you to breathe. I'll just give you this."] = "수도사끼리, {name}. 숨 쉬라는 말은 안 할게요. 그냥 이걸 드릴게요."
L["Two monks, {name}. Xuen sees a contest, Yu'lon a lesson. I see a friend. Here."] = "수도사 둘이네요, {name}. 쉬엔은 시합을, 위론은 가르침을 보겠죠. 전 친구를 봐요. 받아요."
L["Why is every monastery on a mountaintop, {name}? Take this for the climb."] = "왜 수도원은 다 산꼭대기에 있을까요, {name}? 오르막엔 이걸 쓰세요."
L["Take this, {name}; do the forms with me at dawn. Two monks in step is music."] = "이걸 받고, {name}, 새벽에 같이 품새해요. 수도사 둘이 발맞추면 음악이죠."
L["Strangers ask you for wisdom, {name}? I give them this. And say eat something."] = "낯선 이들이 당신한테도 지혜를 구하나요, {name}? 전 이걸 주고, 뭐 좀 먹으라고 해요."
L["Some followed Sarkareth into the dark, {name}. We chose the sky, and this."] = "사카레스를 따라 어둠으로 간 이들도 있었소, {name}. 우린 하늘과 이것을 택했지."
L["Shall we speak Draconic, {name}? The mortals will think this is a quarrel."] = "용언으로 얘기할까, {name}? 필멸자들은 이게 말다툼인 줄 알 거요."
L["Not even the Aspects knew what to make of us, {name}. I do. Here."] = "위상들조차 우릴 어찌할지 몰랐지, {name}. 난 아오. 받으시오."
L["Do you hold a spell a moment too long, {name}, to feel it gather? I just did."] = "당신도 주문을 일부러 조금 오래 붙잡소, {name}? 모이는 걸 느끼려고? 방금 그랬소."
L["Our people are still choosing their customs, {name}. I'd like this one kept."] = "우리 종족은 아직 관습을 정하는 중이오, {name}. 이건 남았으면 하오."
L["Valdrakken was built for grown dragons, {name}. Take this; we'll feel taller."] = "발드라켄은 다 큰 용을 위해 지어졌소, {name}. 이걸 받으시오. 더 커진 기분일 거요."
L["Our magic hums when two of us stand close, {name}. Listen. That's this one."] = "우리 둘이 가까이 서면 마력이 웅웅대지, {name}. 들어 보시오. 바로 이거요."
L["Scalecommanders drilled us both, {name}. Shouts still straighten my back. Here."] = "비늘사령관들이 우리 둘을 훈련시켰지, {name}. 호통 소리에 아직도 등이 펴지오. 받으시오."
L["Whichever side you took, {name}, we were kin before there were sides. Here."] = "어느 편을 골랐든, {name}, 편이 생기기 전부터 우린 동족이었소. 받으시오."
L["Heard the earth grumble just now, {name}? It was giving you this. Good."] = "방금 대지가 투덜대는 거 들었소, {name}? 그대에게 이걸 주던 거요. 좋소."
L["Race you to the next town as wolves, {name}? Take this first. No lightning."] = "늑대로 다음 마을까지 경주할까, {name}? 이것부터 받으시오. 번개는 금지."
L["My ancestors and yours have met by now, {name}. They'd want you to have this."] = "내 조상과 그대 조상은 벌써 만났을 거요, {name}. 그대가 이걸 받길 바랄 거요."
L["Two shamans, one sky, {name}. I asked first, so this storm is mine to give."] = "주술사 둘에 하늘은 하나요, {name}. 내가 먼저 청했으니, 이 폭풍은 내가 드리오."
L["Folk stare when we talk to rocks, {name}. Let them. The rocks gave you this."] = "우리가 바위랑 얘기하면 다들 쳐다보지, {name}. 보라지. 바위가 그대에게 이걸 줬소."
L["Between two shamans, {name}, a storm is just a conversation. Here's my half."] = "주술사끼리라면, {name}, 폭풍은 그저 대화요. 자, 이건 내 몫의 말이오."
L["The elements could go quiet any day, {name}. Today they answered: this."] = "정령들은 언제든 침묵할 수 있소, {name}. 오늘은 응답했지. 이것으로."
L["Ever tried to stop listening, {name}? I did. Everything got louder. Here."] = "듣기를 그만두려 해 본 적 있소, {name}? 난 해 봤지. 다 더 시끄러워졌소. 받으시오."
L["People want storms stopped or started, {name}. I ask the sky; it gave you this."] = "사람들은 폭풍을 멈추거나 일으켜 달라 하지, {name}. 난 하늘에 묻고, 하늘은 그대에게 이걸 줬소."
L["No mana to fill, {name}. It'll just stand about being clever, like me."] = "채울 마나는 없지만, {name}, 이건 그냥 똑똑하게 서 있을 거요. 나처럼."
L["My spell on a warrior, {name}. Call it a small experiment."] = "전사에게 내 주문이라, {name}. 작은 실험이라 칩시다."
L["I only know the one spell for friends, {name}. Rage or mana, you're getting it."] = "벗에게 줄 주문은 이거 하나뿐이오, {name}. 분노든 마나든 받으시오."
L["Your rage doesn't need this, {name}, but I'd feel rude walking past you."] = "그대 분노엔 필요 없겠지만, {name}, 그냥 지나치면 결례 같아서."
L["No mana, I know, {name}. A sharp mind never hurt a sharp blade."] = "마나가 없는 건 아오, {name}. 날카로운 머리가 날카로운 칼에 해가 된 적은 없소."
L["It's meant for mana, {name}. You'll find a use. Rogues always find a use."] = "마나용이긴 하오, {name}. 쓸 데를 찾겠지. 도적은 늘 찾아내니."
L["Not your kind of magic, {name}. Call it a very clever lockpick."] = "그대 쪽 마법은 아니오, {name}. 아주 영리한 자물쇠 따개라 치시오."
L["Aye, {name}, ye only had to ask. Hold still now!"] = "암, {name}, 말만 하면 되지. 가만있어 보게!"
L["Here, {name}, a wee somethin' to keep ye on yer feet."] = "옜네, {name}. 쓰러지지 말라고 주는 작은 선물일세."
L["My thanks, {name}. Allow me to return the kindness."] = "고맙소, {name}. 이 호의에 보답하겠소."
L["Of course, {name}. Stand fast a moment."] = "물론이오, {name}. 잠시 그대로 서 계시오."
L["The road ahead is long, {name}. Take this with you."] = "갈 길이 멀다오, {name}. 이것을 챙겨 가시오."
L["Ishnu-alah, {name}. Your kindness is returned."] = "이슈누 알라, {name}. 그대의 호의를 돌려드리리다."
L["Elune-adore, {name}. Walk softly beneath the stars."] = "엘룬 아도르, {name}. 별빛 아래 사뿐히 걷기를."
L["The Light rewards kindness, {name}, and so shall I."] = "빛이 친절에 보답하듯, 저도 보답하겠습니다, {name}."
L["Of course, {name}. May the Naaru guide your steps."] = "물론입니다, {name}. 나루께서 그대의 길을 인도하시길."
L["The Light is with you, {name}. Go in peace."] = "빛이 그대와 함께합니다, {name}. 평안히 가십시오."
L["Much obliged, {name}. Gilneas never forgets a kindness."] = "신세 졌소, {name}. 길니아스는 은혜를 잊지 않소."
L["Lok'tar ogar, {name}! Take this into battle."] = "록타르 오가르, {name}! 이걸 품고 전장으로 가라!"
L["The Earth Mother sees your kindness, {name}. I return it."] = "대지모신께서 그대의 친절을 보셨소, {name}. 나도 보답하리다."
L["Of course, {name}. Stand tall and be at peace."] = "여부가 있겠소, {name}. 곧게 서서 마음을 편히 가지시오."
L["Walk with the Earth Mother, {name}."] = "대지모신과 함께 걷기를, {name}."
L["Ya be too kind, {name}! Dis one be from me."] = "친절하기도 하지, {name}! 이건 내가 주는 거라고."
L["Sure ting, {name}. Hold still now."] = "암, 그렇고말고, {name}. 가만있으라고."
L["Da loa be watchin' over ya, {name}."] = "로아가 널 지켜보고 있다고, {name}."
L["Such courtesy does you credit, {name}. Anar'alah belore."] = "그 예의, 칭찬할 만하군요, {name}. 아나랄라 벨로레."
L["Anar'alah belore, {name}. May the sun guide you."] = "아나랄라 벨로레, {name}. 태양이 그대를 인도하기를."
L["Your generosity is noted, {name}. Suramar remembers its friends."] = "그 아량, 기억하지요, {name}. 수라마르는 벗을 잊지 않으니."
L["Thank you, {name}! The caravan always repays a kindness."] = "고마워요, {name}님! 대상단은 받은 친절을 꼭 갚아요."
L["Every traveller needs something for the road, {name}."] = "나그네라면 길에서 쓸 게 필요하죠, {name}님."
L["Of course, {name}. Patience, and it is done."] = "물론이지, {name}. 조금만 참으면 다 된다네."
L["Take this, {name}. Even a dragon needs allies."] = "이걸 받으시오, {name}. 용에게도 동료는 필요하오."
L["Thank you, {name}. The Alliance looks after its own."] = "고맙소, {name}. 얼라이언스는 동료를 챙기는 법이오."
L["Of course, {name}. Allies help each other."] = "당연하오, {name}. 동맹은 서로 돕는 법이오."
L["For the Alliance, {name}! Stay strong out there."] = "얼라이언스를 위하여, {name}! 굳건히 버티시오."
L["Strength and honour, {name}. Your kindness is repaid."] = "힘과 명예를, {name}. 받은 호의는 갚았소."
L["Consider it done, {name}. For the Horde."] = "맡겨 두시오, {name}. 호드를 위하여."
L["For the Horde, {name}! Go with strength."] = "호드를 위하여, {name}! 힘이 함께하기를."
L["Thank you, {name}. Good hearts are found everywhere."] = "고맙소, {name}. 선한 마음은 어디에나 있구려."
L["Gladly, {name}, whatever banner you fly."] = "기꺼이, {name}. 그대가 어느 깃발 아래 있든."
L["Friends can come from any side, {name}."] = "벗은 어느 편에서든 오는 법이오, {name}."
L["Safe travels, {name}. Take some {buff} with you."] = "무사히 가시오, {name}. {buff}도 챙겨 가시고."
L["Off ye go, {name}, steady as the mountain."] = "가 보게, {name}. 산처럼 든든하게!"
L["Stand behind me, {name}. Aye, I know. Crouch a bit."] = "내 뒤에 서게, {name}. 암, 아네. 좀 쭈그리게."
L["Right, {name}: I take the front, ye take the loot, and we argue after."] = "자, {name}. 앞은 내가, 전리품은 자네가. 다툼은 그다음일세."
L["If I start singin', {name}, the fight's gone well. Or very badly."] = "내가 노래를 부르면, {name}, 싸움이 잘 풀린 걸세. 아니면 아주 망했거나."
L["Fair winds and following seas, {name}."] = "순풍과 잔잔한 바다가 함께하길, {name}."
L["Arathor's children stand together, {name}."] = "아라소르의 후예는 함께 서는 법이오, {name}."
L["Keep close, {name}. Humans have always won by outnumbering things."] = "가까이 붙으시오, {name}. 인간은 늘 머릿수로 이겨 왔소."
L["Stay in formation, {name}. We haven't got one, but stay in it anyway."] = "대형을 유지하시오, {name}. 대형은 없지만, 아무튼 유지하시오."
L["I'll draw up a plan, {name}, and then we can all ignore it together."] = "작전을 짜 오리다, {name}. 그리고 다 같이 무시합시다."
L["Elune-adore, {name}. Walk softly; the trees are light sleepers."] = "엘룬 아도르, {name}. 사뿐히 걸으시오. 나무들은 잠귀가 밝으니."
L["Ishnu-alah, {name}. Elune keeps her children close."] = "이슈누 알라, {name}. 엘룬께선 자녀들을 늘 곁에 두시지요."
L["Quick one, {name}? By kaldorei reckoning we'll be done before we start."] = "금방 끝내자고, {name}? 칼도레이 셈법으론 시작 전에 끝난 셈이오."
L["I'll be the one you can't see, {name}. That's not a mistake; that's the plan."] = "난 안 보이는 쪽을 맡으리다, {name}. 실수가 아니라 작전이오."
L["Elune watches the whole party, {name}. I'm just the one who waves at her."] = "엘룬께서 파티 전체를 지켜보시오, {name}. 난 손 흔드는 담당이고."
L["The moon's up, {name}. For a kaldorei, this is the middle of the morning."] = "달이 떴소, {name}. 칼도레이에겐 지금이 한창 아침이오."
L["Morning, {name}. My people slept through these for millennia. I'm adapting."] = "아침이구려, {name}. 우린 수천 년간 아침엔 잤소. 적응 중이오."
L["Walk carefully in the dark places, {name}."] = "어둠 속에선 발밑을 조심해요, {name}."
L["Stay close, {name}. The whispers are much quieter in company."] = "곁에 있어요, {name}. 함께 있으면 속삭임이 훨씬 조용해요."
L["If the shadows start giving orders, {name}, ignore them. I usually do."] = "그림자가 명령하기 시작하면, {name}, 무시해요. 저도 보통 그래요."
L["Keep an eye on my shadow, {name}. It wanders off when there's a fight."] = "제 그림자 좀 봐 줘요, {name}. 싸움만 나면 딴 데로 새거든요."
L["Night suits the ren'dorei, {name}. We match the decor."] = "밤은 렌도레이와 잘 어울려요, {name}. 인테리어랑 깔맞춤이죠."
L["For Gnomeregan, {name}! Always nice to talk to somebody at eye level."] = "놈리건을 위하여, {name}님! 눈높이 맞는 상대라 반가워요."
L["I've run the numbers, {name}: with you here, we win. I rounded up."] = "계산해 봤는데요, {name}님. 우리가 이겨요. 반올림했지만요."
L["If I shout 'duck', {name}, don't look for a duck. That went badly last time."] = "제가 '앉아!' 하면, {name}님, 의자 찾지 마세요. 지난번에 큰일 났어요."
L["Morning, {name}! Up since three. The toaster needed a new engine."] = "좋은 아침, {name}님! 세 시부터 깼어요. 토스터에 엔진 새로 다느라."
L["Stay near, {name}. I lost a world once; I'm keeping hold of this party."] = "곁에 계십시오, {name}. 세계를 한 번 잃었으니, 이 파티만은 꼭 붙잡겠습니다."
L["Twenty-five thousand years on the run, {name}. Walking with friends is nicer."] = "2만 5천 년을 도망쳤지요, {name}. 벗들과 걷는 게 훨씬 낫습니다."
L["The naaru would call this a fellowship, {name}. I call it good luck."] = "나루께선 이걸 동행이라 하시겠지요, {name}. 저는 행운이라 부릅니다."
L["Keep your wits about you, {name}. Something is always hunting."] = "정신 바짝 차리시오, {name}. 늘 뭔가가 사냥 중이니."
L["The curse binds us, {name}, but Gilneas binds us tighter."] = "저주보다 길니아스가 우릴 더 단단히 묶는다오, {name}."
L["Pack rules, {name}: nobody wanders off, and nobody mentions the fleas."] = "무리 규칙이오, {name}. 아무도 떨어지지 말 것. 벼룩 얘기는 금지."
L["A pack again, {name}. I hadn't known how much I'd missed one."] = "다시 무리가 생겼구려, {name}. 이렇게 그리웠는지 몰랐소."
L["I'll catch the scent of trouble first, {name}. It's the one perk of the curse."] = "위험 냄새는 내가 먼저 맡으리다, {name}. 저주의 유일한 장점이오."
L["Night again, {name}. I'm at my best and my worst. This is the best part."] = "또 밤이구려, {name}. 내가 가장 좋고도 가장 나쁠 때요. 이건 좋은 쪽이오."
L["Morning, {name}. I'd have been up sooner, but the rug by the fire was so warm."] = "좋은 아침이오, {name}. 더 일찍 일어났을 텐데, 난롯가 깔개가 너무 따뜻해서."
L["Blood and thunder, {name}! Go and earn your glory."] = "피와 천둥이여, {name}! 가서 영광을 쟁취해라!"
L["Throm-ka, {name}! The blood of the clans runs strong in you."] = "쓰롬카, {name}! 네 안에 부족의 피가 힘차게 흐르는군."
L["The plan, {name}: we hit it. Questions? No? Good plan."] = "작전이다, {name}. 때린다. 질문? 없나? 좋은 작전이다."
L["A true warband, {name}. Loud, angry, and all on the same side for once."] = "진짜 전투부대다, {name}. 시끄럽고, 성났고, 웬일로 다 한편이다."
L["Stay with the warband, {name}. Strength in numbers. And in axes."] = "부대에서 떨어지지 마라, {name}. 힘은 머릿수에서 나온다. 도끼 수에서도."
L["Stay alive, {name}. Undercity's housing list is already very long."] = "살아 있으시오, {name}. 언더시티 입주 대기자가 이미 넘치오."
L["If I fall down, {name}, give it a minute. Old habit."] = "내가 쓰러져도, {name}, 잠깐 기다리시오. 오랜 버릇이라."
L["I'll take the front, {name}. What's the worst that could happen? Again?"] = "앞은 내가 맡지, {name}. 최악이래 봐야 뭐겠소? 또 죽는 거?"
L["The dead keep terrible hours, {name}. Nice to have company for once."] = "죽은 자들은 생활 리듬이 엉망이오, {name}. 모처럼 말동무가 있어 좋군."
L["Morning already, {name}? I've been up all night. And all of last decade."] = "벌써 아침이오, {name}? 밤을 꼬박 새웠소. 지난 십 년도."
L["Walk with the Earth Mother, {name}. She's everywhere, so you can't get lost."] = "대지모신과 함께 걸으시오, {name}. 어디에나 계시니 길 잃을 일은 없소."
L["May An'she light your path, {name}."] = "안셰께서 그대의 길을 비추시기를, {name}."
L["The Earth Mother watches over us both, {name}."] = "대지모신께서 우리 둘을 지켜보신다오, {name}."
L["Get behind me, {name}. There's room back there for the whole party."] = "내 뒤로 오시오, {name}. 파티 전체가 들어가고도 남소."
L["The herd moves together, {name}. Mind my hooves; the herd has learned to."] = "무리는 함께 움직이오, {name}. 내 발굽 조심하시오. 무리는 이미 배웠소."
L["An'she rises, {name}, and so do we. Slower, in my case."] = "안셰께서 떠오르시오, {name}. 우리도 일어나야지. 난 좀 느리지만."
L["Mu'sha keeps the night watch, {name}. I'll tell her to keep an eye on you."] = "무샤께서 밤을 지키시오, {name}. 그대를 잘 봐 달라고 말씀드리리다."
L["Stay close, {name}. Trolls regenerate; da rest of ya gotta be careful."] = "붙어 있어, {name}. 트롤은 재생되지만, 너희는 조심해야 한다고."
L["We go in together, {name}, we come out together. That's the plan, mon."] = "같이 들어가서, {name}, 같이 나온다. 그게 작전이다, 친구."
L["Shorel'aran, {name}. Fight with elegance."] = "쇼렐아란, {name}. 우아하게 싸우시길."
L["The Sunwell shines for us both, {name}."] = "태양샘은 우리 둘 모두를 비추지요, {name}."
L["Do keep pace, {name}. We have a reputation for arriving beautifully."] = "보조 좀 맞춰 줘요, {name}. 우린 도착도 아름답게 하기로 유명하니까."
L["Stand where the light is good, {name}. If we must fight, we'll look splendid."] = "조명 좋은 데 서요, {name}. 싸워야 한다면 근사해 보여야죠."
L["A party at last, {name}. I did dress for one."] = "드디어 파티네요, {name}. 파티 옷차림으로 왔거든요."
L["The sun has risen, {name}, and so have I. We coordinate."] = "해가 떴어요, {name}. 나도 일어났죠. 우린 맞춰 움직이거든요."
L["Suramar's children shine together again, {name}."] = "수라마르의 자손들이 다시 함께 빛나는군요, {name}."
L["An expedition, {name}! In Suramar this needed six permits and a masquerade."] = "원정이군요, {name}! 수라마르라면 허가증 여섯 장에 가면무도회까지 필요했죠."
L["The dome kept us safe, {name}. Now we must make do with one another. Gladly."] = "보호막이 우릴 지켜 줬죠, {name}. 이젠 서로가 지켜야죠. 기꺼이."
L["Night at last, {name}. Add a few thousand lanterns and it's nearly Suramar."] = "드디어 밤이네요, {name}. 등불 몇천 개만 달면 거의 수라마르예요."
L["Daylight, {name}. Ten thousand years under a dome, and it still startles me."] = "햇빛이네요, {name}. 만 년을 보호막 아래 살아서, 아직도 깜짝 놀라요."
L["Nobody dies on my contract, {name}. The paperwork's a nightmare."] = "내 계약 기간엔 아무도 못 죽어, {name}. 서류 작업이 지옥이거든."
L["We split the take even, {name}. I'll do the maths. Trust me."] = "몫은 똑같이 나누자, {name}. 계산은 내가 할게. 믿어."
L["A fellow wanderer! The caravan is never far, {name}."] = "같은 방랑자네요! 대상단은 늘 가까이 있어요, {name}님."
L["Caravan rules, {name}: stay together, share the water, nobody sells the alpaca."] = "대상단 규칙이에요, {name}님. 함께 다니기, 물 나누기, 알파카 팔지 않기."
L["Anything shiny in there, {name}, I saw it first. Caravan law."] = "반짝이는 건, {name}님, 제가 먼저 봤어요. 대상단 법이에요."
L["We vulpera travel by night, {name}. Cool sand, sleepy scorpids."] = "불페라는 밤에 다녀요, {name}님. 모래는 시원하고, 전갈은 졸리고."
L["Balance in all things, {name}. Now go with a light heart."] = "모든 일엔 균형이라네, {name}. 이제 가벼운 마음으로 가게."
L["We must share a brew when the road allows, {name}!"] = "길이 허락하면 술 한잔 나누세, {name}!"
L["A fight, then a meal, {name}. That is the correct order. Never the reverse."] = "싸움 다음에 밥일세, {name}. 그게 올바른 순서지. 절대 반대로는 안 되네."
L["Stay together, {name}, like dumplings in a steamer. Warm, and ready."] = "찜기 속 만두처럼 붙어 있게, {name}. 따끈하게, 준비된 채로."
L["We move as one, {name}. Slowly, perhaps, but as one."] = "우린 한 몸처럼 움직이네, {name}. 좀 느릴지언정, 한 몸처럼."
L["Past my first nap, {name}, and before my second. Quickly, while I'm awake."] = "첫 낮잠은 지났고 두 번째 낮잠 전일세, {name}. 깨어 있을 때 얼른."
L["The Forbidden Reach feels far behind us now, {name}."] = "이제 금지된 해안도 먼 옛일 같구려, {name}."
L["Tell me when to breathe fire, {name}. And, please, when not to."] = "불 뿜을 때가 되면 말해 주시오, {name}. 뿜지 말아야 할 때도 꼭."
L["I woke in a cave full of strangers, {name}. This is far better company."] = "눈 떠 보니 낯선 이들 가득한 동굴이었소, {name}. 여기가 훨씬 낫구려."
L["Neltharion made us to fight alone, {name}. We have improved on him."] = "넬타리온은 우릴 홀로 싸우도록 빚었소, {name}. 설계는 우리가 고쳤지."
L["Hagar sent me to see the goddess's work, {name}. You're some of her best."] = "하가르께서 여신의 작품을 보고 오라 하셨소, {name}. 그대는 그중에서도 걸작이오."
L["Two haranir out in the world, {name}. No wonder the elders are up in arms."] = "하라니르 둘이 세상에 나와 있다니, {name}. 장로들이 펄쩍 뛸 만하오."
L["We once mastered every beast on our mountain, {name}. These won't take long."] = "우린 한때 우리 산의 모든 짐승을 길들였소, {name}. 이놈들쯤은 금방이오."
L["Word from Harandar, {name}: the haranir are ready to join the fight."] = "하란다르에서 소식이오, {name}. 하라니르가 싸움에 나설 준비를 마쳤소."
L["It is good to see one of our own, {name}."] = "동족을 만나니 반갑구려, {name}."
L["Stormwind has a statue for every hero, {name}. I'm putting in a word for yours."] = "스톰윈드엔 영웅마다 동상이 있소, {name}. 그대 동상도 건의해 두겠소."
L["Onward, {name}. The Alliance is with you."] = "전진하시오, {name}. 얼라이언스가 함께하오."
L["Together we stand, {name}. For the Alliance!"] = "뭉쳐야 사는 법이오, {name}. 얼라이언스를 위하여!"
L["Right, {name}: shields up, heads down, and nobody charges before the plan does."] = "자, {name}. 방패는 들고, 고개는 숙이고, 작전보다 먼저 돌격하는 자 없기요."
L["The finest company the Alliance ever fielded, {name}. Or at least the nearest."] = "얼라이언스 역사상 최고의 부대요, {name}. 적어도 제일 가까이 있는 부대."
L["Go with honour, {name}. Victory awaits."] = "명예롭게 가시오, {name}. 승리가 기다리오."
L["Go and do something worth a song, {name}. Loud songs. The Horde likes loud."] = "노래가 될 일을 하시오, {name}. 시끄러운 노래로. 호드는 시끄러운 게 좋소."
L["Walk tall, {name}. The Horde always made room for those the world turned away."] = "당당히 걸으시오, {name}. 호드는 늘 세상이 외면한 이들을 품었소."
L["Our strength is each other, {name}. For the Horde!"] = "우리의 힘은 서로에게 있소, {name}. 호드를 위하여!"
L["Forward, {name}. The Horde advances together. Retreats... never, officially."] = "전진하시오, {name}. 호드는 함께 전진하오. 후퇴는... 공식적으론 없소."
L["Together we're a war band, {name}. Apart, we're just loud."] = "뭉치면 전투부대요, {name}. 흩어지면 그냥 시끄러운 무리고."
L["Friends can come from any side, {name}. Or, like me, from none in particular."] = "벗은 어느 편에서든 오는 법이오, {name}. 나처럼 아무 편도 아닌 데서도."
L["Side by side, {name}, whatever comes."] = "어깨를 나란히, {name}. 무엇이 닥치든."
L["No flag over this party, {name}, just us. That's plenty."] = "이 파티엔 깃발 대신 우리가 있소, {name}. 그걸로 충분하오."
L["One day we'll pick sides, {name}. Today we pick fights, together."] = "편 가르기는 나중에, {name}. 오늘은 함께 적을 가릅시다."
L["Your stance says you've had a long day, {name}. Monks notice these things."] = "자세를 보니 긴 하루였구려, {name}. 수도사는 이런 걸 알아보오."
L["We have to stop meeting like this, {name}. Actually, no, we don't."] = "이렇게 자꾸 만나면 곤란하오, {name}. 아니, 곤란할 거 없구려."
L["Somewhere in here a villain is rehearsing a speech, {name}. Let's interrupt."] = "이 안 어딘가서 악당이 연설 연습 중이오, {name}. 가서 끊어 줍시다."
L["Bwonsamdi gonna be real disappointed, {name}. Thanks, mon."] = "브원삼디가 엄청 실망하겠네, {name}. 고맙다, 친구."
L["Sure ting, {name}. Hold still; da mojo don't like a movin' target."] = "암, 그렇고말고, {name}. 가만있어. 주술은 움직이는 과녁을 싫어한다고."
L["No worries, {name}. Da loa got ya covered."] = "걱정 마, {name}. 로아가 챙겨 줄 거라고."
L["Stay away from da voodoo, {name}. ...Except dis voodoo. Dis one fine."] = "부두는 가까이하지 마, {name}. ...이 부두만 빼고. 이건 괜찮다고."
